-- =============================================================================
-- Studuel — Migration 423 : QUESTIONS EN PLUS — FRANÇAIS 1re, LES 260 FICHES DE LECTURE
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main.
--    Regénérer : node scripts/seed-complements.mjs --num 423 --complements francais-lecture-q10,francais-lecture-q11,francais-lecture-q12,francais-lecture-q13,francais-lecture-q14,francais-lecture-q15,francais-lecture-q16,francais-lecture-q17,francais-lecture-q18,francais-lecture-q19,francais-lecture-q20,francais-lecture-q21,francais-lecture-q22
--
-- Quatre questions de plus par fiche de lecture (8 → 12) : huit suffisaient pour se tester une fois sur une œuvre, pas pour la réviser sur plusieurs semaines avant l'épreuve anticipée.
--
-- Cette migration apporte : 1040 questions ajoutées à des quiz existants
-- 0 cours relus (réécrits seulement si leur texte a changé)
-- et 0 questions existantes corrigées sur place (identifiant gardé).
-- AUCUN chapitre créé ni supprimé. Les chapitres sont désignés par leur clé
-- naturelle (matière, niveau, titre) : un chapitre absent est simplement sauté.
--
-- Idempotent : UUID dérivés du contenu, ON CONFLICT DO NOTHING, UPDATE gardés
-- par IS DISTINCT FROM. Rejouable sans risque.
-- À exécuter dans : Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

-- 2. Questions ------------------------------------------------------------
-- Rangées APRÈS celles du quiz : position = dernière position + rang.
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, qz.id, v.question, v.kind, v.options, v.correct_index, v.explanation,
       COALESCE((SELECT max(x.position) FROM public.quiz_questions x WHERE x.quiz_id = qz.id), 0) + v.rang
  FROM (VALUES
    ('07f0a64d-e83e-5aec-a586-fa811e38f409'::uuid, 'francais', '1re', '« Art », Yasmina Reza', 'Quel est le métier de Serge ?', 'mcq', '["Ingénieur","Papetier","Dermatologue","Galeriste"]'::jsonb, 2, 'Serge est dermatologue, Marc ingénieur et Yvan papetier : trois hommes installés, que la toile blanche suffit à faire vaciller.', 1),
    ('1fe388dc-c1b6-50db-9d0c-6843229d3d45'::uuid, 'francais', '1re', '« Art », Yasmina Reza', 'Quel secret Serge garde-t-il quand Marc dessine sur la toile ?', 'mcq', '["Le tableau est une copie","Le feutre est lavable","Le peintre est son cousin","Le tableau n’est pas payé"]'::jsonb, 1, 'Serge savait que le feutre était lavable et ne l’a pas dit : leur amitié repart sur un petit mensonge.', 2),
    ('c227bd2c-c432-52db-8b47-6518f580892e'::uuid, 'francais', '1re', '« Art », Yasmina Reza', 'Que Serge reproche-t-il à Marc ?', 'mcq', '["De mal gagner sa vie","De lui avoir menti sur son âge","De trahir les secrets d’Yvan","De vouloir rester son maître à penser"]'::jsonb, 3, 'Sous la querelle sur l’art, chacun règle ses comptes : Serge reproche à Marc son ascendant, Marc reproche à Serge de s’être inventé un goût.', 3),
    ('0e91a915-a3e5-578c-a5b0-13c76e889fd5'::uuid, 'francais', '1re', '« Art », Yasmina Reza', 'Quelle récompense « Art » reçoit-elle à Broadway en 1998 ?', 'mcq', '["Le Tony Award de la meilleure pièce","Le prix Pulitzer du théâtre","L’Oscar du meilleur scénario","Le Molière de la meilleure pièce"]'::jsonb, 0, 'Après les Molières de 1995 à Paris, la pièce reçoit en 1998 le Tony Award de la meilleure pièce : un succès mondial.', 4),
    ('218ef8bc-353e-5090-8edc-1dc4c29c6776'::uuid, 'francais', '1re', '« Le Bateau ivre », Arthur Rimbaud', 'Selon la « lettre du Voyant », comment le poète se fait-il voyant ?', 'mcq', '["Par une longue et sage imitation des grands poètes anciens","Par un long, immense et raisonné dérèglement de tous les sens","Par un long voyage réel vers les pays lointains","Par un patient retour à la foi de son enfance"]'::jsonb, 1, 'La formule de mai 1871, adressée à Paul Demeny, fait du poète un explorateur de l’inconnu : Le Bateau ivre met ce programme en images.', 1),
    ('ae47ec70-05a3-54a2-a5a8-fb130b1fb6b7'::uuid, 'francais', '1re', '« Le Bateau ivre », Arthur Rimbaud', 'Quand et comment le poème est-il publié ?', 'mcq', '["En 1871, dans une revue de Charleville","En 1873, à la suite d’Une saison en enfer","En 1883, grâce à Verlaine, dans Les Poètes maudits","En 1891, l’année de la mort de Rimbaud"]'::jsonb, 2, 'Composé à l’été 1871, le poème reste inédit pendant douze ans : c’est Verlaine qui le fait connaître dans Les Poètes maudits.', 2),
    ('9ecd521a-f0b6-517e-b446-2ffa12742a72'::uuid, 'francais', '1re', '« Le Bateau ivre », Arthur Rimbaud', 'Que sont les « pontons » du dernier vers ?', 'mcq', '["Des navires-prisons","Des ponts de bateaux","Des phares de port","Des bateaux de pêche"]'::jsonb, 0, 'Le bateau ne peut plus « nager sous les yeux horribles des pontons » : le poème se clôt sur le refus d’un monde d’enfermement.', 3),
    ('dab53c2f-f6f8-54b3-926d-59e607a29523'::uuid, 'francais', '1re', '« Le Bateau ivre », Arthur Rimbaud', 'À l’oral, sur quel contraste le cours conseille-t-il de s’appuyer ?', 'mcq', '["Entre la vie à la ville et la vie aux champs","Entre les passages en vers et ceux en prose","Entre les scènes de rire et celles de larmes","Entre la forme régulière et le déferlement des images"]'::jsonb, 3, 'Vingt-cinq quatrains d’alexandrins contiennent un flot de visions inouïes : la forme régulière tient l’ivresse.', 4),
    ('29f5b91a-1c49-57a8-b0fe-b044aa496249'::uuid, 'francais', '1re', '« Sylvie », Les Filles du feu, Gérard de Nerval', 'Qui Sylvie finit-elle par épouser ?', 'mcq', '["Le narrateur, après la fête","Un comédien de la troupe d’Aurélie","« Le grand frisé », devenu pâtissier","Un riche propriétaire du Valois"]'::jsonb, 2, 'Sylvie épouse « le grand frisé », son camarade d’enfance : la vie réelle continue sans le narrateur, qui n’a jamais su choisir.', 1),
    ('dfd75160-6599-5a57-8748-eeb47155bbd1'::uuid, 'francais', '1re', '« Sylvie », Les Filles du feu, Gérard de Nerval', 'Que représente Sylvie parmi les trois femmes du récit ?', 'mcq', '["L’idéal, la figure inaccessible","Le réel, la tendresse, la vie qui continue","L’illusion, l’image de théâtre","Le renoncement et la vie religieuse"]'::jsonb, 1, 'Sylvie est le réel, Adrienne l’idéal, Aurélie l’illusion : le narrateur court après « une femme faite de trois ».', 2),
    ('04a06bcf-613d-5707-a774-34ed501d2895'::uuid, 'francais', '1re', '« Sylvie », Les Filles du feu, Gérard de Nerval', 'Quel ensemble de sonnets clôt le recueil Les Filles du feu ?', 'mcq', '["Les Chimères","Les Méditations","Les Contemplations","Les Nuits"]'::jsonb, 0, 'Sylvie paraît d’abord dans la Revue des Deux Mondes en 1853, puis entre dans Les Filles du feu (1854), que ferment les sonnets des Chimères.', 3),
    ('53a69299-13a8-50fc-9903-bea955871cda'::uuid, 'francais', '1re', '« Sylvie », Les Filles du feu, Gérard de Nerval', 'Quel écrivain voit dans Sylvie l’ancêtre de sa propre entreprise ?', 'mcq', '["Gustave Flaubert","Victor Hugo","Émile Zola","Marcel Proust"]'::jsonb, 3, 'Proust admire ce récit où le passé revient par fragments et par associations : l’ordre du souvenir y remplace l’ordre chronologique.', 4),
    ('88fdc62c-dddc-51e3-a2ce-70573a2a2295'::uuid, 'francais', '1re', '« Un cœur simple », Trois Contes, Gustave Flaubert', 'Quel objet Flaubert installe-t-il sur sa table pour écrire le conte ?', 'mcq', '["Un portrait de George Sand, son amie disparue","Un perroquet empaillé emprunté au muséum de Rouen","Une colombe sculptée prise dans une église","Une carte de Cuba achetée au port du Havre"]'::jsonb, 1, 'Flaubert se documente jusque sur l’oiseau : le perroquet empaillé du muséum de Rouen lui sert de modèle pour Loulou.', 1),
    ('7f3d97e1-46fc-5381-86a8-da6dad6565e1'::uuid, 'francais', '1re', '« Un cœur simple », Trois Contes, Gustave Flaubert', 'Quel épisode montre chez Félicité « un courage qui ne se sait pas » ?', 'mcq', '["Elle sauve Victor de la noyade au port","Elle chasse des voleurs de la maison Aubain","Elle soigne seule les malades du village","Elle arrête un taureau en lui jetant de la terre"]'::jsonb, 3, 'Face au taureau, Félicité agit sans se regarder agir : sa bonté et son courage n’ont jamais besoin de mots.', 2),
    ('53fbf62c-97e1-514e-9fef-80f7256b1a31'::uuid, 'francais', '1re', '« Un cœur simple », Trois Contes, Gustave Flaubert', 'Qui est Théodore ?', 'mcq', '["Le fiancé qui abandonne Félicité","Le fils de Madame Aubain","Le curé de Pont-l’Évêque","Le père du petit Victor"]'::jsonb, 0, 'L’abandon de Théodore ouvre la longue suite de pertes de Félicité : Virginie, Victor, puis Madame Aubain.', 3),
    ('e9b6d692-cd8c-56cd-9092-d68f7ae1b154'::uuid, 'francais', '1re', '« Un cœur simple », Trois Contes, Gustave Flaubert', 'Selon le cours, quelle grandeur Flaubert donne-t-il à cette vie minuscule ?', 'mcq', '["Celle d’une héroïne de tragédie","Celle d’une reine déchue","Celle d’une vie de sainte","Celle d’une grande amoureuse"]'::jsonb, 2, 'C’est un réalisme qui refuse le mépris : sans ironie ni pathos, la servante illettrée reçoit la grandeur d’une vie de sainte.', 4),
    ('34cda526-1dac-51b6-94bc-16ad3d19c103'::uuid, 'francais', '1re', '1984, George Orwell', 'Que se passe-t-il dans la chambre 101 ?', 'mcq', '["Winston y cache et y écrit son journal interdit","Winston y retrouve Julia, loin des télécrans","Face à ce qu’il redoute le plus, Winston trahit Julia","Winston y réécrit les archives du Parti"]'::jsonb, 2, 'La chambre 101 confronte chacun à ce qu’il redoute le plus : c’est là que le Parti brise le dernier lien de Winston, son amour pour Julia.', 1),
    ('a53a7a35-9b90-5f09-8dee-8e0d154691a0'::uuid, 'francais', '1re', '1984, George Orwell', 'Lequel de ces slogans est bien un slogan du Parti ?', 'mcq', '["La liberté c’est la force","L’ignorance c’est la paix","La guerre c’est la liberté","La liberté c’est l’esclavage"]'::jsonb, 3, 'Les trois slogans — la guerre c’est la paix, la liberté c’est l’esclavage, l’ignorance c’est la force — unissent des contraires : ils exigent la double-pensée.', 2),
    ('73df0e65-621a-57a4-91b9-364bfc5823d3'::uuid, 'francais', '1re', '1984, George Orwell', 'Comment le cours définit-il le genre de 1984 ?', 'mcq', '["Une contre-utopie qui imagine le pire pour en avertir","Un roman historique sur la guerre d’Espagne","Une utopie qui décrit une société idéale","Un roman policier autour d’un complot"]'::jsonb, 0, 'Une contre-utopie projette les dangers d’un pouvoir total dans un monde imaginaire, pour mettre le lecteur en garde.', 3),
    ('d4150ae0-326d-5c49-bc72-95b3d8684661'::uuid, 'francais', '1re', '1984, George Orwell', 'Qui est Julia ?', 'mcq', '["Une espionne envoyée par O’Brien","Sa maîtresse, révoltée par goût de la vie","La sœur de Winston, disparue enfant","Une employée zélée du ministère de l’Amour"]'::jsonb, 1, 'Julia se révolte par goût de la vie plus que par idée : leur amour est le dernier espace de liberté, que le Parti finit par détruire.', 4),
    ('1b5ac31c-042e-5df7-a879-48327e90ec89'::uuid, 'francais', '1re', 'À l’ombre des jeunes filles en fleurs, Marcel Proust', 'Dans « Autour de Madame Swann », quel amour d’enfance se défait ?', 'mcq', '["Son amour pour Albertine","Son amour pour Gilberte","Son amour pour Oriane","Son amour pour Odette"]'::jsonb, 1, 'À Paris, le narrateur fréquente les Swann et voit se défaire son amour pour Gilberte ; Albertine n’apparaît qu’à Balbec.', 1),
    ('87ebf233-8257-539c-9294-417d112fdafd'::uuid, 'francais', '1re', 'À l’ombre des jeunes filles en fleurs, Marcel Proust', 'Quel personnage apporte au narrateur l’amitié aristocratique, à Balbec ?', 'mcq', '["Le baron de Charlus","Bergotte","Robert de Saint-Loup","Elstir"]'::jsonb, 2, 'Saint-Loup incarne l’amitié aristocratique ; Charlus reste une énigme, Elstir apprend à voir, Bergotte est l’écrivain rencontré chez les Swann.', 2),
    ('65ead4af-a00d-5175-9dab-d4706cf87038'::uuid, 'francais', '1re', 'À l’ombre des jeunes filles en fleurs, Marcel Proust', 'De quelle autrice la grand-mère du narrateur est-elle une lectrice fervente ?', 'mcq', '["Mme de Sévigné","Mme de Lafayette","Mme de Staël","Madeleine de Scudéry"]'::jsonb, 0, 'La grand-mère, figure de la tendresse absolue, lit et aime Mme de Sévigné, la grande épistolière du XVIIe siècle.', 3),
    ('58215515-98c4-573a-ad3e-58996ea7e15d'::uuid, 'francais', '1re', 'À l’ombre des jeunes filles en fleurs, Marcel Proust', 'Comment le cours décrit-il la phrase de Proust ?', 'mcq', '["Brève et sèche, sans image ni incise","Familière, faite de dialogues rapides","Rimée et rythmée comme un poème en vers","Longue, ramifiée, elle épouse le mouvement d’une conscience"]'::jsonb, 3, 'Incises et comparaisons développées suivent une conscience qui revient sur elle-même : on ne lit pas Proust pour savoir ce qui arrive.', 4),
    ('bac35d6c-43d6-591e-8e59-f2fca1dd5b57'::uuid, 'francais', '1re', 'Adolphe, Benjamin Constant', 'Quelle est l’origine d’Ellénore ?', 'mcq', '["Anglaise","Polonaise","Italienne","Russe"]'::jsonb, 1, 'Ellénore, d’origine polonaise, maîtresse d’un comte dont elle a deux enfants, quitte tout pour Adolphe.', 1),
    ('b9d92521-144a-554a-b470-bff3227be541'::uuid, 'francais', '1re', 'Adolphe, Benjamin Constant', 'Selon le cours, que démonte Constant dans Adolphe ?', 'mcq', '["Les ruses de la séduction mondaine","Les intrigues politiques de l’Empire","La mécanique de la lâcheté sentimentale","Les rouages de l’ambition sociale"]'::jsonb, 2, 'Le roman montre comment on peut faire un mal immense en voulant éviter d’en faire : la faiblesse y est plus destructrice que la méchanceté.', 2),
    ('02803e89-ad21-50da-8c1d-a6606ffaa314'::uuid, 'francais', '1re', 'Adolphe, Benjamin Constant', 'De quel roman du XVIIe siècle Adolphe est-il l’héritier, comme roman d’analyse ?', 'mcq', '["L’Astrée","Le Roman comique","Artamène ou le Grand Cyrus","La Princesse de Clèves"]'::jsonb, 3, 'Comme La Princesse de Clèves, Adolphe n’a presque pas d’action : tout est dans l’analyse des motifs.', 3),
    ('113326a6-7b43-5bc9-b97f-4627bfa07100'::uuid, 'francais', '1re', 'Adolphe, Benjamin Constant', 'Que dit le roman du regard de la société sur la liaison ?', 'mcq', '["Elle condamne la femme, pas l’homme","Elle excuse les deux amants","Elle condamne surtout le jeune homme","Elle ignore tout de leur liaison"]'::jsonb, 0, 'Ellénore, qui a tout quitté, paie seule le prix social de la liaison : c’est l’un des thèmes du roman.', 4),
    ('a8c1f85b-c199-516b-889d-df752e8ead81'::uuid, 'francais', '1re', 'Alcools, Guillaume Apollinaire', 'Quel poème ferme le recueil ?', 'mcq', '["« Zone »","« Le Pont Mirabeau »","« Vendémiaire »","« Nuit rhénane »"]'::jsonb, 2, 'Le recueil s’ouvre sur « Zone », écrit en dernier, et se ferme sur « Vendémiaire » : l’ordre n’est ni chronologique ni thématique.', 1),
    ('e0c7ec29-c0cb-546d-9c9d-5b1ce3e8800a'::uuid, 'francais', '1re', 'Alcools, Guillaume Apollinaire', 'Comment Apollinaire justifie-t-il la suppression de la ponctuation ?', 'mcq', '["Le rythme et la coupe des vers suffisent à ponctuer","Il imite les manuscrits des poètes médiévaux","Il veut gagner de la place sur les pages","Son éditeur l’exige pour aller plus vite"]'::jsonb, 0, 'Pour Apollinaire, « le rythme même et la coupe des vers, voilà la véritable ponctuation » : l’oreille remplace les virgules.', 2),
    ('0d911231-64aa-5f99-826b-d9bf7107eadd'::uuid, 'francais', '1re', 'Alcools, Guillaume Apollinaire', 'Comment « Zone » appelle-t-il la tour Eiffel ?', 'mcq', '["« reine »","« géante »","« sentinelle »","« bergère »"]'::jsonb, 3, 'La tour Eiffel « bergère » : une image pastorale pour un monument moderne, c’est l’alliage de l’ancien et du nouveau propre à Alcools.', 3),
    ('6b9ef28a-0626-5906-812b-f0af57350b6b'::uuid, 'francais', '1re', 'Alcools, Guillaume Apollinaire', 'Quel mouvement pictural Apollinaire défend-il, en ami de Picasso ?', 'mcq', '["L’impressionnisme","Le cubisme","Le romantisme","Le réalisme"]'::jsonb, 1, 'Ami de Picasso et défenseur du cubisme, Apollinaire est au cœur des avant-gardes parisiennes du début du XXe siècle.', 4),
    ('b9c21aeb-1203-584d-a201-d0da601f224f'::uuid, 'francais', '1re', 'Andromaque, Jean Racine', 'De quelles sources Racine tire-t-il le sujet d’Andromaque ?', 'mcq', '["De Sophocle et d’Homère","D’Euripide et de Virgile","De Sénèque et d’Ovide","De Plutarque et de Tacite"]'::jsonb, 1, 'Le sujet vient d’Euripide et du chant III de l’Énéide de Virgile : la guerre de Troie est finie, mais tous restent enchaînés à elle.', 1),
    ('32be473f-8189-51cd-ae65-5bb60b21106a'::uuid, 'francais', '1re', 'Andromaque, Jean Racine', 'Comment finit Hermione ?', 'mcq', '["Elle épouse Oreste et repart en Grèce","Elle entre au temple et devient prêtresse","Elle maudit Oreste et se tue sur le corps de Pyrrhus","Elle est livrée aux Grecs avec Astyanax"]'::jsonb, 2, 'Après avoir ordonné le meurtre, Hermione renie son ordre (« Qui te l’a dit ? »), maudit Oreste et se tue : la parole donnée ne se reprend pas.', 2),
    ('df8e9708-24e7-584b-adb6-f8bdd91f551e'::uuid, 'francais', '1re', 'Andromaque, Jean Racine', 'Comment la tragédie classique traite-t-elle la violence ?', 'mcq', '["Elle la raconte au lieu de la montrer","Elle la montre sur scène sans retenue","Elle l’écarte entièrement de l’intrigue","Elle la confie à un chœur chanté"]'::jsonb, 0, 'Le meurtre de Pyrrhus a lieu hors de la scène et fait l’objet d’un récit : la violence est racontée, non montrée.', 3),
    ('001d51a9-16db-54d3-8f58-71b01f797f8a'::uuid, 'francais', '1re', 'Andromaque, Jean Racine', 'Qui est Céphise ?', 'mcq', '["La confidente d’Hermione","La mère d’Hector","La sœur de Pyrrhus","La confidente d’Andromaque"]'::jsonb, 3, 'Chaque héros a son confident : Céphise pour Andromaque, Cléone pour Hermione, Pylade pour Oreste, Phœnix auprès de Pyrrhus.', 4),
    ('45311133-80b8-5d88-bda9-45f705132c87'::uuid, 'francais', '1re', 'Antigone, Jean Anouilh', 'Que fait Créon à la toute fin de la pièce ?', 'mcq', '["Il se donne la mort","Il s’exile loin de Thèbes","Il retourne au conseil","Il renonce au trône"]'::jsonb, 2, 'Seul survivant de sa famille, Créon reprend son travail de roi : le compromis nécessaire continue, sans pureté ni héroïsme.', 1),
    ('dcf37ecf-1506-5cca-ad1f-c6bde31779c0'::uuid, 'francais', '1re', 'Antigone, Jean Anouilh', 'Lequel de ces éléments est un anachronisme assumé de la pièce ?', 'mcq', '["Un oracle rendu à Delphes","Des gardes qui parlent de leur solde","Un messager qui fait un récit","Un devin aveugle qui prophétise"]'::jsonb, 1, 'Cigarettes, gardes occupés de leur solde et de leur avancement : Anouilh habille le mythe d’un langage familier et moderne.', 2),
    ('93626a36-5f9d-5ceb-b07e-bea48bcc6610'::uuid, 'francais', '1re', 'Antigone, Jean Anouilh', 'Selon le Chœur, pourquoi la tragédie est-elle « reposante » ?', 'mcq', '["Parce que tout finit toujours bien","Parce que les dieux protègent les héros","Parce qu’elle fait rire le public","Parce que l’espoir n’y existe plus"]'::jsonb, 3, 'Le Chœur distingue la tragédie du drame : dans la tragédie, tout est joué d’avance, et l’absence d’espoir la rend paradoxalement reposante.', 3),
    ('346c26b5-10a4-58d8-be34-6d5742f87971'::uuid, 'francais', '1re', 'Antigone, Jean Anouilh', 'Qu’est-ce qui change par rapport à Sophocle ?', 'mcq', '["Les dieux ont disparu : Antigone se bat pour elle-même","Antigone survit et épouse Hémon","Créon n’est plus le roi de Thèbes","Polynice est enterré par Ismène"]'::jsonb, 0, 'Chez Sophocle, Antigone invoque les lois divines ; chez Anouilh, sans dieux, son refus devient la liberté de dire non.', 4),
    ('14a45694-2312-58a1-a360-d0fb60d1ecf7'::uuid, 'francais', '1re', 'Antigone, Sophocle', 'Lequel des deux frères Créon ordonne-t-il d’honorer ?', 'mcq', '["Polynice","Aucun des deux","Étéocle","Les deux, à égalité"]'::jsonb, 2, 'Après leur guerre fratricide, Créon honore Étéocle et laisse Polynice sans sépulture, sous peine de mort pour qui l’enterrerait.', 1),
    ('ce30b75c-0022-51df-be37-4ee766e2e63a'::uuid, 'francais', '1re', 'Antigone, Sophocle', 'Qu’est-ce que l’hybris qui perd Créon ?', 'mcq', '["La pitié","La lâcheté","La piété","La démesure"]'::jsonb, 3, 'L’hybris est la démesure de celui qui dépasse les limites humaines : averti trop tard par Tirésias, Créon reste seul.', 2),
    ('6d4752fc-05bf-5bd0-b1a7-0f0d1ec6cc4d'::uuid, 'francais', '1re', 'Antigone, Sophocle', 'Combien de pièces de Sophocle nous sont parvenues ?', 'mcq', '["Sept","Trois","Douze","Vingt"]'::jsonb, 0, 'Sur quelque cent vingt pièces écrites, sept seulement ont été conservées, parmi lesquelles Antigone, Œdipe roi et Œdipe à Colone.', 3),
    ('887d1f46-71e2-56c5-a6e2-83bb88be884b'::uuid, 'francais', '1re', 'Antigone, Sophocle', 'Avec quelles pièces Antigone forme-t-elle le cycle thébain ?', 'mcq', '["Médée et Les Bacchantes","Œdipe roi et Œdipe à Colone","Agamemnon et Les Choéphores","Électre et Philoctète"]'::jsonb, 1, 'Le cycle thébain suit le destin de la famille d’Œdipe, dont Antigone est la fille.', 4),
    ('7e6293d9-5c35-5b72-b4e1-d2e9c9c95762'::uuid, 'francais', '1re', 'Armance, Stendhal', 'Quel est le vrai nom de Stendhal ?', 'mcq', '["Henri Brulard","Henri Beyle","Louis Beyle","Henri Mérimée"]'::jsonb, 1, 'Henri Beyle, né à Grenoble en 1783, publie sous le nom de Stendhal ; Armance (1827) précède de trois ans Le Rouge et le Noir.', 1),
    ('d20b27a9-6657-576a-96d4-79508272158d'::uuid, 'francais', '1re', 'Armance, Stendhal', 'De quelle école Octave de Malivert sort-il ?', 'mcq', '["L’École normale","Saint-Cyr","L’École polytechnique","L’École des chartes"]'::jsonb, 2, 'Octave, vingt ans, sort de l’École polytechnique : brillant, mélancolique et secret, il se sait pourtant incapable d’être un époux.', 2),
    ('080a8742-de61-556e-ab03-bf1233622159'::uuid, 'francais', '1re', 'Armance, Stendhal', 'Quel est le sous-titre du roman ?', 'mcq', '["« Quelques scènes d’un salon de Paris en 1827 »","« Chronique d’un jeune homme en 1830 »","« Mœurs de la province et de Paris »","« Histoire d’un émigré revenu en France »"]'::jsonb, 0, 'Le sous-titre annonce la peinture d’une société : le salon aristocratique de la Restauration, ses calculs d’argent et de mariage.', 3),
    ('67e09683-5137-55c1-88bd-67e0642a6b61'::uuid, 'francais', '1re', 'Armance, Stendhal', 'Que deviennent Armance et Mme de Malivert à la fin ?', 'mcq', '["Elles partent rejoindre Octave en Grèce","Elles tiennent ensemble un salon à Paris","Elles retournent vivre en Russie","Elles entrent toutes deux au couvent"]'::jsonb, 3, 'Après la mort d’Octave, empoisonné à bord du navire, les deux femmes se retirent au couvent.', 4),
    ('ea59d8b8-3a37-5d1c-b256-5c31b7f90105'::uuid, 'francais', '1re', 'Artamène ou le Grand Cyrus, Madeleine et Georges de Scudéry', 'Comment appelle-t-on les réunions du salon de Madeleine de Scudéry ?', 'mcq', '["Ses « samedis »","Ses « mardis »","Ses « soirées bleues »","Ses « ruelles du lundi »"]'::jsonb, 0, 'Dans son salon du Marais, les « samedis », on la surnomme Sapho : le roman prolonge l’art de la conversation qui s’y pratique.', 1),
    ('8ceb48e4-6e99-5834-a80b-e17fb70ac1fe'::uuid, 'francais', '1re', 'Artamène ou le Grand Cyrus, Madeleine et Georges de Scudéry', 'Qui les lecteurs reconnaissaient-ils sous les traits de Mandane ?', 'mcq', '["Anne d’Autriche","La Grande Mademoiselle","La duchesse de Longueville","Mme de Rambouillet"]'::jsonb, 2, 'Mandane, l’aimée de Cyrus, cachait la duchesse de Longueville, sœur du Grand Condé : le roman à clé était un jeu de salon.', 2),
    ('07327d0c-075b-58ae-bd3b-b8c22ac01f7d'::uuid, 'francais', '1re', 'Artamène ou le Grand Cyrus, Madeleine et Georges de Scudéry', 'Pendant quel événement politique le roman paraît-il ?', 'mcq', '["Les guerres de Religion, entre catholiques et protestants","La révocation de l’édit de Nantes par Louis XIV","La conjuration de Cinq-Mars contre Richelieu","La Fronde, révolte des grands et du Parlement"]'::jsonb, 3, 'Le roman paraît de 1649 à 1653, pendant et juste après la Fronde : sous Cyrus, les lecteurs voyaient le Grand Condé, héros militaire de ces années.', 3),
    ('3cb6ae31-881f-5b1b-946a-9b166d8ef216'::uuid, 'francais', '1re', 'Artamène ou le Grand Cyrus, Madeleine et Georges de Scudéry', 'Quelle idée défend l’« Histoire de Sapho », dans le dernier volume ?', 'mcq', '["Que l’amour doit céder à l’honneur","Qu’une femme peut être savante","Que les femmes doivent fuir le monde","Que la conversation est un péché"]'::jsonb, 1, 'Madeleine de Scudéry s’y peint sous le nom de Sapho et y défend la place des femmes dans la vie de l’esprit.', 4),
    ('895cdcc4-ad1d-55aa-ba62-c1267aef56d1'::uuid, 'francais', '1re', 'Au Bonheur des Dames, Émile Zola', 'De quel roman précédent des Rougon-Macquart vient Octave Mouret ?', 'mcq', '["L’Assommoir","Pot-Bouille","Nana","La Curée"]'::jsonb, 1, 'Mouret apparaît dans Pot-Bouille (1882) ; dans Au Bonheur des Dames, veuf de Mme Hédouin, il règne sur le grand magasin.', 1),
    ('d367f6bf-d416-56f9-bcc5-367b331fc93f'::uuid, 'francais', '1re', 'Au Bonheur des Dames, Émile Zola', 'Qui finance l’expansion du magasin ?', 'mcq', '["L’oncle Baudu","Henriette Desforges","Le baron Hartmann","Madame Hédouin"]'::jsonb, 2, 'Le banquier Hartmann finance les agrandissements : le grand magasin est aussi une affaire de capitaux, image du capitalisme triomphant.', 2),
    ('6cd50fd2-d897-5e7e-a392-12802f60af99'::uuid, 'francais', '1re', 'Au Bonheur des Dames, Émile Zola', 'Comment s’appelle la boutique de l’oncle Baudu ?', 'mcq', '["Le Bonheur des Dames","Les Dames de Valognes","Le Petit Louvre","Le Vieil Elbeuf"]'::jsonb, 3, 'Au Vieil Elbeuf, le drapier Baudu perd tout : les boutiques anciennes sont écrasées par la machine du grand magasin.', 3),
    ('364666a2-30a7-5379-8dd7-f39d942adcc8'::uuid, 'francais', '1re', 'Au Bonheur des Dames, Émile Zola', 'En quoi ce roman se distingue-t-il des autres Rougon-Macquart, selon le cours ?', 'mcq', '["Il est plus optimiste : la destruction y produit du neuf","Il se passe entièrement à la campagne","Aucun personnage de la famille n’y paraît","Il est écrit à la première personne"]'::jsonb, 0, 'Roman de la modernité conquérante, il montre le progrès comme une loi impitoyable mais féconde : les petites boutiques meurent, un monde neuf naît.', 4),
    ('d652ce09-6c40-55d0-a89c-ecba0f106490'::uuid, 'francais', '1re', 'Aux Champs, Guy de Maupassant', 'Quel enfant Mme d’Hubières voulait-elle d’abord adopter ?', 'mcq', '["Jean Vallin","Charlot Tuvache","Le fils aîné des Vallin","Une petite fille Tuvache"]'::jsonb, 1, 'Elle choisit d’abord Charlot, mais les Tuvache refusent avec indignation ; c’est Jean Vallin qui partira.', 1),
    ('438b3525-b192-527f-bf04-5d9dce9391c1'::uuid, 'francais', '1re', 'Aux Champs, Guy de Maupassant', 'Quelle rente est promise aux Vallin ?', 'mcq', '["Cinquante francs par mois","Mille francs une fois pour toutes","Cent francs par mois, portés à cent vingt","Une ferme et deux vaches"]'::jsonb, 2, 'La rente est de cent francs par mois, portée à cent vingt : c’est un marché, et l’argent est au cœur de la nouvelle.', 2),
    ('a36850b8-3814-53c1-8af0-c4fef9d7afb1'::uuid, 'francais', '1re', 'Aux Champs, Guy de Maupassant', 'Dans quel journal la nouvelle paraît-elle d’abord, en 1882 ?', 'mcq', '["Le Gaulois","Le Figaro","Gil Blas","Le Temps"]'::jsonb, 0, 'Comme beaucoup de nouvelles de Maupassant, Aux Champs paraît d’abord dans la presse, puis dans le recueil Contes de la bécasse.', 3),
    ('ce5f127b-1e6a-5a02-9304-90ada12c9b8f'::uuid, 'francais', '1re', 'Aux Champs, Guy de Maupassant', 'Quel trait des dialogues le cours présente-t-il comme une marque du réalisme ?', 'mcq', '["Les alexandrins rimés","Les citations latines","Les maximes morales","Le patois des paysans"]'::jsonb, 3, 'Le patois fait entendre la voix des paysans normands : Maupassant montre sans juger, jusque dans la langue de ses personnages.', 4),
    ('fb2e0af0-b387-521c-b5a9-11bde9525773'::uuid, 'francais', '1re', 'Bajazet, Jean Racine', 'Comment Racine justifie-t-il le choix d’un sujet contemporain ?', 'mcq', '["Le roi lui a commandé un sujet tiré de l’actualité","L’éloignement des pays remplace l’éloignement dans le temps","Les faits, restés secrets, étaient inconnus du public","Un auteur grec avait déjà traité une histoire semblable"]'::jsonb, 1, 'Les faits datent de 1635 : pour Racine, la distance de Constantinople donne au sujet le recul que donnent d’ordinaire les siècles.', 1),
    ('e27b4828-6be3-5a55-a175-3005b23f54af'::uuid, 'francais', '1re', 'Bajazet, Jean Racine', 'Que devient le vizir Acomat à la fin de la pièce ?', 'mcq', '["Il est exécuté par Orcan","Il remplace le sultan","Il épouse Atalide","Il prend la fuite"]'::jsonb, 3, 'Acomat, qui manœuvrait pour ses propres intérêts, s’enfuit : dans ce palais, le calcul survit mieux que l’amour.', 2),
    ('596af433-b0cd-559a-9e32-14b4a6f5cc5f'::uuid, 'francais', '1re', 'Bajazet, Jean Racine', 'Quel mot Roxane adresse-t-elle à Bajazet au cinquième acte, qui l’envoie à la mort ?', 'mcq', '["« Mourez. »","« Fuyez. »","« Sortez. »","« Adieu. »"]'::jsonb, 2, 'Bajazet sort, et c’est la mort qui l’attend : le mot le plus court de la pièce en est le plus tragique.', 3),
    ('63c573ba-1e72-5ae9-bbca-994a157893f3'::uuid, 'francais', '1re', 'Bajazet, Jean Racine', 'Comment finit Atalide ?', 'mcq', '["Elle se donne la mort","Elle épouse Bajazet","Elle est exilée à Babylone","Elle devient la favorite"]'::jsonb, 0, 'Bajazet exécuté, Roxane tuée sur ordre d’Amurat, Atalide se tue : chacun meurt d’avoir mal joué son rôle.', 4),
    ('73108c42-d9cc-5533-8239-994df86888fc'::uuid, 'francais', '1re', 'Bel-Ami, Guy de Maupassant', 'Dans quel journal Bel-Ami paraît-il d’abord en feuilleton ?', 'mcq', '["La Vie française","Gil Blas","Le Gaulois","Le Figaro"]'::jsonb, 1, 'Le roman paraît dans Gil Blas en 1885 ; La Vie française est le journal fictif de M. Walter, où Duroy fait carrière.', 1),
    ('1a5c4cf2-eeb8-5507-b42b-7f2b7ddfb8e0'::uuid, 'francais', '1re', 'Bel-Ami, Guy de Maupassant', 'Quel nom Georges Duroy se fabrique-t-il ?', 'mcq', '["« Georges de Varenne »","« Duroy de Walter »","« Du Roy de Cantel »","« Georges de Marelle »"]'::jsonb, 2, 'La particule inventée signe l’ascension : devenu « Du Roy de Cantel », il sort de la Madeleine en triomphe.', 2),
    ('071cfd46-2518-55c0-af7a-52a77f67f675'::uuid, 'francais', '1re', 'Bel-Ami, Guy de Maupassant', 'Quelle affaire de spéculation coloniale le roman met-il en scène ?', 'mcq', '["L’affaire du canal de Panama","L’affaire du canal de Suez","L’affaire du Tonkin","L’affaire du Maroc"]'::jsonb, 3, 'Avec l’affaire du Maroc, presse, politique et argent se confondent : le journal sert la spéculation de ceux qui le possèdent.', 3),
    ('e6510406-ec00-5df9-9d5f-ccdfe7b1f7fc'::uuid, 'francais', '1re', 'Bel-Ami, Guy de Maupassant', 'De quoi le vieux poète Norbert de Varenne parle-t-il à Duroy, une nuit à Paris ?', 'mcq', '["De la mort","De l’amour","De l’argent","De la politique"]'::jsonb, 0, 'Norbert de Varenne lui parle de la mort : c’est la peur que Duroy fuit dans l’action, l’ambition et la séduction.', 4),
    ('16ff3b57-1150-54f4-8cf7-3170c1782c75'::uuid, 'francais', '1re', 'Belle du Seigneur, Albert Cohen', 'Où Albert Cohen est-il né ?', 'mcq', '["À Genève","À Marseille","À Corfou","À Céphalonie"]'::jsonb, 2, 'Né à Corfou dans une famille juive, il grandit à Marseille puis vit à Genève, la ville de la Société des Nations du roman.', 1),
    ('0a00794d-c0f2-5356-9a56-f4d907641517'::uuid, 'francais', '1re', 'Belle du Seigneur, Albert Cohen', 'Comment Solal éloigne-t-il Adrien Deume ?', 'mcq', '["Il le fait promouvoir","Il le fait renvoyer","Il le provoque en duel","Il le fait arrêter"]'::jsonb, 0, 'Solal fait promouvoir le mari pour l’éloigner : la satire de la bureaucratie internationale sert l’intrigue amoureuse.', 2),
    ('d04c8676-d265-5187-8443-c45106ce5597'::uuid, 'francais', '1re', 'Belle du Seigneur, Albert Cohen', 'Quel prix le roman reçoit-il en 1968 ?', 'mcq', '["Le prix Goncourt","Le prix du roman de l’Académie française","Le prix Femina","Le prix Renaudot"]'::jsonb, 1, 'Belle du Seigneur reçoit en 1968 le prix du roman de l’Académie française ; c’est le troisième volet d’un cycle ouvert par Solal (1930).', 3),
    ('683f5df1-70de-5cea-9f8b-99891b9a0184'::uuid, 'francais', '1re', 'Belle du Seigneur, Albert Cohen', 'Selon le cours, que montre Cohen que la plupart des romans d’amour ne montrent pas ?', 'mcq', '["La première rencontre des amants","Le mariage heureux des amants","La vengeance du mari trompé","Ce qui vient après la conquête"]'::jsonb, 3, 'Coupée du monde, la passion meurt d’elle-même — rituels, mensonges, ennui : là où les romans s’arrêtent, Cohen continue.', 4),
    ('2b4ac875-a19b-53fb-b1b7-142c6857737d'::uuid, 'francais', '1re', 'Bérénice, Jean Racine', 'Quel rôle joue Paulin auprès de Titus ?', 'mcq', '["Il l’encourage à épouser Bérénice","Il lui rappelle ce que Rome exige","Il aime Bérénice en secret","Il porte ses lettres à Antiochus"]'::jsonb, 1, 'Paulin, confident de Titus, est la voix de Rome : il rappelle à l’empereur que Rome n’accepte pas de reine étrangère.', 1),
    ('dfc8d98f-4ad4-5899-9e1f-dd21ad82df18'::uuid, 'francais', '1re', 'Bérénice, Jean Racine', 'Par quel mot la pièce se clôt-elle ?', 'mcq', '["« Adieu ! »","« Régnez ! »","« Hélas ! »","« Sortez. »"]'::jsonb, 2, 'Antiochus ferme la pièce sur un seul soupir, « Hélas ! » : les trois personnages restent vivants et séparés.', 2),
    ('adce8486-a893-59f1-8ea3-ba7178f48d62'::uuid, 'francais', '1re', 'Bérénice, Jean Racine', 'Que signifie la formule de Suétone invitus invitam dimisit ?', 'mcq', '["Il la renvoya malgré lui, malgré elle","Il l’épousa malgré le Sénat","Elle le quitta sans un mot","Il la chassa sans regret"]'::jsonb, 0, 'Trois mots latins résument toute la pièce : Titus renvoie Bérénice contre son propre désir et contre celui de la reine.', 3),
    ('da38305c-45d1-5d50-a6fc-d600cbdec26e'::uuid, 'francais', '1re', 'Bérénice, Jean Racine', 'Quel thème le vers « Dans un mois, dans un an, comment souffrirons-nous… » illustre-t-il ?', 'mcq', '["La jalousie","La vengeance","La guerre","Le temps"]'::jsonb, 3, 'Bérénice pense la séparation comme une durée infinie : le tragique ne tient pas à la mort mais à l’avenir sans l’autre.', 4),
    ('da3741d3-24a4-5829-a179-9662c050507d'::uuid, 'francais', '1re', 'Bonjour tristesse, Françoise Sagan', 'Quel prix le roman reçoit-il en 1954 ?', 'mcq', '["Le prix Goncourt","Le prix des Critiques","Le prix Femina","Le prix Interallié"]'::jsonb, 1, 'Publié chez Julliard en 1954, le roman reçoit le prix des Critiques et fait scandale par sa liberté de mœurs et son absence de remords.', 1),
    ('8858c9d3-2bf9-55b4-8989-dd85374091d6'::uuid, 'francais', '1re', 'Bonjour tristesse, Françoise Sagan', 'Que dit le roman de la mort d’Anne ?', 'mcq', '["C’est un crime maquillé en accident","C’est un suicide, annoncé dans une lettre","Il ne tranche pas entre accident et suicide","C’est une panne de freins, prouvée"]'::jsonb, 2, 'Anne part en voiture et se tue : accident ou suicide, le roman laisse la question ouverte, et Cécile découvre une culpabilité qui naît trop tard.', 2),
    ('b77ed376-d01e-5e61-a299-497e6a35e076'::uuid, 'francais', '1re', 'Bonjour tristesse, Françoise Sagan', 'Qui adapte le roman au cinéma en 1958 ?', 'mcq', '["Otto Preminger","François Truffaut","Jean-Luc Godard","Roger Vadim"]'::jsonb, 0, 'Otto Preminger en tire un film en 1958, quatre ans seulement après la parution : le succès du livre est aussitôt mondial.', 3),
    ('69966909-a252-5346-9a2a-ec8cec7a69d7'::uuid, 'francais', '1re', 'Bonjour tristesse, Françoise Sagan', 'Quelle est la forme du récit ?', 'mcq', '["Un journal intime tenu au jour le jour","Un roman par lettres","Un récit à la troisième personne","Un récit rétrospectif à la première personne"]'::jsonb, 3, 'Cécile raconte après coup : ce regard rétrospectif, dans un style limpide et rapide, fait naître la tristesse du titre.', 4),
    ('7417a66a-5f09-56c9-8d4f-a8060f38ec23'::uuid, 'francais', '1re', 'Boubouroche, Georges Courteline', 'Quel est le vrai nom de Georges Courteline ?', 'mcq', '["Georges Courtois","Georges Labiche","Georges Moinaux","Georges Antoine"]'::jsonb, 2, 'Courteline est un pseudonyme : Georges Moinaux est le fils d’un chroniqueur judiciaire humoriste.', 1),
    ('131e7991-ae27-5d05-8954-45b3d0b789cb'::uuid, 'francais', '1re', 'Boubouroche, Georges Courteline', 'Où Boubouroche est-il créé, le 27 avril 1893 ?', 'mcq', '["Au Théâtre-Libre d’André Antoine","À la Comédie-Française","Au théâtre de l’Odéon","Au théâtre de la Porte-Saint-Martin"]'::jsonb, 0, 'Fondé par André Antoine, le Théâtre-Libre est le théâtre du naturalisme : Courteline y fait jouer sa comédie de mœurs.', 2),
    ('47071df0-a326-5b7f-98fc-9865b2632ec1'::uuid, 'francais', '1re', 'Boubouroche, Georges Courteline', 'Sous quelle forme Boubouroche paraît-il d’abord, en 1892 ?', 'mcq', '["Un roman-feuilleton","Une chanson de café-concert","Un monologue comique","Une nouvelle"]'::jsonb, 3, 'Courteline fait d’abord de Boubouroche le héros d’une nouvelle, avant d’en tirer une comédie en deux actes.', 3),
    ('22083695-0cb9-5251-8b93-965f90397463'::uuid, 'francais', '1re', 'Boubouroche, Georges Courteline', 'Quelle explication Adèle propose-t-elle, que Boubouroche refuse d’entendre ?', 'mcq', '["Avouer qu’André est un parent éloigné","Révéler « un secret qui n’est pas le mien »","Montrer une lettre qui l’innocente","Faire témoigner le vieux voisin"]'::jsonb, 1, 'Boubouroche refuse ce « secret » et demande pardon : il choisit de ne pas savoir, parce que la vérité lui coûterait trop cher.', 4),
    ('6df4338e-0b7d-5571-9d66-036b6d13c1ae'::uuid, 'francais', '1re', 'Boule de suif, Guy de Maupassant', 'Où l’officier prussien retient-il la diligence ?', 'mcq', '["À Dieppe","À Tôtes","Au Havre","À Rouen"]'::jsonb, 1, 'Partie de Rouen occupée pour Le Havre, la diligence est arrêtée à Tôtes : c’est là que l’officier pose son exigence.', 1),
    ('5e69a155-9f5e-5424-b36c-961d2ef810ca'::uuid, 'francais', '1re', 'Boule de suif, Guy de Maupassant', 'Quelle classe sociale représentent M. et Mme Carré-Lamadon ?', 'mcq', '["La vieille noblesse","Le petit commerce de vin","La grande bourgeoisie industrielle","Le clergé de Rouen"]'::jsonb, 2, 'La diligence est une société en miniature : les Loiseau sont marchands de vin, les Bréville incarnent la vieille noblesse.', 2),
    ('b8124500-2880-582a-a70f-3e809e36b4cf'::uuid, 'francais', '1re', 'Boule de suif, Guy de Maupassant', 'Quel rôle jouent les deux religieuses quand les voyageurs pressent Boule de suif ?', 'mcq', '["Elles la défendent contre les autres","Elles se taisent sans prendre parti","Elles avertissent l’officier de son refus","Elles justifient le sacrifice par la religion"]'::jsonb, 3, 'Les arguments religieux font partie des « bons arguments » qui endorment Boule de suif : la satire vise aussi l’Église.', 3),
    ('08d97fd2-82a7-546f-b98a-833f50f4d00c'::uuid, 'francais', '1re', 'Boule de suif, Guy de Maupassant', 'Au premier repas, comment les bourgeois accueillent-ils le panier de Boule de suif ?', 'mcq', '["Affamés, ils l’acceptent avec reconnaissance","Ils le refusent par mépris pour elle","Ils le confisquent pour l’officier","Seules les religieuses osent y toucher"]'::jsonb, 0, 'Ce repas partagé répond au dernier, où personne ne lui offre rien : la symétrie des deux repas porte toute la critique.', 4),
    ('19e16a23-0fbd-57fc-b30b-f22cb013365d'::uuid, 'francais', '1re', 'Britannicus, Jean Racine', 'Où Junie se réfugie-t-elle au dénouement ?', 'mcq', '["Chez Agrippine, au palais","Chez les Vestales","Chez Burrhus, hors de Rome","Chez Narcisse, qui la protège"]'::jsonb, 1, 'Junie échappe à Néron en entrant chez les Vestales, tandis qu’Agrippine prophétise la fin de son fils.', 1),
    ('e91e68c5-4abf-5fb2-927c-96b2a76bc322'::uuid, 'francais', '1re', 'Britannicus, Jean Racine', 'Comment la pièce s’ouvre-t-elle ?', 'mcq', '["Néron annonce qu’il épousera Junie","Britannicus confie à Narcisse ses projets","Burrhus et Narcisse se disputent l’empereur","Agrippine attend à l’aube devant la porte de son fils"]'::jsonb, 3, 'Néron ne reçoit plus sa mère : dès la première scène, on voit le pouvoir se libérer de ses tuteurs.', 2),
    ('8e8c4ee3-1746-5aea-ab18-3130c11789a8'::uuid, 'francais', '1re', 'Britannicus, Jean Racine', 'Qui dit « J’aimais jusqu’à ses pleurs que je faisais couler » ?', 'mcq', '["Néron, qui a vu Junie enlevée en larmes","Britannicus, qui a vu Junie captive","Narcisse, qui raconte l’enlèvement","Agrippine, qui se souvient de son fils"]'::jsonb, 0, 'Cet aveu mêle désir et cruauté : chez Néron, l’amour se réduit à la possession.', 3),
    ('7781c7a0-3f10-577a-b473-62f069dbc388'::uuid, 'francais', '1re', 'Britannicus, Jean Racine', 'Avec quel dramaturge Racine rivalise-t-il en choisissant un sujet romain et politique ?', 'mcq', '["Molière","Sénèque","Corneille","Quinault"]'::jsonb, 2, 'La tragédie politique était le terrain de Corneille ; Racine s’y mesure en s’appuyant sur Tacite.', 4),
    ('57d625c6-8da7-5a28-ab83-2314deb943f0'::uuid, 'francais', '1re', 'Caligula, Albert Camus', 'Quelle phrase résume ce que Caligula a compris en revenant ?', 'mcq', '["« Les hommes meurent et ne sont pas heureux »","« Il faut imaginer Sisyphe heureux »","« L’enfer, c’est les autres »","« Tout est au mieux dans le meilleur des mondes »"]'::jsonb, 0, 'De ce constat, Caligula tire une logique implacable : si rien n’a de sens, il exercera une liberté totale.', 1),
    ('0ed53a29-1314-5109-b617-dd4739b241f3'::uuid, 'francais', '1re', 'Caligula, Albert Camus', 'Quel est le dernier cri de Caligula, sous les coups des conjurés ?', 'mcq', '["« Ma liberté n’est pas la bonne »","« Qu’on m’apporte la lune ! »","« Je suis encore vivant ! »","« Rome ne me survivra pas ! »"]'::jsonb, 2, 'Avant de mourir, il a pourtant reconnu que sa liberté « n’est pas la bonne » : la pièce ne lui donne pas raison.', 2),
    ('96a749d1-1d18-5653-af26-8ca1be35bd70'::uuid, 'francais', '1re', 'Caligula, Albert Camus', 'Quel personnage comprend Caligula sans le suivre ?', 'mcq', '["Cherea, le chef du complot","Hélicon, l’affranchi fidèle","Cæsonia, sa maîtresse","Scipion, le jeune poète"]'::jsonb, 3, 'Scipion comprend la révolte de Caligula mais refuse sa voie ; Hélicon, lui, reste fidèle jusqu’au bout.', 3),
    ('55623e26-968f-576f-ab61-337f078026ec'::uuid, 'francais', '1re', 'Caligula, Albert Camus', 'Dans quel essai Camus développera-t-il l’idée que la révolte qui nie l’autre mène au meurtre ?', 'mcq', '["Le Mythe de Sisyphe","L’Homme révolté","L’Étranger","La Chute"]'::jsonb, 1, 'Le Mythe de Sisyphe appartient, avec L’Étranger et Caligula, au cycle de l’absurde ; L’Homme révolté pense les limites de la révolte.', 4),
    ('73e2ef4b-3eb2-5a67-9a02-3a5db51636e5'::uuid, 'francais', '1re', 'Candide ou l’Optimisme, Voltaire', 'Pourquoi Candide est-il chassé du château de Thunder-ten-tronckh ?', 'mcq', '["Pour avoir volé le baron","Pour avoir embrassé Cunégonde","Pour avoir contredit Pangloss","Pour avoir fui les Bulgares"]'::jsonb, 1, 'Ce baiser le jette hors du château : commence un voyage à travers la guerre, les catastrophes et l’horreur du monde.', 1),
    ('89ae4b1e-ea4f-58cf-96fe-6a9df93e4be8'::uuid, 'francais', '1re', 'Candide ou l’Optimisme, Voltaire', 'Quelle philosophie l’optimisme de Pangloss caricature-t-il ?', 'mcq', '["Celle de Descartes","Celle de Pascal","Celle de Rousseau","Celle de Leibniz"]'::jsonb, 3, 'Voltaire vise l’optimisme leibnizien, pour qui notre monde est le meilleur possible malgré le mal qu’on y voit.', 2),
    ('4cbb5ca0-1dba-5dc5-b85a-1c593724e4f8'::uuid, 'francais', '1re', 'Candide ou l’Optimisme, Voltaire', 'Que dénonce l’épisode de l’autodafé ?', 'mcq', '["Le fanatisme","L’esclavage","Le mal naturel","La guerre"]'::jsonb, 0, 'Chaque épreuve a sa cible : le tremblement de terre montre le mal naturel, l’autodafé de l’Inquisition le fanatisme.', 3),
    ('ad51917f-5f23-5cb9-ab2e-b75b7528fce1'::uuid, 'francais', '1re', 'Candide ou l’Optimisme, Voltaire', 'Que fait Candide quand il retrouve Cunégonde devenue laide ?', 'mcq', '["Il la laisse à son frère le baron","Il repart seul vers l’Eldorado","Il l’épouse quand même","Il la confie à la Vieille"]'::jsonb, 2, 'Le conte refuse la fin romanesque : après ce mariage sans illusion, tous s’installent dans une métairie près de Constantinople.', 4),
    ('b70fac54-c9c2-598b-8102-66a6ae56bd4e'::uuid, 'francais', '1re', 'Capitale de la douleur, Paul Éluard', 'Quel est le vrai nom de Paul Éluard ?', 'mcq', '["Paul Grandin","Emmanuel Delorme","Eugène Grindel","Eugène Delaunay"]'::jsonb, 2, 'Eugène Grindel rencontre Gala en 1912 dans un sanatorium suisse ; il écrira sous le nom d’Éluard.', 1),
    ('b9f6e456-f74c-5bd1-9054-71861e04b3f0'::uuid, 'francais', '1re', 'Capitale de la douleur, Paul Éluard', 'Que dit le titre, Capitale de la douleur, trouvé en dernier ?', 'mcq', '["La souffrance amoureuse du poète","La douleur des soldats de 1914","Le deuil de la ville de Paris","La maladie soignée au sanatorium"]'::jsonb, 0, 'Gala partage alors sa vie entre Éluard et le peintre Max Ernst ; elle le quittera pour Dalí en 1929.', 2),
    ('70a14e41-0cb5-5b95-82ed-8fe296e81cd7'::uuid, 'francais', '1re', 'Capitale de la douleur, Paul Éluard', 'Par quel vers s’ouvre le poème « L’amoureuse » ?', 'mcq', '["« Sous le pont Mirabeau coule la Seine »","« Je suis le ténébreux, le veuf, l’inconsolé »","« Mon beau navire ô ma mémoire »","« Elle est debout sur mes paupières »"]'::jsonb, 3, 'L’image est simple et inouïe : la femme aimée habite le regard du poète, lieu où le monde devient visible.', 3),
    ('f496d36a-7294-5344-9304-0278576239b4'::uuid, 'francais', '1re', 'Capitale de la douleur, Paul Éluard', 'D’où naissent les sections les plus expérimentales du recueil ?', 'mcq', '["De traductions de poètes anglais","De l’écriture automatique et des peintres","De l’imitation des sonnets anciens","Des chansons entendues en voyage"]'::jsonb, 1, 'Ernst, Chirico, Picasso : poètes et peintres surréalistes inventent ensemble, et un poème du recueil s’intitule « Max Ernst ».', 4),
    ('1a9ff0db-1445-5272-b727-7fe147e3eb4d'::uuid, 'francais', '1re', 'Carmen, Prosper Mérimée', 'Qui est García le Borgne ?', 'mcq', '["Le lieutenant tué par José","Le picador aimé de Carmen","Le mari de Carmen, chef de contrebandiers","Le guide du narrateur savant"]'::jsonb, 2, 'José le tue : après la désertion et la mort de l’officier, ce meurtre lui ferme toute issue.', 1),
    ('9af1114e-6db5-530f-bde3-a347d59176c3'::uuid, 'francais', '1re', 'Carmen, Prosper Mérimée', 'D’où vient don José ?', 'mcq', '["De Navarre : c’est un Basque","D’Andalousie : c’est un Rom","De Castille : c’est un noble","De Catalogne : c’est un marin"]'::jsonb, 0, 'Don José Lizarrabengoa, Basque de Navarre, est d’abord un soldat honnête qui se perd par amour.', 2),
    ('ac6da09d-4e2e-5c91-b9d4-cc9b33e17917'::uuid, 'francais', '1re', 'Carmen, Prosper Mérimée', 'Qu’ajoute Mérimée en 1847 à la nouvelle parue en 1845 ?', 'mcq', '["Une préface sur ses voyages","Un dernier chapitre, une étude sur les Roms","Le récit de l’exécution de José","Une lettre de Carmen à José"]'::jsonb, 1, 'Ce chapitre savant prolonge la voix du narrateur : Mérimée mêle exotisme, dissertation savante et sécheresse du récit.', 3),
    ('96d49f21-9d55-528b-8b31-2c8ee6517232'::uuid, 'francais', '1re', 'Carmen, Prosper Mérimée', 'Quel effet produit le dispositif des récits enchâssés ?', 'mcq', '["Carmen raconte elle-même son histoire","Le récit suit un ordre chronologique strict","Le lecteur connaît d’emblée ses pensées","On n’entend Carmen qu’à travers deux voix d’hommes"]'::jsonb, 3, 'Le savant rapporte le récit de José, qui rapporte Carmen : cette distance entretient le mystère du personnage.', 4),
    ('b3159e2c-e111-5aa9-a615-025cc378128f'::uuid, 'francais', '1re', 'Cinna, Corneille', 'Pourquoi Cinna conseille-t-il à Auguste de garder l’Empire ?', 'mcq', '["Pour garder le tyran qu’il veut tuer","Parce qu’il croit à la monarchie","Pour plaire à Livie, l’impératrice","Pour devenir lui-même son héritier"]'::jsonb, 0, 'Si Auguste abdiquait, il n’y aurait plus de tyran à abattre, et Émilie ne serait pas vengée.', 1),
    ('a14d1b5e-71c5-592b-b687-37fd8f835c08'::uuid, 'francais', '1re', 'Cinna, Corneille', 'Quel lien unit Émilie à Auguste ?', 'mcq', '["Elle est sa nièce","Elle est sa fille adoptive","Elle est son épouse","Elle est sa sœur"]'::jsonb, 1, 'Émilie conspire donc contre celui qui l’a élevée, pour venger son père tué lors des proscriptions.', 2),
    ('8d829ffa-2afe-5a29-b4d7-ba4cbe344c00'::uuid, 'francais', '1re', 'Cinna, Corneille', 'Quel sentiment pousse Maxime à trahir le complot ?', 'mcq', '["Il craint la colère du Sénat","Il veut prendre la place d’Auguste","Il aime lui aussi Émilie","Il est payé par l’impératrice"]'::jsonb, 2, 'Rival de Cinna, Maxime laisse son affranchi Euphorbe dénoncer le complot à Auguste.', 3),
    ('0b144902-127c-5b6f-b195-693f52785307'::uuid, 'francais', '1re', 'Cinna, Corneille', 'Qu’est-ce qui distingue le héros cornélien des héros de Racine ?', 'mcq', '["Il meurt toujours au dénouement","Il est la victime de ses passions","Il ignore tout sentiment amoureux","Il surmonte sa passion par un choix"]'::jsonb, 3, 'Auguste l’illustre : après une longue délibération intérieure, il choisit la clémence ; les héros de Racine subissent leur passion.', 4),
    ('e7f3d0f9-6c52-58d4-8488-3cae2134a7c7'::uuid, 'francais', '1re', 'Cinq Semaines en ballon, Jules Verne', 'D’où le Victoria décolle-t-il ?', 'mcq', '["De Tombouctou","De Zanzibar","Du Caire","De Saint-Louis du Sénégal"]'::jsonb, 1, 'Parti de Zanzibar, à l’est, le ballon traverse le continent jusqu’au Sénégal, à l’ouest.', 1),
    ('aea3f8e4-2ecb-5603-a5b4-f17b0b0e103a'::uuid, 'francais', '1re', 'Cinq Semaines en ballon, Jules Verne', 'Où et quand s’ouvre le roman ?', 'mcq', '["À Londres, le 14 janvier 1862","À Paris, chez Hetzel, en 1863","À Nantes, le jour du départ","À Zanzibar, la veille de l’envol"]'::jsonb, 0, 'Devant la Société royale de géographie de Londres, Fergusson annonce son projet : le roman s’ouvre sur une séance savante.', 2),
    ('2e9c78e9-9223-5030-9f7f-a4387eecad8d'::uuid, 'francais', '1re', 'Cinq Semaines en ballon, Jules Verne', 'Quelle quête d’explorateurs sert de toile de fond au roman ?', 'mcq', '["La conquête du pôle Sud","La traversée de l’Australie","La recherche des sources du Nil","Le passage du Nord-Ouest"]'::jsonb, 2, 'Burton, Speke et d’autres cherchent alors les sources du Nil ; le Victoria les découvre au cours de son voyage.', 3),
    ('7b760f4d-1892-5671-a212-9ab86d20dd73'::uuid, 'francais', '1re', 'Cinq Semaines en ballon, Jules Verne', 'Quel épisode du voyage apporte l’émotion ?', 'mcq', '["La mort de Kennedy, tué par un fauve","L’abandon de Joe, laissé à Zanzibar","La destruction du ballon par la foudre","Le sauvetage d’un missionnaire, mort peu après"]'::jsonb, 3, 'Les voyageurs sauvent un missionnaire français qui meurt peu après : le roman d’aventures fait aussi place à l’émotion.', 4),
    ('424192fa-3deb-5dcd-a2a3-d7e94c7dd82e'::uuid, 'francais', '1re', 'Clélie, histoire romaine, Madeleine de Scudéry', 'D’où part le voyage sur la carte de Tendre ?', 'mcq', '["De Nouvelle-Amitié","De Tendre-sur-Estime","Du lac d’Indifférence","De Billet-Doux"]'::jsonb, 0, 'De Nouvelle-Amitié, trois chemins mènent aux trois villes de Tendre : le sentiment se construit à partir de l’amitié.', 1),
    ('96320338-68fa-5b04-94a9-ede131f5194f'::uuid, 'francais', '1re', 'Clélie, histoire romaine, Madeleine de Scudéry', 'Quelle voie mène le plus directement à l’une des villes de Tendre ?', 'mcq', '["Les villages de Petits-Soins et d’Assiduité","Les villages de Grand-Esprit et de Jolis-Vers","Le fleuve, jusqu’à Tendre-sur-Inclination","La traversée de la mer d’Inimitié"]'::jsonb, 2, 'L’inclination mène droit au but ; l’estime et la reconnaissance se gagnent village après village.', 2),
    ('5f1f46fd-9253-5e77-a773-ec3e7a7ba099'::uuid, 'francais', '1re', 'Clélie, histoire romaine, Madeleine de Scudéry', 'Par quels villages passe-t-on pour atteindre Tendre-sur-Reconnaissance ?', 'mcq', '["Grand-Esprit, Jolis-Vers, Billet-Doux","Complaisance, Petits-Soins, Assiduité","Négligence, Tiédeur, Oubli","Sincérité, Inimitié, Indifférence"]'::jsonb, 1, 'La reconnaissance se gagne par les égards et les services ; Grand-Esprit, Jolis-Vers et Billet-Doux mènent à Tendre-sur-Estime.', 3),
    ('5ee8240e-ab44-51cf-8d43-82afc64556b2'::uuid, 'francais', '1re', 'Clélie, histoire romaine, Madeleine de Scudéry', 'De quoi la carte de Tendre est-elle née ?', 'mcq', '["D’une commande de Louis XIV","D’un traité de géographie savante","D’un relevé des environs de Rome","D’un jeu de la société des salons"]'::jsonb, 3, 'Cette cartographie du sentiment vient de la société précieuse qui se réunit aux « samedis » de Madeleine de Scudéry.', 4),
    ('9877e266-8a81-5912-b8e3-514fdc67abce'::uuid, 'francais', '1re', 'Colomba, Prosper Mérimée', 'Qu’est-ce qu’un vocero, comme ceux qu’improvise Colomba ?', 'mcq', '["Une danse guerrière corse","Un chant funèbre improvisé","Un serment de vengeance écrit","Une berceuse de village"]'::jsonb, 1, 'Par ses voceri, ses rumeurs et ses preuves montées, Colomba pousse son frère vers la vendetta.', 1),
    ('2c94124f-8565-5f19-9297-a660cbabd125'::uuid, 'francais', '1re', 'Colomba, Prosper Mérimée', 'Qui sont Brandolaccio et Castriconi, dit le Curé ?', 'mcq', '["Deux bandits d’honneur qui aident Orso","Les deux fils de l’avocat Barricini","Deux gendarmes chargés de l’enquête","Deux officiers amis du colonel Nevil"]'::jsonb, 0, 'Les fils de l’avocat Barricini, tués par Orso, s’appellent Orlanduccio et Vincentello.', 2),
    ('9c1b1148-6f89-5145-9237-c5bc7df4d0e0'::uuid, 'francais', '1re', 'Colomba, Prosper Mérimée', 'Qu’appelle-t-on le « coup double » d’Orso ?', 'mcq', '["Il épouse Lydia et marie sa sœur","Il trahit à la fois le préfet et Colomba","Il gagne deux procès contre Barricini","Deux coups de fusil qui font deux morts"]'::jsonb, 3, 'Attaqué, Orso tue les deux fils Barricini en légitime défense, le bras gauche blessé ; il se cache dans le maquis avant d’être innocenté.', 3),
    ('0b7dc0f6-1ac3-5336-8060-26c81be984e0'::uuid, 'francais', '1re', 'Colomba, Prosper Mérimée', 'Dans quelle nouvelle antérieure Mérimée avait-il déjà pris la Corse pour cadre ?', 'mcq', '["Carmen","La Vénus d’Ille","Mateo Falcone","Tamango"]'::jsonb, 2, 'Mateo Falcone (1829) est une nouvelle très brève ; Colomba, rapportée du voyage de 1839, paraît en 1840.', 4),
    ('1774dd2a-4f93-5728-b4ee-6fe330ee13cf'::uuid, 'francais', '1re', 'Contes de ma mère l’Oye, Charles Perrault', 'Sous quel nom le recueil paraît-il en 1697 ?', 'mcq', '["Sous le nom de Colbert, son protecteur","Sous le pseudonyme de « ma mère l’Oye »","Sous le nom du fils de Perrault","Sous le nom de l’Académie française"]'::jsonb, 2, 'Le vrai titre est Histoires ou contes du temps passé, avec des moralités ; « Contes de ma mère l’Oye » figure sur le frontispice.', 1),
    ('523a5960-56d9-54bf-ac4d-4fc970e25243'::uuid, 'francais', '1re', 'Contes de ma mère l’Oye, Charles Perrault', 'Quel thème relie Le Petit Poucet et Le Chat botté ?', 'mcq', '["La curiosité punie","La ruse du faible","La bonté récompensée","La beauté et l’esprit"]'::jsonb, 1, 'Le plus petit des frères et un simple chat l’emportent par la ruse ; La Barbe bleue, elle, punit la curiosité.', 2),
    ('80093c97-20ba-527c-957c-da052c92ca26'::uuid, 'francais', '1re', 'Contes de ma mère l’Oye, Charles Perrault', 'Qui visent les « loups » de la moralité du Petit Chaperon rouge ?', 'mcq', '["Les bêtes des forêts du royaume","Les brigands des grands chemins","Les ennemis du roi en guerre","Les séducteurs doucereux des salons"]'::jsonb, 3, 'La moralité met en garde les jeunes filles contre les « loups doucereux » : elle vise la cour, pas la forêt.', 3),
    ('3d3edbf7-d787-527a-bcee-811a87ea6bd8'::uuid, 'francais', '1re', 'Contes de ma mère l’Oye, Charles Perrault', 'Pour quel public Perrault écrit-il ces récits jusque-là oraux ?', 'mcq', '["Un public de cour, lettré et raffiné","Les enfants des campagnes","Les savants de l’Université","Le peuple des foires et des veillées"]'::jsonb, 0, 'Perrault fixe des récits populaires dans une langue élégante et brève, et ses moralités en vers sont souvent ironiques.', 4),
    ('a8d9ebc8-43e6-5994-a242-d14e975ccae7'::uuid, 'francais', '1re', 'Correspondance, André Gide et Paul Valéry', 'Quand leur correspondance est-elle publiée ?', 'mcq', '["En 1925, à l’élection de Valéry","En 1947, pour le Nobel de Gide","En 1955, après leur mort","En 1917, avec La Jeune Parque"]'::jsonb, 2, 'Elle paraît en 1955, dix ans après la mort de Valéry (1945) et quatre ans après celle de Gide (1951).', 1),
    ('c56cd5fd-9770-59d6-9a7d-d236805eea38'::uuid, 'francais', '1re', 'Correspondance, André Gide et Paul Valéry', 'Comment le cours oppose-t-il les deux tempéraments ?', 'mcq', '["Gide le sincère, Valéry l’analyste","Gide le sceptique, Valéry l’autobiographe","Gide le mathématicien, Valéry le romancier","Gide le dramaturge, Valéry le critique"]'::jsonb, 0, 'Gide, inquiet et autobiographe, Valéry, intellectuel sceptique : deux tempéraments opposés qui se lisent et se corrigent.', 2),
    ('aad95f11-d056-539e-b5c4-6fcc4f3083b3'::uuid, 'francais', '1re', 'Correspondance, André Gide et Paul Valéry', 'Quelle œuvre de Valéry paraît en 1896 ?', 'mcq', '["Charmes","La Jeune Parque","Les Nourritures terrestres","Monsieur Teste"]'::jsonb, 3, 'Monsieur Teste précède le long silence poétique de Valéry ; Les Nourritures terrestres (1897) sont de Gide.', 3),
    ('43175395-d77d-5c38-828b-2e785fbd60b7'::uuid, 'francais', '1re', 'Correspondance, André Gide et Paul Valéry', 'Quelle distinction Gide reçoit-il en 1947 ?', 'mcq', '["Le prix Goncourt","Le prix Nobel de littérature","Un siège à l’Académie française","Le grand prix du roman"]'::jsonb, 1, 'Valéry, lui, avait été élu à l’Académie française en 1925.', 4),
    ('ea5b071d-73c6-5f63-b5fe-5336cb615993'::uuid, 'francais', '1re', 'Cyrano de Bergerac, Edmond Rostand', 'Qui est Ragueneau ?', 'mcq', '["Le capitaine des cadets de Gascogne","Le pâtissier-poète qui nourrit les poètes","L’acteur chassé de scène à l’acte I","L’ami fidèle et raisonnable de Cyrano"]'::jsonb, 1, 'Autour de Cyrano : Le Bret, l’ami raisonnable, Carbon de Castel-Jaloux, le capitaine, Montfleury, l’acteur qu’il chasse de scène.', 1),
    ('17a283c8-ac17-5f9c-97fa-fc10bb00cb81'::uuid, 'francais', '1re', 'Cyrano de Bergerac, Edmond Rostand', 'Que se passe-t-il pendant la scène du balcon ?', 'mcq', '["Christian avoue la vérité à Roxane","Roxane reconnaît la voix de Cyrano","Cyrano provoque Christian en duel","Cyrano parle dans l’ombre, Christian reçoit le baiser"]'::jsonb, 3, 'La scène résume le pacte : l’esprit de Cyrano, la beauté de Christian ; l’un parle, l’autre est aimé.', 2),
    ('37dc16ce-1f00-5555-8b21-d5cee4041d96'::uuid, 'francais', '1re', 'Cyrano de Bergerac, Edmond Rostand', 'Qu’est-ce qui déclenche la tirade des nez ?', 'mcq', '["Un vicomte qui juge son nez « très grand »","Roxane qui se moque de lui en public","Montfleury qui l’insulte depuis la scène","Un cadet qui dessine sa caricature"]'::jsonb, 0, 'À cette platitude, Cyrano répond en inventant vingt versions bien meilleures : « C’est un roc !… c’est un pic !… c’est un cap ! »', 3),
    ('93f09f2c-a18c-548f-8cef-61f93d63e79e'::uuid, 'francais', '1re', 'Cyrano de Bergerac, Edmond Rostand', 'Que fait Rostand en 1897, à la fin du siècle du naturalisme ?', 'mcq', '["Il invente le théâtre de l’absurde","Il écrit une pièce naturaliste en prose","Il ressuscite le drame romantique en vers","Il imite la tragédie classique à l’antique"]'::jsonb, 2, 'Comédie héroïque en cinq actes et en vers, Cyrano mêle comique, lyrique, héroïque et pathétique.', 4),
    ('e06cabd2-36e9-5de7-aa0a-fe59dbd73593'::uuid, 'francais', '1re', 'De l’esprit des lois, Montesquieu', 'Quel est le ressort de la monarchie selon Montesquieu ?', 'mcq', '["La vertu","La crainte","L’honneur","La foi"]'::jsonb, 2, 'À chaque gouvernement son ressort : la vertu pour la république, l’honneur pour la monarchie, la crainte pour le despotisme.', 1),
    ('aa91825e-dfb2-54d8-841b-3bb5e9412ef3'::uuid, 'francais', '1re', 'De l’esprit des lois, Montesquieu', 'Comment Montesquieu définit-il les lois ?', 'mcq', '["Des rapports nécessaires dérivant de la nature des choses","Des décisions arbitraires prises par le souverain","Des commandements révélés par Dieu aux hommes","L’expression de la volonté du plus fort"]'::jsonb, 0, 'Il ne les tient pas pour des décrets arbitraires : il cherche à les expliquer, en observant et en comparant les peuples.', 2),
    ('cf9c1b95-bd70-54f3-b30d-05d979e5457e'::uuid, 'francais', '1re', 'De l’esprit des lois, Montesquieu', 'Quelle sanction l’Église prend-elle contre l’ouvrage en 1751 ?', 'mcq', '["Elle excommunie Montesquieu","Elle fait brûler le livre à Rome","Elle fait arrêter l’imprimeur","Elle le met à l’Index"]'::jsonb, 3, 'Attaqué dès sa parution, le livre avait été défendu par son auteur dans la Défense de l’Esprit des lois (1750).', 3),
    ('480a3f2b-c672-57b5-9066-7626a33d8c24'::uuid, 'francais', '1re', 'De l’esprit des lois, Montesquieu', 'Quel texte de 1789 reprend l’exigence de séparation des pouvoirs dans son article 16 ?', 'mcq', '["Les cahiers de doléances","La Déclaration des droits de l’homme et du citoyen","Le serment du Jeu de paume","Le décret d’abolition des privilèges"]'::jsonb, 1, 'Selon l’article 16, une société sans garantie des droits ni séparation des pouvoirs « n’a point de Constitution ».', 4),
    ('0bb2ee4a-8d71-5024-9396-81991b5bac57'::uuid, 'francais', '1re', 'De la dignité de l’homme, Jean Pic de la Mirandole', 'Sur combien de thèses Pic voulait-il ouvrir une dispute publique à Rome ?', 'mcq', '["Quatre-vingt-quinze","Neuf cents","Trois cents","Mille deux cents"]'::jsonb, 1, 'Le discours devait ouvrir ce grand débat sur neuf cents thèses ; le pape en interdit la tenue.', 1),
    ('57b888fb-60ed-5232-8afa-ec610edcd8e3'::uuid, 'francais', '1re', 'De la dignité de l’homme, Jean Pic de la Mirandole', 'Quel cercle Pic fréquente-t-il à Florence ?', 'mcq', '["Celui de Marsile Ficin et de Laurent de Médicis","Celui d’Érasme et de Thomas More","Celui de Rabelais et de Clément Marot","Celui de Luther et de Mélanchthon"]'::jsonb, 0, 'Ce prince érudit lit le latin, le grec, l’hébreu et l’arabe ; il meurt à trente et un ans, en 1494.', 2),
    ('45c9c7fb-b7d1-5455-b42a-8c515e7da363'::uuid, 'francais', '1re', 'De la dignité de l’homme, Jean Pic de la Mirandole', 'Qui publie le discours, en 1496 ?', 'mcq', '["Le pape Innocent VIII","Marsile Ficin","Son neveu","Laurent de Médicis"]'::jsonb, 2, 'Le texte paraît après la mort de Pic, et le titre sous lequel on le connaît lui a été donné après coup.', 3),
    ('31b51a64-2bc7-5187-a951-529912d6e4c5'::uuid, 'francais', '1re', 'De la dignité de l’homme, Jean Pic de la Mirandole', 'Pourquoi, dans le récit, Dieu donne-t-il à l’homme une condition à part ?', 'mcq', '["L’homme l’a mérité par ses prières","Les anges le lui ont demandé","L’homme a été créé le premier","Il n’avait plus ni place ni nature à lui donner"]'::jsonb, 3, 'Ce manque devient un privilège : sans place ni forme propre, l’homme peut s’élever vers l’ange ou dégénérer vers l’animal.', 4),
    ('af75f091-1620-58e4-9b73-fc0c9348d40d'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne, Olympe de Gouges', 'À qui la Déclaration est-elle dédiée ?', 'mcq', '["Au roi Louis XVI","À la reine Marie-Antoinette","Aux députés de l’Assemblée","Aux citoyennes de Paris"]'::jsonb, 1, 'Olympe de Gouges presse la reine de défendre la cause des femmes ; le postambule, lui, s’adresse aux femmes elles-mêmes.', 1),
    ('6a061e08-0d74-5147-9292-2a4a8832c9a5'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne, Olympe de Gouges', 'Combien d’articles la Déclaration compte-t-elle ?', 'mcq', '["Dix","Douze","Vingt","Dix-sept"]'::jsonb, 3, 'Ses dix-sept articles suivent l’ordre exact de 1789 : ce pastiche rend l’exclusion des femmes criante sans avoir à la démontrer.', 2),
    ('132bd943-19d8-570b-a7b2-5cb5a2e0f898'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne, Olympe de Gouges', 'Quelle autre injustice sociale Olympe de Gouges dénonce-t-elle ?', 'mcq', '["Le sort des enfants nés hors mariage","Le travail des enfants dans les usines","L’impôt sur le sel","Le tirage au sort des soldats"]'::jsonb, 0, 'Son combat pour l’égalité est aussi social : elle défend les enfants nés hors mariage comme les esclaves.', 3),
    ('149fdacd-6f58-5b1e-a55d-0a6d69b744ad'::uuid, 'francais', '1re', 'Déclaration des droits de la femme et de la citoyenne, Olympe de Gouges', 'Dans quelle ville Olympe de Gouges est-elle née ?', 'mcq', '["Bordeaux","Toulouse","Montauban","Lyon"]'::jsonb, 2, 'Née Marie Gouze à Montauban, elle monte à Paris, écrit pour le théâtre et publie des dizaines de brochures politiques.', 4),
    ('b506b360-3f1f-54ba-aae7-6b512d5bf6c5'::uuid, 'francais', '1re', 'Défense et illustration de la langue française, Joachim du Bellay', 'Selon Du Bellay, pourquoi le français paraît-il pauvre ?', 'mcq', '["Par manque de culture, non par nature","Parce qu’il dérive trop du latin","Parce qu’il est divisé en dialectes","Parce que la cour lui préfère l’italien"]'::jsonb, 0, 'C’est le sens de « défendre » : une langue n’est pas pauvre par nature, elle s’enrichit si on la cultive.', 1),
    ('03446f7d-e426-51c0-a391-753b42b8c29b'::uuid, 'francais', '1re', 'Défense et illustration de la langue française, Joachim du Bellay', 'Quel recueil le manifeste accompagne-t-il en 1549 ?', 'mcq', '["Les Regrets","Les Antiquités de Rome","L’Olive","Les Amours de Cassandre"]'::jsonb, 2, 'Les Antiquités de Rome et Les Regrets paraîtront en 1558, après le séjour de Du Bellay à Rome.', 2),
    ('cf21fab7-f8a5-5d75-a614-46d845a74a9b'::uuid, 'francais', '1re', 'Défense et illustration de la langue française, Joachim du Bellay', 'Que reproche Barthélemy Aneau à Du Bellay dès 1550 ?', 'mcq', '["D’écrire en latin plutôt qu’en français","D’avoir recopié mot à mot Ronsard","D’attaquer l’ordonnance de Villers-Cotterêts","De mépriser les poètes d’avant lui, comme Marot"]'::jsonb, 3, 'Aneau lui reproche aussi d’écrire lui-même en imitateur : le manifeste déclenche aussitôt une querelle.', 3),
    ('4892b0ae-9c82-52d5-b98b-893aa36350b6'::uuid, 'francais', '1re', 'Défense et illustration de la langue française, Joachim du Bellay', 'Par quels moyens le manifeste veut-il enrichir le vocabulaire ?', 'mcq', '["En supprimant les mots d’origine populaire","Par des emprunts et des néologismes","En revenant aux seuls mots du Moyen Âge","En interdisant tout mot étranger"]'::jsonb, 1, 'Du Bellay puise au grec, au latin, aux dialectes et aux métiers, et invente des mots nouveaux.', 4),
    ('9787d354-f3f2-5b5b-affd-02aa72821fba'::uuid, 'francais', '1re', 'Des Souris et des Hommes, John Steinbeck', 'Qui est Crooks ?', 'mcq', '["Le vieil homme manchot du ranch","Le charretier que tous respectent","Le palefrenier noir, tenu à l’écart","Le fils agressif du patron"]'::jsonb, 2, 'Crooks, Candy et Lennie sont les plus faibles du ranch : la brutalité faite aux faibles traverse tout le roman.', 1),
    ('6dc50f12-db59-5167-bfa9-22e4f191b6dc'::uuid, 'francais', '1re', 'Des Souris et des Hommes, John Steinbeck', 'Quel trait de Lennie explique ses gestes mortels ?', 'mcq', '["Il caresse ce qui est doux sans mesurer sa force","Il est jaloux de ceux qui approchent George","Il cède à des colères cruelles et calculées","Il perd la tête dès qu’il a bu"]'::jsonb, 0, 'Colosse doux et déficient mental, Lennie tue sans le vouloir : un chiot, puis la femme de Curley qu’il voulait faire taire.', 2),
    ('ecf9a8b8-3186-5dda-b3cf-a76a6d362b8f'::uuid, 'francais', '1re', 'Des Souris et des Hommes, John Steinbeck', 'Quel roman Steinbeck publie-t-il deux ans après Des souris et des hommes ?', 'mcq', '["À l’est d’Éden","Tortilla Flat","La Perle","Les Raisins de la colère"]'::jsonb, 3, 'Des souris et des hommes paraît en 1937, Les Raisins de la colère en 1939 ; Steinbeck reçoit le prix Nobel en 1962.', 3),
    ('d051658e-bda0-5fb0-b3f1-adbfa01e05ec'::uuid, 'francais', '1re', 'Des Souris et des Hommes, John Steinbeck', 'Que répète George pour dire ce qui les distingue des autres ouvriers ?', 'mcq', '["Un jour, ils seront riches et respectés","Eux deux ont chacun l’autre, les autres n’ont personne","Il faut toujours obéir au patron du ranch","La Californie tient toujours ses promesses"]'::jsonb, 1, 'Ce refrain dit l’amitié, qui les sépare de tous les autres personnages, enfermés dans leur solitude.', 4),
    ('fbc0cc60-0ab6-5e3d-971e-b2a5dd51a1f0'::uuid, 'francais', '1re', 'Désert, Jean-Marie Gustave Le Clézio', 'Qui est Naman ?', 'mcq', '["Le jeune mendiant de Marseille","Le berger muet qu’aime Lalla","L’enfant qui suit Ma el Aïnine","Le vieux pêcheur conteur"]'::jsonb, 3, 'Autour de Lalla : Aamma, la tante qui l’a recueillie, Naman, le vieux pêcheur conteur, et à Marseille Radicz, le jeune mendiant.', 1),
    ('56165004-6f94-5eee-9ae6-2fe14e38771f'::uuid, 'francais', '1re', 'Désert, Jean-Marie Gustave Le Clézio', 'Que refuse Lalla dans son bidonville de la côte marocaine ?', 'mcq', '["Un travail à la ville","Un mariage arrangé","La langue de ses ancêtres","L’école des religieuses"]'::jsonb, 1, 'Viendront ensuite l’exil à Marseille, la misère, puis un bref succès comme modèle photographique.', 2),
    ('92519597-c1f2-55d2-a452-ca89d7fe952d'::uuid, 'francais', '1re', 'Désert, Jean-Marie Gustave Le Clézio', 'Comment se caractérise l’écriture de Désert ?', 'mcq', '["Sensorielle et lente, contemplative","Rapide, tout entière dans l’action","Ironique, riche en dialogues vifs","Savante, chargée de notes érudites"]'::jsonb, 0, 'Lumière, sable, vent, chaleur : on éprouve le désert, et le récit préfère la contemplation à l’action.', 3),
    ('61b13342-7c5a-5c5f-a048-59716eb36a93'::uuid, 'francais', '1re', 'Désert, Jean-Marie Gustave Le Clézio', 'Quel livre fait connaître Le Clézio dès 1963 ?', 'mcq', '["Mondo","Onitsha","Le Procès-verbal","Étoile errante"]'::jsonb, 2, 'Le Procès-verbal reçoit le prix Renaudot ; Désert, en 1980, installe Le Clézio comme grand écrivain, prix Nobel en 2008.', 4),
    ('c138cec2-e267-560a-ade4-8355755a5a14'::uuid, 'francais', '1re', 'Dictionnaire philosophique, Voltaire', 'Que désigne « l’Infâme » que Voltaire combat depuis Ferney ?', 'mcq', '["La monarchie absolue et ses ministres","Les philosophes matérialistes","Le fanatisme et l’intolérance","La censure des libraires parisiens"]'::jsonb, 2, 'Voltaire désigne ainsi le fanatisme et l’intolérance religieuse : c’est l’adversaire de tout le Dictionnaire.', 1),
    ('ac1c060f-81d3-5a37-984e-f220b933c722'::uuid, 'francais', '1re', 'Dictionnaire philosophique, Voltaire', 'Quel texte Voltaire publie-t-il en 1763 pour défendre la mémoire de Jean Calas ?', 'mcq', '["Candide","Traité sur la tolérance","Lettres philosophiques","Zadig"]'::jsonb, 1, 'Calas, protestant de Toulouse, avait été exécuté à tort en 1762 : ce combat pour la tolérance prépare le Dictionnaire de 1764.', 2),
    ('435f877f-2664-54f7-b537-536871f33165'::uuid, 'francais', '1re', 'Dictionnaire philosophique, Voltaire', 'Dans l’article « Fanatisme », à quoi Voltaire compare-t-il le fanatique ?', 'mcq', '["À un malade contagieux","À un soldat discipliné","À un enfant capricieux","À un juge trop sévère"]'::jsonb, 0, 'L’image médicale dit que le fanatisme se propage comme une maladie ; d’où la formule : « Le fanatisme est à la superstition ce que le transport est à la fièvre. »', 3),
    ('e5a78362-1208-5253-8e56-ed91c1e8ebc9'::uuid, 'francais', '1re', 'Dictionnaire philosophique, Voltaire', 'Quel procédé Voltaire emploie-t-il dans l’article « Guerre » ?', 'mcq', '["Il raconte en vers héroïques une bataille célèbre","Il dresse un tableau chiffré des morts de chaque siècle","Il cite longuement les maximes des généraux antiques","Il énumère avec calme des massacres aux causes dérisoires"]'::jsonb, 3, 'Le décalage entre le ton tranquille et l’horreur des faits est ironique : c’est le lecteur qui s’indigne, à la place de l’auteur.', 4),
    ('69791d95-2393-512c-ac48-8c794f19a9a6'::uuid, 'francais', '1re', 'Discours de la servitude volontaire, Étienne de La Boétie', 'Sous quel autre titre le Discours de la servitude volontaire est-il connu ?', 'mcq', '["L’Anti-Machiavel","L’Éloge de la folie","Le Prince","Le Contr’un"]'::jsonb, 3, '« Contre un » : le texte vise le pouvoir d’un seul, qui ne tient que par la force que tous lui prêtent.', 1),
    ('17e99133-d773-5882-bde6-fe17cbf5c14f'::uuid, 'francais', '1re', 'Discours de la servitude volontaire, Étienne de La Boétie', 'Que montre l’exemple des deux chiens de Lycurgue ?', 'mcq', '["Que l’éducation fait tout","Que la nature fixe le caractère","Que la force l’emporte toujours","Que la fidélité finit par payer"]'::jsonb, 0, 'Élevés différemment, l’un chasse, l’autre court à la soupe : ce n’est pas la nature qui fait les serviteurs, c’est l’habitude qu’on leur donne.', 2),
    ('6c74a2a9-577f-540c-b29b-b96a240303cb'::uuid, 'francais', '1re', 'Discours de la servitude volontaire, Étienne de La Boétie', 'Qui imprime le Discours dans les années 1570 ?', 'mcq', '["La Boétie lui-même, à Bordeaux","Montaigne, en tête des Essais","Des protestants, après la Saint-Barthélemy","Des magistrats, à la demande du roi"]'::jsonb, 2, 'Ils en font une arme contre la monarchie ; voyant cet usage, Montaigne renonce à placer le texte au centre du livre I des Essais.', 3),
    ('29a25016-259b-5f9b-8ad5-061f33bc705f'::uuid, 'francais', '1re', 'Discours de la servitude volontaire, Étienne de La Boétie', 'Quelle charge La Boétie exerce-t-il ?', 'mcq', '["Maire de Sarlat","Conseiller au parlement de Bordeaux","Précepteur des enfants du roi","Ambassadeur à Venise"]'::jsonb, 1, 'Né à Sarlat en 1530, ce magistrat meurt à trente-deux ans, Montaigne à son chevet.', 4),
    ('1d9a70a3-da00-5fc7-9332-d8da964b7ecf'::uuid, 'francais', '1re', 'Dom Juan, Molière', 'Quel rôle Molière joue-t-il lui-même à la création de la pièce ?', 'mcq', '["Dom Juan","Dom Louis","Sganarelle","Le Commandeur"]'::jsonb, 2, 'Créée le 15 février 1665 au Palais-Royal, la pièce laisse le dernier mot à ce valet comique : « Mes gages ! mes gages ! »', 1),
    ('f16270c5-9f8a-5208-adbf-0e1d4d502a88'::uuid, 'francais', '1re', 'Dom Juan, Molière', 'Dans la scène du pauvre, à quelle condition Dom Juan offre-t-il d’abord un louis d’or ?', 'mcq', '["Que le pauvre prie pour lui","Que le pauvre accepte de jurer","Que le pauvre lui montre la route","Que le pauvre quitte la forêt"]'::jsonb, 1, 'Le pauvre refuse de blasphémer ; Dom Juan lui donne pourtant la pièce « pour l’amour de l’humanité » : une des scènes qui firent scandale.', 2),
    ('31cefc3e-6584-5657-bbca-b25912f3893d'::uuid, 'francais', '1re', 'Dom Juan, Molière', 'Qui est Pierrot ?', 'mcq', '["Le frère de Mathurine, jaloux de Charlotte","Le valet de Dom Louis, envoyé en éclaireur","Un créancier venu réclamer son dû","Le paysan qui sauve Dom Juan de la noyade"]'::jsonb, 3, 'Dom Juan remercie son sauveur en séduisant sa fiancée, Charlotte : l’ingratitude s’ajoute à la transgression.', 3),
    ('7a1bcc8e-b74e-5060-8cd5-1797be903d21'::uuid, 'francais', '1re', 'Dom Juan, Molière', 'Sous quelles formes le Spectre apparaît-il à Dom Juan ?', 'mcq', '["Une femme voilée, puis le Temps avec sa faux","Un moine en prière, puis un ange armé","Le fantôme de son père, puis un démon","Un vieillard aveugle, puis un chœur de pleureuses"]'::jsonb, 0, 'C’est le dernier avertissement avant la statue du Commandeur : Dom Juan le méprise, et la statue l’entraîne dans les flammes.', 4),
    ('0ce6f4a8-c64f-563a-9cb2-5d307bc5965b'::uuid, 'francais', '1re', 'Don Quichotte, Miguel de Cervantes', 'Lors de quelle bataille Cervantes perd-il l’usage de la main gauche ?', 'mcq', '["Pavie","Lépante","Rocroi","Trafalgar"]'::jsonb, 1, 'C’était en 1571 ; il est ensuite captif à Alger pendant cinq ans : l’auteur a lui-même une vie de roman.', 1),
    ('4af9fdba-5a38-58f6-93cb-072c5c461074'::uuid, 'francais', '1re', 'Don Quichotte, Miguel de Cervantes', 'Qui est Dulcinée du Toboso ?', 'mcq', '["Une princesse enlevée par un géant","La nièce du curé du village","Une paysanne dont il fait sa dame","La duchesse qui se moque de lui"]'::jsonb, 2, 'Tout chevalier errant sert une dame : don Quichotte transforme une simple paysanne en héroïne de roman de chevalerie.', 2),
    ('490de5cc-7a66-596e-a72d-7b5e7f48fe4b'::uuid, 'francais', '1re', 'Don Quichotte, Miguel de Cervantes', 'Que font les galériens que don Quichotte a libérés ?', 'mcq', '["Ils le rouent de coups","Ils deviennent ses compagnons","Ils l’adoubent chevalier","Ils le ramènent au village"]'::jsonb, 0, 'Il voyait en eux des innocents à délivrer : à chaque aventure, le réel dément l’idéal tiré des livres.', 3),
    ('f5ef6e2d-2a6c-5d8f-8642-9aa8df3306cb'::uuid, 'francais', '1re', 'Don Quichotte, Miguel de Cervantes', 'Quel rôle le duc et la duchesse confient-ils à Sancho ?', 'mcq', '["Écuyer officiel de leur château","Maire de son propre village","Capitaine d’une galère du roi","Gouverneur de l’« île » de Barataria"]'::jsonb, 3, 'C’est une de leurs mises en scène pour humilier les héros, qu’ils connaissent par la première partie : les guillemets disent que cette « île » est une farce.', 4),
    ('1f8f2e79-b8f4-503e-915e-27609b47707d'::uuid, 'francais', '1re', 'Du côté de chez Swann, Marcel Proust', 'Quel écrivain refuse le manuscrit pour la NRF, avant de le regretter ?', 'mcq', '["Paul Valéry","Paul Claudel","André Gide","Jean Cocteau"]'::jsonb, 2, 'Proust passait pour un mondain et un amateur : refusé par plusieurs éditeurs, le volume paraît à compte d’auteur chez Grasset en 1913.', 1),
    ('6f4d7022-4b96-5471-bd0c-4ce164d53f81'::uuid, 'francais', '1re', 'Du côté de chez Swann, Marcel Proust', 'Qui offrait à l’enfant, à Combray, la madeleine trempée dans le tilleul ?', 'mcq', '["Sa mère","La tante Léonie","Sa grand-mère","Françoise"]'::jsonb, 1, 'C’est ce goût retrouvé des années plus tard qui fait resurgir tout Combray : la mémoire involontaire.', 2),
    ('7a6770e0-37a5-5e6f-96ca-0ccf285ab494'::uuid, 'francais', '1re', 'Du côté de chez Swann, Marcel Proust', 'Comment s’intitule la troisième partie du volume ?', 'mcq', '["« Noms de pays : le nom »","« Autour de Mme Swann »","« Le Temps retrouvé »","« Le Côté de Guermantes »"]'::jsonb, 0, 'La rêverie sur les noms de villes s’y mêle à l’amour d’enfance du narrateur pour Gilberte, aux Champs-Élysées.', 3),
    ('340facee-a0bf-55ac-911e-fbfc5b961771'::uuid, 'francais', '1re', 'Du côté de chez Swann, Marcel Proust', 'Comment Swann juge-t-il finalement Odette ?', 'mcq', '["Comme la seule femme qu’il ait aimée","Comme une muse digne de Vinteuil","Comme une épouse enfin fidèle","Comme une femme qui n’était pas son genre"]'::jsonb, 3, '« Dire que j’ai gâché des années de ma vie, […] pour une femme qui ne me plaisait pas » : et pourtant, il l’épousera.', 4),
    ('11849821-5fa1-5860-bfc2-e30270fb925f'::uuid, 'francais', '1re', 'Électre, Jean Giraudoux', 'Quel métier Giraudoux exerce-t-il à côté de l’écriture ?', 'mcq', '["Diplomate","Avocat","Médecin","Professeur de grec"]'::jsonb, 0, 'Ce diplomate connaît de près la politique européenne : dans Électre, en 1937, la justice absolue se heurte au compromis politique.', 1),
    ('35ff7238-d70d-574b-9d1f-f84aaeecd9ae'::uuid, 'francais', '1re', 'Électre, Jean Giraudoux', 'Que fait le jardinier dans son célèbre « lamento » ?', 'mcq', '["Il supplie Égisthe d’annuler le mariage","Il révèle à Oreste le crime de sa mère","Il vient parler seul au public","Il chante la mort d’Agamemnon"]'::jsonb, 2, 'Le personnage sort de l’action pour s’adresser à la salle : Giraudoux mêle au mythe une parole directe, brillante et ironique.', 2),
    ('631e7931-9419-5818-b693-7b36d92af73e'::uuid, 'francais', '1re', 'Électre, Jean Giraudoux', 'Que parodie l’intrigue du Président et d’Agathe ?', 'mcq', '["La guerre de Troie","Le drame des Atrides","Les amours des dieux","La fondation d’Argos"]'::jsonb, 1, 'Leur adultère bourgeois fait écho, sur le mode comique, au crime de Clytemnestre et d’Égisthe.', 3),
    ('88ae1349-ed53-5873-8387-cb2a08460750'::uuid, 'francais', '1re', 'Électre, Jean Giraudoux', 'Combien d’actes compte Électre ?', 'mcq', '["Un","Trois","Cinq","Deux"]'::jsonb, 3, 'Créée en 1937 au théâtre de l’Athénée, la pièce resserre le mythe en deux actes, jusqu’à la réplique finale sur l’aurore.', 4),
    ('a049d730-4631-597a-adac-71400715105a'::uuid, 'francais', '1re', 'En attendant Godot, Samuel Beckett', 'Qu’est-ce qui a changé dans le décor à l’acte II ?', 'mcq', '["L’arbre a été abattu","L’arbre porte quelques feuilles","Une chaise a été ajoutée","La route est barrée"]'::jsonb, 1, 'Ce détail minuscule est presque le seul changement : le temps passe sans rien apporter, l’attente recommence.', 1),
    ('2f11d1e7-0e8d-538d-b64a-7aef8e794b54'::uuid, 'francais', '1re', 'En attendant Godot, Samuel Beckett', 'Qu’annonce le garçon à la fin de chaque acte ?', 'mcq', '["Que Godot est mort pendant la nuit","Que Pozzo les attend plus loin","Que Godot ne viendra pas ce soir, mais demain","Qu’il faut quitter la route avant l’aube"]'::jsonb, 2, 'La même annonce revient à l’acte II : la promesse d’un « demain » entretient une attente sans fin.', 2),
    ('087ad2e6-99e0-5471-a5a8-e99d77e842af'::uuid, 'francais', '1re', 'En attendant Godot, Samuel Beckett', 'Dans quel état Pozzo et Lucky reviennent-ils à l’acte II ?', 'mcq', '["Pozzo est aveugle, Lucky muet","Pozzo est muet, Lucky aveugle","Pozzo est mort, Lucky libéré","Lucky tient Pozzo en laisse"]'::jsonb, 0, 'Leur dégradation est le seul « changement » de la pièce : le temps n’avance pas, il use.', 3),
    ('5f0c2166-e192-53e1-b622-70288fc6ba66'::uuid, 'francais', '1re', 'En attendant Godot, Samuel Beckett', 'Quelle forme de comique Beckett met-il au service du désespoir ?', 'mcq', '["La comédie d’intrigue à rebondissements","La satire politique des puissants","Le comique de caractère à la Molière","Le music-hall : duo, gags, chutes"]'::jsonb, 3, 'Vladimir et Estragon fonctionnent comme un duo de clowns : le rire rend le vide de l’attente à la fois supportable et plus sensible.', 4),
    ('a5b70776-d51c-5469-91ea-1d782cfb4d38'::uuid, 'francais', '1re', 'Encyclopédie, Denis Diderot, Jean le Rond d’Alembert', 'Quel est le sous-titre de l’Encyclopédie ?', 'mcq', '["Recueil méthodique des connaissances anciennes","Tableau historique des progrès de l’esprit","Dictionnaire raisonné des sciences, des arts et des métiers","Dictionnaire universel des mots et des choses"]'::jsonb, 2, '« Raisonné » : les savoirs n’y sont pas seulement rangés, ils sont reliés et examinés ; et les « métiers » y entrent à égalité avec les sciences.', 1),
    ('73b61a8e-5f3e-5116-85ee-d23993f06d50'::uuid, 'francais', '1re', 'Encyclopédie, Denis Diderot, Jean le Rond d’Alembert', 'Quel collaborateur rédige à lui seul près d’un quart des articles ?', 'mcq', '["Voltaire","Rousseau","Montesquieu","Jaucourt"]'::jsonb, 3, 'Près de deux cents collaborateurs participent, des philosophes aux artisans et aux médecins : l’Encyclopédie est une œuvre collective.', 2),
    ('3996e3b3-f494-5bd6-b535-c36bc53b63f5'::uuid, 'francais', '1re', 'Encyclopédie, Denis Diderot, Jean le Rond d’Alembert', 'Vers quel article l’article « Anthropophages » renvoie-t-il ironiquement ?', 'mcq', '["« Eucharistie »","« Cannibales »","« Sauvages »","« Barbarie »"]'::jsonb, 0, 'Le renvoi rapproche, sans le dire, manger de la chair humaine et la communion : l’ironie passe par la structure du dictionnaire.', 3),
    ('3e329798-23a6-53a2-b4c6-c565235a3990'::uuid, 'francais', '1re', 'Encyclopédie, Denis Diderot, Jean le Rond d’Alembert', 'Que découvre Diderot en 1764 ?', 'mcq', '["Que d’Alembert a vendu le projet","Que Le Breton a censuré des articles en secret","Que le pape a levé sa condamnation","Que les planches ont été volées"]'::jsonb, 1, 'Après les interdictions de 1752 et la révocation du privilège en 1759, le coup vient de l’intérieur : le libraire a coupé des articles déjà imprimés.', 4),
    ('7ccaaac4-3833-5853-9197-168c75ba1869'::uuid, 'francais', '1re', 'Énéide, Virgile', 'Qui Énée porte-t-il sur ses épaules en fuyant Troie ?', 'mcq', '["Son fils Ascagne","Le roi Priam","Son père Anchise","Son ami Achate"]'::jsonb, 2, 'Il fuit avec son fils Ascagne : l’image du fils qui porte son père résume la pietas, le devoir envers la famille et les dieux.', 1),
    ('3935aee7-d6e9-5712-a91d-c57b75cf4305'::uuid, 'francais', '1re', 'Énéide, Virgile', 'Quelle est la forme de l’Énéide ?', 'mcq', '["Vingt-quatre chants en hexamètres","Douze chants en hexamètres","Douze chants en alexandrins","Dix livres en distiques"]'::jsonb, 1, 'L’hexamètre est le vers de l’épopée antique, celui d’Homère, avec qui Virgile rivalise ; l’Iliade et l’Odyssée comptent vingt-quatre chants.', 2),
    ('d5c91147-b802-5c19-a2fd-78cc223bad08'::uuid, 'francais', '1re', 'Énéide, Virgile', 'Qui forge le bouclier d’Énée ?', 'mcq', '["Mars","Jupiter","Minerve","Vulcain"]'::jsonb, 3, 'Vulcain y grave l’histoire future de Rome jusqu’à Auguste : l’épopée légitime le pouvoir du prince.', 3),
    ('513edffc-3687-5de1-9f8a-e5c6300bfd63'::uuid, 'francais', '1re', 'Énéide, Virgile', 'Quel poète fait de Virgile son guide ?', 'mcq', '["Dante","Pétrarque","Du Bellay","Ronsard"]'::jsonb, 0, 'Dans la Divine Comédie, Virgile conduit Dante à travers l’Enfer et le Purgatoire : il est devenu un modèle absolu pour la littérature européenne.', 4),
    ('a866fb78-577e-5e37-a1c0-b612984f24e9'::uuid, 'francais', '1re', 'Entretiens sur la pluralité des mondes, Bernard Le Bouyer de Fontenelle', 'Que sont les étoiles fixes, selon le philosophe des Entretiens ?', 'mcq', '["Des trous dans la voûte céleste","Des planètes très éloignées","Autant de soleils","Des comètes immobiles"]'::jsonb, 2, 'Chacune pourrait avoir ses propres mondes : l’univers dépasse l’imagination, et la Terre y perd sa place centrale.', 1),
    ('51c0fc5c-d40b-593d-96a7-c1d54663b7c4'::uuid, 'francais', '1re', 'Entretiens sur la pluralité des mondes, Bernard Le Bouyer de Fontenelle', 'Combien de soirs comptait la première édition, en 1686 ?', 'mcq', '["Six","Cinq","Sept","Trois"]'::jsonb, 1, 'Le sixième soir est ajouté en 1687 : l’ouvrage s’enrichit d’une édition à l’autre.', 2),
    ('a4a4084c-ec92-5c42-b2f2-50d6a401bcf0'::uuid, 'francais', '1re', 'Entretiens sur la pluralité des mondes, Bernard Le Bouyer de Fontenelle', 'Quelle fonction Fontenelle occupe-t-il à partir de 1697 ?', 'mcq', '["Astronome de l’Observatoire royal","Précepteur du duc de Bourgogne","Secrétaire perpétuel de l’Académie française","Secrétaire perpétuel de l’Académie des sciences"]'::jsonb, 3, 'Il y fait de l’éloge des savants un genre littéraire : le vulgarisateur devient le porte-parole de la science.', 3),
    ('f6eabdfd-1148-54e5-95e0-d56571767edd'::uuid, 'francais', '1re', 'Entretiens sur la pluralité des mondes, Bernard Le Bouyer de Fontenelle', 'Selon la phrase à citer, sur quoi toute la philosophie est-elle fondée ?', 'mcq', '["L’esprit curieux et les yeux mauvais","La raison et la foi","Le calcul et l’expérience","Le doute et la mémoire"]'::jsonb, 0, 'Nous voulons savoir plus que nous ne voyons : la curiosité pousse à chercher, la faiblesse de nos sens oblige à raisonner.', 4),
    ('fcd5f097-b79f-5784-b991-a7597ab6f43e'::uuid, 'francais', '1re', 'Essais, Michel de Montaigne', 'Quel chapitre des Essais évoque la destruction du Nouveau Monde ?', 'mcq', '["« De l’amitié »","« Des Coches »","« De l’expérience »","« De l’institution des enfants »"]'::jsonb, 1, 'Montaigne y juge la conquête de l’Amérique ; dans « Des Cannibales », il retournait déjà l’accusation de barbarie contre les Européens.', 1),
    ('42616567-1ade-553c-b62f-92a508f8af44'::uuid, 'francais', '1re', 'Essais, Michel de Montaigne', 'Que sont les « allongeails » ?', 'mcq', '["Les notes ajoutées par Marie de Gournay","Les citations latines du texte","Les ajouts de Montaigne d’une édition à l’autre","Les chapitres consacrés au corps"]'::jsonb, 2, 'Montaigne ne corrige pas, il ajoute : le livre grandit avec son auteur, jusqu’à sa mort en 1592.', 2),
    ('fff5fb4e-ee9c-5831-866f-add6605481e7'::uuid, 'francais', '1re', 'Essais, Michel de Montaigne', 'Quelle phrase de « Des Cannibales » relativise la notion de barbarie ?', 'mcq', '["« Chacun appelle barbarie ce qui n’est pas de son usage »","« L’homme est un loup pour l’homme »","« Science sans conscience n’est que ruine de l’âme »","« Il faut cultiver notre jardin »"]'::jsonb, 0, 'Le barbare, c’est d’abord celui qui n’a pas nos habitudes : c’est le relativisme humaniste face aux autres cultures.', 3),
    ('33e16a3c-5192-5b71-b6ca-9313e0a115b9'::uuid, 'francais', '1re', 'Essais, Michel de Montaigne', 'Comment Montaigne utilise-t-il les citations antiques ?', 'mcq', '["Comme des preuves qui closent le débat","Comme des modèles à imiter mot pour mot","Comme de simples ornements de style","Comme un matériau, non une autorité"]'::jsonb, 3, 'Il les discute et les confronte à l’expérience : c’est la lecture critique des Anciens propre à l’humanisme.', 4),
    ('52d178bd-5b58-5a55-be0f-f5b105544385'::uuid, 'francais', '1re', 'Éthiopiques, Léopold Sédar Senghor', 'Comment s’intitule la postface où Senghor s’explique sur sa poétique ?', 'mcq', '["« Orphée noir »","« Comme les lamantins vont boire à la source »","« Discours sur le colonialisme »","« Cahier d’un retour au pays natal »"]'::jsonb, 1, '« Orphée noir » est la préface de Sartre à l’Anthologie de 1948 ; le Discours et le Cahier sont d’Aimé Césaire.', 1),
    ('803d53cf-761d-5e68-8cf1-05556a37e6c1'::uuid, 'francais', '1re', 'Éthiopiques, Léopold Sédar Senghor', 'Quels poètes ont inspiré les versets amples de Senghor ?', 'mcq', '["Hugo et Lamartine","Ronsard et Du Bellay","Claudel et Saint-John Perse","Baudelaire et Verlaine"]'::jsonb, 2, 'Leur verset long et rythmé convient à une poésie faite pour être dite et accompagnée, comme la parole du griot.', 2),
    ('bafe1a00-a4d3-53d2-828b-ee0c48ec4a3c'::uuid, 'francais', '1re', 'Éthiopiques, Léopold Sédar Senghor', 'Avec qui Senghor forge-t-il la notion de négritude, dans les années 1930 ?', 'mcq', '["Aimé Césaire et Léon-Gontran Damas","Jean-Paul Sartre et Albert Camus","Frantz Fanon et Édouard Glissant","Birago Diop et Camara Laye"]'::jsonb, 0, 'La négritude revendique une identité et une culture noires contre l’assimilation coloniale ; Senghor la vit de façon plus lyrique et conciliatrice que Césaire.', 3),
    ('3bcd74ff-f873-5948-a7e4-3bf65770f3c7'::uuid, 'francais', '1re', 'Éthiopiques, Léopold Sédar Senghor', 'À quoi le poème « Congo » compare-t-il le fleuve ?', 'mcq', '["À un serpent qui menace","À une route d’acier","À un guerrier zoulou","À une femme et une mère"]'::jsonb, 3, 'Le fleuve rejoint ainsi la célébration de la femme, terre et promesse, qui traverse l’œuvre.', 4),
    ('917a5866-a447-5a53-86a3-e600f96a87e0'::uuid, 'francais', '1re', 'Eugénie Grandet, Honoré de Balzac', 'Pourquoi Charles arrive-t-il ruiné à Saumur ?', 'mcq', '["Il a tout perdu au jeu à Paris","Son père, en faillite, s’est suicidé","Un incendie a détruit ses biens","Sa mère l’a déshérité"]'::jsonb, 1, 'Grandet accueille froidement ce neveu sans le sou ; Eugénie, elle, découvre l’amour et lui donne son or en secret.', 1),
    ('09e75c7e-be91-57c3-ac4f-85d362a1b9e4'::uuid, 'francais', '1re', 'Eugénie Grandet, Honoré de Balzac', 'Quelles familles courtisent l’héritière ?', 'mcq', '["Les Rastignac et les Nucingen","Les Maheu et les Grégoire","Les Verdurin et les Guermantes","Les Cruchot et les des Grassins"]'::jsonb, 3, 'Ce n’est pas Eugénie qu’ils courtisent, c’est sa fortune : l’argent structure jusqu’au mariage.', 2),
    ('bab43205-426e-53c9-ba9c-7e1da1c6a307'::uuid, 'francais', '1re', 'Eugénie Grandet, Honoré de Balzac', 'Comment Grandet punit-il sa fille après la découverte du don ?', 'mcq', '["Il la séquestre au pain et à l’eau","Il l’envoie au couvent","Il la marie de force au président","Il la chasse de la maison"]'::jsonb, 0, 'Madame Grandet ne survit pas à ce drame : l’avarice tue sans violence apparente.', 3),
    ('dce307cc-b359-5863-884e-9ac8419bf6c1'::uuid, 'francais', '1re', 'Eugénie Grandet, Honoré de Balzac', 'Dans quelle section de La Comédie humaine le roman est-il rangé ?', 'mcq', '["Scènes de la vie parisienne","Études philosophiques","Scènes de la vie de province","Scènes de la vie militaire"]'::jsonb, 2, 'La vie étroite de Saumur, ses regards et ses calculs, y comptent autant que les personnages.', 4),
    ('542f0dc9-8c0e-5f33-a536-b1cd66ff90af'::uuid, 'francais', '1re', 'Fables, Jean de La Fontaine', 'Quel protecteur de La Fontaine est arrêté en 1661 sur ordre de Louis XIV ?', 'mcq', '["Colbert","Mazarin","Fouquet","Le Grand Condé"]'::jsonb, 2, 'La disgrâce du surintendant rejaillit sur ses amis : La Fontaine connaît de près l’arbitraire du pouvoir qu’il peint sous les traits du lion.', 1),
    ('f805b6ac-7415-5f09-a950-cd77d9ce352f'::uuid, 'francais', '1re', 'Fables, Jean de La Fontaine', 'Selon la préface, une fable a un « corps » et une « âme » : que désigne l’âme ?', 'mcq', '["Le récit","La morale","Les animaux","Le vers"]'::jsonb, 1, 'Le corps est le récit, l’âme la leçon : « une morale nue apporte de l’ennui », le conte la fait passer.', 2),
    ('74e6c7a5-7be2-5898-96f0-e1a126234de8'::uuid, 'francais', '1re', 'Fables, Jean de La Fontaine', 'Quel type humain le renard représente-t-il souvent ?', 'mcq', '["Le courtisan rusé et flatteur","Le roi et son arbitraire","La force brutale","La victime qu’on accable"]'::jsonb, 0, 'Dans « Le Corbeau et le Renard », il obtient le fromage par la flatterie : la fable devient une satire de la cour.', 3),
    ('498bc29c-1cca-5c02-9e9f-59edc0f006c5'::uuid, 'francais', '1re', 'Fables, Jean de La Fontaine', 'Où La Fontaine place-t-il la morale de ses fables ?', 'mcq', '["Toujours dans le dernier vers","Toujours avant le récit","Toujours dans le titre","Au début, à la fin, ou nulle part"]'::jsonb, 3, 'Cette liberté fait partie de son art : parfois, c’est au lecteur de tirer lui-même la leçon du récit.', 4),
    ('08b99a92-a87e-53b0-a0fe-a9d58c2380ab'::uuid, 'francais', '1re', 'Fin de partie, Samuel Beckett', 'Quelle est l’infirmité de Clov ?', 'mcq', '["Il est aveugle","Il ne peut pas s’asseoir","Il est muet","Il ne peut pas marcher"]'::jsonb, 1, 'Hamm, aveugle et paralysé, ne peut se passer de lui ; Clov, qui ne peut ni s’asseoir ni partir, reste : personne ne supporte l’autre, personne ne s’en passe.', 1),
    ('84f3ca6c-0501-5f53-b97a-8778adc42fbc'::uuid, 'francais', '1re', 'Fin de partie, Samuel Beckett', 'De quel souvenir heureux Nagg et Nell parlent-ils depuis leurs poubelles ?', 'mcq', '["Leur mariage à Dublin","La naissance de Hamm","Un jour au lac de Côme","Un bal à Paris"]'::jsonb, 2, 'Le bonheur n’existe plus qu’au passé, dans un monde où il n’y a plus « rien » dehors.', 2),
    ('14846cda-7047-589b-98f7-17622b8d1339'::uuid, 'francais', '1re', 'Fin de partie, Samuel Beckett', 'Qu’évoquent, selon une remarque souvent faite, les noms Hamm, Clov, Nagg et Nell ?', 'mcq', '["Des personnages de Shakespeare","Des villes d’Irlande","Des pièces du jeu d’échecs","Le marteau et les clous"]'::jsonb, 3, 'Hammer (marteau) face à clou, nail, Nagel : un personnage qui frappe et d’autres qui subissent.', 3),
    ('2c1d29e1-ecb2-5f25-a7be-1472a73cd89b'::uuid, 'francais', '1re', 'Fin de partie, Samuel Beckett', 'Quel mot Clov ressasse-t-il dans la réplique qui ouvre la pièce ?', 'mcq', '["« Fini »","« Rien »","« Zéro »","« Partir »"]'::jsonb, 0, 'La pièce s’ouvre sur une fin annoncée qui n’arrive pas : c’est le sens du titre, emprunté aux échecs.', 4),
    ('3e91d0e4-fda0-51dd-a1fc-ff6768ee937f'::uuid, 'francais', '1re', 'Gargantua, François Rabelais', 'Comment naît Gargantua ?', 'mcq', '["Par l’oreille de sa mère, en criant « À boire ! »","Dans une forêt, recueilli par des bergers","Au milieu d’une bataille contre Picrochole","Dans une abbaye, élevé par Frère Jean"]'::jsonb, 0, 'Cette naissance burlesque, après un repas de tripes, donne le ton : le rire du corps, de l’excès et du gigantisme.', 1),
    ('db204597-53c4-5cb2-a782-262077fd2f9c'::uuid, 'francais', '1re', 'Gargantua, François Rabelais', 'À quoi le prologue compare-t-il le livre ?', 'mcq', '["À un miroir","Aux Silènes","À une horloge","À un labyrinthe"]'::jsonb, 1, 'Les Silènes étaient de petites boîtes peintes de figures joyeuses qui renfermaient des drogues précieuses : sous l’apparence comique se cache un contenu de valeur.', 2),
    ('b9bb90fa-2e7d-5cce-823c-90f08a650825'::uuid, 'francais', '1re', 'Gargantua, François Rabelais', 'Que vient réclamer Janotus de Bragmardo ?', 'mcq', '["La jument de Gargantua","Les fouaces volées","Le précepteur Ponocrates","Les cloches de Notre-Dame"]'::jsonb, 3, 'Sa harangue ridicule fait de ce sophiste la caricature de la scolastique que le livre combat.', 3),
    ('55bdaebf-c12c-5c22-b28e-100ac26fa6ff'::uuid, 'francais', '1re', 'Gargantua, François Rabelais', 'Quelle limite le cours relève-t-il dans l’utopie de Thélème ?', 'mcq', '["Elle interdit toute lecture","Elle est réservée aux moines","Elle suppose des gens « bien nés, bien instruits »","Elle impose des horaires très stricts"]'::jsonb, 2, 'La règle « Fais ce que voudras » ne fonctionne qu’entre gens bien nés et bien instruits : la liberté y est un privilège d’élite.', 4),
    ('b93de898-d17d-5fe2-a072-84479289f90b'::uuid, 'francais', '1re', 'Germinal, Émile Zola', 'Où Zola s’est-il rendu pour se documenter sur la mine ?', 'mcq', '["À Carmaux","À Anzin","À Decazeville","À Saint-Étienne"]'::jsonb, 1, 'Le naturalisme s’appuie sur l’enquête : Zola observe sur place le travail, les puits et la vie des mineurs avant d’écrire.', 1),
    ('596bd980-79ce-5a41-a9d1-31ba9921ec2c'::uuid, 'francais', '1re', 'Germinal, Émile Zola', 'Qui sont les Grégoire ?', 'mcq', '["Des actionnaires rentiers de la Compagnie","Des mineurs voisins des Maheu","Les directeurs successifs du Voreux","Des boutiquiers du coron"]'::jsonb, 0, 'Ils vivent des dividendes de la mine sans y descendre : le « ventre » des bourgeois face à la faim des mineurs.', 2),
    ('1b38a404-2772-5a23-9238-b3fa61008809'::uuid, 'francais', '1re', 'Germinal, Émile Zola', 'Quel rang Germinal occupe-t-il dans les Rougon-Macquart ?', 'mcq', '["Le premier","Le septième","Le vingtième","Le treizième"]'::jsonb, 3, 'C’est le plus célèbre des vingt romans ; le septième, L’Assommoir, raconte la vie de Gervaise, la mère d’Étienne.', 3),
    ('bac9a3db-b334-5414-bba0-59e61decd057'::uuid, 'francais', '1re', 'Germinal, Émile Zola', 'À quelle saison Étienne quitte-t-il le pays, à la fin ?', 'mcq', '["En plein hiver","À l’automne","Au printemps","En été"]'::jsonb, 2, 'La saison répond au titre : de la défaite peut germer une révolte future, « une armée noire, vengeresse ».', 4),
    ('c3987dee-efae-52c9-ba9c-7aaf0be449e9'::uuid, 'francais', '1re', 'Germinie Lacerteux, Edmond et Jules de Goncourt', 'Comment s’appelait la bonne des Goncourt dont la double vie a inspiré le roman ?', 'mcq', '["Félicité","Rose Malingre","Françoise","Nanon"]'::jsonb, 1, 'Ils avaient découvert sa double vie à sa mort. Félicité, Françoise et Nanon sont les servantes de Flaubert, de Proust et de Balzac.', 1),
    ('96b6c1ba-08a6-589e-a162-f4457ca6b294'::uuid, 'francais', '1re', 'Germinie Lacerteux, Edmond et Jules de Goncourt', 'Qui est Jupillon ?', 'mcq', '["Le frère de Mlle de Varandeuil","Un médecin de l’hôpital","Le fils d’une crémière, qui ruine Germinie","Le mari que Germinie a quitté"]'::jsonb, 2, 'Jeune homme veule et sans scrupule, il exploite l’amour de Germinie ; sa mère, la crémière, profite elle aussi de la servante.', 2),
    ('7447aca1-0f7d-5b00-9a1d-b69e1502ae1f'::uuid, 'francais', '1re', 'Germinie Lacerteux, Edmond et Jules de Goncourt', 'Comment la préface définit-elle le roman ?', 'mcq', '["« La clinique de l’Amour »","« Un miroir qu’on promène le long d’un chemin »","« Une histoire naturelle et sociale »","« Une tranche de vie »"]'::jsonb, 0, 'La formule revendique une prétention scientifique : le romancier observe la passion comme un médecin observe une maladie.', 3),
    ('c7cd0a15-d01c-588c-8be7-034dc0d02b90'::uuid, 'francais', '1re', 'Germinie Lacerteux, Edmond et Jules de Goncourt', 'Quelle expression Edmond de Goncourt forgera-t-il plus tard pour désigner cette méthode ?', 'mcq', '["Le roman expérimental","L’écriture blanche","Le réalisme magique","Le document humain"]'::jsonb, 3, 'Le mot n’est pas encore dans la préface de 1865, mais la démarche y est : partir d’un cas vrai, observé.', 4),
    ('78b790a3-4be9-556f-b209-8ea8220eae3c'::uuid, 'francais', '1re', 'Gil Blas de Santillane, Alain-René Lesage', 'Pour quelle ville Gil Blas quitte-t-il Oviedo, au début du roman ?', 'mcq', '["Salamanque","Madrid","Séville","Tolède"]'::jsonb, 0, 'Il part y étudier, mais il est aussitôt volé, puis embrigadé de force par des brigands : l’apprentissage du monde commence.', 1),
    ('e0607b7e-7d92-5fd2-beed-10559b2091f2'::uuid, 'francais', '1re', 'Gil Blas de Santillane, Alain-René Lesage', 'Qui est le capitaine Rolando ?', 'mcq', '["Le maître d’armes de Gil Blas","Le chef des brigands qui retiennent Gil Blas","Un officier qui enrôle Gil Blas","Le père de son valet Scipion"]'::jsonb, 1, 'Gil Blas est retenu dans leur caverne : la violence du monde frappe le héros naïf dès son départ.', 2),
    ('1ab2f6bd-1856-5c86-a769-1453f21222ae'::uuid, 'francais', '1re', 'Gil Blas de Santillane, Alain-René Lesage', 'Quel est le sommet de la carrière de Gil Blas ?', 'mcq', '["Archevêque de Grenade","Chef d’une troupe de comédiens","Secrétaire du duc de Lerme, premier ministre","Médecin à la cour du roi"]'::jsonb, 2, 'La faveur mène à la prison et à la disgrâce : l’ascension sociale est une roue qui tourne.', 3),
    ('72d94978-ac5d-5356-9789-ba45eb12a1c4'::uuid, 'francais', '1re', 'Gil Blas de Santillane, Alain-René Lesage', 'Quelle comédie de Lesage fait la satire des financiers ?', 'mcq', '["Le Joueur","Le Légataire universel","Le Bourgeois gentilhomme","Turcaret"]'::jsonb, 3, 'Comme Gil Blas, elle peint les mœurs de son temps ; ici, le pouvoir de l’argent.', 4),
    ('8aa1f610-fc83-54f7-9215-611c1c648d88'::uuid, 'francais', '1re', 'Harry Potter et le prisonnier d’Azkaban, J. K. Rowling', 'Quelle forme prend le Patronus de Harry ?', 'mcq', '["Un loup","Un phénix","Une loutre","Un cerf"]'::jsonb, 3, 'Le cerf rappelle son père : l’héritage des parents protège Harry contre les Détraqueurs.', 1),
    ('effb3dd9-1092-5f99-9aa0-92f78e75f852'::uuid, 'francais', '1re', 'Harry Potter et le prisonnier d’Azkaban, J. K. Rowling', 'Qui révèle que Lupin est un loup-garou ?', 'mcq', '["Severus Rogue","Drago Malefoy","Peter Pettigrow","Albus Dumbledore"]'::jsonb, 0, 'Le professeur hostile trahit le secret de son collègue : dans ce tome, les adultes ne se partagent plus simplement en bons et méchants.', 2),
    ('a9c4f7fb-aa55-5f2a-b234-8e215ed5be60'::uuid, 'francais', '1re', 'Harry Potter et le prisonnier d’Azkaban, J. K. Rowling', 'Pourquoi l’hippogriffe Buck est-il condamné ?', 'mcq', '["Il a attaqué Hagrid","Il a blessé Drago, qui l’avait provoqué","Il s’est échappé de la forêt","Il a aidé Sirius à s’évader"]'::jsonb, 1, 'Buck est condamné pour un accident, Sirius l’a été sans procès : l’injustice est l’un des thèmes du tome.', 3),
    ('3798eb84-08af-56f3-b916-19beff3319c2'::uuid, 'francais', '1re', 'Harry Potter et le prisonnier d’Azkaban, J. K. Rowling', 'De quoi les Détraqueurs sont-ils une image, comme Rowling l’a confirmé ?', 'mcq', '["De la guerre","De la vieillesse","De la dépression","De la trahison"]'::jsonb, 2, 'Ils aspirent les souvenirs heureux et laissent le froid et le désespoir : une peur que le Patronus apprend à affronter.', 4),
    ('f2d46cd8-c220-5040-aa80-8a6ff4b733cc'::uuid, 'francais', '1re', 'Hernani, Victor Hugo', 'Quel texte de Hugo, paru en 1827, sert de manifeste au drame romantique ?', 'mcq', '["La préface des Odes et Ballades","La préface de Cromwell","La préface de Ruy Blas","La préface des Orientales"]'::jsonb, 1, 'Hugo y réclame le mélange des genres et le rejet des unités ; Hernani, trois ans plus tard, applique ce programme sur la scène de la Comédie-Française.', 1),
    ('59a9ed05-482e-57e9-ba12-e5866e020b8b'::uuid, 'francais', '1re', 'Hernani, Victor Hugo', 'Pourquoi Hugo fait-il jouer Hernani en 1830 plutôt que Marion de Lorme ?', 'mcq', '["Marion de Lorme a été sifflée par les classiques","Marion de Lorme n’est pas encore écrite","La Comédie-Française refuse Marion de Lorme","Marion de Lorme a été interdite par la censure"]'::jsonb, 3, 'La censure ayant interdit Marion de Lorme en 1829, c’est Hernani qui est créé au temple du classicisme, le 25 février 1830.', 2),
    ('a402490a-7e5d-5f22-b95f-cd9527414521'::uuid, 'francais', '1re', 'Hernani, Victor Hugo', 'Quel écrivain assiste à la première d’Hernani en gilet rouge ?', 'mcq', '["Alfred de Musset","Alexandre Dumas","Théophile Gautier","Gérard de Nerval"]'::jsonb, 2, 'Le gilet rouge du jeune Gautier est resté le symbole des romantiques qui défendaient la pièce contre les sifflets des classiques.', 3),
    ('204dbd0a-05be-593e-92e3-b63660a01b9d'::uuid, 'francais', '1re', 'Hernani, Victor Hugo', 'Que fait don Carlos une fois devenu empereur ?', 'mcq', '["Il pardonne et permet le mariage des amants","Il fait exécuter Hernani pour trahison","Il épouse Doña Sol contre son gré","Il exile don Ruy Gomez hors d’Espagne"]'::jsonb, 0, 'Après son monologue au tombeau de Charlemagne, le roi passionné devient un souverain clément : c’est le serment du cor, et non le roi, qui ramène la tragédie.', 4),
    ('979bb808-feef-515b-b6ba-df9aef025957'::uuid, 'francais', '1re', 'Hippolyte, Euripide', 'Quelle déesse Hippolyte sert-il seule, au mépris d’Aphrodite ?', 'mcq', '["Athéna, déesse de la sagesse","Héra, l’épouse de Zeus","Artémis, la chaste chasseresse","Déméter, déesse des moissons"]'::jsonb, 2, 'Ce refus total de l’amour est l’excès que la pièce punit : Aphrodite et Artémis s’affrontent à travers les hommes.', 1),
    ('19bc8fea-7f76-56e5-947a-03a201f180b2'::uuid, 'francais', '1re', 'Hippolyte, Euripide', 'Comment Phèdre lutte-t-elle d’abord contre sa passion ?', 'mcq', '["Elle s’exile loin de Trézène","Elle se laisse mourir de faim","Elle avoue tout à Thésée","Elle supplie Artémis de l’aider"]'::jsonb, 1, 'Elle préfère mourir en silence : c’est la nourrice qui, en lui arrachant son secret, déclenche la catastrophe.', 2),
    ('ab95b0b5-ab22-5f22-809b-9db09452a472'::uuid, 'francais', '1re', 'Hippolyte, Euripide', 'Quel dieu exauce la malédiction de Thésée contre son fils ?', 'mcq', '["Zeus","Apollon","Arès","Poséidon"]'::jsonb, 3, 'Poséidon envoie un taureau surgi de la mer qui épouvante les chevaux d’Hippolyte : la parole du père tue aussi sûrement qu’une arme.', 3),
    ('644615a4-1de6-5b6a-b7a4-f8329e42df3a'::uuid, 'francais', '1re', 'Hippolyte, Euripide', 'Quel auteur latin a réécrit l’histoire de Phèdre entre Euripide et Racine ?', 'mcq', '["Sénèque","Plaute","Cicéron","Tite-Live"]'::jsonb, 0, 'Sénèque, puis Racine en 1677, reprennent le mythe en déplaçant son centre : chez Racine, l’accent passe de la vengeance divine à la conscience coupable.', 4),
    ('e88aad55-9438-54a0-935c-f3f82e0c9b7b'::uuid, 'francais', '1re', 'Histoire de Tom Jones, enfant trouvé, Henry Fielding', 'Quel roman Fielding parodie-t-il dans Joseph Andrews (1742) ?', 'mcq', '["Clarisse, de Richardson","Paméla, de Richardson","Robinson Crusoé, de Defoe","Tristram Shandy, de Sterne"]'::jsonb, 1, 'Contre la vertu calculée de Paméla, Fielding oppose déjà une peinture généreuse et comique de la nature humaine, qu’il développera dans Tom Jones (1749).', 1),
    ('2628b408-4ba1-5b8e-a763-b30bf8773e53'::uuid, 'francais', '1re', 'Histoire de Tom Jones, enfant trouvé, Henry Fielding', 'Comment Fielding définit-il le roman dans la préface de Joseph Andrews ?', 'mcq', '["Une histoire vraie racontée en lettres","Un traité de morale mis en récit","Un poème épique comique en prose","Une tragédie bourgeoise en prose"]'::jsonb, 2, 'Il y revient dans les chapitres-préfaces de Tom Jones, où il parle de son écriture « prosaï-comi-épique ».', 2),
    ('acd00a87-2fce-5426-b860-7eee5a2b119f'::uuid, 'francais', '1re', 'Histoire de Tom Jones, enfant trouvé, Henry Fielding', 'Pourquoi Sophia Western s’enfuit-elle de chez son père ?', 'mcq', '["Pour ne pas épouser Blifil","Pour rejoindre Tom en prison","Pour échapper à un procès","Pour chercher sa vraie mère"]'::jsonb, 0, 'Sa fuite vers Londres croise la route de Tom et ajoute aux méprises d’une intrigue « d’horlogerie », où tout se recolle à la fin.', 3),
    ('ee8a5bc5-9952-557a-a23a-c75bae0c8ad6'::uuid, 'francais', '1re', 'Histoire de Tom Jones, enfant trouvé, Henry Fielding', 'À qui le narrateur se compare-t-il pour présenter son livre ?', 'mcq', '["À un juge qui rend sa sentence","À un peintre devant son modèle","À un capitaine à la barre","À un aubergiste qui sert un repas"]'::jsonb, 3, 'La « provision » qu’il offre au lecteur, annonce-t-il au livre I, n’est autre que la nature humaine : le lecteur est un convive qu’on prend à témoin.', 4),
    ('7a10686f-fe6d-5d5c-9e6a-bb26c429a5df'::uuid, 'francais', '1re', 'Histoire du romantisme, Théophile Gautier', 'Quelle vocation le jeune Gautier a-t-il d’abord voulu suivre ?', 'mcq', '["Musicien","Comédien","Peintre","Avocat"]'::jsonb, 2, 'Ce goût des arts plastiques se retrouve dans ses portraits de la bande romantique, où figure le peintre et graveur Célestin Nanteuil.', 1),
    ('d39bd2e5-48a1-5dc1-b12a-86889215fc34'::uuid, 'francais', '1re', 'Histoire du romantisme, Théophile Gautier', 'Qu’était en réalité le fameux « gilet rouge » de la première d’Hernani ?', 'mcq', '["Un pourpoint de satin cerise","Une écharpe de soie écarlate","Un habit de velours vert","Une cape de drap pourpre"]'::jsonb, 0, 'Gautier corrige lui-même la légende : le vêtement avait été taillé exprès pour la soirée, et il est devenu le symbole d’une génération.', 2),
    ('8c8be6ff-2b54-53cf-860a-e5cba970e470'::uuid, 'francais', '1re', 'Histoire du romantisme, Théophile Gautier', 'Comment s’appelle le groupe des jeunes romantiques que Gautier raconte ?', 'mcq', '["La Pléiade","Le petit cénacle","Le groupe de Médan","L’Oulipo"]'::jsonb, 1, 'Nerval, Pétrus Borel, Célestin Nanteuil ou Philothée O’Neddy en font partie : Gautier en raconte les excentricités, les modes et les manifestes.', 3),
    ('2ddbc76b-5a6d-5763-b412-ab1c0f2d91f0'::uuid, 'francais', '1re', 'Histoire du romantisme, Théophile Gautier', 'Quel mouvement poétique l’« art pour l’art » de Gautier annonce-t-il ?', 'mcq', '["Le symbolisme","Le surréalisme","Le naturalisme","Le Parnasse"]'::jsonb, 3, 'Dans Émaux et Camées et la préface de Mademoiselle de Maupin, Gautier défend un art qui ne sert à rien : c’est la voie que suivront les Parnassiens.', 4),
    ('7e797783-0e73-5086-b120-d8e87346b7b3'::uuid, 'francais', '1re', 'Horace, Pierre Corneille', 'Après quelle querelle Corneille écrit-il une tragédie plus régulière ?', 'mcq', '["La querelle des Anciens et des Modernes","La querelle du Cid","La bataille d’Hernani","La querelle de L’École des femmes"]'::jsonb, 1, 'En 1637, on avait reproché au Cid de ne pas respecter les règles ; Horace, en 1640, répond par une tragédie plus régulière.', 1),
    ('044c850b-e0ac-5bad-9f62-e5f7a05a8c22'::uuid, 'francais', '1re', 'Horace, Pierre Corneille', 'À qui Corneille dédie-t-il Horace ?', 'mcq', '["À Louis XIV","À Mazarin","À Richelieu","À Anne d’Autriche"]'::jsonb, 2, 'Dédier au cardinal une pièce sur le service de l’État n’a rien de neutre : Horace interroge le prix de la grandeur d’État.', 2),
    ('5be9dcff-7a09-5743-81ec-3ecc53605ff6'::uuid, 'francais', '1re', 'Horace, Pierre Corneille', 'Qui est Sabine ?', 'mcq', '["La sœur d’Horace, fiancée à Curiace","La mère des trois Horaces","La confidente de Camille","La sœur des Curiaces, épouse d’Horace"]'::jsonb, 3, 'Symétrique de Camille, elle est déchirée entre sa famille d’Albe et son mari romain : le combat la blesse, quel que soit le vainqueur.', 3),
    ('4d73d1aa-53c0-5001-9567-2fcab02a1d64'::uuid, 'francais', '1re', 'Horace, Pierre Corneille', 'Par quel vers s’ouvre l’imprécation de Camille contre Rome ?', 'mcq', '["« Rome, l’unique objet de mon ressentiment ! »","« Rome n’est plus dans Rome, elle est toute où je suis »","« Je suis maître de moi comme de l’univers »","« Ô rage ! ô désespoir ! ô vieillesse ennemie ! »"]'::jsonb, 0, 'Camille préfère son amour à sa patrie ; Horace la tue, et la pièce laisse ouverte la question : héros ou monstre ?', 4),
    ('3846387b-a679-5143-a55f-2d19f8525ff5'::uuid, 'francais', '1re', 'Huis clos, Jean-Paul Sartre', 'Quand et où Huis clos est-il créé ?', 'mcq', '["En 1938, à la Comédie-Française","En 1944, au théâtre du Vieux-Colombier","En 1947, au théâtre de l’Odéon","En 1951, au théâtre de l’Atelier"]'::jsonb, 1, 'Créée le 27 mai 1944, sous l’Occupation, quelques jours avant le Débarquement, un an après L’Être et le Néant.', 1),
    ('81f2437a-0319-5850-8194-6d5debeab1ec'::uuid, 'francais', '1re', 'Huis clos, Jean-Paul Sartre', 'Qu’est-ce que Garcin attend d’Inès ?', 'mcq', '["Qu’elle lui pardonne sa trahison","Qu’elle l’aide à ouvrir la porte","Qu’elle le croie courageux","Qu’elle l’aime comme Estelle"]'::jsonb, 2, 'Estelle veut Garcin, Inès veut Estelle, Garcin veut le regard d’Inès : chacun a besoin d’un autre qui le lui refuse, et le triangle est sans issue.', 2),
    ('f85442e2-a833-54e4-913e-1df29d91a08a'::uuid, 'francais', '1re', 'Huis clos, Jean-Paul Sartre', 'Selon la pièce, pourquoi Garcin est-il un lâche ?', 'mcq', '["Parce que sa nature est lâche depuis l’enfance","Parce que les autres en ont décidé ainsi","Parce que la guerre rend tout homme lâche","Parce qu’il a fui : on est la somme de ses actes"]'::jsonb, 3, 'Pour l’existentialisme, il n’y a pas d’essence, seulement des actes ; et, mort, Garcin ne peut plus rien faire pour changer ce qu’il a été.', 3),
    ('ccea26b5-4e19-5966-bf6e-9edb632b7575'::uuid, 'francais', '1re', 'Huis clos, Jean-Paul Sartre', 'Qu’appelle-t-on la « mauvaise foi » dans la pièce ?', 'mcq', '["Se raconter une version flatteuse de sa vie","Refuser de croire en Dieu ou au diable","Mentir aux autres pour mieux les blesser","Trahir une promesse faite à un proche"]'::jsonb, 0, 'Chacun des trois morts arrange son passé pour s’en donner une belle image ; le regard des deux autres fait tomber ces mensonges.', 4),
    ('94d21f2a-c349-5dc5-a985-20dd5d2e7762'::uuid, 'francais', '1re', 'Iliade, Homère', 'Quelle part de la guerre de Troie l’Iliade raconte-t-elle ?', 'mcq', '["Les dix années entières du siège","Cinquante et un jours de la dixième année","La seule nuit de la prise de Troie","La première année, après l’enlèvement d’Hélène"]'::jsonb, 1, 'Le poème ne raconte pas toute la guerre mais l’épisode de la colère d’Achille : la chute de Troie n’y figure pas.', 1),
    ('b47dad5d-14e9-5742-904a-53103f71cd08'::uuid, 'francais', '1re', 'Iliade, Homère', 'Quels dieux prennent le parti des Troyens ?', 'mcq', '["Athéna et Héra","Zeus et Poséidon","Apollon et Aphrodite","Hermès et Héphaïstos"]'::jsonb, 2, 'Athéna et Héra soutiennent les Grecs, Zeus arbitre : les dieux interviennent sans cesse dans les combats.', 2),
    ('07695a0f-3f77-5965-9ade-596497d5cea0'::uuid, 'francais', '1re', 'Iliade, Homère', 'Qu’est-ce qu’un aède ?', 'mcq', '["Un prêtre qui interprète les oracles","Un scribe qui recopie les poèmes","Un acteur de tragédie masquée","Un poète chanteur qui dit l’épopée"]'::jsonb, 3, 'Homère est présenté comme un aède d’Ionie : l’Iliade est l’aboutissement d’une longue tradition orale.', 3),
    ('079fd3a1-43ce-5064-adf0-883c28311109'::uuid, 'francais', '1re', 'Iliade, Homère', 'Quel procédé épique le « dénombrement des vaisseaux » illustre-t-il ?', 'mcq', '["Le catalogue","L’épithète de nature","La comparaison développée","L’invocation à la Muse"]'::jsonb, 0, 'La longue liste des navires venus à Troie donne à la guerre son ampleur ; elle s’ajoute aux épithètes et aux comparaisons développées.', 4),
    ('5dc3c306-ae68-5f94-813d-97e51299ae22'::uuid, 'francais', '1re', 'Illuminations, Arthur Rimbaud', 'Quels textes du recueil sont écrits en vers libres ?', 'mcq', '["« Aube » et « Génie »","« Marine » et « Mouvement »","« Villes » et « Barbare »","« Départ » et « Solde »"]'::jsonb, 1, 'Le vers libre y apparaît quinze ans avant sa généralisation ; le reste du recueil est fait de poèmes en prose.', 1),
    ('802e3ac0-7962-5956-8c5a-6054be15b641'::uuid, 'francais', '1re', 'Illuminations, Arthur Rimbaud', 'Que raconte le poème « Aube » ?', 'mcq', '["Un départ en mer au lever du jour","Le réveil d’une ville moderne","Une nuit d’ivresse à Bruxelles","La poursuite d’une déesse jusqu’au réveil"]'::jsonb, 3, 'De « J’ai embrassé l’aube d’été » au réveil final, le poème suit la poursuite de la déesse-aube : un récit bref qui se referme comme un rêve.', 2),
    ('ce0af22b-a749-5dca-a315-03adaa2bf4a1'::uuid, 'francais', '1re', 'Illuminations, Arthur Rimbaud', 'Par quelle formule le poème « Départ » dit-il la rupture ?', 'mcq', '["« Assez vu. »","« Je est un autre. »","« J’ai embrassé l’aube d’été. »","« Il faut être absolument moderne. »"]'::jsonb, 0, 'Deux mots secs : le départ et la rupture sont des thèmes majeurs d’un recueil que Rimbaud laisse derrière lui avant de cesser d’écrire.', 3),
    ('6105009a-1404-510a-8f52-35ffaa67e920'::uuid, 'francais', '1re', 'Illuminations, Arthur Rimbaud', 'Selon le cours, que fait le poème des Illuminations ?', 'mcq', '["Il décrit fidèlement des paysages vus","Il raconte la liaison avec Verlaine","Il ne décrit plus : il produit une réalité","Il imite les formes du Parnasse"]'::jsonb, 2, 'Visions juxtaposées, villes suspendues, ponts de cristal : c’est l’aboutissement du programme du voyant, qui invente un monde au lieu de le copier.', 4),
    ('7f87dc67-49be-503d-8d6d-a96fc87eb714'::uuid, 'francais', '1re', 'Iphigénie, Jean Racine', 'Pourquoi la lettre d’Agamemnon n’arrête-t-elle pas Iphigénie ?', 'mcq', '["Ulysse l’intercepte et la détruit","Arcas, qui la porte, manque les voyageuses","Calchas en révèle le contenu à l’armée","Clytemnestre refuse de la lire"]'::jsonb, 1, 'Égarées en chemin, Iphigénie et Clytemnestre ne croisent pas Arcas : le remords du père arrive trop tard, et le piège se referme.', 1),
    ('66a519c8-67b9-5822-9ff3-cc03c2afb77a'::uuid, 'francais', '1re', 'Iphigénie, Jean Racine', 'De qui Ériphile est-elle la fille ?', 'mcq', '["D’Agamemnon et de Clytemnestre","De Priam et d’Hécube","De Léda et de Zeus","D’Hélène et de Thésée"]'::jsonb, 3, 'Elle est donc, elle aussi, une « Iphigénie » : Racine justifie cette invention, dans sa préface, par une autre tradition antique.', 2),
    ('7b0bde88-7ca7-5d11-beef-8cbb15b96343'::uuid, 'francais', '1re', 'Iphigénie, Jean Racine', 'Pourquoi la mort d’Ériphile est-elle racontée et non montrée ?', 'mcq', '["Pour respecter la bienséance classique","Pour abréger une pièce jugée trop longue","Pour suivre le dénouement d’Euripide","Pour obéir à la règle de l’unité de lieu"]'::jsonb, 0, 'Au théâtre classique, le sang ne coule pas sur scène : Ulysse fait le récit du dénouement dans un récit final.', 3),
    ('b8e6d045-1551-54f4-8476-5b031486fb53'::uuid, 'francais', '1re', 'Iphigénie, Jean Racine', 'Qui révèle qu’Ériphile est la victime réclamée par les dieux ?', 'mcq', '["Ulysse","Achille","Calchas","Arcas"]'::jsonb, 2, 'Le devin révèle qu’Ériphile est elle-même une « Iphigénie » : elle se tue sur l’autel, et les vents se lèvent.', 4),
    ('005264b4-afa8-55b0-9112-237603333f10'::uuid, 'francais', '1re', 'Isabelle, André Gide', 'Qui est Casimir ?', 'mcq', '["Le jeune frère de Gérard","Le jardinier du château","Le mari d’Isabelle","Le fils infirme d’Isabelle"]'::jsonb, 3, 'Enfant attachant, élevé par l’abbé Santal : l’indifférence de sa mère à son égard fait partie de ce que Gérard découvre.', 1),
    ('bf4b1309-d75c-5b95-85f8-9d97139d52fc'::uuid, 'francais', '1re', 'Isabelle, André Gide', 'Qui est M. Floche ?', 'mcq', '["Le notaire qui vend le domaine","Un vieil érudit qui possède les documents","L’ancien amant d’Isabelle","Le père de Gérard Lacase"]'::jsonb, 1, 'Gérard vient à La Quartfourche consulter ses documents pour sa thèse sur Bossuet.', 2),
    ('8ca83eb8-42e0-537f-ab8a-e7017805dfac'::uuid, 'francais', '1re', 'Isabelle, André Gide', 'Quelle œuvre Gide considère-t-il comme son unique « roman » ?', 'mcq', '["Les Caves du Vatican","La Porte étroite","Les Faux-Monnayeurs","L’Immoraliste"]'::jsonb, 2, 'Il distingue ses « récits » (L’Immoraliste, La Porte étroite, Isabelle), ses « soties » (Les Caves du Vatican) et son seul « roman ».', 3),
    ('f03d8671-fabc-5aac-a20f-36e30e5b68d0'::uuid, 'francais', '1re', 'Isabelle, André Gide', 'Selon le cours, d’où naît le romanesque dans Isabelle ?', 'mcq', '["D’un manque d’information, que le réel corrige","D’une passion partagée par deux amants","D’un héritage disputé par la famille","D’un crime découvert par le narrateur"]'::jsonb, 0, 'Gérard invente une héroïne à partir d’une lettre ; quand Isabelle paraît, le rêve meurt de sa correction, et la littérature est accusée de fabriquer des attentes.', 4),
    ('867d0a3b-490c-513a-9af6-ca540c42b2d7'::uuid, 'francais', '1re', 'Ivanhoé, Walter Scott', 'Pourquoi Cedric a-t-il déshérité son fils Wilfred ?', 'mcq', '["Il a trahi les Saxons au tournoi","Il a épousé Rebecca en secret","Il a suivi Richard et aimé Rowena","Il a refusé de partir en croisade"]'::jsonb, 2, 'Pour le Saxon Cedric, suivre le roi Richard Cœur de Lion est impardonnable : Wilfred revient de croisade en déshérité, d’où la devise « Desdichado ».', 1),
    ('9335e6f8-2a69-584b-9cd6-11e02e450ecb'::uuid, 'francais', '1re', 'Ivanhoé, Walter Scott', 'Quel roman, publié anonymement en 1814, lance Scott comme romancier ?', 'mcq', '["Rob Roy","Waverley","Quentin Durward","Kenilworth"]'::jsonb, 1, 'On l’appellera longtemps « l’auteur de Waverley » ; Ivanhoé, en 1819, est le premier de ses romans situé en Angleterre.', 2),
    ('1a96a321-eec2-5d3a-b455-6058b409d201'::uuid, 'francais', '1re', 'Ivanhoé, Walter Scott', 'Dans la recette du roman historique, quelle place ont les personnages réels ?', 'mcq', '["Ils mènent l’intrigue au premier plan","Ils sont remplacés par des allégories","Ils sont tous inventés par l’auteur","Ils restent à l’arrière-plan de la fiction"]'::jsonb, 3, 'Une intrigue fictive se noue dans une époque documentée, et la couleur locale reconstitue la langue et les costumes.', 3),
    ('9aba8a0a-4845-5448-a857-2ba78f5fad7a'::uuid, 'francais', '1re', 'Ivanhoé, Walter Scott', 'Qui est Isaac d’York ?', 'mcq', '["Le père de Rebecca, prêteur humilié","Le templier rival d’Ivanhoé","L’écuyer fidèle d’Ivanhoé","Le tuteur saxon de Rowena"]'::jsonb, 0, 'À travers lui et sa fille Rebecca, le roman montre l’intolérance envers les Juifs dans l’Angleterre médiévale.', 4),
    ('7c4b19a1-5a2a-5429-a612-7d52861ec412'::uuid, 'francais', '1re', 'Jacques le fataliste, Denis Diderot', 'Où Jacques a-t-il été blessé au genou ?', 'mcq', '["À la bataille de Fontenoy","Au siège de Maastricht","À la bataille de Rocroi","Dans un duel à Paris"]'::jsonb, 0, 'Le valet bavard est un ancien soldat ; son maître, lui, n’a même pas de nom et dépend de lui.', 1),
    ('b1415b99-6bf5-5e11-b38a-5d384730bf63'::uuid, 'francais', '1re', 'Jacques le fataliste, Denis Diderot', 'Comment Madame de La Pommeraye se venge-t-elle du marquis des Arcis ?', 'mcq', '["En le ruinant au jeu","En le dénonçant à la police","En lui faisant épouser une ancienne fille de joie","En séduisant son meilleur ami"]'::jsonb, 2, 'Abandonnée par le marquis, elle monte une machination patiente ; l’hôtesse du Grand-Cerf raconte cette histoire, la plus célèbre des digressions du livre.', 2),
    ('b89ef791-877a-5c3f-a8ea-f777bda7fd97'::uuid, 'francais', '1re', 'Jacques le fataliste, Denis Diderot', 'Où le texte circule-t-il d’abord, du vivant de Diderot ?', 'mcq', '["Dans l’Encyclopédie","Dans la Correspondance littéraire de Grimm","Dans le Mercure de France","Dans le Journal de Trévoux"]'::jsonb, 1, 'Cette publication était réservée à quelques princes d’Europe ; le livre n’est imprimé qu’en 1796, après la mort de Diderot.', 3),
    ('722381dc-f113-529e-9638-0695a2a8a7b6'::uuid, 'francais', '1re', 'Jacques le fataliste, Denis Diderot', 'Comment Diderot répond-il à la question « Sommes-nous libres ? »', 'mcq', '["Il prouve que l’homme est entièrement libre","Il condamne sans appel le fatalisme de Jacques","Il défend un fatalisme d’inspiration religieuse","Il ne tranche pas, il montre la contradiction"]'::jsonb, 3, 'Jacques professe que tout est écrit sur le grand rouleau, mais agit comme s’il était libre : la contradiction est laissée au jugement du lecteur.', 4),
    ('b156a5f8-ffd4-5849-bece-9eea336fce27'::uuid, 'francais', '1re', 'Jean de Florette, Marcel Pagnol', 'Que veulent cultiver les Soubeyran sur le domaine des Romarins ?', 'mcq', '["Des œillets","De la vigne","Des oliviers","Du blé"]'::jsonb, 0, 'Pour ces fleurs, il leur faut l’eau de la source : c’est pourquoi ils la bouchent en secret avant l’arrivée du nouvel héritier.', 1),
    ('ca1eb04a-2444-5fd6-99a2-c1ce9231dad2'::uuid, 'francais', '1re', 'Jean de Florette, Marcel Pagnol', 'Comment Jean fait-il face au manque d’eau ?', 'mcq', '["Il achète l’eau aux paysans du village","Il fait venir l’eau de la ville en charrette","Il porte des seaux depuis une source lointaine","Il détourne le ruisseau des Soubeyran"]'::jsonb, 2, 'Il s’épuise, s’endette et refuse d’abandonner, jusqu’à mourir en creusant, tué par une charge de mine.', 2),
    ('01b06618-fa22-5b5f-96c0-6ed7f5840b2c'::uuid, 'francais', '1re', 'Jean de Florette, Marcel Pagnol', 'Sous quel titre paraît le roman en deux volumes ?', 'mcq', '["Souvenirs d’enfance","L’Eau des collines","La Trilogie marseillaise","Le Temps des secrets"]'::jsonb, 1, 'Jean de Florette en est le premier volume ; le second, Manon des sources, est le récit de la vengeance.', 3),
    ('1d85fb1d-491e-5e77-a55c-53f0cefbd3c2'::uuid, 'francais', '1re', 'Jean de Florette, Marcel Pagnol', 'Qu’est-ce qui rend la construction du roman tragique ?', 'mcq', '["Le héros connaît son destin dès le début","Le village prédit la mort de Jean","Le narrateur annonce la fin au premier chapitre","Le lecteur sait la source bouchée, le héros l’ignore"]'::jsonb, 3, 'Chaque effort de Jean devient une souffrance pour le lecteur, qui partage le secret gardé par tout le village.', 4),
    ('b67c8186-053a-5aef-aa7e-a7708d20ff69'::uuid, 'francais', '1re', 'Journal des faux-monnayeurs, André Gide', 'Pendant quelles années Gide travaille-t-il aux Faux-Monnayeurs ?', 'mcq', '["De 1919 à 1925","De 1908 à 1911","De 1930 à 1936","De 1893 à 1897"]'::jsonb, 0, 'Pendant ces années, il tient un carnet réservé à ce seul chantier : c’est le Journal des faux-monnayeurs, publié en 1926.', 1),
    ('a1853eb4-bb8c-56f3-984e-df7556d06583'::uuid, 'francais', '1re', 'Journal des faux-monnayeurs, André Gide', 'Qu’est-ce qu’une mise en abyme ?', 'mcq', '["Un récit qui commence par sa fin","Une œuvre qui contient une image réduite d’elle-même","Un narrateur qui ment sciemment au lecteur","Un roman composé uniquement de lettres"]'::jsonb, 1, 'Dans le roman, Édouard prépare un livre intitulé Les Faux-Monnayeurs : l’œuvre se reflète en son centre, comme le petit écu dans le grand.', 2),
    ('6dd95bd8-1396-5818-9b35-16d5f31976f2'::uuid, 'francais', '1re', 'Journal des faux-monnayeurs, André Gide', 'Selon une formule du Journal, que doit être le roman pour Gide ?', 'mcq', '["« Un miroir qu’on promène le long d’un chemin »","« Une tranche de vie »","« Un carrefour — un rendez-vous de problèmes »","« Un poème épique comique en prose »"]'::jsonb, 2, 'Il ne veut ni description gratuite ni événements racontés pour eux-mêmes : le roman doit croiser les questions, pas seulement raconter.', 3),
    ('5a79ec99-9ab2-514c-ba23-9000460502f3'::uuid, 'francais', '1re', 'Journal des faux-monnayeurs, André Gide', 'Qui est Bernard Profitendieu dans le roman ?', 'mcq', '["Le neveu d’Édouard, ami de Bernard","L’écrivain mondain, rival d’Édouard","L’enfant dont le suicide clôt le roman","Le jeune homme qui se découvre bâtard"]'::jsonb, 3, 'Il quitte sa famille en découvrant qu’il est un bâtard ; son ami Olivier Molinier est le neveu d’Édouard.', 4),
    ('4ea1e2f7-fe96-5895-ad37-05fb26f870a5'::uuid, 'francais', '1re', 'Journal, André Gide', 'Quelle revue Gide a-t-il cofondée en 1908-1909 ?', 'mcq', '["Le Mercure de France","Les Temps modernes","La Revue blanche","La Nouvelle Revue française"]'::jsonb, 3, 'La NRF domine la vie littéraire de l’entre-deux-guerres ; le Journal en fait le portrait, de Claudel et Valéry à Proust, Malraux et Sartre.', 1),
    ('53b7f2fc-069e-545e-b343-f7e3c9b2b24f'::uuid, 'francais', '1re', 'Journal, André Gide', 'Quel est, selon le cours, le fil de tout le Journal ?', 'mcq', '["L’exigence d’être sincère avec soi-même","Le récit suivi de ses voyages","La recherche d’un style classique","La défense de la foi protestante"]'::jsonb, 0, 'Gide s’examine sans complaisance et se reprend souvent, tout en sachant qu’il écrit pour être lu : c’est toute la difficulté.', 2),
    ('936b1dd2-5a25-5b40-b960-05d00e95ebb3'::uuid, 'francais', '1re', 'Journal, André Gide', 'Dans quelles œuvres Gide assume-t-il publiquement la liberté du désir ?', 'mcq', '["Les Caves du Vatican et Paludes","La Porte étroite et Isabelle","Corydon et Si le grain ne meurt","Voyage au Congo et Retour de l’URSS"]'::jsonb, 2, 'Le Journal accompagne ces livres, comme il accompagne ses engagements contre le colonialisme puis contre le stalinisme.', 3),
    ('682282fd-1ae9-5a05-8a8f-1bf8e54fd215'::uuid, 'francais', '1re', 'Journal, André Gide', 'Le Journal de Gide a été découvert et publié après sa mort, contre sa volonté.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un journal publié par son auteur, entré dans la Pléiade de son vivant : il est déjà une œuvre, écrite en pensant au lecteur.', 4),
    ('a79dccfa-7ac4-5b62-bf95-b40d67992040'::uuid, 'francais', '1re', 'Julie ou la Nouvelle Héloïse, Jean-Jacques Rousseau', 'Quel est le sous-titre de Julie ?', 'mcq', '["Lettres recueillies dans une société et publiées pour l’instruction de quelques autres","Mémoires et aventures d’un homme de qualité qui s’est retiré du monde","Lettres de deux amants habitants d’une petite ville au pied des Alpes","Histoire de deux amants malheureux sur les rives du lac Léman"]'::jsonb, 2, 'Rousseau se présente comme l’éditeur de ces lettres ; le premier sous-titre proposé ici est celui des Liaisons dangereuses.', 1),
    ('825072e7-0dc0-59fc-bf15-f240c9e2d71d'::uuid, 'francais', '1re', 'Julie ou la Nouvelle Héloïse, Jean-Jacques Rousseau', 'Qui Julie épouse-t-elle par obéissance à son père ?', 'mcq', '["Milord Édouard Bomston","M. de Wolmar","M. d’Orbe","Un magistrat de Genève"]'::jsonb, 1, 'Plus âgé, athée serein, sage et lucide, il accueillera plus tard Saint-Preux à Clarens en sachant tout de leur passé.', 2),
    ('6f81ce05-1709-5e41-9a9a-3ad46277afcc'::uuid, 'francais', '1re', 'Julie ou la Nouvelle Héloïse, Jean-Jacques Rousseau', 'Quel pari fait Wolmar en accueillant Saint-Preux à Clarens ?', 'mcq', '["Celui de les surprendre pour les chasser","Celui de le renvoyer au bout d’un mois","Celui de le convertir à la foi de Julie","Celui de la vertu, car il sait tout"]'::jsonb, 3, 'Il confie les anciens amants à leur propre vertu : Clarens est une utopie de la transparence des cœurs.', 3),
    ('55968a0c-619b-526a-bd64-877d1b28864a'::uuid, 'francais', '1re', 'Julie ou la Nouvelle Héloïse, Jean-Jacques Rousseau', 'Avec quel roman compare-t-on souvent Julie, pour l’usage opposé de la lettre ?', 'mcq', '["Les Liaisons dangereuses, de Laclos","Manon Lescaut, de l’abbé Prévost","Candide, de Voltaire","La Princesse de Clèves, de Mme de La Fayette"]'::jsonb, 0, 'Même forme épistolaire en 1782 : chez Rousseau, la lettre donne accès à l’intimité des cœurs ; chez Laclos, elle sert à tromper.', 4),
    ('56997222-f9cc-5777-bfb6-46b6cb41a8f8'::uuid, 'francais', '1re', 'Juste la fin du monde, Jean-Luc Lagarce', 'Quel âge a Louis quand il revient dans sa famille ?', 'mcq', '["Vingt-quatre ans","Trente-quatre ans","Quarante-quatre ans","Cinquante-quatre ans"]'::jsonb, 1, 'Il revient après des années d’absence pour annoncer sa mort prochaine, qu’il confie au public dès le prologue.', 1),
    ('5eead1bd-6dc2-5de4-ac67-763edddfdb9e'::uuid, 'francais', '1re', 'Juste la fin du monde, Jean-Luc Lagarce', 'Comment la pièce est-elle construite ?', 'mcq', '["En cinq actes et en vers","En un acte unique, sans pause","En trois tableaux avec un chœur","Prologue, deux parties, intermède, épilogue"]'::jsonb, 3, 'Le prologue et l’épilogue, adressés au public, encadrent la pièce : Louis y est à la fois personnage et narrateur.', 2),
    ('2a7994d8-3b16-562c-8a01-9875f40317c8'::uuid, 'francais', '1re', 'Juste la fin du monde, Jean-Luc Lagarce', 'Dans quelles conditions Lagarce écrit-il la pièce ?', 'mcq', '["À Berlin en 1990, se sachant malade","À Avignon en 1985, pour le festival","À Paris en 1995, l’année de sa mort","À Besançon en 1980, pour sa troupe"]'::jsonb, 0, 'Refusée d’abord par les théâtres, la pièce n’est montée qu’après sa mort, puis entre au répertoire de la Comédie-Française en 2008.', 3),
    ('f2ac910a-2113-57d9-97fa-d0ae3d91642b'::uuid, 'francais', '1re', 'Juste la fin du monde, Jean-Luc Lagarce', 'Que raconte Louis dans l’épilogue ?', 'mcq', '["Son retour en train vers la ville","L’annonce enfin faite de sa mort","Une marche de nuit où il n’a pas crié","Le repas de famille qui recommence"]'::jsonb, 2, 'Le long d’une voie ferrée, il voulait pousser un grand cri et ne l’a pas fait : l’image résume une pièce où l’essentiel n’est jamais dit.', 4),
    ('6f73ee63-50b3-58ef-bd8d-061b02f5a4a3'::uuid, 'francais', '1re', 'L’Adolescence clémentine, Clément Marot', 'Au service de quelle protectrice Marot entre-t-il ?', 'mcq', '["Diane de Poitiers","Marguerite de Navarre","Catherine de Médicis","Anne de Bretagne"]'::jsonb, 1, 'Sœur de François Ier, elle protège les évangéliques ; Marot, soupçonné de sympathie pour la Réforme, a besoin de cet appui.', 1),
    ('8ed9c9ff-27f1-55fd-8e5a-40ae9688ec93'::uuid, 'francais', '1re', 'L’Adolescence clémentine, Clément Marot', 'Après quel événement Marot doit-il s’exiler ?', 'mcq', '["La Saint-Barthélemy","Le concordat de Bologne","L’affaire des Placards","L’édit de Nantes"]'::jsonb, 2, 'En 1534, des affiches contre la messe déclenchent la répression des suspects de Réforme ; Marot fuit, et il meurt à Turin en 1544.', 2),
    ('931d8cde-4e88-5bca-bd55-052b310ae53e'::uuid, 'francais', '1re', 'L’Adolescence clémentine, Clément Marot', 'Quels textes traduits par Marot seront chantés par les protestants ?', 'mcq', '["Les Psaumes","Les Fables d’Ésope","Les Évangiles","Les Odes d’Horace"]'::jsonb, 0, 'Ses Psaumes (1541-1543) viennent après l’Adolescence clémentine, qui contient déjà sa traduction de la première Bucolique de Virgile.', 3),
    ('c5e59061-88f6-5053-a104-280608b951a5'::uuid, 'francais', '1re', 'L’Adolescence clémentine, Clément Marot', 'Quels écrivains se réclameront du style de Marot ?', 'mcq', '["Ronsard et Du Bellay","Corneille et Racine","Hugo et Lamartine","La Fontaine et Voltaire"]'::jsonb, 3, 'Ils admirent sa liberté de ton, son humour et l’art de la pointe finale, alors que la Pléiade rejettera ses formes médiévales.', 4),
    ('7fbc09f0-576d-5158-8b73-382d6bfbd213'::uuid, 'francais', '1re', 'L’Amant, Marguerite Duras', 'Quelle tenue singulière porte la jeune fille sur le bac ?', 'mcq', '["Un casque colonial et des sandales","Un feutre d’homme et des chaussures de lamé","Un uniforme de pension et un canotier","Une robe de soie et un éventail"]'::jsonb, 1, 'C’est dans cette tenue, pauvre et insolite, qu’elle traverse le Mékong le jour où le Chinois de Cholen l’aborde.', 1),
    ('ebb329c5-0ac6-5dd0-9cae-380517991480'::uuid, 'francais', '1re', 'L’Amant, Marguerite Duras', 'Quel procédé fait varier la distance entre la narratrice et son personnage ?', 'mcq', '["Le passage de la prose aux vers","Le recours au dialogue théâtral","L’alternance du « je » et du « elle »","L’insertion de lettres dans le récit"]'::jsonb, 2, 'La jeune fille est tantôt « je », tantôt « elle » : la narratrice se souvient et se regarde de loin, entre autobiographie et fiction.', 2),
    ('b2e3157d-f355-5a72-8cc7-16c719496871'::uuid, 'francais', '1re', 'L’Amant, Marguerite Duras', 'De quel film Duras a-t-elle écrit le scénario en 1959 ?', 'mcq', '["Jules et Jim","À bout de souffle","Les Quatre Cents Coups","Hiroshima mon amour"]'::jsonb, 3, 'Avant L’Amant, Duras est déjà une autrice reconnue : romancière d’Un barrage contre le Pacifique et scénariste pour le cinéma.', 3),
    ('ff28abad-9bad-5ff5-8400-684e994672b0'::uuid, 'francais', '1re', 'L’Amant, Marguerite Duras', 'Dans quel livre Duras reprend-elle la même matière en 1991 ?', 'mcq', '["L’Amant de la Chine du Nord","Un barrage contre le Pacifique","Le Vice-consul","La Douleur"]'::jsonb, 0, 'Chez Duras, les souvenirs reviennent de livre en livre sous des formes nouvelles : L’Amant (1984) reprenait déjà la jeunesse indochinoise.', 4),
    ('0f42db7c-9db6-58f3-9305-1e09f8cc405e'::uuid, 'francais', '1re', 'L’Argent, Émile Zola', 'Quel rang L’Argent occupe-t-il dans les Rougon-Macquart ?', 'mcq', '["Le dixième volume","Le quinzième volume","Le dix-huitième volume","Le vingtième volume"]'::jsonb, 2, 'Paru en 1891, il reprend Aristide Saccard, déjà héros de La Curée, passé de la spéculation immobilière à la Bourse.', 1),
    ('d17cb6be-154a-584d-9e4d-0355cd812ea0'::uuid, 'francais', '1re', 'L’Argent, Émile Zola', 'Que doit financer la Banque universelle de Saccard ?', 'mcq', '["Des mines de charbon dans le Nord","De grands travaux en Orient","Les grands magasins parisiens","Le percement du canal de Panama"]'::jsonb, 1, 'Les projets sont portés par l’ingénieur honnête Georges Hamelin ; Saccard, lui, en fait une machine à spéculer.', 2),
    ('3b588c6c-0668-5bf1-b44d-1e69a330bffc'::uuid, 'francais', '1re', 'L’Argent, Émile Zola', 'Quel rôle la presse joue-t-elle dans l’ascension de la Banque ?', 'mcq', '["Elle dénonce la fraude dès le début","Elle reste neutre et informe les épargnants","Elle provoque à elle seule l’effondrement","Elle fabrique l’enthousiasme et fait monter le cours"]'::jsonb, 3, 'Une campagne de presse gonfle artificiellement l’action et entraîne jusqu’aux petits épargnants : finance et presse s’allient pour fabriquer l’opinion.', 3),
    ('bb296bc2-1227-5774-99f0-c61faa3dbfc4'::uuid, 'francais', '1re', 'L’Argent, Émile Zola', 'Qui est Victor ?', 'mcq', '["Le fils naturel de Saccard, grandi dans la misère","Le frère de Madame Caroline","Le comptable de Gundermann","Un petit épargnant ruiné"]'::jsonb, 0, 'Devenu brutal, il est la face sombre de la vie de Saccard, que Madame Caroline, conscience du roman, découvre.', 4),
    ('804cb958-a497-516c-843f-dba24e146cef'::uuid, 'francais', '1re', 'L’Art poétique, Nicolas Boileau', 'Sur quel modèle antique Boileau compose-t-il L’Art poétique ?', 'mcq', '["La Poétique d’Aristote","L’Art poétique d’Horace","L’Énéide de Virgile","Les Métamorphoses d’Ovide"]'::jsonb, 1, 'Boileau reprend le poème didactique d’Horace, qui donnait déjà en vers des conseils aux poètes ; la Poétique d’Aristote, elle, est un traité en prose.', 1),
    ('a497cd39-66a2-5fb6-b99e-0a9a35f44021'::uuid, 'francais', '1re', 'L’Art poétique, Nicolas Boileau', 'Que signifie le précepte « Le vrai peut quelquefois n’être pas vraisemblable » ?', 'mcq', '["Il faut raconter les faits exactement comme ils se sont passés","Une histoire vraie vaut toujours mieux qu’une histoire inventée","Mieux vaut ce que le public peut croire que ce qui est seulement arrivé","Le théâtre doit renoncer à dire la moindre vérité"]'::jsonb, 2, 'C’est la primauté du vraisemblable sur le vrai : un fait réel mais incroyable choque le spectateur, que la fiction doit pouvoir convaincre.', 2),
    ('e551af29-2a58-56fc-bcfd-3372b7bb5f84'::uuid, 'francais', '1re', 'L’Art poétique, Nicolas Boileau', 'Quels conseils Boileau réserve-t-il au chant IV ?', 'mcq', '["Les règles des grands genres : tragédie, épopée, comédie","Les règles des genres brefs : ode, sonnet, satire","Les règles générales : clarté, travail, vraisemblance","L’intégrité morale, la patience, le refus de la flatterie"]'::jsonb, 3, 'Le dernier chant s’adresse au poète lui-même : après les règles de l’écriture, Boileau lui fixe une conduite, patiente et honnête, loin de l’argent facile.', 3),
    ('2e9dc335-fb4c-58c3-8549-bcfeb5d32c40'::uuid, 'francais', '1re', 'L’Art poétique, Nicolas Boileau', 'Quel surnom a longtemps désigné Boileau ?', 'mcq', '["Le législateur du Parnasse","Le prince des poètes","Le père du romantisme","Le Molière des vers"]'::jsonb, 0, 'On le crut longtemps l’auteur des lois de la poésie ; les romantiques rejetteront violemment ce « législateur » et ses règles.', 4),
    ('0a24b25c-016c-5503-9a45-84c494236c9e'::uuid, 'francais', '1re', 'L’Assommoir, Émile Zola', 'Quel repas marque l’apogée de Gervaise ?', 'mcq', '["Le repas de sa noce","Le dîner chez les Lorilleux","La fête de l’oie","Le souper chez Goujet"]'::jsonb, 2, 'La fête de l’oie couronne l’ascension de la blanchisseuse devenue patronne de sa boutique : Zola place ce banquet juste avant la glissade.', 1),
    ('dd0dd8fa-0fb0-5084-a027-18cf2578ebbd'::uuid, 'francais', '1re', 'L’Assommoir, Émile Zola', 'Qui sont les Lorilleux ?', 'mcq', '["Des cabaretiers amis du père Colombe","La sœur de Coupeau et son mari, chaînistes","Les parents de Virginie, blanchisseurs","Des forgerons, collègues de Goujet"]'::jsonb, 1, 'Avares et envieux, les Lorilleux incarnent la mesquinerie du milieu qui entoure Gervaise.', 2),
    ('3fd8d2bc-32df-5151-97a0-e24c36f10800'::uuid, 'francais', '1re', 'L’Assommoir, Émile Zola', 'De quoi Coupeau meurt-il ?', 'mcq', '["D’une nouvelle chute d’un toit","D’une rixe à l’Assommoir","De faim, sous un escalier","Du delirium tremens, à Sainte-Anne"]'::jsonb, 3, 'L’alcool le tue : le delirium tremens est la crise de folie des alcooliques. C’est Gervaise qui meurt de misère sous un escalier.', 3),
    ('f83f536a-f2a0-5fa5-bd9a-81585c415a60'::uuid, 'francais', '1re', 'L’Assommoir, Émile Zola', 'Quelle thèse naturaliste le roman illustre-t-il ?', 'mcq', '["Le milieu et l’hérédité écrasent l’individu","Le travail suffit à sortir de la misère","Le peuple est corrompu par nature","L’argent fait le bonheur des ouvriers"]'::jsonb, 0, 'Ce déterminisme n’empêche pas la compassion : Zola montre une femme courageuse et bonne, broyée par ce qui la dépasse.', 4),
    ('db352a64-debc-5598-8467-3f5fba5441c0'::uuid, 'francais', '1re', 'L’Avare, Molière', 'Quel rôle Molière tenait-il lui-même à la création de L’Avare ?', 'mcq', '["Valère","Maître Jacques","Harpagon","La Flèche"]'::jsonb, 2, 'Chef de troupe, Molière jouait les grands rôles comiques : il créa Harpagon au Palais-Royal, en septembre 1668.', 1),
    ('94291637-3e0f-5207-aeb6-1dc28bfca393'::uuid, 'francais', '1re', 'L’Avare, Molière', 'Pourquoi Valère flatte-t-il Harpagon ?', 'mcq', '["Pour rester près d’Élise, qu’il aime","Pour lui voler sa cassette","Pour épouser Mariane","Pour obtenir de lui un prêt"]'::jsonb, 0, 'Entré au service de la maison comme intendant, Valère approuve tout ce que dit l’avare afin de rester auprès d’Élise.', 2),
    ('c9304f79-9ba5-522f-b94b-da3e8e52a80f'::uuid, 'francais', '1re', 'L’Avare, Molière', 'Qui est Frosine ?', 'mcq', '["La servante d’Élise","La mère de Mariane","La sœur d’Anselme","L’entremetteuse qui vit d’intrigues"]'::jsonb, 3, 'Une entremetteuse arrange les mariages et les rencontres : Frosine vit de ses intrigues et de ce qu’elles lui rapportent.', 3),
    ('c6ff0c50-e00b-5afe-8a2e-32ef2f5c51df'::uuid, 'francais', '1re', 'L’Avare, Molière', 'À quel type de comique appartient la réplique « Sans dot ! », répétée par Harpagon ?', 'mcq', '["Le comique de gestes","Le comique de répétition","Le comique de situation","Le comique de mots"]'::jsonb, 1, 'Harpagon répète « sans dot » comme un argument qui répond à tout : la répétition révèle l’idée fixe de l’avare.', 4),
    ('6b3f3183-f5fd-5e54-b013-5421806cdb69'::uuid, 'francais', '1re', 'L’Écume des jours, Boris Vian', 'Qui est Nicolas dans L’Écume des jours ?', 'mcq', '["Le cuisinier de Colin","Le médecin de Chloé","Le rival amoureux de Colin","Le philosophe admiré par Chick"]'::jsonb, 0, 'Nicolas prépare les repas raffinés de Colin : il appartient à l’univers de luxe et de fantaisie du début du roman.', 1),
    ('73b541dc-a4c1-5c11-a75f-f3f8f2a1e9c2'::uuid, 'francais', '1re', 'L’Écume des jours, Boris Vian', 'Quel prix le roman avait-il manqué ?', 'mcq', '["Le prix Goncourt","Le prix Renaudot","Le prix de la Pléiade","Le prix Femina"]'::jsonb, 2, 'Longtemps ignoré après cet échec, le roman n’est devenu le livre adoré des lycéens qu’à partir des années 1960.', 2),
    ('6b77bac9-8a6e-55d6-b10d-910e00a1407f'::uuid, 'francais', '1re', 'L’Écume des jours, Boris Vian', 'Quel paradoxe l’avant-propos énonce-t-il ?', 'mcq', '["L’histoire est fausse parce qu’elle a été vécue","L’histoire est entièrement vraie puisque l’auteur l’a imaginée","L’histoire est vraie parce que Chloé a existé","L’histoire est un rêve que l’auteur a oublié"]'::jsonb, 1, 'Vian renverse le rapport du vrai et de l’inventé : la fiction dit une vérité à sa manière.', 3),
    ('85de0b7b-af30-5409-97f4-7c5bcff6aa37'::uuid, 'francais', '1re', 'L’Écume des jours, Boris Vian', 'Quelles cibles la satire du roman vise-t-elle ?', 'mcq', '["La guerre, la police et l’école","L’argent, la médecine et le mariage","La presse, le cinéma et le sport","Le travail, la religion et la mode intellectuelle"]'::jsonb, 3, 'Le travail y est une machine qui use les hommes ; la mode intellectuelle, c’est Sartre caricaturé en Jean-Sol Partre.', 4),
    ('6dd432a1-3da6-5518-9120-b745472de02f'::uuid, 'francais', '1re', 'L’Éducation sentimentale, Gustave Flaubert', 'Quel est le sous-titre de L’Éducation sentimentale ?', 'mcq', '["« Mœurs de province »","« Chronique de 1830 »","« Histoire d’un jeune homme »","« Scènes de la vie parisienne »"]'::jsonb, 2, 'Il annonce un roman d’apprentissage… dont le héros n’apprend que la désillusion. « Mœurs de province » est le sous-titre de Madame Bovary.', 1),
    ('4604a674-5816-58d9-be59-126d754e5505'::uuid, 'francais', '1re', 'L’Éducation sentimentale, Gustave Flaubert', 'Où Frédéric aperçoit-il Madame Arnoux pour la première fois ?', 'mcq', '["Sur un bateau, la Ville-de-Montereau","Dans la boutique d’art de son mari","Dans un bal de l’Opéra","Sur la plage de Trouville"]'::jsonb, 0, 'L’incipit s’ouvre sur ce bateau, quai Saint-Bernard, le 15 septembre 1840. Trouville est le lieu où Flaubert, lui, avait rencontré Élisa Schlésinger.', 2),
    ('f875baf3-0966-5db4-8a65-bed5cebe5270'::uuid, 'francais', '1re', 'L’Éducation sentimentale, Gustave Flaubert', 'Qui est Deslauriers ?', 'mcq', '["Le mari de Madame Arnoux","Le républicain devenu agent de police","Le commis généreux tué en 1851","L’ami d’enfance ambitieux, rival discret"]'::jsonb, 3, 'Deslauriers partage les rêves de Frédéric mais poursuit la réussite ; les deux amis se retrouvent, vieillis, au dernier chapitre.', 3),
    ('11cbfe46-c0fa-5222-862e-aaac99373cc0'::uuid, 'francais', '1re', 'L’Éducation sentimentale, Gustave Flaubert', 'Quels sont, selon le cours, les deux outils majeurs de Flaubert dans ce roman ?', 'mcq', '["Le lyrisme et l’emphase","L’ellipse et l’ironie","Le monologue et la lettre","Le suspense et le coup de théâtre"]'::jsonb, 1, 'L’ellipse fait passer des années en une phrase ; l’ironie tient à distance l’émotion et les illusions du héros.', 4),
    ('e837efdd-eb56-5caf-8516-91fe66047204'::uuid, 'francais', '1re', 'L’éloge de la folie, Érasme', 'Qui est Philautie, l’une des compagnes de la Folie ?', 'mcq', '["La Flatterie","L’Oubli","La Paresse","L’Amour-propre"]'::jsonb, 3, 'Philautie, c’est l’amour de soi : la Folie montre que chacun a besoin de s’illusionner sur lui-même pour vivre content.', 1),
    ('2c6cfe48-e8c0-5ff2-adc2-2756f6d65dcc'::uuid, 'francais', '1re', 'L’éloge de la folie, Érasme', 'Quel artiste a illustré les marges d’un exemplaire de L’Éloge de la folie ?', 'mcq', '["Albrecht Dürer","Holbein le Jeune","Jérôme Bosch","Pieter Bruegel"]'::jsonb, 1, 'Les dessins de Holbein le Jeune en marge du texte montrent combien le livre fut lu et goûté dans le monde humaniste.', 2),
    ('9ca858fe-d08c-5915-ad24-10461765d76d'::uuid, 'francais', '1re', 'L’éloge de la folie, Érasme', 'Quel surnom donne-t-on à Érasme ?', 'mcq', '["Le « prince des humanistes »","Le « père de la Réforme »","Le « docteur de la grâce »","Le « prince des poètes »"]'::jsonb, 0, 'Érasme domine l’Europe savante de son temps : auteur des Adages, il publie aussi le Nouveau Testament en grec (1516).', 3),
    ('937eb805-eb89-5d69-bf1e-31401cad7a23'::uuid, 'francais', '1re', 'L’éloge de la folie, Érasme', 'Selon la Folie, pourquoi est-elle indispensable ?', 'mcq', '["Parce qu’elle seule connaît la vérité sur Dieu","Parce que les savants lui doivent leurs découvertes","Parce que sans illusion, ni amour ni société ne tiendraient","Parce que les princes la consultent avant de gouverner"]'::jsonb, 2, 'C’est le premier temps, badin, du discours : l’illusion rend la vie supportable et les liens humains possibles.', 4),
    ('52c3794b-7fb2-54ae-8e00-e91fe3460a70'::uuid, 'francais', '1re', 'L’Étrange Cas du docteur Jekyll et de M. Hyde, Robert Louis Stevenson', 'Quel livre avait déjà rendu Stevenson célèbre ?', 'mcq', '["Le Portrait de Dorian Gray","Frankenstein","Le Horla","L’Île au trésor"]'::jsonb, 3, 'L’Île au trésor (1883) lui apporte le succès. Dorian Gray est de Wilde, Frankenstein de Mary Shelley, Le Horla de Maupassant.', 1),
    ('d952c3a6-0923-598a-a173-f369da038c16'::uuid, 'francais', '1re', 'L’Étrange Cas du docteur Jekyll et de M. Hyde, Robert Louis Stevenson', 'Qui est Poole ?', 'mcq', '["Le majordome de Jekyll, qui donne l’alerte","Le cousin d’Utterson","L’ancien ami de Jekyll, mort de saisissement","Le député assassiné par Hyde"]'::jsonb, 0, 'Fidèle majordome, Poole s’inquiète de ce qui se passe chez son maître : son alerte précipite le dénouement.', 2),
    ('00ad77db-574d-5aad-a36c-27162248a6f4'::uuid, 'francais', '1re', 'L’Étrange Cas du docteur Jekyll et de M. Hyde, Robert Louis Stevenson', 'Qui est la victime du meurtre commis par Hyde ?', 'mcq', '["Richard Enfield","Le docteur Lanyon","Sir Danvers Carew, un député","Gabriel Utterson"]'::jsonb, 2, 'Le meurtre de Carew fait de Hyde un criminel recherché ; Lanyon, lui, meurt de saisissement après avoir vu la transformation.', 3),
    ('2722a81e-a20c-5954-9f55-b076c9afefef'::uuid, 'francais', '1re', 'L’Étrange Cas du docteur Jekyll et de M. Hyde, Robert Louis Stevenson', 'Qu’est-ce qui précipite la fin de Jekyll ?', 'mcq', '["La police découvre son laboratoire","Il est à court de l’ingrédient de sa potion","Lanyon le dénonce à la police","Hyde est arrêté et jugé"]'::jsonb, 1, 'Sans l’ingrédient, il ne peut plus maîtriser ses transformations : il s’enferme et se suicide, laissant les documents qui expliquent tout.', 4),
    ('5a4000f8-132b-5cfb-ae64-2a6d753a1a14'::uuid, 'francais', '1re', 'L’Étranger, Albert Camus', 'Que raconte la seconde partie du roman ?', 'mcq', '["L’enterrement de la mère de Meursault","La liaison de Meursault avec Marie","L’instruction et le procès de Meursault","Le retour de Meursault en France"]'::jsonb, 2, 'Le roman bascule au coup de feu : la première partie mène jusqu’au meurtre, la seconde montre la société qui juge.', 1),
    ('c6c9c439-1d10-587a-92a9-7a36b52e2deb'::uuid, 'francais', '1re', 'L’Étranger, Albert Camus', 'Quel temps domine le récit de Meursault ?', 'mcq', '["Le passé composé","Le passé simple","Le présent de narration","Le plus-que-parfait"]'::jsonb, 0, 'Le passé composé, temps de l’oral, colle à l’instant et isole les phrases les unes des autres, loin du passé simple du roman traditionnel.', 2),
    ('0d44cf19-eb76-5886-9757-2404d973c018'::uuid, 'francais', '1re', 'L’Étranger, Albert Camus', 'Avec quelles œuvres L’Étranger forme-t-il le cycle de l’absurde ?', 'mcq', '["La Peste et L’Homme révolté","La Chute et Les Justes","Noces et L’Envers et l’Endroit","Le Mythe de Sisyphe et Caligula"]'::jsonb, 3, 'Un roman, un essai, une pièce : Camus explore l’absurde par trois genres. La Peste et L’Homme révolté appartiennent au cycle suivant, celui de la révolte.', 3),
    ('3217720b-7531-5c45-9a2a-c851213d2a29'::uuid, 'francais', '1re', 'L’Étranger, Albert Camus', 'Qui est Raymond Sintès ?', 'mcq', '["Le restaurateur qui témoigne au procès","Le voisin qui entraîne Meursault dans sa querelle","Le juge d’instruction","Le vieux voisin qui bat son chien"]'::jsonb, 1, 'C’est en aidant Raymond dans une histoire louche que Meursault se retrouve sur la plage où il tue l’Arabe.', 4),
    ('e0eb6c88-8a7d-56ba-8cff-30d328ec3a95'::uuid, 'francais', '1re', 'L’Être et le Néant, Jean-Paul Sartre', 'Quel est le sous-titre de L’Être et le Néant ?', 'mcq', '["« Traité de la liberté humaine »","« Essai sur les passions de l’âme »","« Introduction à la morale de l’engagement »","« Essai d’ontologie phénoménologique »"]'::jsonb, 3, 'L’ontologie est l’étude de l’être ; la méthode phénoménologique, héritée de Husserl, décrit ce qui apparaît à la conscience.', 1),
    ('99bd0763-d202-597b-8ae9-5c9388e3a83c'::uuid, 'francais', '1re', 'L’Être et le Néant, Jean-Paul Sartre', 'D’où naît l’angoisse, selon Sartre ?', 'mcq', '["De la peur de la mort","De la découverte que rien ne fonde mes choix","De la souffrance du corps","Du souvenir de mes fautes passées"]'::jsonb, 1, 'Sans nature préalable, aucune règle ne décide à ma place : je suis seul responsable de ce que je choisis.', 2),
    ('0853c6d3-deda-56a5-b75b-9c92cea5cb20'::uuid, 'francais', '1re', 'L’Être et le Néant, Jean-Paul Sartre', 'Que fait la femme au rendez-vous, exemple de mauvaise foi ?', 'mcq', '["Elle laisse sa main dans la sienne en feignant de ne pas la sentir","Elle retire aussitôt sa main et quitte la table","Elle lui dit franchement qu’elle ne l’aime pas","Elle lui avoue son amour sans aucun détour"]'::jsonb, 0, 'Elle refuse de choisir entre accepter et repousser : elle fait de sa main une chose pour fuir sa liberté.', 3),
    ('d7bc81da-571e-58f8-a11b-588a1d691813'::uuid, 'francais', '1re', 'L’Être et le Néant, Jean-Paul Sartre', 'Quelle pièce de Sartre est l’illustration théâtrale du regard d’autrui ?', 'mcq', '["Les Mouches","Les Mains sales","Huis clos","Le Diable et le Bon Dieu"]'::jsonb, 2, 'Dans Huis clos, les personnages enfermés ne peuvent échapper au regard des autres, qui les fige et les juge.', 4),
    ('d39b0564-2e20-50bf-8541-a8ee296640e4'::uuid, 'francais', '1re', 'L’Homme qui rit, Victor Hugo', 'Qui est Barkilphedro ?', 'mcq', '["Le chef des comprachicos","L’intrigant jaloux qui déclenche la révélation","Le forain qui recueille les enfants","Le père de Gwynplaine"]'::jsonb, 1, 'Son intrigue fait sortir Gwynplaine du monde des forains pour la Chambre des lords : la révélation le mène à la catastrophe.', 1),
    ('cd10f2d5-2f73-528f-8a1d-5887568e8918'::uuid, 'francais', '1re', 'L’Homme qui rit, Victor Hugo', 'Quel roman devait conclure la trilogie ouverte par L’Homme qui rit ?', 'mcq', '["Quatrevingt-treize, sur la Révolution","Les Misérables, sur le peuple","Notre-Dame de Paris, sur le Moyen Âge","Les Travailleurs de la mer, sur l’océan"]'::jsonb, 0, 'Hugo voulait peindre l’aristocratie, puis la monarchie, puis la Révolution : Quatrevingt-treize en est le dernier volet.', 2),
    ('888c0e1a-876f-530d-a96e-259ea7de36e7'::uuid, 'francais', '1re', 'L’Homme qui rit, Victor Hugo', 'Sous quel règne l’action de L’Homme qui rit culmine-t-elle ?', 'mcq', '["Celui d’Élisabeth Ire","Celui de Charles Ier","Celui de Victoria","Celui de la reine Anne"]'::jsonb, 3, 'Le début du XVIIIe siècle anglais permet à Hugo de peindre une aristocratie toute-puissante, avec ses lords et sa cour.', 3),
    ('1f67ba4d-0d53-556e-b5b2-19305ada209b'::uuid, 'francais', '1re', 'L’Homme qui rit, Victor Hugo', 'Que symbolise le rire figé de Gwynplaine, selon le cours ?', 'mcq', '["Le bonheur du peuple sous la monarchie","La folie qui menace l’artiste","Le peuple condamné à faire rire ceux qui le dominent","La gaieté naturelle des forains"]'::jsonb, 2, 'Quand Gwynplaine parle de la misère aux lords, ils rient de son visage : quoi qu’il dise, le peuple n’est pas entendu.', 4),
    ('6c87a3ab-756b-5ea3-84dd-b2d0e328163a'::uuid, 'francais', '1re', 'L’Île des esclaves, Marivaux', 'Qui est Cléanthis ?', 'mcq', '["La servante d’Euphrosine","L’épouse de Trivelin","L’esclave d’Iphicrate","La fille du gouverneur"]'::jsonb, 0, 'Sur l’île, Cléanthis devient la maîtresse de son ancienne maîtresse ; l’esclave d’Iphicrate, c’est Arlequin.', 1),
    ('f0cc716b-b207-5d30-9283-2c940a2608d9'::uuid, 'francais', '1re', 'L’Île des esclaves, Marivaux', 'Quelle pièce de 1730 reprend l’échange des rôles entre maîtres et valets ?', 'mcq', '["Les Fausses Confidences","Le Mariage de Figaro","Le Jeu de l’amour et du hasard","La Dispute"]'::jsonb, 2, 'Dans Le Jeu de l’amour et du hasard, Marivaux fait encore échanger leurs rôles aux maîtres et aux valets, cette fois pour éprouver l’amour.', 2),
    ('050179af-65f0-5ac1-841a-632e7b0f389f'::uuid, 'francais', '1re', 'L’Île des esclaves, Marivaux', 'Pourquoi rattache-t-on la pièce au genre de l’utopie ?', 'mcq', '["Parce qu’elle se passe dans l’Antiquité grecque","Parce qu’un lieu imaginaire y sert à juger le monde réel","Parce qu’elle annonce la Révolution française","Parce que tout y finit bien pour chacun"]'::jsonb, 1, 'L’île est une école morale : ce qui s’y passe renvoie les spectateurs à leur propre société.', 3),
    ('dad79673-96b8-5c9e-a1df-d08fde7fe23e'::uuid, 'francais', '1re', 'L’Île des esclaves, Marivaux', 'Que font d’abord Arlequin et Cléanthis, devenus maîtres ?', 'mcq', '["Ils refusent de changer d’habits","Ils demandent la mort de leurs anciens maîtres","Ils tentent de s’enfuir de l’île","Ils font de leurs anciens maîtres des portraits impitoyables"]'::jsonb, 3, 'Ces portraits font rire mais blessent : le maître découvre ce qu’il fait subir, avant que les serviteurs ne choisissent le pardon.', 4),
    ('8dad2083-1a00-54b8-a9b2-5bf43baa9858'::uuid, 'francais', '1re', 'L’Île mystérieuse, Jules Verne', 'Qui est en réalité le capitaine Nemo ?', 'mcq', '["Un savant américain exilé après la guerre","Le prince Dakkar, Indien révolté contre les Anglais","Un officier nordiste évadé de Richmond","Un pirate repenti du Pacifique"]'::jsonb, 1, 'Vieilli, Nemo protège en secret les colons avant de mourir dans son Nautilus : la révélation relie le roman à Vingt Mille Lieues sous les mers.', 1),
    ('7112912a-c967-54c0-b08f-0b7bccf06735'::uuid, 'francais', '1re', 'L’Île mystérieuse, Jules Verne', 'Qui affirme « L’eau est le charbon de l’avenir » ?', 'mcq', '["Le capitaine Nemo","Le marin Pencroff","Le journaliste Spilett","L’ingénieur Cyrus Smith"]'::jsonb, 3, 'La formule résume la foi de l’ingénieur dans le progrès : la science saura faire de l’eau un combustible.', 2),
    ('a6518446-b8d9-5aba-a146-182c234490a7'::uuid, 'francais', '1re', 'L’Île mystérieuse, Jules Verne', 'Où L’Île mystérieuse paraît-elle d’abord en feuilleton ?', 'mcq', '["Dans le Magasin d’éducation et de récréation","Dans la Revue des Deux Mondes","Dans le Journal des débats","Dans Le Figaro"]'::jsonb, 0, 'Cette revue de l’éditeur Hetzel s’adresse à la jeunesse : Verne y met en récit la science et le progrès (1874-1875).', 3),
    ('6afce308-681a-52c2-86d4-42bc95b90ff4'::uuid, 'francais', '1re', 'L’Île mystérieuse, Jules Verne', 'Quelle leçon le roman oppose-t-il à Robinson Crusoé ?', 'mcq', '["La solitude rend l’homme plus fort","La Providence veille sur les naufragés","Le savoir et le travail collectif remplacent le miracle","La nature finit toujours par vaincre l’homme"]'::jsonb, 2, 'Chez Defoe, un homme seul s’en remet à la Providence ; chez Verne, un groupe organisé autour de l’ingénieur reconstruit la civilisation.', 4),
    ('bb26bd09-fb58-5c04-aad7-e72745bcacbb'::uuid, 'francais', '1re', 'L’Illusion comique, Pierre Corneille', 'Dans quel théâtre L’Illusion comique est-elle jouée en 1636 ?', 'mcq', '["À l’Hôtel de Bourgogne","Au théâtre du Marais","Au Palais-Royal","À la Comédie-Française"]'::jsonb, 1, 'La pièce est créée au théâtre du Marais ; la Comédie-Française n’existe pas encore, elle ne naîtra qu’en 1680.', 1),
    ('8e910bf5-21b8-5ed7-9e85-fe82c537d168'::uuid, 'francais', '1re', 'L’Illusion comique, Pierre Corneille', 'Quelle pièce de Corneille est créée quelques mois après L’Illusion comique ?', 'mcq', '["Horace","Cinna","Polyeucte","Le Cid"]'::jsonb, 3, 'Le Cid est créé au début de 1637 : Corneille passe de l’« étrange monstre » baroque à l’œuvre qui fera sa gloire.', 2),
    ('241f77c4-45ff-5d46-a49e-235b1657d007'::uuid, 'francais', '1re', 'L’Illusion comique, Pierre Corneille', 'Que découvre Pridamant quand Alcandre tire le rideau ?', 'mcq', '["Les personnages en train de compter de l’argent","Son fils mort, couché sur la scène","Une grotte vide, sans personne","Isabelle et Lyse en habits de deuil"]'::jsonb, 0, 'Les « morts » sont des comédiens qui se partagent la recette : Clindor n’a pas été assassiné, il jouait une tragédie.', 3),
    ('c611014d-626f-588c-b944-dc5e8113952e'::uuid, 'francais', '1re', 'L’Illusion comique, Pierre Corneille', 'Que reconnaît la déclaration de Louis XIII en 1641 ?', 'mcq', '["Que le théâtre doit être interdit le dimanche","Que les comédiens peuvent être excommuniés","Que le métier de comédien n’est pas infamant s’il reste honnête","Que seules les tragédies peuvent être jouées"]'::jsonb, 2, 'Cinq ans après L’Illusion comique, le pouvoir royal réhabilite en partie un métier alors méprisé, que la pièce défendait.', 4),
    ('d429a82a-04a9-5671-982a-84a93e8d4e4b'::uuid, 'francais', '1re', 'L’Immoraliste, André Gide', 'Pourquoi Michel épouse-t-il Marceline ?', 'mcq', '["Par amour, après de longues fiançailles","Pour sa fortune, qui lui permet d’étudier","Sans amour, par obéissance à son père mourant","Pour suivre les conseils de Ménalque"]'::jsonb, 2, 'Ce mariage de devoir, conforme à son éducation, prépare le drame : Michel sacrifiera celle qu’il n’a pas choisie.', 1),
    ('a3c8aa87-68e4-52ae-8bb3-04cbb3d19a03'::uuid, 'francais', '1re', 'L’Immoraliste, André Gide', 'Dans quelle éducation Michel a-t-il été élevé ?', 'mcq', '["La rigueur protestante","La tradition catholique","La liberté des libertins","L’austérité janséniste"]'::jsonb, 0, 'Gide, lui aussi d’éducation protestante, montre un héros qui rompt avec cette rigueur en découvrant son corps et la sensualité.', 2),
    ('14bea26b-bc3f-5574-b69f-e4ae0382a9b0'::uuid, 'francais', '1re', 'L’Immoraliste, André Gide', 'Qui est Charles ?', 'mcq', '["Un ami venu en Algérie écouter Michel","Le frère de Marceline","Un enfant arabe de Biskra","Le fils du fermier de Normandie, qu’admire Michel"]'::jsonb, 3, 'Charles appartient à l’épisode normand, après le retour d’Afrique : Michel l’admire, lui qui veut désormais vivre selon sa seule nature.', 3),
    ('193b4478-65eb-5b36-a9cb-6c87c5a7e5a5'::uuid, 'francais', '1re', 'L’Immoraliste, André Gide', 'Qu’appelle-t-on un « récit » au sens de Gide ?', 'mcq', '["Un long roman à plusieurs intrigues","Un texte court, confié à un narrateur unique","Un conte merveilleux pour enfants","Un journal intime publié tel quel"]'::jsonb, 1, 'Le récit à la première personne laisse le lecteur seul juge : Gide expose la conduite de Michel sans conclure.', 4),
    ('4747a328-a19e-5959-a531-457b06331a96'::uuid, 'francais', '1re', 'L’Ingénu, Voltaire', 'Sous quelle présentation L’Ingénu paraît-il en 1767 ?', 'mcq', '["Signé de Voltaire, avec une longue préface","Anonyme, comme une histoire véritable du père Quesnel","Comme la traduction d’un récit huron","Comme la correspondance d’un voyageur"]'::jsonb, 1, 'Présenté comme tiré des manuscrits du père Quesnel, le conte se donne l’apparence d’un témoignage vrai, sans nom d’auteur.', 1),
    ('ab3f2171-9d6e-5a5f-9bfb-53c7ef4b73ba'::uuid, 'francais', '1re', 'L’Ingénu, Voltaire', 'Quelle affaire de 1762 mobilise Voltaire contre l’intolérance avant L’Ingénu ?', 'mcq', '["L’affaire du Collier","L’affaire des Poisons","L’affaire Dreyfus","L’affaire Calas"]'::jsonb, 3, 'Le protestant Jean Calas est exécuté à Toulouse : Voltaire y répond par le Traité sur la tolérance (1763).', 2),
    ('9a7c156b-15d4-5e9a-8e95-fc1c5fb47f03'::uuid, 'francais', '1re', 'L’Ingénu, Voltaire', 'Pourquoi l’Ingénu ne peut-il pas épouser Mademoiselle de Saint-Yves ?', 'mcq', '["Elle est sa marraine","Elle est sa cousine","Elle est déjà mariée","Elle est protestante"]'::jsonb, 0, 'L’interdit religieux paraît sans fondement à la logique implacable du Huron : son regard neuf fait d’abord rire de nos coutumes.', 3),
    ('acc97a63-e6c0-568f-9d26-6a4ea63c2f8d'::uuid, 'francais', '1re', 'L’Ingénu, Voltaire', 'Quelle pratique de l’arbitraire royal le conte dénonce-t-il ?', 'mcq', '["Les impôts sur le sel","Les procès en sorcellerie","Les lettres de cachet","La vente des offices"]'::jsonb, 2, 'Une lettre de cachet permet d’emprisonner sans jugement : l’Ingénu, dénoncé, est embastillé après avoir servi le roi.', 4),
    ('99c7f138-e521-5efc-b896-5ee7500f91d4'::uuid, 'francais', '1re', 'L’Œuvre, Émile Zola', 'Qui est Bongrand dans L’Œuvre ?', 'mcq', '["Le vieux maître reconnu, lucide sur ses limites","Le peintre habile qui adoucit les audaces des autres","L’écrivain méthodique, double de Zola","Le marchand qui achète les toiles de Claude"]'::jsonb, 0, 'Face à Claude, Bongrand montre que la reconnaissance n’efface pas le doute : même le maître connaît ses limites.', 1),
    ('8595d927-8765-5ce2-8786-d5cc5b40c39a'::uuid, 'francais', '1re', 'L’Œuvre, Émile Zola', 'De quel personnage des Rougon-Macquart Claude Lantier est-il le fils ?', 'mcq', '["De Nana","De Gervaise","De Coupeau","De Virginie"]'::jsonb, 1, 'Fils de Gervaise, Claude apparaissait déjà dans Le Ventre de Paris : les personnages relient les volumes du cycle.', 2),
    ('8b6663ac-b260-58ab-917b-be0bb8e9148f'::uuid, 'francais', '1re', 'L’Œuvre, Émile Zola', 'Que ressent Christine face à la peinture de Claude ?', 'mcq', '["De l’indifférence","Une admiration sans réserve","De la jalousie, comme devant une rivale","Du mépris pour l’art moderne"]'::jsonb, 2, 'Elle pose pour lui, mais sent que la toile lui prend son mari : la création dévore la vie de famille.', 3),
    ('83d49964-dfdd-54ef-a81c-ce825f06774d'::uuid, 'francais', '1re', 'L’Œuvre, Émile Zola', 'Comment Claude Lantier meurt-il ?', 'mcq', '["Il meurt de misère à l’hôpital","Il se noie dans la Seine","Il est tué en duel par Fagerolles","Il se pend devant sa toile inachevée"]'::jsonb, 3, 'Incapable de faire coïncider sa toile et sa vision, il se tue devant elle : c’est le prix payé par l’art.', 4),
    ('1630cbb3-6966-55f5-ae85-dff27cb226c7'::uuid, 'francais', '1re', 'La Ballade des pendus, François Villon', 'Sous quel autre titre connaît-on la Ballade des pendus ?', 'mcq', '["Le Testament","L’Épitaphe Villon","Le Lais","La Complainte des morts"]'::jsonb, 1, 'Une épitaphe est une inscription pour un tombeau : Villon, condamné à la pendaison, y fait parler les morts.', 1),
    ('65bc0dec-66ee-58d8-ab73-25c03a270891'::uuid, 'francais', '1re', 'La Ballade des pendus, François Villon', 'D’où vient le nom de Villon ?', 'mcq', '["De son village natal, près de Paris","Du collège où il a étudié","De son protecteur, le chanoine Guillaume de Villon","D’un surnom reçu en prison"]'::jsonb, 2, 'Né François de Montcorbier, il prend le nom du chanoine qui l’a protégé.', 2),
    ('8e080cbc-81c6-56bd-bd24-c24330c1570b'::uuid, 'francais', '1re', 'La Ballade des pendus, François Villon', 'Quel vol Villon a-t-il commis en 1456 ?', 'mcq', '["Celui du collège de Navarre","Celui du trésor de Notre-Dame","Celui des bijoux du duc d’Orléans","Celui de la caisse du Parlement"]'::jsonb, 0, 'Un an après avoir tué un prêtre dans une rixe, il participe au vol du collège de Navarre : maître ès arts, il est aussi voleur.', 3),
    ('9732be37-5be8-5df7-98d5-670ffc4952d3'::uuid, 'francais', '1re', 'La Ballade des pendus, François Villon', 'Quel effet produit le refrain qui clôt chaque strophe ?', 'mcq', '["Il fait rire le lecteur des pendus","Il annonce un envoi adressé au roi","Il résume les crimes des pendus","Il rend la prière obsédante"]'::jsonb, 3, '« Mais priez Dieu que tous nous veuille absoudre ! » revient à la fin de chaque strophe : la supplication insiste jusqu’au bout.', 4),
    ('b828697a-ecf7-5273-b39e-663bc303838b'::uuid, 'francais', '1re', 'La Bête humaine, Émile Zola', 'Qui est Cabuche ?', 'mcq', '["Le chauffeur de la Lison","Le carrier innocent, condamné à la place de Jacques","Le garde-barrière qui empoisonne sa femme","Le haut fonctionnaire qui étouffe l’affaire"]'::jsonb, 1, 'Condamné avec Roubaud pour le meurtre de Séverine, commis par Jacques, Cabuche montre une justice aveugle.', 1),
    ('03a273dd-e342-5d2a-8279-981395e56e19'::uuid, 'francais', '1re', 'La Bête humaine, Émile Zola', 'Quel rôle joue Camy-Lamotte ?', 'mcq', '["Il défend Cabuche au procès","Il conduit la locomotive de Jacques","Il est le sous-chef de gare du Havre","Il étouffe l’affaire pour protéger le pouvoir"]'::jsonb, 3, 'Haut fonctionnaire, il préfère le silence à la vérité : la justice, dans le roman, est soumise au pouvoir.', 2),
    ('97da10a4-6f24-5f1f-ba18-007fb8aac85c'::uuid, 'francais', '1re', 'La Bête humaine, Émile Zola', 'Sur quelle ligne de chemin de fer l’action se déroule-t-elle ?', 'mcq', '["Paris-Le Havre","Paris-Lyon","Paris-Lille","Paris-Bordeaux"]'::jsonb, 0, 'De la gare Saint-Lazare au port du Havre : le chemin de fer n’est pas un décor, la machine devient un personnage.', 3),
    ('53a9c4f5-daa1-55aa-8294-b4e4dd86bdc7'::uuid, 'francais', '1re', 'La Bête humaine, Émile Zola', 'Qui est Pecqueux ?', 'mcq', '["Le mari de Flore","Le frère de Séverine","Le chauffeur de Jacques, qui tombe avec lui","Le juge qui instruit l’affaire"]'::jsonb, 2, 'Leur bagarre sur la locomotive lancée laisse le train sans conducteur, plein de soldats : c’est l’image finale du roman.', 4),
    ('f78db765-41a4-5f80-81c8-9ba3ad6cb339'::uuid, 'francais', '1re', 'La Chartreuse de Parme, Stendhal', 'Qui est Clélia Conti ?', 'mcq', '["La fille du gouverneur de la prison","La nièce du comte Mosca","La sœur de Fabrice","L’épouse du prince de Parme"]'::jsonb, 0, 'Fabrice la découvre du haut de sa cellule de la tour Farnèse : la fille de son geôlier devient l’amour de sa vie.', 1),
    ('7ae2ec09-34d0-5950-8831-a4d13436cb28'::uuid, 'francais', '1re', 'La Chartreuse de Parme, Stendhal', 'Que montre le récit de Waterloo, vu par Fabrice ?', 'mcq', '["Une bataille héroïque et glorieuse","La guerre vue d’en bas, où l’on ne comprend rien","Le génie de Napoléon en action","La victoire des troupes françaises"]'::jsonb, 1, 'Le point de vue interne démythifie la guerre : Fabrice est au cœur de la bataille sans rien y comprendre, et c’est exact.', 2),
    ('c6b6cb70-9c60-5ed5-8e89-86cd676f3863'::uuid, 'francais', '1re', 'La Chartreuse de Parme, Stendhal', 'Quel écrivain consacre un article enthousiaste à La Chartreuse de Parme en 1840 ?', 'mcq', '["Sainte-Beuve","Victor Hugo","Alfred de Musset","Balzac"]'::jsonb, 3, 'Dans ses Études sur M. Beyle (1840), Balzac salue le roman dans un article dithyrambique.', 3),
    ('24f14a43-d256-52c2-b9a6-d47c757111bd'::uuid, 'francais', '1re', 'La Chartreuse de Parme, Stendhal', 'Quel poste Stendhal occupe-t-il quand il dicte La Chartreuse ?', 'mcq', '["Préfet de l’Isère","Ambassadeur à Rome","Consul à Civitavecchia, en congé à Paris","Officier de la Grande Armée"]'::jsonb, 2, 'Consul à Civitavecchia depuis 1831, il dicte le roman à Paris pendant un congé, fin 1838 : il y met son amour de l’Italie.', 4),
    ('a7ec6831-e05e-541b-b1e0-0627d915650d'::uuid, 'francais', '1re', 'La Comédie humaine, Honoré de Balzac', 'Quel projet Balzac compare-t-il au travail de Buffon ?', 'mcq', '["Classer les « espèces sociales »","Classer les genres littéraires","Décrire les paysages de France","Réformer la langue française"]'::jsonb, 0, 'Comme Buffon classait les espèces animales, Balzac veut décrire les types humains que produit la société.', 1),
    ('9772e4bf-4e7f-5f89-a612-47b3a3dc9200'::uuid, 'francais', '1re', 'La Comédie humaine, Honoré de Balzac', 'Qui est Vautrin ?', 'mcq', '["Le banquier, maître de la spéculation","Le forçat évadé qui finit chef de la police","Le poète de province perdu par Paris","L’usurier qui prête à tout Paris"]'::jsonb, 1, 'Vautrin, de son vrai nom Jacques Collin, reparaît d’un roman à l’autre : c’est l’un des grands exemples du retour des personnages.', 2),
    ('a57fdceb-2ead-5043-8c49-155d80ade834'::uuid, 'francais', '1re', 'La Comédie humaine, Honoré de Balzac', 'Quel roman appartient aux Études philosophiques ?', 'mcq', '["Le Père Goriot","Eugénie Grandet","La Peau de chagrin","La Cousine Bette"]'::jsonb, 2, 'Dans les Études philosophiques, Balzac cherche les causes ; les trois autres romans font partie des Études de mœurs.', 3),
    ('da7a12cf-a282-50ff-b872-25314b3eb333'::uuid, 'francais', '1re', 'La Comédie humaine, Honoré de Balzac', 'Quel échec pèse sur toute la vie de Balzac ?', 'mcq', '["La perte d’un héritage au jeu","L’interdiction de ses romans par la censure","Un exil forcé hors de France","Sa faillite d’imprimeur, qui le couvre de dettes"]'::jsonb, 3, 'Pour rembourser, il écrit la nuit, à grand renfort de café : l’argent, moteur de sa société romanesque, est aussi celui de sa vie.', 4),
    ('115121c3-ee61-5d3f-b2e3-7e16ad2d60a2'::uuid, 'francais', '1re', 'La Comtesse de Tende, Madame de La Fayette', 'Dans quelle revue La Comtesse de Tende paraît-elle en 1724 ?', 'mcq', '["Le Mercure galant","Le Nouveau Mercure","La Gazette de France","Le Journal des savants"]'::jsonb, 1, 'La nouvelle paraît dans Le Nouveau Mercure, plus de trente ans après la mort de l’autrice (1693), qui ne l’avait pas publiée.', 1),
    ('0bcee402-8f18-5557-a6d8-82c200121b6f'::uuid, 'francais', '1re', 'La Comtesse de Tende, Madame de La Fayette', 'À quel moment de l’histoire de France le récit se situe-t-il ?', 'mcq', '["À la fin du règne d’Henri IV (1610)","Pendant la Fronde, sous Mazarin (1648)","Au début de la régence de Catherine de Médicis (1560)","Au début du règne personnel de Louis XIV (1661)"]'::jsonb, 2, 'La nouvelle se passe à la cour des Valois, en 1560 : juste après l’époque de La Princesse de Clèves, située sous Henri II.', 2),
    ('6157c34f-7b3e-5571-b96f-0de6bf13be34'::uuid, 'francais', '1re', 'La Comtesse de Tende, Madame de La Fayette', 'Qui est la comtesse de Tende avant son mariage ?', 'mcq', '["Une Strozzi, parente de Catherine de Médicis","Une princesse de la maison de Savoie","La sœur cadette du chevalier de Navarre","Une jeune veuve, amie de la reine"]'::jsonb, 0, 'Née Strozzi, elle est mariée très jeune au comte de Tende, grand seigneur de la maison de Savoie ; la jeune veuve, c’est la princesse de Neufchâtel.', 3),
    ('4dd68d09-9343-5142-8c72-8d0aa7769338'::uuid, 'francais', '1re', 'La Comtesse de Tende, Madame de La Fayette', 'Pourquoi le chevalier de Navarre épouse-t-il la princesse de Neufchâtel ?', 'mcq', '["Par un amour sincère pour elle","Pour obéir à un ordre de la reine","Pour rendre la comtesse jalouse","Par ambition : il est noble mais sans fortune"]'::jsonb, 3, 'De grande naissance mais sans bien, il trouve dans ce parti brillant la fortune qui lui manque — avec l’aide de la comtesse, qui l’aime pourtant.', 4),
    ('31ee2c66-6025-5fb6-97bb-8c9ae7ed217f'::uuid, 'francais', '1re', 'La Condition humaine, André Malraux', 'À quel penseur le titre du roman renvoie-t-il ?', 'mcq', '["Montaigne","Pascal","Descartes","Rousseau"]'::jsonb, 1, 'Pascal comparait les hommes à des condamnés qui regardent mourir leurs compagnons en attendant leur tour : c’est la « condition humaine » que les personnages affrontent.', 1),
    ('8738ed4a-7c6a-534e-aece-2a83136a3bee'::uuid, 'francais', '1re', 'La Condition humaine, André Malraux', 'Quelle réponse à la condition humaine le vieux Gisors incarne-t-il ?', 'mcq', '["La révolution","L’érotisme","La drogue","Le mythe"]'::jsonb, 2, 'Sinologue et fumeur d’opium, le père de Kyo fuit dans la drogue ; les autres opposent la révolution (Kyo), l’érotisme (Ferral), l’art et le mythe (Clappique).', 2),
    ('e2e8650a-14fa-53f2-9aff-add91bfc92b3'::uuid, 'francais', '1re', 'La Condition humaine, André Malraux', 'Qui est May ?', 'mcq', '["La maîtresse de Ferral","La sœur de Tchen","Une espionne du Kuomintang","L’épouse de Kyo, médecin"]'::jsonb, 3, 'May est médecin et l’épouse de Kyo ; leur couple affronte la jalousie et la question de la liberté de chacun.', 3),
    ('4ef5110f-cf05-570f-bfce-1e1844491440'::uuid, 'francais', '1re', 'La Condition humaine, André Malraux', 'Pourquoi Malraux a-t-il été arrêté en Indochine dans les années 1920 ?', 'mcq', '["Pour avoir prélevé des statues d’un temple khmer","Pour avoir déserté l’armée coloniale","Pour avoir organisé une grève d’ouvriers","Pour avoir espionné au service de la Chine"]'::jsonb, 0, 'Il a ensuite dénoncé le colonialisme dans un journal : l’Asie de ses romans, il l’a connue de près.', 4),
    ('9a5bd6b0-1ab2-5ea2-854d-5567da1b582a'::uuid, 'francais', '1re', 'La Critique de l’École des femmes, Molière', 'À qui Molière dédie-t-il La Critique de l’École des femmes ?', 'mcq', '["À Louis XIV","À Monsieur, frère du roi","À la reine mère, Anne d’Autriche","À Nicolas Boileau"]'::jsonb, 2, 'Créée le 1er juin 1663, la pièce est dédiée à la reine mère, Anne d’Autriche, alors que dévots, précieuses et auteurs rivaux attaquent L’École des femmes.', 1),
    ('efd5770c-6422-550f-a14c-59cd3b825abb'::uuid, 'francais', '1re', 'La Critique de l’École des femmes, Molière', 'Quel est le sujet de L’École des femmes, la pièce défendue ici ?', 'mcq', '["Arnolphe veut épouser Agnès, élevée dans l’ignorance","Harpagon, avare, se fait voler sa cassette d’or","Tartuffe, faux dévot, s’installe chez Orgon","Alceste, misanthrope, aime la coquette Célimène"]'::jsonb, 0, 'Arnolphe a fait élever Agnès dans l’ignorance pour l’épouser : le succès de décembre 1662 déclenche une querelle.', 2),
    ('86f68b01-bc0d-5468-a789-f05a0380308f'::uuid, 'francais', '1re', 'La Critique de l’École des femmes, Molière', 'Quelle est la forme de La Critique de l’École des femmes ?', 'mcq', '["Cinq actes en alexandrins","Trois actes en prose","Un acte en vers","Un acte en prose"]'::jsonb, 3, 'Une comédie courte, en un acte et en prose : au lieu d’une préface, Molière écrit une conversation de salon sur sa pièce précédente.', 3),
    ('6033fa5d-e6e7-5404-b3d1-fcb994a5cee9'::uuid, 'francais', '1re', 'La Critique de l’École des femmes, Molière', 'Selon Dorante, que doit faire l’auteur de comédie ?', 'mcq', '["Respecter les règles d’Aristote et d’Horace","Peindre d’après nature pour faire rire les honnêtes gens","Imiter les héros nobles de la tragédie","Corriger les mœurs sans jamais faire rire"]'::jsonb, 1, 'Les portraits doivent ressembler, et le rire des honnêtes gens est difficile à obtenir ; ce sont les règles des Anciens que Lysidas, le pédant, invoque.', 4),
    ('e9d45c2f-3b08-5815-a437-1822e51def53'::uuid, 'francais', '1re', 'La Curée, Émile Zola', 'Pourquoi la publication de La Curée en feuilleton est-elle interrompue ?', 'mcq', '["Zola tombe gravement malade","Le journal La Cloche fait faillite","La guerre de 1870 éclate","Le parquet juge le roman immoral"]'::jsonb, 3, 'Le feuilleton, paru dans La Cloche en 1871-1872, est arrêté par le parquet : Zola y peint sans fard la « fête impériale ».', 1),
    ('f623e5da-298d-56b4-a76c-cbc476e02c33'::uuid, 'francais', '1re', 'La Curée, Émile Zola', 'Quel est le vrai nom d’Aristide Saccard ?', 'mcq', '["Aristide Macquart","Aristide Rougon","Aristide Mouret","Aristide Quenu"]'::jsonb, 1, 'Né Aristide Rougon, il a changé de nom pour faire fortune ; son frère Eugène Rougon est un homme politique puissant de l’Empire.', 2),
    ('21db1408-8e24-5344-a376-622af52da5a8'::uuid, 'francais', '1re', 'La Curée, Émile Zola', 'Quel lieu de l’hôtel du parc Monceau symbolise la passion de Renée et de Maxime ?', 'mcq', '["La serre, à la végétation tropicale","La bibliothèque de Saccard","La grande salle de bal","Le jardin à la française"]'::jsonb, 0, 'Chaude, luxuriante, étouffante, la serre dit le désir et l’excès : le décor devient le symbole de la passion.', 3),
    ('21560bc0-433f-5a66-b7da-2a88df4b1dab'::uuid, 'francais', '1re', 'La Curée, Émile Zola', 'Comment Renée finit-elle ?', 'mcq', '["Noyée dans la Seine, par désespoir","D’un coup de pistolet, après un bal","D’une méningite, ruinée et abandonnée","En couches, dans l’hôtel du parc"]'::jsonb, 2, 'Dépouillée par Saccard, qui lui a fait signer ses papiers, puis abandonnée, Renée meurt d’une méningite.', 4),
    ('88545f08-1cfc-5574-acd1-a8f716d855da'::uuid, 'francais', '1re', 'La Ferme des animaux, George Orwell', 'Quel sous-titre Orwell donne-t-il à son livre ?', 'mcq', '["« Une fable politique »","« Un roman russe »","« Conte de fées »","« Histoire naturelle »"]'::jsonb, 2, 'Publié en août 1945, le livre est sous-titré « conte de fées » : une forme simple, presque enfantine, pour une thèse politique.', 1),
    ('adc17e1c-f7f7-5be8-bc58-fcf84420a6f3'::uuid, 'francais', '1re', 'La Ferme des animaux, George Orwell', 'Quel rôle joue Brille-Babil ?', 'mcq', '["Il est chargé de la propagande","Il dirige la construction du moulin","Il garde le fermier Jones","Il mène les moutons au pré"]'::jsonb, 0, 'Brille-Babil justifie chaque décision de Napoléon : il incarne la propagande, qui réécrit l’histoire au profit du chef.', 2),
    ('cbdd570d-2872-576a-8750-95ac243bc167'::uuid, 'francais', '1re', 'La Ferme des animaux, George Orwell', 'Comment Napoléon s’impose-t-il face à Boule de Neige ?', 'mcq', '["Par un vote loyal de tous les animaux","Par sa victoire contre les fermiers","Par un long discours devant la grange","Par des chiens élevés en secret"]'::jsonb, 3, 'Napoléon élève secrètement des chiens, prend le pouvoir et fait expulser son rival, dont il vole ensuite le projet de moulin.', 3),
    ('7d0442ce-0391-5f01-889b-6ef07faa06cf'::uuid, 'francais', '1re', 'La Ferme des animaux, George Orwell', 'Quel est le vrai nom de George Orwell ?', 'mcq', '["Aldous Huxley","Eric Blair","Arthur Koestler","Herbert Wells"]'::jsonb, 1, 'Eric Blair, socialiste anglais, a combattu dans les milices du POUM pendant la guerre d’Espagne, où il a vu les staliniens liquider leurs alliés.', 4),
    ('bf763e2e-11dc-545d-8cf9-37eeca23b578'::uuid, 'francais', '1re', 'La Guerre de Troie n’aura pas lieu, Jean Giraudoux', 'Quel métier Jean Giraudoux exerçait-il en plus d’écrire ?', 'mcq', '["Avocat","Diplomate","Médecin militaire","Professeur de grec"]'::jsonb, 1, 'Diplomate de carrière et ancien combattant blessé en 1914, il connaît de près la négociation comme la guerre.', 1),
    ('7c5d02a2-6333-5bb2-9f47-a69f31975017'::uuid, 'francais', '1re', 'La Guerre de Troie n’aura pas lieu, Jean Giraudoux', 'Comment Hector réagit-il quand Ajax, ivre, le gifle ?', 'mcq', '["Il le provoque aussitôt en duel","Il appelle les Troyens aux armes","Il le fait jeter hors de la ville","Il encaisse, sans répondre au coup"]'::jsonb, 3, 'Hector accepte l’humiliation pour ne donner aucun prétexte à la guerre : pour lui, la paix vaut plus que l’orgueil.', 2),
    ('f6abbeb5-5717-50ab-ba14-1743ee812db4'::uuid, 'francais', '1re', 'La Guerre de Troie n’aura pas lieu, Jean Giraudoux', 'Quelle est l’attitude d’Hélène et de Pâris dans la pièce ?', 'mcq', '["Légers, ils ne se sentent responsables de rien","Ils supplient qu’on les sépare pour la paix","Ils réclament la guerre pour leur gloire","Ils fuient Troie pour éviter le conflit"]'::jsonb, 0, 'Le couple au cœur de la crise reste indifférent : la guerre ne naît pas d’une grande passion, mais des mots, de la vanité et du hasard.', 3),
    ('9872533e-a6aa-59b9-9b89-2d243cfdf1f8'::uuid, 'francais', '1re', 'La Guerre de Troie n’aura pas lieu, Jean Giraudoux', 'Entre quels événements la pièce est-elle créée, en 1935 ?', 'mcq', '["La révolution russe et la fin de la Grande Guerre","La guerre d’Espagne et l’invasion de la Pologne","L’arrivée de Hitler au pouvoir et Munich","La Libération et le début de la guerre froide"]'::jsonb, 2, 'Créée entre 1933 et 1938, la pièce dit l’angoisse d’une génération qui voit revenir la guerre.', 4),
    ('0eebcf53-5c73-5130-9819-a43d89e1a1f4'::uuid, 'francais', '1re', 'La jalousie du Barbouillé, Molière', 'Comment le texte de La Jalousie du Barbouillé nous est-il parvenu ?', 'mcq', '["Par une édition de Molière lui-même","Par le registre de sa troupe","Par une copie tardive","Par une traduction italienne"]'::jsonb, 2, 'Cette farce, parmi les plus anciennes de Molière, n’a pas été éditée par lui : on la connaît par une copie tardive.', 1),
    ('031b1d41-5fb7-57bf-9139-7af1ae66f445'::uuid, 'francais', '1re', 'La jalousie du Barbouillé, Molière', 'Quelle ruse permet à Angélique de rentrer chez elle ?', 'mcq', '["Elle se déguise en docteur","Elle feint de se tuer, et il sort voir","Elle soudoie un valet pour ouvrir","Elle passe par une fenêtre du jardin"]'::jsonb, 1, 'Le mari sort, inquiet ; elle rentre et l’enferme dehors à son tour : la ruse du jaloux se retourne contre lui.', 2),
    ('e06466ed-363a-53e8-93e7-fb94af64a1ec'::uuid, 'francais', '1re', 'La jalousie du Barbouillé, Molière', 'De quoi Angélique accuse-t-elle son mari devant Gorgibus ?', 'mcq', '["De vouloir la mettre au couvent","D’avoir dilapidé toute sa dot","De la tromper avec une servante","De courir les rues toute la nuit"]'::jsonb, 3, 'Resté dehors, le jaloux passe pour le coupable : Gorgibus, juge crédule, croit qu’il rentre de ses courses nocturnes.', 3),
    ('bdb59c9e-fbfd-5b2e-9cf4-982a83a12c8f'::uuid, 'francais', '1re', 'La jalousie du Barbouillé, Molière', 'D’où vient la farce, qui est le socle du théâtre de Molière ?', 'mcq', '["Du Moyen Âge et de la commedia dell’arte","De la tragédie grecque et latine","Des romans précieux du XVIIe siècle","Des pastorales de la Renaissance"]'::jsonb, 0, 'Héritée du Moyen Âge et de la commedia dell’arte, la farce apporte à Molière le rythme, le jeu physique et les situations renversées.', 4),
    ('fa8da092-5ea6-54a9-90b1-5fdfa4ce830c'::uuid, 'francais', '1re', 'La Joie de vivre, Émile Zola', 'Quel philosophe nourrit le pessimisme de Lazare ?', 'mcq', '["Pascal","Schopenhauer","Nietzsche","Voltaire"]'::jsonb, 1, 'Le pessimisme de Schopenhauer est à la mode dans les années 1880 ; Zola y mêle sa propre peur de la mort.', 1),
    ('3fd38926-1bdf-5134-970b-95072e5a157b'::uuid, 'francais', '1re', 'La Joie de vivre, Émile Zola', 'Que devient la fortune de Pauline chez les Chanteau ?', 'mcq', '["Un notaire la place en rentes","La servante Véronique la vole","L’usine d’algues la fait doubler","La famille la dépense peu à peu"]'::jsonb, 3, 'Pauline donne sans compter : ses cent cinquante mille francs fondent au profit des Chanteau et des projets ratés de Lazare.', 2),
    ('fa6bebca-97e5-59ff-b0e7-add27d705123'::uuid, 'francais', '1re', 'La Joie de vivre, Émile Zola', 'Sur quelle réplique le roman se clôt-il ?', 'mcq', '["« Faut-il être bête pour se tuer ! »","« À quoi bon ? »","« Ce n’était pas un rêve. »","« Il faut vivre pour les autres. »"]'::jsonb, 0, 'L’oncle Chanteau, perclus de goutte, lance ce cri absurde devant le suicide de Véronique : le roman finit sur une ironie noire.', 3),
    ('978de27b-c7eb-5656-9bee-70d8c527a7fd'::uuid, 'francais', '1re', 'La Joie de vivre, Émile Zola', 'Dans quelles circonstances Zola écrit-il La Joie de vivre ?', 'mcq', '["Au début de sa carrière, en 1867","Pendant son exil à Londres, en 1898","Après la mort de sa mère, en 1884","Juste avant sa propre mort, en 1902"]'::jsonb, 2, 'Douzième volume des Rougon-Macquart, ce roman intime porte la peur de la mort qui hantait Zola.', 4),
    ('b6c4c6b1-ee8b-515f-83f9-547536f50447'::uuid, 'francais', '1re', 'La Leçon, Eugène Ionesco', 'Quel sous-titre Ionesco donne-t-il à La Leçon ?', 'mcq', '["« Anti-pièce »","« Tragédie du langage »","« Farce tragique »","« Drame comique »"]'::jsonb, 3, 'Le sous-titre annonce le mélange : on rit d’une mécanique absurde qui mène au meurtre.', 1),
    ('f4d50fc7-72b2-5af2-bf1c-27a0c1e2c079'::uuid, 'francais', '1re', 'La Leçon, Eugène Ionesco', 'Que sait faire l’élève en arithmétique ?', 'mcq', '["Additionner, mais pas soustraire","Soustraire, mais pas additionner","Diviser, mais pas multiplier","Compter jusqu’à dix, pas au-delà"]'::jsonb, 0, 'C’est le premier signe de la logique folle de la leçon, avant le discours délirant du professeur sur la philologie.', 2),
    ('5a4056c0-5119-5423-9293-1c85143cc457'::uuid, 'francais', '1re', 'La Leçon, Eugène Ionesco', 'Où La Leçon est-elle jouée sans interruption depuis 1957 ?', 'mcq', '["À la Comédie-Française","Au Théâtre de l’Odéon","Au Théâtre de la Huchette","Au Théâtre de Poche"]'::jsonb, 2, 'Elle y est jouée avec La Cantatrice chauve ; elle avait été créée au Théâtre de Poche, le 20 février 1951.', 3),
    ('c7f6b47a-4a67-5c65-95c9-f5ae04dad3f9'::uuid, 'francais', '1re', 'La Leçon, Eugène Ionesco', 'Que dit la bonne, Marie, pour avertir le professeur ?', 'mcq', '["« Le couteau mène au crime ! »","« La philologie mène au pire ! »","« L’arithmétique rend fou ! »","« Les dents mènent à la mort ! »"]'::jsonb, 1, 'Marie sait tout d’avance : elle met en garde, puis couvre le crime et fait entrer l’élève suivante.', 4),
    ('86f2c717-ab43-58eb-83de-2e2c35ee4879'::uuid, 'francais', '1re', 'La Machine infernale, Jean Cocteau', 'Qui dit le prologue de La Machine infernale ?', 'mcq', '["Le chœur des Thébains","Le devin Tirésias","Une Voix","Le fantôme de Laïos"]'::jsonb, 2, 'Une Voix annonce d’emblée toute l’histoire : le spectateur sait tout, les personnages ne comprennent rien.', 1),
    ('32f4ae62-0f11-5f50-8afa-749bbb5d0888'::uuid, 'francais', '1re', 'La Machine infernale, Jean Cocteau', 'Quel surnom Jocaste donne-t-elle au devin Tirésias ?', 'mcq', '["« Le vieux »","« Zizi »","« Mon oracle »","« Le hibou »"]'::jsonb, 1, 'Ce surnom familier illustre le ton insolent de Cocteau, qui change le regard sur le mythe sans en changer l’issue.', 2),
    ('87132123-e518-5dd2-be1e-1601ad1979f2'::uuid, 'francais', '1re', 'La Machine infernale, Jean Cocteau', 'Quel trait Cocteau donne-t-il à son Œdipe ?', 'mcq', '["Un sage résigné à son destin","Un vieillard aveugle et las","Un enfant naïf et craintif","Un jeune homme ambitieux et vaniteux"]'::jsonb, 3, 'Pressé de régner, Œdipe court au-devant du piège : sa vanité sert la machine des dieux.', 3),
    ('1d7b85b0-ef1c-58f1-8208-2a1b5c9b187a'::uuid, 'francais', '1re', 'La Machine infernale, Jean Cocteau', 'Qui accompagne le Sphinx à l’acte II ?', 'mcq', '["Anubis, le dieu à tête de chacal","Tirésias, le devin de Thèbes","Créon, le frère de Jocaste","Laïos, le roi assassiné"]'::jsonb, 0, 'Anubis est le gardien de la règle divine : le Sphinx, lasse de tuer, voudrait être aimée, mais la machine doit aller à son terme.', 4),
    ('fd86d0eb-2a51-5335-b9c2-dda35ca0ea29'::uuid, 'francais', '1re', 'La Mare au diable, George Sand', 'Qui pousse Germain à se remarier ?', 'mcq', '["Sa mère, veuve elle aussi","Marie, qui le trouve seul","Le curé de la paroisse","Son beau-père, le père Maurice"]'::jsonb, 3, 'Veuf à vingt-huit ans avec trois enfants, Germain part sur ordre de son beau-père, le père Maurice, sage et prudent.', 1),
    ('7b0f1272-dbe6-57dc-a81f-5b1b34b1eb99'::uuid, 'francais', '1re', 'La Mare au diable, George Sand', 'Pourquoi Marie quitte-t-elle la ferme où elle devait être bergère ?', 'mcq', '["Son maître la harcèle","On la trouve trop jeune","Sa mère la rappelle","Le troupeau est vendu"]'::jsonb, 0, 'Marie, seize ans, pauvre et courageuse, fuit ce maître ; de retour au village, Germain comprend qu’il l’aime.', 2),
    ('0ecf9c23-a4dc-5a84-a35a-693e36bd88d5'::uuid, 'francais', '1re', 'La Mare au diable, George Sand', 'Contre quelle conception de la littérature George Sand écrit-elle ?', 'mcq', '["Une littérature utile","La poésie populaire","L’art pour l’art","Le roman fraternel"]'::jsonb, 2, 'Sand veut une littérature utile et fraternelle, qui montre la dignité des paysans, et non un art qui n’aurait d’autre fin que lui-même.', 3),
    ('46cf0279-67b8-576a-b3b1-89cd496ac642'::uuid, 'francais', '1re', 'La Mare au diable, George Sand', 'Avec quels romans La Mare au diable forme-t-elle les romans champêtres de Sand ?', 'mcq', '["Indiana et Lélia","La Petite Fadette et François le Champi","Consuelo et Horace","Mauprat et Lucrezia Floriani"]'::jsonb, 1, 'La Mare au diable (1846) est le premier de ces romans du Berry ; La Petite Fadette paraît en 1849.', 4),
    ('292c93d9-7b46-5879-b2c0-4383ef6f1d97'::uuid, 'francais', '1re', 'La Marmite, Plaute', 'Quel est le titre latin de La Marmite ?', 'mcq', '["Menaechmi","Aulularia","Miles gloriosus","Amphitruo"]'::jsonb, 1, 'Aulularia est le titre original de la comédie de Plaute ; Molière en tirera L’Avare en 1668.', 1),
    ('baaeb91c-1f8a-5679-b781-4097e28d1273'::uuid, 'francais', '1re', 'La Marmite, Plaute', 'Pourquoi la demande en mariage de Mégadore arrange-t-elle Euclion ?', 'mcq', '["Mégadore promet de lui prêter de l’or","Mégadore est un parent de sa femme","Mégadore prend Phédria sans dot","Mégadore lui offre sa propre maison"]'::jsonb, 2, 'Le riche voisin épouse la fille sans dot : l’avare n’aura pas à toucher à son or.', 2),
    ('eb6f7eea-9a49-53c2-a781-4805a37d0276'::uuid, 'francais', '1re', 'La Marmite, Plaute', 'Pourquoi Euclion chasse-t-il à coups de bâton les cuisiniers du mariage ?', 'mcq', '["Il les croit venus voler son or","Ils ont brûlé le repas de noces","Ils réclament un salaire trop élevé","Ils se moquent de sa pauvreté"]'::jsonb, 0, 'Son obsession lui fait voir un voleur en chacun : c’est le comique de caractère poussé jusqu’au délire.', 3),
    ('7a9b41fe-4664-576f-a951-72ca753dd87c'::uuid, 'francais', '1re', 'La Marmite, Plaute', 'Quel répertoire grec Plaute adapte-t-il ?', 'mcq', '["La tragédie d’Eschyle et de Sophocle","La comédie ancienne d’Aristophane","Les mimes populaires de Sicile","La Comédie nouvelle, celle de Ménandre"]'::jsonb, 3, 'Plaute adapte ces modèles pour un public populaire romain, avec chansons, jeux de mots et bastonnades : la comédie est un art de la reprise.', 4),
    ('a0c336f3-78c8-5c83-b5ed-2532242367a3'::uuid, 'francais', '1re', 'La Métamorphose, Franz Kafka', 'Dans quelle langue Kafka écrit-il La Métamorphose ?', 'mcq', '["En tchèque","En yiddish","En allemand","En hébreu"]'::jsonb, 2, 'Juif de Prague, Kafka écrit en allemand ; il est employé dans une compagnie d’assurances contre les accidents du travail.', 1),
    ('7061be62-5b68-5174-9218-2de3edbb28ef'::uuid, 'francais', '1re', 'La Métamorphose, Franz Kafka', 'Quel est le métier de Gregor avant sa métamorphose ?', 'mcq', '["Employé de banque","Fondé de pouvoir","Commis aux écritures","Voyageur de commerce"]'::jsonb, 3, 'Voyageur de commerce, il entretenait seul ses parents et sa sœur : le jour où il ne « sert » plus, tout bascule.', 2),
    ('6d59b624-ed6a-5ebe-b361-785504df46a1'::uuid, 'francais', '1re', 'La Métamorphose, Franz Kafka', 'Qu’est-ce qui attire Gregor hors de sa chambre, devant les locataires ?', 'mcq', '["L’odeur du repas","Le violon de Grete","La voix de sa mère","Un cri de son père"]'::jsonb, 1, 'Attiré par la musique de sa sœur, il se montre : ce scandale conduit Grete à déclarer qu’il faut « s’en débarrasser ».', 3),
    ('c6d99bde-6788-5d63-9670-9d5dc0ece087'::uuid, 'francais', '1re', 'La Métamorphose, Franz Kafka', 'Comment la famille fait-elle face à la perte du salaire de Gregor ?', 'mcq', '["Tous travaillent et prennent des locataires","Elle part vivre chez un oncle riche","Elle vit d’une pension de l’entreprise","Elle emprunte de l’argent au patron"]'::jsonb, 0, 'Le père reprend l’uniforme, la mère et la sœur travaillent : la famille renaît à mesure que Gregor s’éteint.', 4),
    ('811cefcc-0b5e-5358-be35-a4c254a34ffd'::uuid, 'francais', '1re', 'La Modification, Michel Butor', 'Pourquoi Léon Delmont voyage-t-il en troisième classe ?', 'mcq', '["Parce qu’il est ruiné","Parce que le train est complet","Pour mieux observer les voyageurs","Pour ne pas être reconnu"]'::jsonb, 3, 'Directeur d’une firme de machines à écrire, il voyage en troisième classe pour ne pas être reconnu : ce voyage-là est secret.', 1),
    ('ba897cdf-e944-5b44-bf27-b4022bb7fea6'::uuid, 'francais', '1re', 'La Modification, Michel Butor', 'Quel prix La Modification reçoit-elle en 1957 ?', 'mcq', '["Le prix Goncourt","Le prix Renaudot","Le prix Femina","Le prix Médicis"]'::jsonb, 1, 'Prix Renaudot 1957, c’est l’œuvre la plus célèbre du Nouveau Roman, parue aux éditions de Minuit.', 2),
    ('3374cbbc-e64d-511d-9ec2-ad17da157559'::uuid, 'francais', '1re', 'La Modification, Michel Butor', 'Quels temps le roman mêle-t-il ?', 'mcq', '["Le trajet, les voyages passés, l’avenir rêvé","Le seul présent du trajet, minute par minute","L’enfance de Delmont, puis sa vieillesse","Le passé de Cécile, raconté par elle-même"]'::jsonb, 0, 'Souvenirs, rêveries et paysages se mêlent au trajet présent ; l’avenir imaginé avec Cécile à Paris se défait peu à peu.', 3),
    ('b09f777f-1c5b-54ea-83f1-8a1126b56d8e'::uuid, 'francais', '1re', 'La Modification, Michel Butor', 'Que représente Rome pour Léon Delmont ?', 'mcq', '["La routine et le devoir familial","La ville de son enfance","La liberté et le rêve, liés à Cécile","La gloire de sa carrière"]'::jsonb, 2, 'Cécile n’existe pour lui que liée à Rome : l’installer à Paris détruirait ce rêve, d’où la « modification ».', 4),
    ('b3490f5a-6604-501c-9e7d-6c86ec99442b'::uuid, 'francais', '1re', 'La Peau de chagrin, Honoré de Balzac', 'Comment s’intitulent les trois parties du roman ?', 'mcq', '["Le Jeu, L’Orgie, La Mort","Vouloir, Pouvoir, Savoir","La Jeunesse, La Fortune, La Chute","Le Talisman, La Femme sans cœur, L’Agonie"]'::jsonb, 3, 'La deuxième partie est un récit rétrospectif : Raphaël raconte sa jeunesse studieuse et pauvre, et son amour pour Fœdora.', 1),
    ('80d757f0-84d4-5240-a1b4-a681b50470da'::uuid, 'francais', '1re', 'La Peau de chagrin, Honoré de Balzac', 'Dans quel état est Raphaël quand il entre chez l’antiquaire ?', 'mcq', '["Ruiné, il a résolu de se noyer","Riche héritier, il s’ennuie","Malade, il cherche un remède","Amoureux, il cherche un cadeau"]'::jsonb, 0, 'Il vient de perdre sa dernière pièce au jeu : le talisman s’offre à un homme qui n’a plus rien à perdre que sa vie.', 2),
    ('16ddc0af-d25a-55b0-ad89-74ce821bf064'::uuid, 'francais', '1re', 'La Peau de chagrin, Honoré de Balzac', 'Qu’apprend Raphaël juste après le banquet de Taillefer ?', 'mcq', '["Que Fœdora l’aime enfin","Que la peau a disparu","Qu’il hérite de six millions","Que Pauline est morte"]'::jsonb, 2, 'La fortune arrive, mais la peau a déjà rétréci : chaque désir exaucé se paie en temps de vie.', 3),
    ('7267d9dc-333c-5c60-9ec2-b8741debfbad'::uuid, 'francais', '1re', 'La Peau de chagrin, Honoré de Balzac', 'Qui est Pauline ?', 'mcq', '["Une actrice de l’Opéra","La fille de sa logeuse, qui l’aime","La sœur de Rastignac","La nièce de l’antiquaire"]'::jsonb, 1, 'Pauline incarne l’amour pur et dévoué, à l’opposé de Fœdora, la femme sans cœur de la société mondaine.', 4),
    ('5897afb0-1299-5c7b-a8ff-a2e80246b8d8'::uuid, 'francais', '1re', 'La Peste, Albert Camus', 'À quel écrivain Camus emprunte-t-il l’épigraphe de La Peste ?', 'mcq', '["Pascal","Montaigne","Daniel Defoe","Dostoïevski"]'::jsonb, 2, 'Camus, qui a porté le roman pendant toute la guerre, le publie en 1947 avec une épigraphe de l’Anglais Daniel Defoe.', 1),
    ('82f8112f-392b-55c6-a009-c7422c84014b'::uuid, 'francais', '1re', 'La Peste, Albert Camus', 'Que fait Cottard pendant l’épidémie ?', 'mcq', '["Il organise les secours","Il profite du fléau","Il écrit une chronique","Il prêche la pénitence"]'::jsonb, 1, 'Face aux choix de Rieux, de Rambert ou de Tarrou, Cottard est celui qui tire profit du malheur de tous.', 2),
    ('c3f72100-dd9c-55c6-abdb-6a3003805d74'::uuid, 'francais', '1re', 'La Peste, Albert Camus', 'À quoi Grand, l’employé modeste, consacre-t-il ses soirées ?', 'mcq', '["À préparer sa fuite d’Oran","À mettre au point un sérum","À écrire des sermons","À la première phrase d’un roman"]'::jsonb, 3, 'Grand réécrit sans fin la même phrase : un héros modeste et obstiné, loin de tout héroïsme exceptionnel.', 3),
    ('bf26cca4-3572-5be0-a334-1cce87aaf9a9'::uuid, 'francais', '1re', 'La Peste, Albert Camus', 'Quelle lecture allégorique fait-on souvent de la peste ?', 'mcq', '["Le nazisme et l’Occupation","La guerre d’Algérie","La crise de 1929","La révolution russe"]'::jsonb, 0, 'Publié en 1947, le roman se lit comme l’image du nazisme et de l’Occupation, mais aussi du mal en général, qu’on combat ensemble.', 4),
    ('1a2204d1-531e-5b0f-b42c-1743067e503f'::uuid, 'francais', '1re', 'La Petite Fadette, George Sand', 'Quel est le vrai nom de la petite Fadette ?', 'mcq', '["Madelon Fadet","Marie Guillette","Jeanne Barbeau","Fanchon Fadet"]'::jsonb, 3, '« Fadette » est le surnom de Fanchon Fadet, adolescente pauvre et moqueuse, que le village prend pour une sorcière.', 1),
    ('c780c2a9-a782-5875-976b-9ba709337545'::uuid, 'francais', '1re', 'La Petite Fadette, George Sand', 'Pourquoi Sylvinet tombe-t-il malade de jalousie ?', 'mcq', '["Leur père place Landry dans une ferme voisine","Landry s’engage comme soldat","Leur mère ne soigne que Landry","Landry hérite seul de la ferme"]'::jsonb, 0, 'Séparé de son jumeau, le fragile et possessif Sylvinet ne supporte pas l’éloignement : sa jalousie est l’un des fils du roman.', 2),
    ('d21f9270-2079-56bf-8859-ad0207ed41b5'::uuid, 'francais', '1re', 'La Petite Fadette, George Sand', 'Que fait Fadette pour se refaire une réputation ?', 'mcq', '["Elle épouse un riche fermier","Elle quitte le village pour servir en ville","Elle entre au couvent","Elle ouvre une école"]'::jsonb, 1, 'Elle y apprend à se tenir et revient transformée : la « sorcière » devient une femme respectée, comme dans un conte.', 3),
    ('b68331da-de7c-55cf-8305-b72fe1eb23cb'::uuid, 'francais', '1re', 'La Petite Fadette, George Sand', 'Quelle particularité de langue marque les dialogues du roman ?', 'mcq', '["Des citations latines savantes","Des vers rimés et chantés","Des tournures du parler berrichon","Un argot des faubourgs parisiens"]'::jsonb, 2, 'La langue reste simple, mais les dialogues sont teintés de parler berrichon : Sand fait entendre la voix du Berry.', 4),
    ('6931567f-7f48-50ce-b2a9-f848f8b9aa7a'::uuid, 'francais', '1re', 'La Porte étroite, André Gide', 'D’où vient le titre La Porte étroite ?', 'mcq', '["D’une parole de l’Évangile","D’un poème de Baudelaire","D’une maxime de La Rochefoucauld","D’un vers de Racine"]'::jsonb, 0, '« Efforcez-vous d’entrer par la porte étroite », dit l’Évangile : Alissa en fait la règle d’une piété exigeante.', 1),
    ('5faddbc1-24f4-5305-8f0b-b4f603549662'::uuid, 'francais', '1re', 'La Porte étroite, André Gide', 'Que prétend Alissa pour s’effacer ?', 'mcq', '["Que Jérôme aime une autre femme","Qu’elle doit entrer au couvent","Que sa sœur Juliette aime Jérôme","Qu’elle est promise à un pasteur"]'::jsonb, 2, 'Alissa recule le mariage et pousse Juliette vers Jérôme : c’est une étape de son sacrifice.', 2),
    ('7c1e32ec-b013-5e85-878b-22810ce9c091'::uuid, 'francais', '1re', 'La Porte étroite, André Gide', 'Où se déroule l’action du récit ?', 'mcq', '["À Paris, dans un salon protestant","En Provence, dans un mas isolé","En Bretagne, au bord de la mer","En Normandie, près du Havre"]'::jsonb, 3, 'L’action se passe à Fongueusemare, près du Havre : le décor d’un amour d’enfance entre deux cousins.', 3),
    ('1f96094e-ef7d-5407-a9f5-c1989e059569'::uuid, 'francais', '1re', 'La Porte étroite, André Gide', 'Quel événement familial inspire à Alissa la peur du bonheur des sens ?', 'mcq', '["La mort précoce de son père","L’inconduite de sa mère, partie avec un amant","Le mariage malheureux de Juliette","La sévérité d’un oncle pasteur"]'::jsonb, 1, 'Lucile Bucolin fuit le foyer avec un amant : Alissa en garde une peur des sens qui nourrit sa piété.', 4),
    ('8c49cfbc-7242-5053-9e59-4d52857d93b5'::uuid, 'francais', '1re', 'La Princesse de Clèves, Madame de Lafayette', 'Qui entend, caché, l’aveu de la princesse à son mari ?', 'mcq', '["Madame de Chartres","Le vidame de Chartres","La reine dauphine","Le duc de Nemours"]'::jsonb, 3, 'Nemours, caché, entend tout : l’homme que la princesse n’a pas nommé devient le témoin de l’aveu.', 1),
    ('bff35991-d5bb-5762-8cab-8dcd35f0eb60'::uuid, 'francais', '1re', 'La Princesse de Clèves, Madame de Lafayette', 'Quelles raisons la princesse donne-t-elle à son refus d’épouser Nemours ?', 'mcq', '["La volonté de sa mère et un ordre du roi","La pauvreté de Nemours et son rang trop bas","Le devoir envers le mort, la passion qui ne durerait pas","Une vocation religieuse née dans l’enfance"]'::jsonb, 2, 'Elle invoque le devoir envers le prince de Clèves, mort de jalousie et de chagrin, et la certitude que la passion de Nemours ne durerait pas.', 2),
    ('c7065491-feaa-5e1c-b19a-60e991410577'::uuid, 'francais', '1re', 'La Princesse de Clèves, Madame de Lafayette', 'Quelle cour Madame de Lafayette peint-elle à travers celle d’Henri II ?', 'mcq', '["Celle de Louis XIV","Celle de François Ier","Celle d’Henri IV","Celle de Louis XIII"]'::jsonb, 0, 'Elle situe l’action un siècle plus tôt, à la cour des Valois, mais y peint la cour de Louis XIV : un système d’observation et de calcul.', 3),
    ('a736d37a-1841-542d-b632-d634bff47aa4'::uuid, 'francais', '1re', 'La Princesse de Clèves, Madame de Lafayette', 'Dans quel esprit le roman analyse-t-il la passion ?', 'mcq', '["Celui du romantisme : un élan sublime","Celui des moralistes : une maladie à analyser","Celui des libertins : un plaisir à cueillir","Celui de la pastorale : un rêve idyllique"]'::jsonb, 1, 'Dans l’esprit du jansénisme et des moralistes, amis de l’autrice comme La Rochefoucauld, la passion est un trouble qu’on observe et qu’on juge.', 4),
    ('e8a4569c-8da4-5383-8113-69b802a42efa'::uuid, 'francais', '1re', 'La Princesse de Montpensier, Madame de La Fayette', 'Comment meurt le comte de Chabannes ?', 'mcq', '["En duel contre le duc de Guise","Au cours de la Saint-Barthélemy","De chagrin, loin de la cour","Exécuté sur ordre du prince"]'::jsonb, 1, 'Chassé par le prince, Chabannes est tué pendant la Saint-Barthélemy : son dévouement absolu n’est jamais récompensé.', 1),
    ('6388bce5-7d4b-5f73-acc7-926b34aad876'::uuid, 'francais', '1re', 'La Princesse de Montpensier, Madame de La Fayette', 'Quel est le nom de jeune fille de la princesse de Montpensier ?', 'mcq', '["Mademoiselle de Chartres","Mademoiselle de Scudéry","Mademoiselle de Strozzi","Mademoiselle de Mézières"]'::jsonb, 3, 'Amoureuse du duc de Guise, Mademoiselle de Mézières est mariée par sa famille au prince de Montpensier : une alliance de familles, non de cœurs.', 2),
    ('e6c84e19-0646-5df7-b039-c9e54dd03d5b'::uuid, 'francais', '1re', 'La Princesse de Montpensier, Madame de La Fayette', 'Que dit la dernière phrase de la nouvelle ?', 'mcq', '["Qu’elle aurait été heureuse avec plus de vertu et de prudence","Qu’elle fut la plus vertueuse des princesses de son temps","Qu’elle ne regretta jamais d’avoir aimé le duc de Guise","Que son mari lui pardonna avant qu’elle ne meure"]'::jsonb, 0, 'Le narrateur, sobre, juge en une phrase : la passion que ni la vertu ni la prudence ne conduisent se paie par la mort.', 3),
    ('bfdefb25-29fc-571d-94ec-59edf4407409'::uuid, 'francais', '1re', 'La Princesse de Montpensier, Madame de La Fayette', 'Quel sentiment, selon le cours, circule entre tous les hommes du récit ?', 'mcq', '["La foi religieuse","L’avarice","La jalousie","La soif de vengeance"]'::jsonb, 2, 'Mari, amant, rival et confident : la jalousie circule entre tous, dans une cour où l’amour sert l’ambition.', 4),
    ('c52affa2-0b32-5dcb-bbf3-3bbcf0fa79c0'::uuid, 'francais', '1re', 'La Puce à l’oreille, Georges Feydeau', 'Quels sont les trois temps de la pièce, selon le cours ?', 'mcq', '["Exposition, machine infernale, retour à l’ordre","Rencontre, mariage, séparation des époux","Crime, enquête, châtiment du coupable","Exposition, crise, mort du héros"]'::jsonb, 0, 'Trois actes : on installe le soupçon, la machine s’emballe à l’hôtel, puis tout se dénoue chez les Chandebise et le malentendu s’efface.', 1),
    ('e9d85c8e-cf3d-5a4d-a8fc-5b7e57d0e8e1'::uuid, 'francais', '1re', 'La Puce à l’oreille, Georges Feydeau', 'Qui écrit, pour Raymonde, la lettre anonyme de rendez-vous ?', 'mcq', '["Tournel, l’ami du mari","Son amie Lucienne","Le docteur Finache","Camille, le neveu"]'::jsonb, 1, 'Raymonde fait écrire la lettre par Lucienne : c’est cette écriture que reconnaîtra Homenidès, le mari jaloux de Lucienne. Un seul détail suffit à lancer la machine.', 2),
    ('6ae4ee7b-c8b3-584f-9159-3d3f24145289'::uuid, 'francais', '1re', 'La Puce à l’oreille, Georges Feydeau', 'Quel accessoire de l’hôtel du Minet-Galant fait disparaître les amants ?', 'mcq', '["Un placard à double fond","Une trappe dans le plancher","Un lit tournant","Un paravent truqué"]'::jsonb, 2, 'Le lit tournant escamote les amants : chez Feydeau, chaque objet et chaque porte ont une fonction dans la mécanique.', 3),
    ('c5216bf9-0516-557b-8e96-8fd21e57a9a2'::uuid, 'francais', '1re', 'La Puce à l’oreille, Georges Feydeau', 'Quel secret cache Tournel, l’ami de Chandebise ?', 'mcq', '["Il est le sosie de Chandebise","Il dirige l’hôtel du Minet-Galant","Il est le mari de Lucienne","Il courtise Raymonde en secret"]'::jsonb, 3, 'Tournel, envoyé au rendez-vous à la place de son ami, courtise Raymonde en secret. Le sosie de Chandebise, c’est Poche, le garçon d’hôtel.', 4),
    ('3a9945ec-b620-50fa-bab7-d43544da802a'::uuid, 'francais', '1re', 'La rage de l’expression, Francis Ponge', 'Quand les textes sont-ils écrits, et quand le livre paraît-il ?', 'mcq', '["Écrits de 1920 à 1930, parus en 1942","Écrits de 1945 à 1950, parus en 1952","Écrits de 1938 à 1944, parus en 1952","Écrits de 1938 à 1944, parus en 1945"]'::jsonb, 2, 'Les sept ensembles sont écrits de 1938 à 1944, au gré des lieux où vit Ponge, résistant en zone sud, puis publiés en 1952.', 1),
    ('5afb85e5-7df3-580f-91d1-121ceaaebf77'::uuid, 'francais', '1re', 'La rage de l’expression, Francis Ponge', 'Que cherche à dire Ponge dans « La Mounine » ?', 'mcq', '["Un ciel de Provence vu en voyage","Un bois de pins en plein été","Les berges de la Loire au soir","Le vol obstiné d’une guêpe"]'::jsonb, 0, 'Ce ciel de Provence, le poète n’arrive pas à le dire : le texte garde la trace de cet échec et de ses reprises.', 2),
    ('b1c857fb-dd6a-510f-93e8-7c8daf106e2a'::uuid, 'francais', '1re', 'La rage de l’expression, Francis Ponge', 'Quel « je » s’exprime dans ces textes, selon le cours ?', 'mcq', '["Celui d’un cœur qui s’épanche","Celui d’un ouvrier au travail","Celui d’un prophète inspiré","Celui d’un personnage inventé"]'::jsonb, 1, 'Le « je » de Ponge est celui d’un ouvrier au travail : l’émotion est déplacée du poète vers la chose, contre le lyrisme.', 3),
    ('54ed5f73-8d7c-5bf0-9a9f-0758e34ea3c2'::uuid, 'francais', '1re', 'La rage de l’expression, Francis Ponge', 'Sans vers ni rime, à quoi tient la poésie de ces textes ?', 'mcq', '["À la musique des alexandrins","Aux images mythologiques","À l’effusion des sentiments","À l’exigence de justesse"]'::jsonb, 3, 'Chercher le mot exact pour une guêpe ou un œillet est l’acte poétique même : nommer exactement est plus difficile que chanter ses états d’âme.', 4),
    ('d5c62e94-efde-5631-9d1b-b01064680f60'::uuid, 'francais', '1re', 'La Reine Margot, Alexandre Dumas', 'Dans quel journal le roman paraît-il d’abord en feuilleton ?', 'mcq', '["La Presse","Le Journal des débats","Le Siècle","Le Constitutionnel"]'::jsonb, 0, 'Le roman paraît en feuilleton dans La Presse : chapitres courts, rebondissements et fins suspendues tiennent le lecteur d’un numéro à l’autre.', 1),
    ('afda0f14-ee9d-5d25-be52-dad97943d4db'::uuid, 'francais', '1re', 'La Reine Margot, Alexandre Dumas', 'Qui aime Coconnas, l’ami de La Mole ?', 'mcq', '["Marguerite de Valois","La duchesse de Nevers","Catherine de Médicis","Charlotte de Sauve"]'::jsonb, 1, 'Le roman double le couple Margot–La Mole d’un second couple, la duchesse de Nevers et Coconnas ; les deux amis seront exécutés ensemble.', 2),
    ('086a42d2-64b3-5b40-b627-f21e32afe4c0'::uuid, 'francais', '1re', 'La Reine Margot, Alexandre Dumas', 'Qui meurt, finalement, du livre empoisonné destiné à Henri ?', 'mcq', '["Henri de Navarre","Le duc d’Alençon","Charles IX","Catherine de Médicis"]'::jsonb, 2, 'L’arme préparée contre Henri tue le roi Charles IX : dans ce roman, les pires ennemis sont souvent du même sang.', 3),
    ('90719b4a-8380-5c71-9a6e-591f317d97d3'::uuid, 'francais', '1re', 'La Reine Margot, Alexandre Dumas', 'Comment Henri de Navarre gagne-t-il l’amitié de Charles IX ?', 'mcq', '["En se convertissant publiquement","En lui livrant La Mole","En lui offrant un faucon de chasse","En le sauvant d’un sanglier"]'::jsonb, 3, 'Pendant une chasse, Henri sauve le roi d’un sanglier : Charles IX lui en garde de l’amitié. Le futur Henri IV survit à la cour à force de ruse.', 4),
    ('7edab009-f8d7-5bea-98e0-8b7431a28e01'::uuid, 'francais', '1re', 'La Symphonie pastorale, André Gide', 'À quel concert le pasteur conduit-il Gertrude ?', 'mcq', '["Un requiem de Mozart","Un oratorio de Bach","La Symphonie pastorale de Beethoven","Les Quatre Saisons de Vivaldi"]'::jsonb, 2, 'La Symphonie pastorale de Beethoven donne son titre au récit : une musique qui peint un monde harmonieux, comme celui que le pasteur décrit à l’aveugle.', 1),
    ('09b35227-f174-5ca1-a8b9-97aba1091da3'::uuid, 'francais', '1re', 'La Symphonie pastorale, André Gide', 'Comment le pasteur juge-t-il la jalousie de sa femme Amélie ?', 'mcq', '["Il la trouve mesquine","Il la trouve légitime","Il la trouve touchante","Il ne la remarque pas"]'::jsonb, 0, 'Il juge mesquine la jalousie de l’épouse délaissée : il ne voit pas que c’est son propre désir, qu’il ignore, qui la cause.', 2),
    ('7e811791-6b0f-5343-9b8e-c459539bf1cb'::uuid, 'francais', '1re', 'La Symphonie pastorale, André Gide', 'Que devient Jacques, le fils du pasteur ?', 'mcq', '["Il devient pasteur à son tour","Il se convertit au catholicisme","Il épouse Gertrude","Il part s’installer à Paris"]'::jsonb, 1, 'Éloigné par son père, dont il est le rival, Jacques se tourne vers le catholicisme ; Gertrude se convertira elle aussi.', 3),
    ('b312ab88-2f7a-57d4-95e8-b2cfaf41bfa2'::uuid, 'francais', '1re', 'La Symphonie pastorale, André Gide', 'Comment finit Gertrude ?', 'mcq', '["Emportée par une fièvre d’hiver","Morte pendant l’opération","Partie vivre avec Jacques","Elle se jette dans la rivière"]'::jsonb, 3, 'Elle se jette dans la rivière et meurt après avoir tout dit : la vérité qu’elle a vue et comprise retombe sur le pasteur.', 4),
    ('2497660b-218c-5cff-a794-661ee106825c'::uuid, 'francais', '1re', 'La Vie devant soi, Émile Ajar', 'Que prétend Madame Rosa quand le père de Momo vient réclamer son fils ?', 'mcq', '["Qu’elle l’a élevé dans la religion juive","Que l’enfant est mort depuis longtemps","Qu’elle n’a jamais connu cet enfant","Que l’enfant a été adopté ailleurs"]'::jsonb, 0, 'Face à cet homme sorti d’un asile, la ruse de Rosa protège Momo : l’amour hors des liens du sang est au cœur du roman.', 1),
    ('a699699a-b2d2-58c5-a826-acf94e43c231'::uuid, 'francais', '1re', 'La Vie devant soi, Émile Ajar', 'Où Momo aide-t-il Madame Rosa à s’installer pour mourir ?', 'mcq', '["À l’hôpital du quartier","Dans son « trou juif », au sous-sol","Chez le docteur Katz","Chez Madame Lola"]'::jsonb, 1, 'Rosa redoute l’hôpital et l’acharnement thérapeutique ; Momo la descend dans ce refuge du sous-sol et reste près d’elle jusqu’à sa mort, puis trois semaines encore.', 2),
    ('e49eb6d0-cecd-5961-8140-2f36b43c1f42'::uuid, 'francais', '1re', 'La Vie devant soi, Émile Ajar', 'Qui est Madame Lola ?', 'mcq', '["Une ancienne prostituée rescapée des camps","La mère disparue de Momo","Un ancien boxeur sénégalais devenu travesti","L’assistante sociale du quartier"]'::jsonb, 2, 'Madame Lola, voisine de Belleville, fait partie de la famille choisie qui entoure Momo et Rosa, contre tous les clivages.', 3),
    ('24ab616a-8805-56c7-a76a-bf71ce07a8ab'::uuid, 'francais', '1re', 'La Vie devant soi, Émile Ajar', 'Quel auteur Monsieur Hamil récite-t-il en vieillissant ?', 'mcq', '["La Fontaine","Baudelaire","Molière","Victor Hugo"]'::jsonb, 3, 'Monsieur Hamil vieillit en récitant Victor Hugo : avec Rosa, il incarne la vieillesse, l’un des grands thèmes du roman.', 4),
    ('8281ff0f-5176-5b58-bd92-efc9870e981b'::uuid, 'francais', '1re', 'Le Barbier de Séville, Beaumarchais', 'Que signifie le sous-titre « la Précaution inutile » ?', 'mcq', '["Plus Bartholo enferme Rosine, plus elle s’échappe","Figaro prend trop de précautions et échoue","Le comte se méfie à tort de son ancien valet","Rosine se méfie sans raison du jeune Lindor"]'::jsonb, 0, 'Le barbon surveille sa pupille jour et nuit, et c’est ce qui la pousse à la ruse : le mariage est signé sous son nez.', 1),
    ('9b59e5de-1c85-58db-938a-965075f04ba6'::uuid, 'francais', '1re', 'Le Barbier de Séville, Beaumarchais', 'Comment se débarrasse-t-on de Bazile quand il survient à contretemps ?', 'mcq', '["On l’enferme dans un cabinet","On le persuade qu’il a la fièvre","On le fait arrêter par la garde","On lui annonce le départ de Rosine"]'::jsonb, 1, 'Tous lui répètent qu’il a la fièvre et le renvoient se coucher ; une bourse glissée achève de le convaincre : l’homme de la calomnie cède à l’argent.', 2),
    ('04e6ac3c-72ed-5b82-b861-4bdc6b766c2d'::uuid, 'francais', '1re', 'Le Barbier de Séville, Beaumarchais', 'Pourquoi la pièce, d’abord un échec, finit-elle par triompher en 1775 ?', 'mcq', '["Le roi en fait publiquement l’éloge","Beaumarchais en change le dénouement","Beaumarchais la resserre en quatre actes","Elle est jouée avec de la musique"]'::jsonb, 2, 'Jouée en cinq actes, elle échoue ; resserrée en quatre, elle triomphe. La vitesse fait partie de son esprit : rythme d’opéra et virtuosité verbale.', 3),
    ('fc59719f-1ab5-5811-906d-71e20c2cd617'::uuid, 'francais', '1re', 'Le Barbier de Séville, Beaumarchais', 'Quel compositeur tire de la pièce un opéra en 1816 ?', 'mcq', '["Mozart","Verdi","Gluck","Rossini"]'::jsonb, 3, 'Rossini en tire son opéra en 1816 : la comédie de Beaumarchais, lui-même musicien, avait déjà un rythme d’opéra.', 4),
    ('b8fa6363-f8a2-5af8-b33f-f953b8d635a2'::uuid, 'francais', '1re', 'Le Château des Carpathes, Jules Verne', 'Chez quel éditeur paraissent les Voyages extraordinaires de Jules Verne ?', 'mcq', '["Hetzel","Gallimard","Hachette","Flammarion"]'::jsonb, 0, 'Les Voyages extraordinaires paraissent chez Hetzel ; Le Château des Carpathes (1892) arrive à la fin de la carrière de Verne.', 1),
    ('b75a6950-fa98-5a93-8dcd-b66795773b3b'::uuid, 'francais', '1re', 'Le Château des Carpathes, Jules Verne', 'Qui aperçoit le premier de la fumée au-dessus du château ?', 'mcq', '["Le forestier Nic Deck","Le berger Frik, à la lunette","Maître Koltz, le magistrat","Le jeune comte Franz"]'::jsonb, 1, 'Le berger Frik voit la fumée à la lunette : le village de Werst, déjà superstitieux, en conclut que le château est hanté.', 2),
    ('af334c3c-e383-5699-bda0-b0f260ebd895'::uuid, 'francais', '1re', 'Le Château des Carpathes, Jules Verne', 'Selon le cours, que révèle l’attachement de Gortz à une voix enregistrée ?', 'mcq', '["Un désir de vengeance contre Franz","Une foi aveugle dans la science","Un refus de la mort","Une simple curiosité d’inventeur"]'::jsonb, 2, 'Aimer une voix enregistrée, c’est refuser la mort : l’image et la voix survivent à la personne, et le baron ne vit que pour elles.', 3),
    ('f920276e-d824-543e-bddb-7434c724886b'::uuid, 'francais', '1re', 'Le Château des Carpathes, Jules Verne', 'Qui est Rodolphe de Gortz ?', 'mcq', '["Le magistrat superstitieux de Werst","Le savant qui construit les machines","Le jeune amant de La Stilla","Le baron mélomane obsédé par une voix"]'::jsonb, 3, 'Gortz, amoureux fou de la cantatrice, a fait enregistrer sa voix sur des phonographes ; c’est Orfanik, son savant, qui construit les machines.', 4),
    ('4ea99c7d-986c-5247-a748-7b36e134dea0'::uuid, 'francais', '1re', 'Le Cid, Pierre Corneille', 'Contre qui Rodrigue se bat-il dans le duel judiciaire ordonné par le roi ?', 'mcq', '["Don Sanche, soupirant de Chimène","Don Gomès, le père de Chimène","Le chef de l’armée maure","Don Diègue, son propre père"]'::jsonb, 0, 'Don Sanche est le champion malheureux de Chimène ; le roi, arbitre qui temporise, diffère ensuite le mariage d’un an : la fin reste ouverte.', 1),
    ('abf34f56-eb2f-56fd-8b3f-8df853ac7af3'::uuid, 'francais', '1re', 'Le Cid, Pierre Corneille', 'Quel geste de don Gomès déclenche l’intrigue ?', 'mcq', '["Il refuse le mariage des deux jeunes gens","Il gifle don Diègue, le père de Rodrigue","Il provoque Rodrigue en duel","Il insulte publiquement le roi"]'::jsonb, 1, 'Don Diègue, trop vieux pour se venger, confie l’affront à son fils : d’où le dilemme de Rodrigue entre l’honneur et l’amour.', 2),
    ('15374f55-e2bd-56f6-b25e-a3e6538221a7'::uuid, 'francais', '1re', 'Le Cid, Pierre Corneille', 'Qui dit « Va, je ne te hais point » ?', 'mcq', '["L’Infante, à Rodrigue","Don Diègue, à son fils","Chimène, à Rodrigue","Rodrigue, à don Sanche"]'::jsonb, 2, 'C’est l’aveu de Chimène : cette litote dit l’amour qu’elle ne peut pas déclarer au meurtrier de son père.', 3),
    ('0769060b-e97d-50c4-bb06-24bd83e31780'::uuid, 'francais', '1re', 'Le Cid, Pierre Corneille', 'Quel était le genre du Cid à sa création ?', 'mcq', '["Une comédie héroïque","Une pastorale","Une tragédie régulière","Une tragi-comédie"]'::jsonb, 3, 'D’abord tragi-comédie, la pièce devient tragédie dans les éditions suivantes, à l’heure où les règles du classicisme s’imposent.', 4),
    ('9b0dcad7-2fda-5642-9ffd-e43633738e4a'::uuid, 'francais', '1re', 'Le Colonel Chabert, Honoré de Balzac', 'Que tente la comtesse Ferraud pour se débarrasser de Chabert ?', 'mcq', '["L’attirer à la campagne et lui faire signer un désistement","Le faire arrêter comme déserteur de l’armée impériale","Acheter le silence de l’avoué Derville à prix d’or","Fuir à l’étranger en emportant toute sa fortune"]'::jsonb, 0, 'Elle l’attendrit et l’attire à la campagne ; il signe presque, puis comprend qu’elle le méprise et, écœuré, renonce à tout.', 1),
    ('be060906-57a9-5239-8c84-8a1b70120287'::uuid, 'francais', '1re', 'Le Colonel Chabert, Honoré de Balzac', 'Pour quelle ambition le comte Ferraud pourrait-il répudier sa femme ?', 'mcq', '["Épouser une jeune actrice","Devenir pair de France","Racheter les biens de Chabert","Rejoindre la cour à l’étranger"]'::jsonb, 1, 'Le comte, noble de la Restauration, vise la pairie : la comtesse, qui le sait, a tout à craindre du retour d’un premier mari.', 2),
    ('8cb68c83-c8bf-56da-ae7e-0492fe32ec83'::uuid, 'francais', '1re', 'Le Colonel Chabert, Honoré de Balzac', 'Sous quel titre le récit paraît-il d’abord, en 1832 ?', 'mcq', '["Le Revenant d’Eylau","La Comtesse Ferraud","La Transaction","Le Soldat oublié"]'::jsonb, 2, 'Paru en 1832 sous le titre La Transaction, le récit est ensuite intégré à La Comédie humaine : le titre dit déjà que tout, même une identité, se négocie.', 3),
    ('2ba4acdd-ca6f-5e41-aab0-4feacee27c3e'::uuid, 'francais', '1re', 'Le Colonel Chabert, Honoré de Balzac', 'Qu’était la comtesse Ferraud avant d’épouser Chabert ?', 'mcq', '["Une aristocrate d’Ancien Régime","La fille d’un riche notaire","Une actrice de la Comédie-Française","Une fille du Palais-Royal"]'::jsonb, 3, 'Ancienne fille du Palais-Royal devenue comtesse, elle incarne l’ambition sans scrupules : elle doit tout à Chabert et le renie.', 4),
    ('61d073f3-0d7c-587a-9b35-6d6643689f03'::uuid, 'francais', '1re', 'Le Comte de Monte-Cristo, Alexandre Dumas', 'Avec qui Dantès s’éloigne-t-il à la fin du roman ?', 'mcq', '["Avec Haydée","Avec Mercédès","Avec l’armateur Morrel","Avec l’abbé Faria"]'::jsonb, 0, 'Troublé de voir que sa vengeance atteint aussi des innocents, il part avec Haydée, la fille de l’homme que Fernand avait trahi.', 1),
    ('9c1624fb-92ee-5d21-9f42-60a48e68bc2c'::uuid, 'francais', '1re', 'Le Comte de Monte-Cristo, Alexandre Dumas', 'Qui le comte sauve-t-il de la faillite ?', 'mcq', '["Le banquier Danglars","L’armateur Morrel","Le procureur Villefort","Le pêcheur Fernand"]'::jsonb, 1, 'Le comte récompense la loyauté de l’armateur Morrel et punit la trahison : Danglars, devenu baron et banquier, finit ruiné.', 2),
    ('f5d2fbc3-1c89-5987-b9dd-c3eaea99bbea'::uuid, 'francais', '1re', 'Le Comte de Monte-Cristo, Alexandre Dumas', 'Que devient le procureur Villefort ?', 'mcq', '["Il se tue","Il est ruiné","Il devient fou","Il s’exile"]'::jsonb, 2, 'Ruine, déshonneur, folie, suicide : chaque ennemi reçoit son châtiment, et Villefort, qui avait fait disparaître Dantès pour se protéger, finit fou.', 3),
    ('a2c7f6c6-7454-507a-b53a-2ead70f3e3d9'::uuid, 'francais', '1re', 'Le Comte de Monte-Cristo, Alexandre Dumas', 'Quelle formule clôt le roman ?', 'mcq', '["« Tous pour un »","« Vengeance est faite »","« Tout est accompli »","« Attendre et espérer »"]'::jsonb, 3, 'Après la vengeance et le doute, le roman se clôt sur la patience et l’espoir : deux mots qui répondent aux quatorze ans du château d’If.', 4),
    ('bb293647-dbda-5d74-8731-3fb1ee9e5ad1'::uuid, 'francais', '1re', 'Le Dernier Jour d’un condamné, Victor Hugo', 'Quel autre texte prolonge le combat de Hugo contre la peine de mort ?', 'mcq', '["Claude Gueux","Hernani","Les Contemplations","Notre-Dame de Paris"]'::jsonb, 0, 'Claude Gueux, puis le discours de 1848, poursuivent un combat de toute une vie ; la peine de mort ne sera abolie en France qu’en 1981.', 1),
    ('bfbc6984-1577-57f9-aea6-7e8f054a9fe2'::uuid, 'francais', '1re', 'Le Dernier Jour d’un condamné, Victor Hugo', 'Comment le livre paraît-il en 1829 ?', 'mcq', '["Signé de Hugo, avec une préface","Anonymement, revendiqué en 1832","En feuilleton dans un journal","Sous le nom d’un vrai condamné"]'::jsonb, 1, 'Hugo ne revendique le livre que dans la préface de 1832 : en 1829, le récit paraît sans nom d’auteur, comme son condamné paraît sans nom.', 2),
    ('ebdab460-dc5d-5f6e-9812-378ba2d2b537'::uuid, 'francais', '1re', 'Le Dernier Jour d’un condamné, Victor Hugo', 'Comment le cours présente-t-il le prêtre qui assiste le condamné ?', 'mcq', '["Il plaide sa grâce auprès du roi","Il le console vraiment","Il récite des formules, sans le toucher","Il refuse de lui parler"]'::jsonb, 2, 'Le prêtre récite des formules apprises : même la religion devient une étape de la mécanique, comme la toilette et la charrette.', 3),
    ('d2f06ce1-d158-5000-b558-0bc23d175cbc'::uuid, 'francais', '1re', 'Le Dernier Jour d’un condamné, Victor Hugo', 'Quel effet produisent les chapitres très brefs, parfois d’une ligne ?', 'mcq', '["Ils imitent un procès-verbal","Ils ralentissent l’action","Ils trahissent un brouillon inachevé","Ils miment le temps haché de l’angoisse"]'::jsonb, 3, 'Le fragment fait éprouver l’attente minute par minute : l’argument de Hugo n’est pas juridique, il est expérimental.', 4),
    ('45b76f75-b827-5c77-abb5-45e3b6ddaae0'::uuid, 'francais', '1re', 'Le Dindon, Georges Feydeau', 'Quelle formule résume le sort de Pontagnac ?', 'mcq', '["L’arroseur arrosé","Le monde renversé","Le valet devenu maître","La précaution inutile"]'::jsonb, 0, 'Pontagnac tombe dans le piège qu’il tend aux autres : celui qui manœuvre le plus est celui qui perd.', 1),
    ('37fc166b-76f7-50d9-bb43-8e9f545ff0db'::uuid, 'francais', '1re', 'Le Dindon, Georges Feydeau', 'Pourquoi Rédillon, le jeune soupirant de Lucienne, échoue-t-il ?', 'mcq', '["Il se trompe d’hôtel","Il est épuisé au mauvais moment","Il avoue tout à Vatelin","Il est arrêté par le commissaire"]'::jsonb, 1, 'Sa maîtresse Armandine l’a épuisé juste au mauvais moment : chez Feydeau, la vertu est presque toujours un accident de calendrier.', 2),
    ('3bafb9be-aa86-5f86-a2c5-8da5b757264a'::uuid, 'francais', '1re', 'Le Dindon, Georges Feydeau', 'Qui vient relancer Vatelin, le mari honnête ?', 'mcq', '["La femme de Pontagnac","Une actrice du Palais-Royal","Maggy, une ancienne maîtresse anglaise","Armandine, la maîtresse de Rédillon"]'::jsonb, 2, 'Maggy Soldignac débarque à Paris juste après le serment de Lucienne : le passé de Vatelin le rattrape au pire moment.', 3),
    ('dc76128d-e8d5-5af8-9d84-e6cc21afbee2'::uuid, 'francais', '1re', 'Le Dindon, Georges Feydeau', 'Quels objets mécaniques l’hôtel Ultimus réserve-t-il ?', 'mcq', '["Un lit tournant et une trappe","Un téléphone et un phonographe","Un ascenseur et un monte-charge","Une sonnerie électrique et un lit à ressorts"]'::jsonb, 3, 'Chez Feydeau, les objets déclenchent des catastrophes : la mécanique implacable passe autant par les accessoires que par les portes.', 4),
    ('9e9fd7e5-bff4-59c5-b4dc-c39af09b3810'::uuid, 'francais', '1re', 'Le Grand Meaulnes, Alain Fournier', 'Quelle est la dernière image du roman ?', 'mcq', '["Meaulnes, la nuit, enveloppant sa fille dans un manteau","François seul dans la salle de classe vide","Le domaine mystérieux en ruine sous la neige","Frantz et Valentine dansant à la fête étrange"]'::jsonb, 0, 'Meaulnes repart avec l’enfant « pour de nouvelles aventures » : l’aventurier fuit encore le bonheur réel.', 1),
    ('69533d33-a5e5-5a92-9857-5ec67ed9a198'::uuid, 'francais', '1re', 'Le Grand Meaulnes, Alain Fournier', 'Qui est Valentine ?', 'mcq', '["La sœur cadette de François","La fiancée qui a fui Frantz","La cousine d’Yvonne de Galais","L’institutrice du village"]'::jsonb, 1, 'Meaulnes la rencontre à Paris sans savoir qu’elle est la fiancée de Frantz : sa promesse imprudente à Frantz le rattrapera.', 2),
    ('9f30060f-0812-5755-a7fe-0a377b14616e'::uuid, 'francais', '1re', 'Le Grand Meaulnes, Alain Fournier', 'Combien de temps dure la disparition de Meaulnes ?', 'mcq', '["Une seule nuit","Trois semaines","Trois jours","Toute une année"]'::jsonb, 2, 'Meaulnes disparaît trois jours et revient transformé : en se perdant, il a trouvé le domaine, la fête et Yvonne de Galais.', 3),
    ('0b6ee7f7-2ec9-5a05-8f19-3128a792e7b8'::uuid, 'francais', '1re', 'Le Grand Meaulnes, Alain Fournier', 'Comment meurt Yvonne de Galais ?', 'mcq', '["Noyée dans l’étang du domaine","D’une fièvre, pendant la fête","Dans un accident de voiture","En donnant naissance à une fille"]'::jsonb, 3, 'Yvonne meurt en donnant naissance à une fille : l’amour idéal était fragile, et Meaulnes ne revient qu’après.', 4),
    ('dbbe53dc-995e-5014-9c1b-3ef885c03388'::uuid, 'francais', '1re', 'Le Guépard, Giuseppe Tomasi di Lampedusa', 'Quel prix littéraire italien le roman obtient-il ?', 'mcq', '["Le prix Strega","Le prix Goncourt","Le prix Viareggio","Le prix Nobel"]'::jsonb, 0, 'Refusé du vivant de son auteur, le roman posthume reçoit le prix Strega et devient un immense succès mondial.', 1),
    ('99b3c0e4-faab-58cc-b2e2-afd611efc633'::uuid, 'francais', '1re', 'Le Guépard, Giuseppe Tomasi di Lampedusa', 'Que devient Bendicò, le chien du prince, dans l’épilogue de 1910 ?', 'mcq', '["Il est enterré dans la chapelle","Empaillé, il est jeté à la poubelle","Il est offert à Tancredi","Il meurt le même jour que le prince"]'::jsonb, 1, 'Le chien empaillé jeté aux ordures clôt le livre : même la mémoire du prince finit à la poubelle.', 2),
    ('be9b2a17-596e-5223-8a95-25816700126f'::uuid, 'francais', '1re', 'Le Guépard, Giuseppe Tomasi di Lampedusa', 'De qui l’auteur s’inspire-t-il pour le prince Salina ?', 'mcq', '["De Garibaldi lui-même","De son père, ministre du roi","De son arrière-grand-père, prince et astronome","D’un cardinal de Palerme"]'::jsonb, 2, 'Aristocrate de Palerme, Lampedusa prête au prince Salina les traits de son arrière-grand-père, prince et astronome.', 3),
    ('b46a98ca-b5e3-5a13-8c60-8aa4bada3a27'::uuid, 'francais', '1re', 'Le Guépard, Giuseppe Tomasi di Lampedusa', 'Quel est le parcours politique de Tancredi ?', 'mcq', '["Il reste fidèle aux Bourbons","Il devient sénateur à la place du prince","Il s’exile à Naples avec sa famille","Il rejoint les garibaldiens, puis l’armée royale"]'::jsonb, 3, 'Tancredi suit le mouvement de l’histoire et épouse la fortune neuve d’Angelica : il incarne la formule « Il faut que tout change pour que rien ne change ».', 4),
    ('65c2b77a-02d5-59b7-9e1f-a8f8fec596a1'::uuid, 'francais', '1re', 'Le Horla, Guy de Maupassant', 'Sur quels mots le récit s’achève-t-il ?', 'mcq', '["« il va donc falloir que je me tue, moi »","« Il est mort, je suis enfin sauvé »","« Je pars demain pour le Brésil »","« Tout cela n’était qu’un rêve »"]'::jsonb, 0, 'L’être invisible a survécu à l’incendie : la chute ne tranche pas entre folie et surnaturel, elle enferme le narrateur.', 1),
    ('d54aa624-e582-55a1-9dc4-7ff7cb45c817'::uuid, 'francais', '1re', 'Le Horla, Guy de Maupassant', 'Quel geste anodin le narrateur fera-t-il plus tard l’origine de son mal ?', 'mcq', '["Il a bu l’eau d’une source","Il a salué un trois-mâts brésilien","Il a acheté un miroir ancien","Il a cueilli une rose rouge"]'::jsonb, 1, 'Le trois-mâts passe devant sa maison au bord de la Seine ; plus tard, un article sur une épidémie de folie au Brésil lui fait croire que l’être est venu par ce navire.', 2),
    ('98577eae-d508-50d1-bc6c-514c9d69790e'::uuid, 'francais', '1re', 'Le Horla, Guy de Maupassant', 'À quelle force que l’on ne voit pas le moine du Mont-Saint-Michel fait-il penser ?', 'mcq', '["La lumière","Le feu","Le vent","La mer"]'::jsonb, 2, 'Le vent agit et pourtant on ne le voit pas : le moine demande si nous voyons « la cent millième partie de ce qui existe ».', 3),
    ('bf5ec758-b74a-5424-b6a0-0159e05c4e82'::uuid, 'francais', '1re', 'Le Horla, Guy de Maupassant', 'Que montre au narrateur la séance d’hypnotisme du docteur Parent ?', 'mcq', '["Que le Horla n’existe pas","Que la science explique tout","Que sa cousine est folle","Que la volonté peut être possédée"]'::jsonb, 3, 'Le docteur Parent hypnotise la cousine du narrateur : les savoirs du temps (hypnose, microbes, évolution) nourrissent la peur au lieu de l’apaiser.', 4),
    ('c10f677e-d582-5502-990e-2e1026725b07'::uuid, 'francais', '1re', 'Le Hussard sur le toit, Jean Giono', 'Qui est Giuseppe ?', 'mcq', '["Le frère de lait d’Angelo, cordonnier","Le vieux marquis, mari de Pauline","Le jeune médecin qui meurt","Un policier lancé à ses trousses"]'::jsonb, 0, 'Giuseppe, frère de lait d’Angelo, cordonnier et révolutionnaire, rappelle l’engagement de carbonaro du héros.', 1),
    ('2789a624-00f7-5210-b999-fa501eb231ca'::uuid, 'francais', '1re', 'Le Hussard sur le toit, Jean Giono', 'Que fait Angelo à la fin du roman ?', 'mcq', '["Il épouse Pauline en Provence","Il ramène Pauline chez elle, puis repart","Il meurt du choléra à Manosque","Il reste soigner les malades"]'::jsonb, 1, 'Il ramène Pauline chez elle et repart pour l’Italie : l’amour sans aveu garde toute son intensité.', 2),
    ('190a63c8-fcd9-56da-ab2d-65de3e7f742f'::uuid, 'francais', '1re', 'Le Hussard sur le toit, Jean Giono', 'De quoi la foule accuse-t-elle Angelo ?', 'mcq', '["D’être un espion autrichien","De dépouiller les morts","D’empoisonner les fontaines","De propager la peste"]'::jsonb, 2, 'La panique cherche des coupables : poursuivi comme empoisonneur de fontaines, Angelo se réfugie sur les toits. La barbarie des vivants dépasse celle de la maladie.', 3),
    ('8eafc0b4-e7b9-5e96-9914-76e270721a21'::uuid, 'francais', '1re', 'Le Hussard sur le toit, Jean Giono', 'Quel écrivain influence le « second Giono », celui d’après-guerre ?', 'mcq', '["Zola","Proust","Flaubert","Stendhal"]'::jsonb, 3, 'Moins lyrique, plus romanesque, le second Giono se tourne vers Stendhal : Angelo, jeune, plein de panache et d’honneur, est un héros stendhalien.', 4),
    ('ed26433f-deb1-559a-86e3-632f2f9c1353'::uuid, 'francais', '1re', 'Le Jeu de l’amour et du hasard, Marivaux', 'Que redoute Silvia dans le mariage ?', 'mcq', '["Qu’un mari aimable en société soit un tyran chez lui","De devoir quitter pour toujours la maison de son père","D’épouser un homme bien moins riche qu’elle","De perdre la compagnie de sa suivante Lisette"]'::jsonb, 0, 'Silvia se méfie des apparences : d’où l’idée d’observer le prétendant sous un déguisement. La sincérité ne se prouve que par une épreuve.', 1),
    ('8317ea3e-ef06-54b9-9526-07a19ac98141'::uuid, 'francais', '1re', 'Le Jeu de l’amour et du hasard, Marivaux', 'Qui avoue le premier sa véritable identité ?', 'mcq', '["Silvia","Dorante","Arlequin","Lisette"]'::jsonb, 1, 'Dorante avoue le premier ; Silvia, elle, prolonge le jeu jusqu’à obtenir qu’il la demande en mariage en la croyant servante.', 2),
    ('07925da5-d828-5565-a47d-e56dadc790ca'::uuid, 'francais', '1re', 'Le Jeu de l’amour et du hasard, Marivaux', 'Qu’appelle-t-on le marivaudage ?', 'mcq', '["Le comique des coups de bâton","L’usage de l’alexandrin comique","L’art de dire et de retarder l’aveu","Le mélange de la farce et du drame"]'::jsonb, 2, 'Les personnages découvrent ce qu’ils sentent en parlant : le langage retarde l’aveu tout en le préparant.', 3),
    ('2e6a9bb1-21a5-5e85-9212-57557da75fb2'::uuid, 'francais', '1re', 'Le Jeu de l’amour et du hasard, Marivaux', 'D’où viennent les noms de Silvia et d’Arlequin ?', 'mcq', '["De personnages de Molière","De la comédie latine","De héros de romans précieux","Des rôles habituels des Comédiens-Italiens"]'::jsonb, 3, 'Marivaux écrit pour les Comédiens-Italiens, dont le jeu vif et naturel convient à ses dialogues : Silvia et Arlequin sont les noms de leurs rôles habituels.', 4),
    ('93afba6b-7d96-58bd-8ddf-885b338321ee'::uuid, 'francais', '1re', 'Le Lys dans la vallée, Honoré de Balzac', 'Quel geste de Félix, lors d’un bal, ouvre l’histoire ?', 'mcq', '["Il embrasse les épaules d’Henriette","Il lui offre un premier bouquet","Il la demande aussitôt en mariage","Il provoque son mari en duel"]'::jsonb, 0, 'Ce baiser impulsif d’un jeune homme mal aimé de sa mère lance une passion qui ne sera jamais consommée.', 1),
    ('dc869f00-8716-5a06-82ef-5667a451ddeb'::uuid, 'francais', '1re', 'Le Lys dans la vallée, Honoré de Balzac', 'Quel amour de jeunesse de Balzac le roman transpose-t-il ?', 'mcq', '["Celui pour Madame Hanska","Celui pour Madame de Berny","Celui pour la duchesse de Castries","Celui pour George Sand"]'::jsonb, 1, 'Madame de Berny avait vingt-deux ans de plus que lui : Balzac transpose cet amour dans la Touraine, sa province natale.', 2),
    ('83c5a050-ea32-5c3a-8923-71f1a9f058ee'::uuid, 'francais', '1re', 'Le Lys dans la vallée, Honoré de Balzac', 'Qui est M. de Mortsauf ?', 'mcq', '["Le père de Félix de Vandenesse","Un jeune officier ambitieux","Un ancien émigré brisé et tyrannique","Le médecin de la famille"]'::jsonb, 2, 'Mari malade et aigri, il fait souffrir les siens : Henriette, mère de deux enfants fragiles, vit prisonnière de ce foyer.', 3),
    ('d2c46b72-bea1-50b7-849b-58a45b40806f'::uuid, 'francais', '1re', 'Le Lys dans la vallée, Honoré de Balzac', 'Comment Natalie de Manerville répond-elle au récit de Félix ?', 'mcq', '["Par une longue lettre d’amour","En le rejoignant à Clochegourde","Elle ne lui répond jamais","Par un billet sec et ironique"]'::jsonb, 3, 'Tout le roman est une longue lettre à Natalie, qui refuse de rivaliser avec une morte et rompt : la fin retourne le récit contre son narrateur.', 4),
    ('546afcf7-a74e-5855-9b7f-87e622c5b1fc'::uuid, 'francais', '1re', 'Le Malade imaginaire, Molière', 'Quel rôle Molière joue-t-il lui-même dans la pièce ?', 'mcq', '["Argan","Béralde","Purgon","Monsieur Diafoirus"]'::jsonb, 0, 'Molière, malade, joue le malade imaginaire : une pièce qui rit de la mort, écrite et jouée par un auteur mourant.', 1),
    ('8dfb79be-43bd-5bd2-be8d-9e7d572e92c2'::uuid, 'francais', '1re', 'Le Malade imaginaire, Molière', 'Sous quel déguisement Toinette contredit-elle Purgon ?', 'mcq', '["En notaire","En médecin de passage","En apothicaire","En maître de musique"]'::jsonb, 1, 'Déguisée en médecin, Toinette a une réponse à tout (« Le poumon, le poumon, vous dis-je ») et parodie le jargon de la médecine.', 2),
    ('d7e393da-cc5f-5c55-824f-457b9b023352'::uuid, 'francais', '1re', 'Le Malade imaginaire, Molière', 'Que fait Argan, seul, au lever du rideau ?', 'mcq', '["Il écrit son testament","Il lit un traité de médecine","Il fait ses comptes d’apothicaire","Il répète une chanson"]'::jsonb, 2, 'Il additionne lavements, purges et médecines : dès la première scène, la manie d’Argan est posée, celle d’un caractère de comédie.', 3),
    ('5c0c79c1-3677-5589-a3ec-fcb9c3c4e2fc'::uuid, 'francais', '1re', 'Le Malade imaginaire, Molière', 'Comment Cléante s’introduit-il auprès d’Angélique ?', 'mcq', '["En médecin appelé par Argan","En notaire venu pour le contrat","En valet de Béralde","En maître de musique"]'::jsonb, 3, 'Il se fait passer pour maître de musique et chante son amour devant Argan : jouer un rôle devient un moyen de dire la vérité.', 4),
    ('6a99b5bb-02ff-5fee-8995-a3831d29fbb0'::uuid, 'francais', '1re', 'Le Mariage de Figaro, Beaumarchais', 'Que doit faire Chérubin, caché dans la chambre de la comtesse ?', 'mcq', '["Sauter par la fenêtre","Se déguiser en jardinier","Se cacher sous le lit","Se cacher dans la cheminée"]'::jsonb, 0, 'Le page, amoureux de toutes les femmes, est le contretemps des intrigues : sa fuite par la fenêtre est un grand moment de comique de situation.', 1),
    ('fd45f08b-8446-5cb3-8af0-f5f1cdcbe24f'::uuid, 'francais', '1re', 'Le Mariage de Figaro, Beaumarchais', 'Qui est la comtesse Almaviva ?', 'mcq', '["La mère de Figaro","L’ancienne Rosine du Barbier","La sœur de Bartholo","La cousine de Suzanne"]'::jsonb, 1, 'Rosine, l’héroïne du Barbier de Séville, est devenue une épouse délaissée et mélancolique : le comte qui l’a conquise la trompe désormais.', 2),
    ('5ea0afba-38f1-53f7-82f2-1c493daf431c'::uuid, 'francais', '1re', 'Le Mariage de Figaro, Beaumarchais', 'Que dénonce la tirade de Marceline ?', 'mcq', '["La censure","La justice vénale","Le sort fait aux femmes","Le privilège de naissance"]'::jsonb, 2, 'Chaque cible a son moyen : le monologue pour les privilèges, l’acte III pour la justice vénale, la tirade de Marceline pour le sort des femmes.', 3),
    ('5bd1e5d9-d9ef-5b2d-8a17-a5a7cda456e0'::uuid, 'francais', '1re', 'Le Mariage de Figaro, Beaumarchais', 'Qu’est-ce qui caractérise le juge Brid’oison ?', 'mcq', '["Il est incorruptible et sévère","Il est l’amant de Marceline","Il ne dit pas un mot","Il est bègue et attaché à « la forme »"]'::jsonb, 3, 'Le juge bègue, qui ne jure que par « la forme », sert la satire d’une justice plus soucieuse de procédure que de vérité.', 4),
    ('3332ccaf-3c0a-5174-aca1-fade62e9fd7f'::uuid, 'francais', '1re', 'Le médecin volant, Molière', 'Pourquoi le texte du Médecin volant nous est-il parvenu si tard ?', 'mcq', '["Il était écrit en italien et fut traduit bien plus tard","Les dévots en avaient obtenu l’interdiction en 1664","Il n’a été publié qu’au XIXe siècle, d’après une copie ancienne","Il a été reconstitué au XXe siècle par des comédiens"]'::jsonb, 2, 'Molière jouait ces petites farces à l’italienne en province, entre 1645 et 1658 ; peu nous sont parvenues, et celle-ci a survécu grâce à une copie ancienne.', 1),
    ('c6be068c-89f0-57dc-a92a-7757b558850f'::uuid, 'francais', '1re', 'Le médecin volant, Molière', 'Quelle vérité Sganarelle attribue-t-il gravement à Hippocrate et Galien ?', 'mcq', '["Que l’amour est la pire des fièvres","Qu’une personne ne se porte pas bien quand elle est malade","Que la saignée guérit tous les maux","Que les filles à marier tombent souvent malades"]'::jsonb, 1, 'C’est une tautologie prononcée avec assurance : le faux savoir fait rire par le comique de mots. Ce médecin charlatan annonce Diafoirus et Purgon.', 2),
    ('052510ae-b628-5bf7-b5a6-0836f7f68f36'::uuid, 'francais', '1re', 'Le médecin volant, Molière', 'Que fait Sganarelle pendant la consultation de la fausse malade ?', 'mcq', '["Il la saigne sous les yeux de son père","Il consulte les astres pour dater sa guérison","Il lui fait avaler une poudre de licorne","Il examine ses urines et va jusqu’à y goûter"]'::jsonb, 3, 'C’est le comique de gestes, le plus physique, hérité de la farce et de la commedia dell’arte : le rire de Molière commence par le corps.', 3),
    ('2da0af8d-5bfa-5483-aafd-b8366515aa87'::uuid, 'francais', '1re', 'Le médecin volant, Molière', 'Comment la farce se termine-t-elle ?', 'mcq', '["Démasqué, Sganarelle est pardonné et Lucile épousera Valère","Démasqué, Sganarelle est bastonné puis chassé par Gorgibus","Gorgibus impose Villebrequin, et Lucile doit s’y résigner","Gros-René prend la place de Sganarelle comme faux médecin"]'::jsonb, 0, 'La ruse a atteint son but : le père crédule pardonne et l’obstacle au mariage tombe. Molière reprendra ce canevas dans Le Médecin malgré lui (1666).', 4),
    ('297b5304-a844-5fb0-b898-2b95df6f9725'::uuid, 'francais', '1re', 'Le Meilleur des mondes, Aldous Huxley', 'En quelle année se déroule l’action du roman ?', 'mcq', '["En 1984, sous Big Brother","En l’an 632 après Ford","En l’an 2000 après J.-C.","En 1932, l’année de parution"]'::jsonb, 1, 'Le calendrier part de Ford : ce monde est bâti sur le modèle de la production en série, le fordisme du temps où Huxley écrit.', 1),
    ('5f656a92-5c1e-53f4-a11c-6e98df61b00a'::uuid, 'francais', '1re', 'Le Meilleur des mondes, Aldous Huxley', 'Quel statut ont les mots « mère » et « père » dans ce monde ?', 'mcq', '["Ils sont réservés aux seuls Alphas","Ils sont enseignés par hypnopédie","Ils sont devenus obscènes","Ils désignent les administrateurs"]'::jsonb, 2, 'La famille est supprimée, les humains sortent de flacons : avoir un enfant devient une honte, d’où le scandale du Directeur, père de John.', 2),
    ('05be3043-4687-573f-9c23-2fda94a670d7'::uuid, 'francais', '1re', 'Le Meilleur des mondes, Aldous Huxley', 'Que réclame John face à l’administrateur Mustapha Menier ?', 'mcq', '["Une place parmi les Alphas","Le droit de gouverner à sa place","La suppression du soma pour tous","Le droit d’être malheureux"]'::jsonb, 3, 'Menier lui explique posément que le bonheur a un prix ; John préfère une liberté douloureuse à un confort organisé.', 3),
    ('30233a47-fbc1-5725-8a85-c9623390a775'::uuid, 'francais', '1re', 'Le Meilleur des mondes, Aldous Huxley', 'Que deviennent Bernard Marx et son ami Helmholtz Watson ?', 'mcq', '["Ils sont exilés sur une île","Ils sont exécutés en public","Ils remplacent le Directeur","Ils partent vivre dans la réserve"]'::jsonb, 0, 'La dictature par le plaisir n’a pas besoin de terreur : elle éloigne ceux qui ne s’adaptent pas, comme Helmholtz, écrivain insatisfait.', 4),
    ('0ea38c20-35ae-5af8-9425-7bbf6889362c'::uuid, 'francais', '1re', 'Le Menteur, Pierre Corneille', 'Quel mensonge Dorante oppose-t-il au mariage que son père Géronte a arrangé ?', 'mcq', '["Il se dit fiancé à Lucrèce depuis l’enfance","Il prétend avoir fait vœu d’entrer en religion","Il invente un mariage secret à Poitiers","Il affirme être ruiné par une dette de jeu"]'::jsonb, 2, 'Il ne se contente pas d’un prétexte : il bâtit un mariage secret complet. Chez Dorante, chaque mensonge devient un petit roman.', 1),
    ('52556549-73f6-51f5-b291-787ed27c451c'::uuid, 'francais', '1re', 'Le Menteur, Pierre Corneille', 'Qui Dorante épouse-t-il au dénouement ?', 'mcq', '["La vraie Lucrèce, l’amie de Clarice","Clarice, qu’il croyait nommée Lucrèce","Personne : il repart seul à Poitiers","La jeune femme de son faux mariage"]'::jsonb, 0, 'Démasqué, il retombe sur ses pieds, ni puni ni corrigé : ce dénouement a gêné les commentateurs et rend la pièce très moderne.', 2),
    ('91d4fe5e-d1a1-59dc-978a-a8558c4ea13a'::uuid, 'francais', '1re', 'Le Menteur, Pierre Corneille', 'Quelles pièces Corneille a-t-il déjà écrites quand il revient à la comédie avec Le Menteur ?', 'mcq', '["Andromaque, Britannicus et Phèdre","Le Tartuffe, Dom Juan et L’Avare","Hernani, Ruy Blas et Cromwell","Le Cid, Horace et Cinna"]'::jsonb, 3, 'Déjà célèbre, Corneille fait jouer Le Menteur au théâtre du Marais ; selon une anecdote, Molière aurait dit lui devoir sa vocation de grand auteur comique.', 3),
    ('5a2bd5c7-1125-563b-9df1-e10e0587241d'::uuid, 'francais', '1re', 'Le Menteur, Pierre Corneille', 'Dans quel type de comique range-t-on le quiproquo sur les noms de Clarice et de Lucrèce ?', 'mcq', '["Le comique de caractère","Le comique de situation","Le comique de mots","Le comique de gestes"]'::jsonb, 1, 'Le quiproquo relève de la situation ; le menteur pris à son piège, du caractère ; les tirades d’invention, du comique de mots.', 4),
    ('9fea4a55-d71e-5efc-9aad-a2e704d6b3d3'::uuid, 'francais', '1re', 'Le Misanthrope, Molière', 'Qui Philinte finira-t-il par épouser ?', 'mcq', '["Célimène, la coquette","Arsinoé, la prude","Éliante, la cousine sincère de Célimène","Aucune : il suit Alceste au désert"]'::jsonb, 2, 'Éliante, sincère, forme avec Philinte le couple de la mesure, en contrepoint d’Alceste qui part seul.', 1),
    ('b2a75f2f-bd99-5bd4-9834-5444ed446f03'::uuid, 'francais', '1re', 'Le Misanthrope, Molière', 'Pourquoi Alceste perd-il son procès ?', 'mcq', '["Oronte témoigne contre lui","Il refuse de solliciter ses juges","Célimène soutient son adversaire","Il insulte les maréchaux de France"]'::jsonb, 1, 'Face à un adversaire malhonnête, il refuse les usages du monde : Alceste a raison sur le fond et tort dans la vie.', 2),
    ('20513b27-b717-5961-8aab-b296a4ced3fa'::uuid, 'francais', '1re', 'Le Misanthrope, Molière', 'Qu’est-ce qui démasque Célimène au dénouement ?', 'mcq', '["Ses lettres à plusieurs prétendants, rendues publiques","L’aveu qu’elle fait elle-même devant Alceste","Une confidence d’Éliante à Oronte","Un duel entre les deux marquis rivaux"]'::jsonb, 0, 'Ses lettres révèlent son double jeu ; Alceste lui propose pourtant de le suivre au désert, et elle refuse : elle a vingt ans.', 3),
    ('0bf8c88c-2057-5de7-8d36-c123b6cf3c29'::uuid, 'francais', '1re', 'Le Misanthrope, Molière', 'Qu’Alceste oppose-t-il aux vers précieux du sonnet d’Oronte ?', 'mcq', '["Un sonnet de sa propre composition","Des vers tirés d’une tragédie de Corneille","Une maxime de Philinte sur la mesure","Une vieille chanson populaire, jugée plus vraie"]'::jsonb, 3, 'Contre l’ornement précieux, Alceste défend la simplicité du cœur ; sa critique lui vaudra le tribunal des maréchaux.', 4),
    ('1eff28bb-ef9f-5c88-814e-ea54a53ba0c9'::uuid, 'francais', '1re', 'Le Neveu de Rameau, Denis Diderot', 'Où MOI rencontre-t-il le neveu ?', 'mcq', '["Dans le salon du financier Bertin","À l’Opéra, un soir de première","Dans la boutique d’un libraire","Au café de la Régence"]'::jsonb, 3, 'Le dialogue naît d’une rencontre de hasard dans un café parisien : deux voix s’y affrontent sans qu’aucune l’emporte.', 1),
    ('4ee483e5-8332-57f5-bf60-5aebc8fcafd7'::uuid, 'francais', '1re', 'Le Neveu de Rameau, Denis Diderot', 'Pourquoi Diderot garde-t-il ce texte secret ?', 'mcq', '["Il y met en scène, sous leurs vrais noms, les ennemis des philosophes","Il y attaque ouvertement le roi et toute sa cour","Il le juge raté et indigne d’être publié","Il l’a écrit pour Goethe, qui devait le traduire"]'::jsonb, 0, 'Écrit et remanié entre 1761 et 1774, ce texte satirique vise des personnes réelles ; il n’a jamais été publié du vivant de Diderot.', 2),
    ('b998942a-672a-5ee7-88ae-9e0a1cfc4a91'::uuid, 'francais', '1re', 'Le Neveu de Rameau, Denis Diderot', 'Que mime le neveu, à lui seul, au sommet du dialogue ?', 'mcq', '["Un procès au Parlement de Paris","Une bataille de l’armée royale","Un opéra entier, orchestre compris","Une messe chantée à Notre-Dame"]'::jsonb, 2, 'Le neveu est un acteur qui joue tous les rôles ; la scène rejoint la réflexion de l’œuvre sur la musique, au temps de la querelle des Bouffons.', 3),
    ('76e2f848-50fd-5fc8-91bf-40a24fc653a9'::uuid, 'francais', '1re', 'Le Neveu de Rameau, Denis Diderot', 'Que veut dire la formule de la première page : « Mes pensées, ce sont mes catins » ?', 'mcq', '["Le philosophe méprise ses propres idées","Le philosophe laisse vagabonder son esprit","Le neveu avoue ses débauches passées","Le philosophe renonce à penser seul"]'::jsonb, 1, 'L’image audacieuse ouvre un texte libre, qui suit ses idées au hasard, comme la conversation qui va suivre.', 4),
    ('4e79d1d8-ba0e-5186-a6ed-215c340f6da9'::uuid, 'francais', '1re', 'Le Parti pris des choses, Francis Ponge', 'Qui soutient la publication du recueil chez Gallimard en 1942 ?', 'mcq', '["Jean Paulhan","André Breton","Paul Valéry","André Gide"]'::jsonb, 0, 'Ponge, longtemps employé chez Hachette, écrivait le soir ; Paulhan l’aide à publier, et l’essai de Sartre (1944) le fera connaître.', 1),
    ('57d7b59b-f12c-5eb8-ae96-6ab0d52dc4b7'::uuid, 'francais', '1re', 'Le Parti pris des choses, Francis Ponge', 'Sous quelle forme les textes du recueil sont-ils écrits ?', 'mcq', '["En sonnets réguliers","En alexandrins à rimes plates","En longs vers libres","En prose, en textes brefs"]'::jsonb, 3, 'Ce sont des poèmes en prose : la poésie tient au regard et au travail du mot, pas au vers.', 2),
    ('78f891e6-551b-5f90-85a2-a0685adf53a2'::uuid, 'francais', '1re', 'Le Parti pris des choses, Francis Ponge', 'Que refuse le poème de Ponge, selon son programme ?', 'mcq', '["La description exacte de l’objet","Le lyrisme, le symbole et le « je » sentimental","Le travail sur l’étymologie des mots","L’humour et les doubles sens"]'::jsonb, 1, 'Ponge veut l’objet pour lui-même, décrit exactement, au lieu d’en faire le miroir des émotions du poète.', 3),
    ('7f680456-a694-5e96-a415-1b88a7e7afa0'::uuid, 'francais', '1re', 'Le Parti pris des choses, Francis Ponge', 'Comment se termine « Le Cageot » ?', 'mcq', '["Par une morale sur le gaspillage","Par une plainte sur la mort du poète","Par une tendresse pour cette chose méprisée","Par le souvenir de la forêt d’origine"]'::jsonb, 2, 'Parti du mot, placé entre cage et cachot, Ponge décrit l’objet léger, fragile, jeté après usage, puis lui rend justice : il donne une voix à ce qui n’en a pas.', 4),
    ('62d2e80d-b48c-50af-bfda-33fa5f71cf19'::uuid, 'francais', '1re', 'Le paysan parvenu, Marivaux', 'Qui s’oppose au mariage de Jacob avec Mademoiselle Habert ?', 'mcq', '["Madame de Ferval et Madame de Fécour","Sa sœur aînée et le directeur de conscience","Le père de Jacob, resté à la ferme","Geneviève et le maître qui l’entretient"]'::jsonb, 1, 'C’est la satire des dévots : chez les sœurs Habert, la piété se mêle à l’intérêt.', 1),
    ('764d7b9b-1fb5-57c1-b26d-3d3c3d055789'::uuid, 'francais', '1re', 'Le paysan parvenu, Marivaux', 'Comment Jacob gagne-t-il la protection d’un jeune seigneur ?', 'mcq', '["En lui prêtant l’argent de sa femme","En le flattant dans un salon mondain","En lui vendant le vin de son père","En le sauvant d’une attaque dans la rue"]'::jsonb, 3, 'L’ascension de Jacob ne tient pas qu’à la séduction : son courage lui ouvre ici une protection de plus vers le monde qu’il vise.', 2),
    ('28301c44-819e-5bb3-9c92-59fc068e99d5'::uuid, 'francais', '1re', 'Le paysan parvenu, Marivaux', 'Que déclare le narrateur dès la première phrase du roman ?', 'mcq', '["Que le titre de ses Mémoires annonce sa naissance","Qu’il a toujours eu honte de ses origines","Qu’il est le fils d’un gentilhomme ruiné","Que ses Mémoires sont une pure invention"]'::jsonb, 0, '« Le titre que je donne à mes Mémoires annonce ma naissance » : le vieux narrateur ne l’a jamais cachée, et il juge avec ironie le jeune homme qu’il fut.', 3),
    ('9a9b8ac2-23d8-5235-9450-67d8715084c1'::uuid, 'francais', '1re', 'Le paysan parvenu, Marivaux', 'Quels héros du roman du XIXe siècle Jacob annonce-t-il ?', 'mcq', '["Candide et Zadig","Jean Valjean et Gavroche","Bel-Ami et Julien Sorel","Emma Bovary et Nana"]'::jsonb, 2, 'Comme eux, il monte par la séduction ; mais chez Marivaux, sans tragédie : la comédie sociale reste souriante.', 4),
    ('0239810c-46db-5ef1-b8c5-a30d2b4920f1'::uuid, 'francais', '1re', 'Le Père Goriot, Honoré de Balzac', 'Quand et sous quel régime se déroule l’action ?', 'mcq', '["En 1819, sous la Restauration","En 1830, sous la monarchie de Juillet","En 1848, sous la IIe République","En 1805, sous le Premier Empire"]'::jsonb, 0, 'Balzac publie en 1835 un roman situé en 1819 : le Paris de la Restauration y est un champ de bataille où l’argent fait la loi.', 1),
    ('6f0175d0-1319-57d8-a6f2-5baed26eb9b2'::uuid, 'francais', '1re', 'Le Père Goriot, Honoré de Balzac', 'Comment s’appellent les deux filles du père Goriot ?', 'mcq', '["Laure et Agathe de Rastignac","Victorine Taillefer et Delphine de Nucingen","Anastasie de Restaud et Delphine de Nucingen","Anastasie de Restaud et Victorine Taillefer"]'::jsonb, 2, 'Goriot les aime jusqu’à l’aveuglement, et elles ne viennent le voir que pour de l’argent : il incarne la paternité dévorée.', 2),
    ('979daa35-1abc-59ad-8f46-d31f9ba24660'::uuid, 'francais', '1re', 'Le Père Goriot, Honoré de Balzac', 'Que fait Rastignac quand le frère de Victorine est tué en duel, comme Vautrin l’avait prévu ?', 'mcq', '["Il épouse aussitôt Victorine","Il refuse d’en profiter","Il dénonce Vautrin à la police","Il provoque le meurtrier en duel"]'::jsonb, 1, 'Rastignac repousse le crime lucide de Vautrin ; celui-ci est vendu à la police par deux pensionnaires et arrêté.', 3),
    ('9f41fb5d-6cf4-51ac-b436-23ab4a8c4ca7'::uuid, 'francais', '1re', 'Le Père Goriot, Honoré de Balzac', 'Quels sont les trois « maîtres » de Rastignac dans ce roman d’apprentissage ?', 'mcq', '["Mme Vauquer, Victorine et Goriot","Delphine, Anastasie et Vautrin","Mme de Beauséant, Victorine et Mme Vauquer","Mme de Beauséant, Vautrin et Goriot"]'::jsonb, 3, 'La grande dame lui ouvre le monde, le forçat lui en dit la loi cynique, le vieux père lui en montre le prix : Rastignac s’initie à l’ambition.', 4),
    ('cc51a057-641f-5b03-a63d-28c32ac59b82'::uuid, 'francais', '1re', 'Le Petit Malade, Georges Courteline', 'Quel métier Courteline a-t-il exercé avant de faire rire la Belle Époque ?', 'mcq', '["Médecin de campagne","Avocat au barreau de Paris","Employé de ministère","Officier de marine"]'::jsonb, 2, 'Il en a tiré sa satire de la bêtise administrative, par exemple dans Messieurs les ronds-de-cuir.', 1),
    ('e66321e7-4439-59fe-be74-c0cccaf1233d'::uuid, 'francais', '1re', 'Le Petit Malade, Georges Courteline', 'Quel procédé comique les chutes successives de Toto illustrent-elles ?', 'mcq', '["Le comique de répétition","Le comique de caractère","Le jeu de mots","La parodie tragique"]'::jsonb, 0, 'Les chutes se suivent, identiques (« Pouf ! ») : la répétition prépare la chute finale, au sens propre comme au sens théâtral.', 2),
    ('7aea3cd3-589b-538c-bc63-ec1af8aff93d'::uuid, 'francais', '1re', 'Le Petit Malade, Georges Courteline', 'Qui est le seul personnage à ne pas s’inquiéter ?', 'mcq', '["La mère, qui fait venir le médecin","Le médecin, pourtant compétent","Aucun : tous finissent par paniquer","Toto, qui répond « Oui, monsieur »"]'::jsonb, 3, 'Pendant que la mère s’affole et que le médecin conclut à la paralysie, l’enfant, qui n’a mal nulle part et a faim, respire la santé.', 3),
    ('b05b5afc-6674-59fc-9126-d7e042254b6b'::uuid, 'francais', '1re', 'Le Petit Malade, Georges Courteline', 'Dans quelle lignée s’inscrit la satire du savoir médical de la saynète ?', 'mcq', '["Celle de Racine","Celle de Molière","Celle de Zola","Celle de Victor Hugo"]'::jsonb, 1, 'Comme chez Molière, le jargon remplace l’observation : le médecin pose un diagnostic grave sur des indices qui disent le contraire.', 4),
    ('60382ad8-78a5-56ef-8568-a7788ae7dcc3'::uuid, 'francais', '1re', 'Le Procès, Franz Kafka', 'Où Joseph K. découvre-t-il que siège la justice qui le poursuit ?', 'mcq', '["Dans un palais de justice monumental","Dans des greniers, des couloirs, des arrière-cours","Dans la banque même où il travaille","Dans une prison militaire de la ville"]'::jsonb, 1, 'Cette justice tentaculaire est partout et nulle part : c’est la bureaucratie invisible que désigne l’adjectif « kafkaïen ».', 1),
    ('bb67e83e-f392-57f3-9491-46c04f087eaa'::uuid, 'francais', '1re', 'Le Procès, Franz Kafka', 'Que lui apprend le peintre Titorelli ?', 'mcq', '["Que son procès sera jugé dès le lendemain matin","Que l’avocat Huld saura obtenir son acquittement","Qu’il est accusé d’avoir calomnié un haut juge","Qu’on obtient des ajournements, jamais un vrai acquittement"]'::jsonb, 3, 'Titorelli, le peintre des juges, connaît les ficelles du tribunal : le procès ne se termine pas, il s’étire.', 2),
    ('c1ce8400-ce2a-5086-98b5-9c5679ef06bc'::uuid, 'francais', '1re', 'Le Procès, Franz Kafka', 'Qui raconte à K. la parabole « Devant la Loi » ?', 'mcq', '["Un aumônier","L’avocat Huld","Le peintre Titorelli","Son oncle"]'::jsonb, 0, 'La parabole est une mise en abyme : en une page, elle résume tout le roman — une porte ouverte pour un seul homme, qui n’y entre jamais.', 3),
    ('bb7f42a3-e4f8-5ac5-b465-1bb948955f9f'::uuid, 'francais', '1re', 'Le Procès, Franz Kafka', 'Quel était le métier de Kafka lui-même ?', 'mcq', '["Juge dans un tribunal de Prague","Fondé de pouvoir dans une banque","Docteur en droit, employé d’assurances","Avocat, comme le personnage de Huld"]'::jsonb, 2, 'Kafka connaissait de l’intérieur le droit et l’administration ; c’est son héros, Joseph K., qui est fondé de pouvoir dans une banque.', 4),
    ('49cccb1f-513b-5d65-9a78-3728fc9f4ea4'::uuid, 'francais', '1re', 'Le Roi des Aulnes, Michel Tournier', 'Comment s’appelle le journal que tient Abel Tiffauges ?', 'mcq', '["Les « Cahiers noirs »","Le « Journal d’un ogre »","Les « Mémoires du marais »","Les « Écrits sinistres »"]'::jsonb, 3, 'Ce journal oblige le lecteur à suivre de l’intérieur une conscience trouble, persuadée que le monde lui envoie des signes.', 1),
    ('6f7d101b-c114-5457-acd1-7bde85ac0c53'::uuid, 'francais', '1re', 'Le Roi des Aulnes, Michel Tournier', 'Qu’est-ce qui permet à Tiffauges d’échapper au procès où il est accusé à tort ?', 'mcq', '["Le témoignage de son ami Nestor","La déclaration de guerre","La protection de Göring","Une erreur de la police"]'::jsonb, 1, 'L’Histoire intervient comme un signe du destin : il devient soldat dans une unité de pigeons voyageurs pendant la drôle de guerre.', 2),
    ('62cb38d9-cca2-59ee-9ccc-e1484c3e877d'::uuid, 'francais', '1re', 'Le Roi des Aulnes, Michel Tournier', 'Quel poste Tiffauges occupe-t-il à Rominten ?', 'mcq', '["Garde-chasse chez Göring","Rabatteur d’enfants pour la napola","Colombophile dans l’armée française","Gardien de prisonniers français"]'::jsonb, 0, 'Prisonnier en Prusse-Orientale, il passe par Rominten avant Kaltenborn, où il deviendra rabatteur d’enfants pour la napola.', 3),
    ('8b6f1805-853b-52e3-a887-e51b4b305b2e'::uuid, 'francais', '1re', 'Le Roi des Aulnes, Michel Tournier', 'Parmi les figures du « porteur », laquelle enlève l’enfant pour le dévorer ?', 'mcq', '["Saint Christophe","Le Roi des Aulnes","L’ogre","Le passeur des morts"]'::jsonb, 2, 'Saint Christophe porte l’enfant pour le sauver, le Roi des Aulnes l’arrache à son père, l’ogre l’enlève pour le dévorer : porter, c’est aimer — et capturer.', 4),
    ('3fc166b3-99fd-5eca-81bc-b4d5a3e2796c'::uuid, 'francais', '1re', 'Le Roi se meurt, Eugène Ionesco', 'Quel rôle joue la seconde reine, Marie ?', 'mcq', '["Jeune et aimante, elle le retient dans l’illusion","Lucide, elle l’aide à se détacher de tout","Elle prépare en secret sa succession","Elle soigne le roi avec le médecin"]'::jsonb, 0, 'Les deux reines opposent le déni (Marie) à l’acceptation (Marguerite) : le roi est tiraillé entre elles.', 1),
    ('55d29920-a040-59e6-bd32-a8872317bcd0'::uuid, 'francais', '1re', 'Le Roi se meurt, Eugène Ionesco', 'En quoi cette pièce renouvelle-t-elle l’absurde d’Ionesco ?', 'mcq', '["Elle renonce à tout rire et à toute farce","Elle devient une pièce à thèse politique","L’absurde du langage cède à celui de la mort","Elle quitte la scène pour la radio"]'::jsonb, 2, 'Écrite après une maladie, c’est la pièce la plus grave d’Ionesco : on meurt sans avoir appris ; le rire y persiste, grinçant.', 2),
    ('f7ddd230-d8d2-5252-83a1-f2f5f0cce284'::uuid, 'francais', '1re', 'Le Roi se meurt, Eugène Ionesco', 'Que découvre le roi à travers le récit de la servante Juliette ?', 'mcq', '["Un complot pour lui voler son trône","La vie pénible des autres, trop tard","Le remède qui pourrait le guérir","L’existence d’un héritier caché"]'::jsonb, 1, 'Le roi, qui n’est plus qu’un homme, s’intéresse enfin à la vie ordinaire au moment où il la quitte.', 3),
    ('53a49365-7a90-5c2c-ab9b-9e6079b6a9bc'::uuid, 'francais', '1re', 'Le Roi se meurt, Eugène Ionesco', 'Quel effet produit la coïncidence entre la durée de la pièce et celle de l’agonie ?', 'mcq', '["Le spectateur oublie que le roi va mourir","La pièce doit être coupée par un entracte","Le roi peut revenir en arrière dans le temps","Le spectateur vit l’agonie à la vitesse du roi"]'::jsonb, 3, 'C’est le temps réel : la mort, annoncée pour « la fin du spectacle », arrive au terme de la représentation, jouée d’un seul tenant.', 4),
    ('f2b19244-9713-5703-ab9e-bb666e04fcd1'::uuid, 'francais', '1re', 'Le Roman de la momie, Théophile Gautier', 'De qui Poëri, l’Hébreu aimé de Tahoser, est-il amoureux ?', 'mcq', '["De Tahoser, qu’il épouse en secret","De la fille du pharaon","De Ra’hel, une femme de son peuple","De personne : il vit en solitaire"]'::jsonb, 2, 'Le roman repose sur une chaîne d’amours non partagés : le pharaon aime Tahoser, qui aime Poëri, qui aime Ra’hel.', 1),
    ('bb437bf4-1828-5ba4-ba33-bb56d175532f'::uuid, 'francais', '1re', 'Le Roman de la momie, Théophile Gautier', 'Où Tahoser est-elle ensevelie à sa mort ?', 'mcq', '["Dans le tombeau préparé pour le pharaon","Dans une simple fosse du désert","Dans la sépulture des Hébreux en exil","Dans le tombeau de son père, le grand prêtre"]'::jsonb, 0, 'C’est pourquoi le prologue découvre, dans la Vallée des Rois, une tombe royale intacte occupée par la momie d’une jeune femme.', 2),
    ('3ef04125-83a4-53d6-b005-a7cf0fbba100'::uuid, 'francais', '1re', 'Le Roman de la momie, Théophile Gautier', 'Que devient le jeune lord anglais après la découverte ?', 'mcq', '["Il épouse une riche héritière anglaise","Il se fait moine dans un couvent d’Égypte","Il part fouiller les ruines de la Grèce","Il ne se marie jamais, amoureux de la momie"]'::jsonb, 3, 'Le cadre moderne se referme sur la fascination : la beauté antique l’emporte, pour lui, sur toutes les vivantes.', 3),
    ('5c1b0813-4cb7-5a8c-859f-b787e20ac5db'::uuid, 'francais', '1re', 'Le Roman de la momie, Théophile Gautier', 'Quelle formule résume la doctrine de l’art pour l’art défendue par Gautier ?', 'mcq', '["« L’art doit servir le progrès et éclairer le peuple. »","« Il n’y a de vraiment beau que ce qui ne peut servir à rien. »","« La poésie doit peindre la vie telle qu’elle est. »","« Le poète doit être utile à la cité et à ses lois. »"]'::jsonb, 1, 'Gautier la défend depuis la préface de Mademoiselle de Maupin (1835) ; dans le roman, la beauté visuelle prime sur la psychologie.', 4),
    ('8d584fe6-23fc-59e7-8ebc-1f4e3c751e49'::uuid, 'francais', '1re', 'Le Roman inachevé, Louis Aragon', 'Quel chanteur a mis en musique « Que serais-je sans toi » ?', 'mcq', '["Léo Ferré","Jean Ferrat","Georges Brassens","Jacques Brel"]'::jsonb, 1, 'Léo Ferré, lui, a chanté « L’Affiche rouge » et « Est-ce ainsi que les hommes vivent » : la rime rend les vers d’Aragon chantables.', 1),
    ('843e7f1e-da79-5bd6-9d27-c22d8a990c3e'::uuid, 'francais', '1re', 'Le Roman inachevé, Louis Aragon', 'De quel recueil vient « Il n’y a pas d’amour heureux », chanté par Brassens ?', 'mcq', '["Le Roman inachevé","Le Crève-cœur","Les Yeux d’Elsa","La Diane française"]'::jsonb, 3, 'Brassens a chanté un poème d’un autre recueil ; les chansons tirées du Roman inachevé sont celles de Ferré et de Ferrat.', 2),
    ('2be1b7bb-d648-52e8-9ef6-d061f35c3ff9'::uuid, 'francais', '1re', 'Le Roman inachevé, Louis Aragon', 'Pourquoi Aragon défend-il le retour de la rime ?', 'mcq', '["Appui de la mémoire, elle rend la poésie populaire et chantable","Elle sépare la poésie savante de la chanson populaire","Elle respecte les règles fixées par les surréalistes","Elle permet d’écrire uniquement en alexandrins"]'::jsonb, 0, 'Il la défend dès la guerre, dans « La Rime en 1940 » (Le Crève-cœur), contre les modernes qui l’avaient abandonnée.', 3),
    ('f8a5b02c-0871-5188-8c07-caf09c240a0a'::uuid, 'francais', '1re', 'Le Roman inachevé, Louis Aragon', 'Que dit le titre du recueil, selon le cours ?', 'mcq', '["Qu’Aragon a renoncé à un roman en prose","Que le recueil a paru après la mort du poète","Qu’une vie ne se referme pas","Que la guerre a interrompu son écriture"]'::jsonb, 2, 'Le recueil est une autobiographie en vers, écrite depuis la vieillesse qui commence : la vie racontée reste ouverte.', 4),
    ('c1ebbd35-5615-5d65-9d05-17647e4aa47c'::uuid, 'francais', '1re', 'Le Rouge et le Noir, Stendhal', 'Quel est le vrai nom de Stendhal ?', 'mcq', '["Henri Brulard","Antoine Berthet","Julien Beyle","Henri Beyle"]'::jsonb, 3, 'Henri Beyle, ancien officier de Napoléon, publie le roman en novembre 1830, quelques mois après la révolution de Juillet.', 1),
    ('c7a6ff9a-fc5e-5187-a6d8-77204e87a392'::uuid, 'francais', '1re', 'Le Rouge et le Noir, Stendhal', 'Qui est l’abbé Pirard ?', 'mcq', '["Le directeur janséniste du séminaire, qui protège Julien","Le confesseur qui dicte la lettre de Madame de Rênal","Le curé de Verrières qui fait arrêter Julien","Le précepteur des enfants de Monsieur de Rênal"]'::jsonb, 0, 'Janséniste intègre, il protège Julien au séminaire de Besançon, sous une Restauration où l’Église est la seule voie d’ascension.', 2),
    ('f07a4c78-8c3b-5cc0-8a3f-660fbe167954'::uuid, 'francais', '1re', 'Le Rouge et le Noir, Stendhal', 'Que devient Madame de Rênal après l’exécution de Julien ?', 'mcq', '["Elle entre au couvent","Elle épouse Valenod","Elle meurt trois jours après","Elle élève l’enfant de Mathilde"]'::jsonb, 2, 'Elle a survécu au coup de pistolet mais meurt trois jours après Julien, qu’elle aimait d’un amour tendre et sincère ; Mathilde enterre son amant.', 3),
    ('e3023eb1-591f-5bd0-8b7b-8d1e0c651a0c'::uuid, 'francais', '1re', 'Le Rouge et le Noir, Stendhal', 'Quel procédé fait entrer la pensée du personnage dans le récit ?', 'mcq', '["Le monologue théâtral","Le discours indirect libre","La lettre du héros","Le récit enchâssé"]'::jsonb, 1, 'Avec la focalisation serrée, il fait suivre les calculs de Julien ; l’ironie du narrateur, elle, dit souvent le contraire de ce qu’il montre.', 4),
    ('03dd3f5c-ea0c-5d47-9151-215a474935c4'::uuid, 'francais', '1re', 'Le Tartuffe, Molière', 'Qui partage l’aveuglement d’Orgon envers Tartuffe ?', 'mcq', '["La servante Dorine","Sa mère, Madame Pernelle","Son beau-frère Cléante","Son fils Damis"]'::jsonb, 1, 'Face aux deux aveugles, les lucides — Dorine, Damis, Cléante, Elmire — voient clair dans le faux dévot.', 1),
    ('1c106ca8-e9d3-595f-8692-c67ff72f16f6'::uuid, 'francais', '1re', 'Le Tartuffe, Molière', 'Comment Molière défend-il sa pièce interdite ?', 'mcq', '["Par un pamphlet contre les dévots","Par une lettre à l’Académie","Par une comédie en réponse","Par des placets adressés au roi"]'::jsonb, 3, 'Protégé par Louis XIV, Molière lui adresse des placets ; interdite en 1664 puis en 1667, la pièce n’est autorisée qu’en 1669.', 2),
    ('28cc11c2-c270-5fd1-a367-c9fc40d1df16'::uuid, 'francais', '1re', 'Le Tartuffe, Molière', 'Quel personnage distingue la piété sincère de la « grimace » ?', 'mcq', '["Cléante","Dorine","Valère","Orgon"]'::jsonb, 0, 'Le beau-frère d’Orgon sépare le vrai dévot du faux : Molière vise l’hypocrisie religieuse, non la religion.', 3),
    ('1447c307-5dc7-5aa0-a2d2-add6d52e7fc6'::uuid, 'francais', '1re', 'Le Tartuffe, Molière', 'À quelle occasion la première version est-elle jouée à Versailles en 1664 ?', 'mcq', '["Le mariage de Louis XIV","La naissance du Dauphin","Les fêtes des Plaisirs de l’île enchantée","L’inauguration de la galerie des Glaces"]'::jsonb, 2, 'C’est une première version en trois actes ; les dévots, notamment la Compagnie du Saint-Sacrement, en obtiennent aussitôt l’interdiction.', 4),
    ('1b228d9d-16d4-5bad-a557-36328ab07231'::uuid, 'francais', '1re', 'Le Voyage d’Urien, André Gide', 'Quelle inscription les voyageurs découvrent-ils au pôle ?', 'mcq', '["HIC DESPERATUS","MEMENTO MORI","NON PLUS ULTRA","ET IN ARCADIA EGO"]'::jsonb, 0, 'L’inscription latine dit le désespoir au bout de la quête ; c’est sous la glace, à cet endroit, que les voyageurs trouvent un cadavre.', 1),
    ('34a08db2-da3a-52ce-be6c-029b705b9067'::uuid, 'francais', '1re', 'Le Voyage d’Urien, André Gide', 'Que tient le cadavre découvert sous la glace ?', 'mcq', '["Une carte du pôle","Une lettre d’adieu","Un papier tout blanc","Le journal de bord"]'::jsonb, 2, 'Au terme de la quête, aucun message : le papier est vierge, et l’Envoi avouera que le voyage n’a jamais eu lieu.', 2),
    ('07e2ffbc-ad0f-5d31-8f74-1fa8a82439c5'::uuid, 'francais', '1re', 'Le Voyage d’Urien, André Gide', 'Que devient l’équipage dans la mer des Sargasses ?', 'mcq', '["Il cède aux plaisirs des escales","Il s’enlise dans une mer immobile et morne","Il atteint enfin le pôle mystérieux","Il fait naufrage dans une tempête"]'::jsonb, 1, 'Après les tentations de l’Océan pathétique, l’immobilité des Sargasses précède la mer glaciale, blanche et pure : chaque paysage figure un état d’âme.', 3),
    ('b4157be0-48b7-59e3-a23b-e361104085b6'::uuid, 'francais', '1re', 'Le Voyage d’Urien, André Gide', 'Quel livre de Gide la tentation du renoncement, installée ici, annonce-t-elle ?', 'mcq', '["L’Immoraliste","Les Nourritures terrestres","Les Faux-Monnayeurs","La Porte étroite"]'::jsonb, 3, 'L’autre thème, l’ambiguïté du désir, annonce L’Immoraliste ; Les Nourritures terrestres (1897) marqueront le tournant vers la ferveur.', 4),
    ('5d9ac0c9-7ccd-5c3d-b342-f261007177a9'::uuid, 'francais', '1re', 'Les Amours Jaunes, Tristan Corbière', 'Qui était le père de Tristan Corbière ?', 'mcq', '["Un pêcheur de Roscoff","Un poète du Parnasse","Un capitaine, auteur de romans maritimes","Un professeur de lettres à Morlaix"]'::jsonb, 2, 'Édouard Corbière écrivait des romans de mer ; son fils, qui grandit près de Morlaix, écrira en marge du Parnasse, sans école ni protecteur.', 1),
    ('0c0c84ea-e597-504e-bed5-25c68a1ef68a'::uuid, 'francais', '1re', 'Les Amours Jaunes, Tristan Corbière', 'Comment le recueil paraît-il en 1873 ?', 'mcq', '["À compte d’auteur, presque sans lecteurs","Chez un grand éditeur, avec succès","En feuilleton dans un journal breton","Après la mort du poète, par Verlaine"]'::jsonb, 0, 'Il passe totalement inaperçu ; Corbière meurt en 1875, à vingt-neuf ans, et Verlaine le sauvera dans Les Poètes maudits.', 2),
    ('73119e88-e95b-5c21-a973-870d2bb87685'::uuid, 'francais', '1re', 'Les Amours Jaunes, Tristan Corbière', 'Que trouve-t-on dans la section « Rondels pour après » ?', 'mcq', '["La Bretagne des pardons et des mendiants","Les marins, loin des clichés romantiques","L’autoportrait ironique du poète","La mort, sur un ton de berceuse"]'::jsonb, 3, 'Chaque section a son univers : « Armor » la Bretagne, « Gens de mer » les marins, « Ça » l’autoportrait ; les rondels finaux parlent de la mort avec douceur.', 3),
    ('878667f9-98b6-500a-a39e-6b5626db37a2'::uuid, 'francais', '1re', 'Les Amours Jaunes, Tristan Corbière', 'Quels lecteurs ont reconnu la modernité de Corbière ?', 'mcq', '["Lamartine, Hugo et Musset","Laforgue, les surréalistes, T. S. Eliot","Les Parnassiens et Leconte de Lisle","Boileau et les poètes classiques"]'::jsonb, 1, 'Tous y ont reconnu une voix qui refuse la pose du poète : illisible pour ses contemporains, l’œuvre devient majeure au XXe siècle.', 4),
    ('f3c0c4cc-64de-5f36-9cce-d10524108b71'::uuid, 'francais', '1re', 'Les Amours, Pierre de Ronsard', 'Pourquoi Ronsard renonce-t-il à la carrière des armes ?', 'mcq', '["Il est blessé pendant les guerres d’Italie","Il perd la faveur du roi Henri II","Il est exilé après une querelle de cour","Devenu sourd jeune, il se tourne vers l’étude"]'::jsonb, 3, 'Il étudie les Anciens au collège de Coqueret, fonde la Pléiade avec Du Bellay et deviendra le poète des rois, notamment de Charles IX.', 1),
    ('a6c62a04-cd47-5f9c-9c53-cdb55913a66f'::uuid, 'francais', '1re', 'Les Amours, Pierre de Ronsard', 'Dans quel mètre sont écrits les sonnets des Amours de Cassandre (1552) ?', 'mcq', '["En alexandrins","En décasyllabes","En octosyllabes","En vers libres"]'::jsonb, 1, 'Ces sonnets pétrarquistes chantent un amour idéal et inaccessible, avec des images précieuses et une mythologie abondante.', 2),
    ('5d58a8b9-631d-583b-8502-ec23ce515c7d'::uuid, 'francais', '1re', 'Les Amours, Pierre de Ronsard', 'À quel ensemble appartient « Comme on voit sur la branche… » ?', 'mcq', '["Aux poèmes sur la mort de Marie","Aux Amours de Cassandre (1552)","Aux Sonnets pour Hélène (1578)","Aux Odes, avec « Mignonne »"]'::jsonb, 0, 'C’est la déploration après la mort de Marie, la jeune Angevine du « beau style bas » : le chant d’amour devient deuil.', 3),
    ('6a0c750d-df25-5b32-b339-dfe4cf757135'::uuid, 'francais', '1re', 'Les Amours, Pierre de Ronsard', 'Selon le cours, quelle est « l’arme finale » du poète pour séduire ?', 'mcq', '["La promesse d’un mariage à la cour","La menace du jugement divin","Sa gloire, qui seule immortalise la belle","La fortune du poète des rois"]'::jsonb, 2, 'Dans « Quand vous serez bien vieille », la belle vieillie se dira : « Ronsard me célébrait du temps que j’étais belle » — la poésie est la seule immortalité.', 4),
    ('c12409b6-038f-57f9-96de-4d7a19c7182f'::uuid, 'francais', '1re', 'Les Aventures de Télémaque, Fénelon', 'Quelle querelle vaut à Fénelon d’être exilé dans son diocèse en 1697 ?', 'mcq', '["La querelle du quiétisme","La querelle des Anciens et des Modernes","La querelle du Cid","La querelle des Bouffons"]'::jsonb, 0, 'Exilé avant même la publication du livre (1699, sans son accord), il tombe ensuite dans une disgrâce définitive, le Télémaque étant lu comme une critique de Louis XIV.', 1),
    ('3e5be7c2-106c-5d9e-b425-31b097cee5c0'::uuid, 'francais', '1re', 'Les Aventures de Télémaque, Fénelon', 'Quelles réformes Mentor mène-t-il à Salente ?', 'mcq', '["Plus de commerce de luxe et une cour agrandie","Une armée plus nombreuse et de nouvelles conquêtes","Moins de luxe, plus d’agriculture, une cour simplifiée","L’abolition de la royauté au profit du peuple"]'::jsonb, 2, 'Salente est réformée sous les yeux du lecteur : un contre-modèle du règne de Louis XIV, de son luxe et de ses courtisans.', 2),
    ('d4f4be4b-49f0-5519-af1e-9f24cdfd59b5'::uuid, 'francais', '1re', 'Les Aventures de Télémaque, Fénelon', 'Qui est Idoménée ?', 'mcq', '["Le père de Télémaque, roi d’Ithaque","Le frère de la nymphe Calypso","Un prêtre de la déesse Minerve","Le roi de Salente, qui se corrige"]'::jsonb, 3, 'Idoménée est le roi qui se corrige grâce aux conseils de Mentor : une leçon directe pour le prince à éduquer.', 3),
    ('7789c8fc-036c-500e-9cae-6d68391930cd'::uuid, 'francais', '1re', 'Les Aventures de Télémaque, Fénelon', 'Quel genre le livre illustre-t-il, selon le cours ?', 'mcq', '["La tragédie classique","L’apologue","Le roman épistolaire","La satire en vers"]'::jsonb, 1, 'Une fiction plaisante au service d’une leçon politique : le livre sert un sujet sur la littérature et le pouvoir.', 4),
    ('1ae9e21e-d194-5d2b-a622-60bdb8641d3e'::uuid, 'francais', '1re', 'Les Bonnes, Jean Genet', 'Qu’est-ce qui interrompt chaque soir la cérémonie des deux sœurs ?', 'mcq', '["Le téléphone de Monsieur","Le réveil qui sonne","L’arrivée de la police","Les cris de Madame"]'::jsonb, 1, 'La cérémonie va toujours jusqu’au bord du meurtre sans jamais aboutir : le réveil sonne et met fin au jeu.', 1),
    ('63c49e70-c4be-5cf4-87b8-5bc4b620ef31'::uuid, 'francais', '1re', 'Les Bonnes, Jean Genet', 'Quels écrivains ont soutenu Jean Genet à ses débuts ?', 'mcq', '["Camus et Malraux","Gide et Valéry","Cocteau et Sartre","Aragon et Breton"]'::jsonb, 2, 'Enfant de l’Assistance publique, passé par la maison de correction et la prison, Genet commence à écrire en détention ; Cocteau et Sartre le soutiennent.', 2),
    ('467afe9b-31ff-5441-9704-81b3691ad689'::uuid, 'francais', '1re', 'Les Bonnes, Jean Genet', 'Pourquoi le projet des deux sœurs s’emballe-t-il pendant la pièce ?', 'mcq', '["Madame a découvert le poison","Solange vient d’être renvoyée","La police les soupçonne d’un vol","Monsieur est libéré : elles craignent d’être découvertes"]'::jsonb, 3, 'Elles ont dénoncé Monsieur par des lettres anonymes ; sa libération fait craindre que tout soit découvert, et la peur précipite l’engrenage.', 3),
    ('ad2f0f85-edc3-56d2-ba2f-c99b952dedd4'::uuid, 'francais', '1re', 'Les Bonnes, Jean Genet', 'Que désigne la « domination intériorisée » que montre la pièce ?', 'mcq', '["Les bonnes haïssent Madame, mais se haïssent en elle","Madame se sent dominée en secret par ses bonnes","Monsieur domine Madame sans jamais paraître","Les bonnes refusent de jouer le moindre rôle"]'::jsonb, 0, 'La haine des servantes se retourne contre elles-mêmes : en jouant Madame, elles jouent aussi le mépris qu’elles ont appris à se porter.', 4),
    ('39fe055f-d336-5da9-b8ff-bfcbcc548e2f'::uuid, 'francais', '1re', 'Les Burgraves, Victor Hugo', 'Quelle pièce triomphe la même saison que l’échec des Burgraves ?', 'mcq', '["Hernani de Hugo","Chatterton de Vigny","Lucrèce de Ponsard","Lorenzaccio de Musset"]'::jsonb, 2, 'La Lucrèce de Ponsard, néoclassique, triomphe en 1843 : le public se détourne du drame romantique au moment même où Hugo le pousse à la démesure.', 1),
    ('ba2338dc-35f9-534a-8cc8-f51e2e854105'::uuid, 'francais', '1re', 'Les Burgraves, Victor Hugo', 'Qui est en réalité Guanhumara, l’esclave empoisonneuse ?', 'mcq', '["Ginevra, la femme que Fosco a vendue","La mère de la jeune Régina","La veuve de l’empereur Barberousse","La sœur cadette du vieux Job"]'::jsonb, 0, 'Autrefois aimée des deux demi-frères Fosco et Donato, Ginevra a été vendue comme esclave par Fosco, devenu Job : sa vengeance vise le vieillard.', 2),
    ('fa627bd3-6322-5dad-ac8b-2c8c11489fa6'::uuid, 'francais', '1re', 'Les Burgraves, Victor Hugo', 'Qui est Otbert, que Guanhumara veut armer contre Job ?', 'mcq', '["Le petit-fils de Barberousse","Un burgrave rival de Job","L’ancien amant de Guanhumara","Le fils perdu de Job"]'::jsonb, 3, 'Guanhumara ignore qu’Otbert est le fils perdu du vieillard : le parricide menace, jusqu’à ce que Barberousse arrête le bras du jeune homme.', 3),
    ('938cbbae-3597-5619-8525-7899e4e8980e'::uuid, 'francais', '1re', 'Les Burgraves, Victor Hugo', 'Quel voyage a inspiré la pièce à Victor Hugo ?', 'mcq', '["Un voyage en Espagne","Un voyage sur les bords du Rhin","Un long séjour à Rome","Une traversée vers l’Angleterre"]'::jsonb, 1, 'Hugo revient du Rhin (Le Rhin, 1842), dont les châteaux en ruine l’ont fasciné ; il veut un drame épique, à la manière d’Eschyle.', 4),
    ('acb41412-6572-56b8-b3cd-79d2445be20d'::uuid, 'francais', '1re', 'Les Cahiers d’André Walter, André Gide', 'Comment s’intitulent les deux cahiers qui composent le livre ?', 'mcq', '["Le Cahier rouge et le Cahier vert","Le Cahier blanc et le Cahier noir","Autrefois et Aujourd’hui","Le Livre d’or et le Livre de sang"]'::jsonb, 1, 'Le livre se présente comme les cahiers posthumes d’André Walter : le Cahier blanc, puis le Cahier noir, où il sombre peu à peu dans le délire.', 1),
    ('59b00349-8369-5cc0-b436-da6a4f72ee21'::uuid, 'francais', '1re', 'Les Cahiers d’André Walter, André Gide', 'Quand Gide épouse-t-il réellement sa cousine Madeleine Rondeaux ?', 'mcq', '["En 1891, dès la parution du livre","En 1909, à la fondation de la NRF","En 1895, pour un mariage blanc","Jamais : elle refuse toute sa vie"]'::jsonb, 2, 'Madeleine refuse d’abord sa demande ; Gide l’épouse en 1895, et ils vivront un mariage blanc — l’amour pur du livre devient une vie.', 2),
    ('a787e713-b2f4-54dd-8ba5-71bb27b86436'::uuid, 'francais', '1re', 'Les Cahiers d’André Walter, André Gide', 'Quel style marque ce livre de jeunesse, selon le cours ?', 'mcq', '["Un style naturaliste","Un style classique","Un style réaliste","Un style symboliste"]'::jsonb, 3, 'Le livre est très marqué par la période symboliste ; Gide jugera plus tard ce style avec sévérité.', 3),
    ('72592ac9-6980-5b6c-b319-a98fb5dbf0cc'::uuid, 'francais', '1re', 'Les Cahiers d’André Walter, André Gide', 'Dans quelles œuvres futures de Gide retrouve-t-on la forme du journal ?', 'mcq', '["Les Faux-Monnayeurs et le Journal","L’Immoraliste et Paludes","La Porte étroite et Corydon","Les Nourritures terrestres et Saül"]'::jsonb, 0, 'Walter tient un journal ; Édouard en tiendra un dans Les Faux-Monnayeurs, et Gide tiendra le sien toute sa vie : ce premier livre est une matrice.', 4),
    ('b4779e8e-f712-5030-a7fa-4833c4b390a2'::uuid, 'francais', '1re', 'Les Cahiers de Douai, Arthur Rimbaud', 'À qui Rimbaud confie-t-il les poèmes recopiés à Douai ?', 'mcq', '["Georges Izambard","Paul Verlaine","Théodore de Banville","Paul Demeny"]'::jsonb, 3, 'Il les recopie en deux liasses pour le jeune poète Paul Demeny, en espérant être publié ; Izambard, lui, est son professeur.', 1),
    ('199befa9-948c-5f1f-b38e-6cf1ff815cc9'::uuid, 'francais', '1re', 'Les Cahiers de Douai, Arthur Rimbaud', 'Quel est le parcours associé à l’œuvre pour l’épreuve du bac ?', 'mcq', '["Alchimie poétique : la boue et l’or","Les mémoires d’une âme","Émancipations créatrices","Individu, morale et société"]'::jsonb, 2, 'L’émancipation est triple : celle de l’adolescent contre sa famille, du citoyen contre l’ordre impérial, du poète contre les formes héritées.', 2),
    ('6b1bf97d-fd16-5841-8d21-51a0d50dad31'::uuid, 'francais', '1re', 'Les Cahiers de Douai, Arthur Rimbaud', 'À quelle veine du recueil appartient « Ma Bohème » ?', 'mcq', '["La satire politique","La fugue et la sensation","La provocation","L’élégie funèbre"]'::jsonb, 1, 'Le corps y marche, mange, regarde ; la nature remplace la maison — « Mes étoiles au ciel avaient un doux frou-frou ».', 3),
    ('5fda1194-54c5-5200-ad2e-0477df3de02e'::uuid, 'francais', '1re', 'Les Cahiers de Douai, Arthur Rimbaud', 'Contre quoi s’émancipe le citoyen, selon le cours ?', 'mcq', '["Contre sa famille","Contre les formes héritées","Contre l’ordre impérial","Contre l’Église catholique"]'::jsonb, 2, 'Les poèmes satiriques sont écrits pendant la guerre franco-prussienne et la chute du Second Empire : le citoyen se dresse contre l’ordre impérial.', 4),
    ('6c7fbe0a-9aac-512a-b3fe-b60969e9a95b'::uuid, 'francais', '1re', 'Les Caractères, Jean de La Bruyère', 'Dans quel camp La Bruyère entre-t-il à l’Académie française en 1693 ?', 'mcq', '["Dans le camp des Modernes","Dans le camp des Anciens","Du côté des jansénistes","Du côté des libertins"]'::jsonb, 1, 'Il se range parmi les Anciens, qui tiennent les auteurs de l’Antiquité pour des modèles : son livre s’est d’abord présenté comme une traduction de Théophraste.', 1),
    ('43d5f335-fef8-5de3-9630-b09e35cdeed8'::uuid, 'francais', '1re', 'Les Caractères, Jean de La Bruyère', 'Quel changement social La Bruyère observe-t-il, selon le cours ?', 'mcq', '["La noblesse gagne du pouvoir sur le roi","Les paysans s’enrichissent vite","L’argent commence à concurrencer la naissance","Le clergé perd toute influence"]'::jsonb, 2, 'Classique dans la forme, il est presque sociologue dans le regard : Giton le riche occupe l’espace, Phédon le pauvre n’ose rien.', 2),
    ('6266cff6-abc5-54e8-830c-6b8058411e3b'::uuid, 'francais', '1re', 'Les Caractères, Jean de La Bruyère', 'Qui La Bruyère décrit-il comme des « animaux farouches » qui se révèlent des hommes ?', 'mcq', '["Les courtisans","Les bourgeois de la ville","Les soldats","Les paysans"]'::jsonb, 3, 'Cette page du livre XI, « De l’homme », est l’une des plus fortes du siècle : le regard du moraliste découvre l’humanité de ceux qu’on ne voit pas.', 3),
    ('e60809d7-59d7-5c95-8a7f-8728d52a4845'::uuid, 'francais', '1re', 'Les Caractères, Jean de La Bruyère', 'Que vise le livre « De la ville » ?', 'mcq', '["La bourgeoisie qui singe la cour","Les paysans des provinces","Les auteurs à la mode","Les ministres du roi"]'::jsonb, 0, 'La ville imite la cour : la satire montre une société où chacun copie les manières de ceux qui sont au-dessus de lui.', 4),
    ('39361fdb-513e-58df-ac87-c0f78ab36c23'::uuid, 'francais', '1re', 'Les Caves du Vatican, André Gide', 'Qui mène la bande d’escrocs du livre ?', 'mcq', '["Julius de Baraglioul","Protos","Anthime Armand-Dubois","Lafcadio Wluiki"]'::jsonb, 1, 'Protos, ancien camarade de collège de Lafcadio, est le maître des déguisements : sa bande répand la rumeur du pape séquestré.', 1),
    ('32782329-f99a-50ba-92bd-e1ce89854bfd'::uuid, 'francais', '1re', 'Les Caves du Vatican, André Gide', 'Qui est Anthime Armand-Dubois ?', 'mcq', '["Un cardinal complice des escrocs","Le père naturel de Lafcadio","Un savant athée converti après un miracle","Un policier romain très zélé"]'::jsonb, 2, 'Savant athée converti après un miracle, il est l’un des beaux-frères de Fleurissoire : la sotie se moque autant de la religion que de la crédulité.', 2),
    ('17800230-13f1-5571-a797-d1a6586ee20d'::uuid, 'francais', '1re', 'Les Caves du Vatican, André Gide', 'Qui Lafcadio pousse-t-il par la portière d’un train ?', 'mcq', '["Protos","Julius de Baraglioul","Anthime Armand-Dubois","Amédée Fleurissoire"]'::jsonb, 3, 'Sans mobile, par pure disponibilité, il pousse Fleurissoire, le pèlerin naïf parti délivrer le pape : c’est l’acte gratuit.', 3),
    ('3933adcc-9619-521e-9915-1b084e543c94'::uuid, 'francais', '1re', 'Les Caves du Vatican, André Gide', 'Quel personnage annonce la mise en abyme des Faux-Monnayeurs ?', 'mcq', '["Julius, romancier qui veut écrire un personnage gratuit","Protos, qui change sans cesse de déguisement","Fleurissoire, qui raconte son voyage à Rome","Anthime, qui abandonne ses expériences"]'::jsonb, 0, 'Julius, romancier dans le roman, veut écrire un personnage « gratuit » : Gide reprendra ce jeu avec Édouard dans Les Faux-Monnayeurs.', 4),
    ('b953bcdd-69bd-595b-b21e-cd866b8cdcb2'::uuid, 'francais', '1re', 'Les Chaises, Eugène Ionesco', 'Où vivent le Vieux et la Vieille ?', 'mcq', '["Dans un appartement parisien","Dans un asile de vieillards","Dans une maison entourée d’eau","Dans un château en ruine"]'::jsonb, 2, 'Seuls dans une maison isolée, entourée d’eau, ils ont quatre-vingt-quinze et quatre-vingt-quatorze ans : tout dit la solitude.', 1),
    ('9cd78683-cd12-5731-b1e0-1faca46e227a'::uuid, 'francais', '1re', 'Les Chaises, Eugène Ionesco', 'Que font les deux vieillards une fois l’Orateur arrivé ?', 'mcq', '["Ils s’endorment dans leurs chaises","Ils chassent tous les invités","Ils prennent la parole à sa place","Ils se jettent par la fenêtre"]'::jsonb, 3, 'Rassurés de voir leur message confié à l’Orateur, ils se jettent par la fenêtre — avant que la foule vide découvre qu’il est sourd-muet.', 2),
    ('2a178899-0df0-5511-89ae-6eeb395865a7'::uuid, 'francais', '1re', 'Les Chaises, Eugène Ionesco', 'Quelle pièce d’Ionesco, créée en 1950, avait déjà révolutionné la scène ?', 'mcq', '["En attendant Godot","La Cantatrice chauve","Rhinocéros","Fin de partie"]'::jsonb, 1, 'Ionesco, né en Roumanie et installé en France, bouleverse la scène avec La Cantatrice chauve (1950), deux ans avant Les Chaises.', 3),
    ('cbcde178-a1d7-58f3-80ef-eecf32226243'::uuid, 'francais', '1re', 'Les Chaises, Eugène Ionesco', 'Que figure la prolifération des chaises, selon le cours ?', 'mcq', '["Les mots qui envahissent le vide","La richesse soudaine du couple","Le succès du message du Vieux","Une foule qui écoute vraiment"]'::jsonb, 0, 'Les chaises remplissent l’espace comme les mots envahissent le vide — et comme l’angoisse remplit la vie.', 4),
    ('490a9a67-2975-5194-85cf-f3006cf70b30'::uuid, 'francais', '1re', 'Les Châtiments, Victor Hugo', 'Quel surnom Hugo donne-t-il à Louis-Napoléon Bonaparte ?', 'mcq', '["Napoléon le Grand","Napoléon le Petit","Le Roi-Citoyen","Le Neveu prodigue"]'::jsonb, 1, '« Napoléon le Petit » : le neveu n’est qu’un nain qui singe son oncle, dont l’ombre l’écrase dans « L’expiation ».', 1),
    ('fda95d94-c4ad-5f2b-be65-2ee7c9a30b7f'::uuid, 'francais', '1re', 'Les Châtiments, Victor Hugo', 'Quel poème clôt le recueil en annonçant un avenir lumineux ?', 'mcq', '["Nox","L’expiation","Chanson","Lux"]'::jsonb, 3, 'Après sept livres de combat, « Lux » (la lumière) annonce l’avenir : la satire débouche sur l’espérance.', 2),
    ('b1a41003-c9aa-5906-af2a-75d74924cd71'::uuid, 'francais', '1re', 'Les Châtiments, Victor Hugo', 'Combien d’années Hugo reste-t-il en exil ?', 'mcq', '["Cinq ans","Dix ans","Dix-neuf ans","Trente ans"]'::jsonb, 2, 'Il refuse l’amnistie de 1859 — « quand la liberté rentrera, je rentrerai » — et ne revient qu’à la chute de l’Empire, en 1870.', 3),
    ('70875424-bdc9-5029-9763-0b6a3621da41'::uuid, 'francais', '1re', 'Les Châtiments, Victor Hugo', 'Quel poème du recueil célèbre l’épopée révolutionnaire ?', 'mcq', '["« Ô soldats de l’an deux ! »","« Souvenir de la nuit du 4 »","« Chanson »","« Lux »"]'::jsonb, 0, 'Hugo oppose aux soldats du Second Empire l’élan des volontaires de l’an II : le registre épique sert la satire.', 4),
    ('52671107-6c79-5ef5-a04a-4de4f7660ea0'::uuid, 'francais', '1re', 'Les Complaintes, Jules Laforgue', 'Où Jules Laforgue est-il né ?', 'mcq', '["À Tarbes","À Berlin","À Montevideo","À Bruxelles"]'::jsonb, 2, 'Né en Uruguay, il grandit à Tarbes puis à Paris ; Berlin est la ville où il sera lecteur de l’impératrice Augusta.', 1),
    ('3a3139ff-d53a-5825-b12f-87df90f7ee63'::uuid, 'francais', '1re', 'Les Complaintes, Jules Laforgue', 'Quel philosophe du pessimisme Laforgue lit-il ?', 'mcq', '["Schopenhauer","Nietzsche","Pascal","Descartes"]'::jsonb, 0, 'La lecture de Schopenhauer nourrit l’ennui et la tristesse des Complaintes — que l’ironie empêche de tourner à l’épanchement.', 2),
    ('4b75a323-5d8d-5391-b639-03d69618cd30'::uuid, 'francais', '1re', 'Les Complaintes, Jules Laforgue', 'Que symbolise la Lune dans le recueil ?', 'mcq', '["La fécondité et l’espoir","La stérilité, l’ennui, le rêve froid","La passion amoureuse partagée","La gloire future du poète"]'::jsonb, 1, 'Astre blême et inutile, la Lune est le symbole de la stérilité et de l’ennui — voir « Complainte de la Lune en province ».', 3),
    ('7d15d24e-412e-5c6b-948b-69881801742a'::uuid, 'francais', '1re', 'Les Complaintes, Jules Laforgue', 'Dans quelles conditions le recueil paraît-il en 1885 ?', 'mcq', '["Chez un grand éditeur, avec succès","En revue, sous un pseudonyme","Après sa mort, grâce à ses amis","À compte d’auteur, à vingt-quatre ans"]'::jsonb, 3, 'Publié à ses frais par un poète de vingt-quatre ans, mort de tuberculose deux ans plus tard : une influence très supérieure à sa notoriété.', 4),
    ('35f6928b-3f0c-5d82-813b-82f826fd9b98'::uuid, 'francais', '1re', 'Les Confessions, Jean-Jacques Rousseau', 'Combien de livres comptent Les Confessions ?', 'mcq', '["Six","Douze","Vingt-quatre","Trois"]'::jsonb, 1, 'Douze livres écrits entre 1765 et 1770 : les six premiers paraissent en 1782, les six suivants en 1789, après la mort de Rousseau.', 1),
    ('b8f6f555-4fc5-5f27-8384-352dc91ad54c'::uuid, 'francais', '1re', 'Les Confessions, Jean-Jacques Rousseau', 'Où se déroule l’épisode de la fessée donnée par Mlle Lambercier ?', 'mcq', '["À Annecy","Aux Charmettes","À Bossey","À Turin"]'::jsonb, 2, 'À Bossey, chez le pasteur Lambercier : l’épisode montre l’importance que Rousseau donne à l’enfance et aux sensations.', 2),
    ('0b741954-12cb-546c-af0f-72fa4a8cfd0d'::uuid, 'francais', '1re', 'Les Confessions, Jean-Jacques Rousseau', 'À quel prédécesseur Rousseau s’oppose-t-il dans la peinture de soi ?', 'mcq', '["Pascal, auteur des Pensées","Saint-Simon, auteur des Mémoires","Voltaire, auteur de Candide","Montaigne, auteur des Essais"]'::jsonb, 3, 'Il s’oppose aux Essais de Montaigne ; en faisant primer le sentiment intérieur sur les faits, il annonce le romantisme.', 3),
    ('90d77acc-0628-5e7d-9933-ce94f574763e'::uuid, 'francais', '1re', 'Les Confessions, Jean-Jacques Rousseau', 'Quelle distinction faut-il faire pour bien lire Les Confessions ?', 'mcq', '["Le narrateur adulte qui juge et l’enfant qui vit","L’auteur réel et un héros entièrement inventé","Le maître et le valet qui racontent tour à tour","Le poète et la Muse qui lui dicte le livre"]'::jsonb, 0, 'L’analyse accompagne le récit : l’adulte commente et juge ce que l’enfant a vécu et ressenti.', 4),
    ('e4589577-5238-577a-9217-33ac65f62ded'::uuid, 'francais', '1re', 'Les Contemplations, Victor Hugo', 'Que permet à Hugo le succès du recueil ?', 'mcq', '["Acheter un hôtel particulier à Paris","Acheter Hauteville House, à Guernesey","Fonder un journal républicain","Racheter la maison de Villequier"]'::jsonb, 1, 'Le succès de 1856 lui permet d’acheter Hauteville House, sa maison d’exil à Guernesey.', 1),
    ('965f051d-3beb-5dcc-8314-1cdd1be59dad'::uuid, 'francais', '1re', 'Les Contemplations, Victor Hugo', 'Dans quel poème Hugo écrit-il « Je mis un bonnet rouge au vieux dictionnaire » ?', 'mcq', '["« Melancholia »","« À Villequier »","« Réponse à un acte d’accusation »","« Paroles sur la dune »"]'::jsonb, 2, 'Le bonnet rouge, symbole révolutionnaire, dit la révolution romantique de la langue : tous les mots ont droit de cité en poésie.', 2),
    ('bc800bc4-4dab-5a9a-9389-e400ccc08fc3'::uuid, 'francais', '1re', 'Les Contemplations, Victor Hugo', 'Où et quand Léopoldine s’est-elle noyée ?', 'mcq', '["À Guernesey, en 1855","À Jersey, en 1852","Au Havre, en 1848","À Villequier, en 1843"]'::jsonb, 3, 'Sa mort, à dix-neuf ans, sépare Autrefois d’Aujourd’hui : elle est le pivot du recueil.', 3),
    ('d73cda81-70d6-502c-96e6-659331f85db2'::uuid, 'francais', '1re', 'Les Contemplations, Victor Hugo', 'Pourquoi Hugo vit-il à Guernesey en 1856 ?', 'mcq', '["Il a été expulsé de Jersey","Il y a été élu député","Il y possède une maison de famille","Il fuit la Commune de Paris"]'::jsonb, 0, 'Exilé depuis le coup d’État de 1851, expulsé de Jersey, il s’installe à Guernesey l’année précédant la publication.', 4),
    ('0912233c-ec3f-5600-a4a9-0855c3033f52'::uuid, 'francais', '1re', 'Les Destinées, Alfred de Vigny', 'Combien de poèmes compte le recueil ?', 'mcq', '["Sept","Vingt-deux","Onze","Cinquante"]'::jsonb, 2, 'Onze poèmes philosophiques écrits sur trente ans : chacun développe une idée par un symbole.', 1),
    ('681c991d-2c5e-5e85-9aaa-c6813f25a336'::uuid, 'francais', '1re', 'Les Destinées, Alfred de Vigny', 'Quelle idée porte « L’Esprit pur » ?', 'mcq', '["La noblesse de l’esprit contre celle du sang","La pureté de l’amour de jeunesse","Le silence de Dieu face à l’homme","L’indifférence de la nature"]'::jsonb, 0, 'L’aristocrate Vigny place la vraie noblesse dans l’œuvre de l’esprit, non dans la naissance.', 2),
    ('b63ae648-7aa6-5fc1-a9f2-d99c9c2c4d6c'::uuid, 'francais', '1re', 'Les Destinées, Alfred de Vigny', 'Quel thème développe « La Colère de Samson » ?', 'mcq', '["Le stoïcisme face à la mort","La trahison amoureuse","La transmission du savoir","La gloire militaire"]'::jsonb, 1, 'Samson, trahi par la femme qu’il aime, figure l’homme trahi par l’amour : un symbole porte une idée.', 3),
    ('3a1c21fb-56a5-59d9-9dc6-85ff7b8ac64a'::uuid, 'francais', '1re', 'Les Destinées, Alfred de Vigny', 'À quel poète le cours oppose-t-il l’austérité de Vigny ?', 'mcq', '["Leconte de Lisle","Baudelaire","Mallarmé","Lamartine"]'::jsonb, 3, 'Vigny, le plus pessimiste des grands romantiques, fait du poème la démonstration d’une idée par une image — loin du lyrisme sentimental de Lamartine.', 4),
    ('5999ae79-a1c8-503e-9353-75e3fc683334'::uuid, 'francais', '1re', 'Les Fausses Confidences, Marivaux', 'Qu’appelle-t-on le « marivaudage » ?', 'mcq', '["Un langage précieux sans aucun sentiment","L’art de peindre les détours d’un amour inavoué","Une intrigue de valets trompant leurs maîtres","Un mariage d’argent arrangé par la famille"]'::jsonb, 1, 'On aime sans vouloir se l’avouer, et le langage trahit ce qu’il cache : c’est tout l’art de Marivaux.', 1),
    ('ade64554-5f22-5952-a989-3d3ed80ef20d'::uuid, 'francais', '1re', 'Les Fausses Confidences, Marivaux', 'Sous quelle fonction Dorante entre-t-il chez Araminte ?', 'mcq', '["Précepteur","Secrétaire","Intendant","Notaire"]'::jsonb, 2, 'Son oncle, M. Remy, le fait présenter comme intendant : le voilà dans la maison de celle qu’il aime, sans fortune pour y prétendre.', 2),
    ('8192b660-e0ed-5f61-b431-16fcdc779255'::uuid, 'francais', '1re', 'Les Fausses Confidences, Marivaux', 'Qui Madame Argante veut-elle faire épouser à sa fille ?', 'mcq', '["Dorante","Monsieur Remy","Un riche financier","Le comte Dorimont"]'::jsonb, 3, 'Madame Argante, autoritaire et intéressée, veut un beau mariage : un comte pour sa fille.', 3),
    ('1a4cdd26-2d86-5f36-90fe-10192a73ca30'::uuid, 'francais', '1re', 'Les Fausses Confidences, Marivaux', 'Selon le cours, comment Dubois mène-t-il son stratagème ?', 'mcq', '["Il choisit quand la vérité est dite","Il ment à chaque scène","Il falsifie les contrats","Il achète les domestiques"]'::jsonb, 0, 'Dubois ne ment presque jamais : il règle le moment où chaque vérité éclate, et le stratagème lève les obstacles plus qu’il ne fabrique le sentiment.', 4),
    ('a38259a8-d3ea-539e-b0e7-77d6f5754b0f'::uuid, 'francais', '1re', 'Les Faux-Monnayeurs, André Gide', 'Quel texte Gide publie-t-il l’année suivante pour accompagner le roman ?', 'mcq', '["Les Cahiers d’André Walter","Un recueil de lettres d’Édouard","Le Journal des faux-monnayeurs","Un essai sur le Nouveau Roman"]'::jsonb, 2, 'Le Journal des faux-monnayeurs raconte la fabrication du roman : le livre se réfléchit jusque hors de lui-même.', 1),
    ('e69a10cf-c41e-5018-bcb6-c50e2fc7e97e'::uuid, 'francais', '1re', 'Les Faux-Monnayeurs, André Gide', 'Par quel personnage cynique Olivier est-il attiré ?', 'mcq', '["Le pasteur Vedel","Le comte de Passavant","Strouvilhou","Bernard Profitendieu"]'::jsonb, 1, 'Olivier, ami de Bernard, est attiré par le cynique comte de Passavant, avant de se tourner vers Édouard.', 2),
    ('7a3bec42-3a2a-5b2b-ba6d-2f39015684f6'::uuid, 'francais', '1re', 'Les Faux-Monnayeurs, André Gide', 'Qui délaisse Laura, enceinte, pour Lady Griffith ?', 'mcq', '["Édouard","Olivier","Georges","Vincent"]'::jsonb, 3, 'Vincent, frère aîné d’Olivier, abandonne Laura, la fille du pasteur Vedel, pour Lady Griffith.', 3),
    ('126249b5-d6ff-5bbf-9533-c6acc550302c'::uuid, 'francais', '1re', 'Les Faux-Monnayeurs, André Gide', 'Quel lien unit Édouard et Olivier ?', 'mcq', '["Édouard est l’oncle d’Olivier","Ils sont demi-frères","Édouard est son professeur","Aucun lien de parenté"]'::jsonb, 0, 'Édouard est le demi-frère de la mère d’Olivier : l’écrivain qui prépare Les Faux-Monnayeurs est l’oncle du jeune homme.', 4),
    ('8b7577b0-921b-5a97-937e-1cd04539cbf1'::uuid, 'francais', '1re', 'Les Fleurs du mal, Charles Baudelaire', 'Quel procureur fait condamner le recueil en 1857 ?', 'mcq', '["Maxime Du Camp","Ernest Pinard","Sainte-Beuve","Barbey d’Aurevilly"]'::jsonb, 1, 'Ernest Pinard avait déjà poursuivi Madame Bovary la même année : deux chefs-d’œuvre devant le tribunal en 1857.', 1),
    ('5bd56a5e-8cb9-52ba-942a-35067a3804f7'::uuid, 'francais', '1re', 'Les Fleurs du mal, Charles Baudelaire', 'En quelle année la condamnation des Fleurs du mal est-elle annulée ?', 'mcq', '["1861","1867","1905","1949"]'::jsonb, 3, 'Il faut attendre 1949 pour que la condamnation pour outrage aux bonnes mœurs soit annulée et les six pièces réhabilitées.', 2),
    ('4bb86d11-fc2d-59e0-aeb8-ca63a9ff147e'::uuid, 'francais', '1re', 'Les Fleurs du mal, Charles Baudelaire', 'Quel poème invente le regard du flâneur dans la ville ?', 'mcq', '["« Une Charogne »","« La Chevelure »","« À une passante »","« L’Invitation au voyage »"]'::jsonb, 2, 'Une rencontre d’un instant dans la rue : Baudelaire fait de la ville moderne et du transitoire une matière poétique.', 3),
    ('004e32ec-d6b5-51d2-adc4-3b2f47eb830b'::uuid, 'francais', '1re', 'Les Fleurs du mal, Charles Baudelaire', 'Quelle section clôt le recueil ?', 'mcq', '["La Mort","Révolte","Le Vin","Spleen et Idéal"]'::jsonb, 0, 'L’architecture mène de l’élan vers l’idéal jusqu’à la mort, dernière évasion : « Au fond de l’Inconnu pour trouver du nouveau ! »', 4),
    ('9deef1f3-283a-5f69-ad15-f4f2b99639c7'::uuid, 'francais', '1re', 'Les Fourberies de Scapin, Molière', 'Dans quelle ville se déroule l’action ?', 'mcq', '["À Paris","À Naples","À Venise","À Rome"]'::jsonb, 1, 'Molière revient à l’Italie et à la farce de ses débuts : l’action se passe à Naples.', 1),
    ('8935ef7b-1fc3-59bd-8273-7a4c2e7e64a3'::uuid, 'francais', '1re', 'Les Fourberies de Scapin, Molière', 'Comment Scapin obtient-il son pardon au dénouement ?', 'mcq', '["En rendant l’argent volé","En avouant tout à genoux","En feignant d’être mourant","Grâce à l’appui d’Octave"]'::jsonb, 2, 'Il se fait apporter comme un mourant pour arracher le pardon de Géronte : une dernière fourberie.', 2),
    ('04a287ad-48df-51a8-8c45-65353357c25d'::uuid, 'francais', '1re', 'Les Fourberies de Scapin, Molière', 'Quel écrivain reproche à Molière ce retour à la farce ?', 'mcq', '["Racine","Corneille","La Fontaine","Boileau"]'::jsonb, 3, 'Dans son Art poétique : « Dans ce sac ridicule où Scapin s’enveloppe, / Je ne reconnais plus l’auteur du Misanthrope ».', 3),
    ('dbe1a52f-8d93-5aa9-8fad-8adacc10f7ea'::uuid, 'francais', '1re', 'Les Fourberies de Scapin, Molière', 'Quelle ruse Scapin emploie-t-il contre Argante ?', 'mcq', '["Un faux spadassin exige de l’argent pour casser le mariage","Son fils serait retenu sur une galère turque","Hyacinte serait une voleuse recherchée","Octave aurait perdu au jeu toute sa fortune"]'::jsonb, 0, 'Un soi-disant frère d’Hyacinte, spadassin, se ferait payer pour faire casser le mariage — sinon, ce serait un procès ruineux.', 4),
    ('5ce4271c-b83f-514f-ac5c-5719822e5713'::uuid, 'francais', '1re', 'Les Justes, Albert Camus', 'Que demande Dora à la fin de la pièce ?', 'mcq', '["À quitter l’organisation","À voir le corps de Kaliayev","À rencontrer la grande-duchesse","À lancer la prochaine bombe"]'::jsonb, 3, 'Après la pendaison de Kaliayev, Dora demande à lancer la prochaine bombe : la pièce ne se termine pas sur une issue heureuse.', 1),
    ('7e7497ea-2c49-534f-926b-f06637040c37'::uuid, 'francais', '1re', 'Les Justes, Albert Camus', 'Qui est Foka ?', 'mcq', '["Le chef du groupe terroriste","Un prisonnier devenu bourreau","Le cocher du grand-duc","Un indicateur de la police"]'::jsonb, 1, 'Foka est devenu bourreau pour réduire sa peine : un personnage qui montre ce que la violence fait des hommes.', 2),
    ('ad84aeab-e2d1-58b6-8e06-1577c8a5edaf'::uuid, 'francais', '1re', 'Les Justes, Albert Camus', 'Selon Camus, à quelle condition le révolté peut-il tuer ?', 'mcq', '["S’il est sûr de réussir","S’il agit sur ordre du parti","S’il accepte de payer ce meurtre de sa vie","S’il épargne sa propre famille"]'::jsonb, 2, 'Pour Camus, le révolté doit payer de sa vie le meurtre qu’il commet, et refuser de tuer des innocents, au risque d’être inefficace.', 3),
    ('0c48a827-7f30-532c-bc9c-708f11082745'::uuid, 'francais', '1re', 'Les Justes, Albert Camus', 'Qui dirige le groupe de socialistes révolutionnaires ?', 'mcq', '["Annenkov","Stepan","Kaliayev","Voinov"]'::jsonb, 0, 'Annenkov, le chef, donne raison à Kaliayev contre Stepan quand il renonce à lancer la bombe sur une calèche où sont des enfants.', 4),
    ('e9076b26-7a1d-5fbd-a811-2ae8b11b849c'::uuid, 'francais', '1re', 'Les Liaisons dangereuses, Pierre Choderlos de Laclos', 'Quel était le métier de Choderlos de Laclos ?', 'mcq', '["Magistrat","Officier d’artillerie","Abbé de cour","Fermier général"]'::jsonb, 1, 'Officier d’artillerie en garnison, il construit son unique roman comme un plan de bataille.', 1),
    ('e81e2f07-2b52-5edb-a503-a8f613b7775e'::uuid, 'francais', '1re', 'Les Liaisons dangereuses, Pierre Choderlos de Laclos', 'Quel est l’enjeu du pari entre Valmont et Merteuil ?', 'mcq', '["Une nuit avec la marquise","Une forte somme d’argent","La main de Cécile","Un duel avec Gercourt"]'::jsonb, 0, 'Si Valmont séduit la présidente de Tourvel, Merteuil lui promet une nuit : la séduction devient une campagne militaire.', 2),
    ('f4a37797-725d-5c0c-a084-2349b202c1d9'::uuid, 'francais', '1re', 'Les Liaisons dangereuses, Pierre Choderlos de Laclos', 'À qui Valmont lègue-t-il les lettres de Merteuil ?', 'mcq', '["À Madame de Rosemonde","À Cécile de Volanges","À Madame de Volanges","À Danceny"]'::jsonb, 3, 'Tué en duel par Danceny, il lui lègue les lettres de la marquise : leur publication la démasque.', 3),
    ('c6928faa-fce2-535d-880f-bcdff9264d5f'::uuid, 'francais', '1re', 'Les Liaisons dangereuses, Pierre Choderlos de Laclos', 'Qu’est-ce qui fait de ce roman un chef-d’œuvre de polyphonie ?', 'mcq', '["Un narrateur omniscient commente chaque lettre","Le roman alterne les vers et la prose","Chaque lettre a son style, son destinataire, sa stratégie","Tous les personnages écrivent de la même façon"]'::jsonb, 2, 'Aucune voix ne domine : le lecteur reconstitue seul la vérité, entre les mensonges et les confidences.', 4),
    ('9b111f4b-cde1-5cf2-afc7-5cd160f18832'::uuid, 'francais', '1re', 'Les Mains sales, Jean-Paul Sartre', 'Dans quel pays se déroule l’action ?', 'mcq', '["En Hongrie","En Pologne","En Illyrie","En Russie"]'::jsonb, 2, 'L’Illyrie est un pays imaginaire d’Europe de l’Est, entre 1943 et 1945, quand les partis se disputent le pouvoir à venir.', 1),
    ('d9bd658d-f41e-57a2-874d-a4c5919ff910'::uuid, 'francais', '1re', 'Les Mains sales, Jean-Paul Sartre', 'Comment la pièce est-elle construite ?', 'mcq', '["En sept tableaux, surtout en flash-back","En cinq actes chronologiques","En un seul acte continu","En trois journées successives"]'::jsonb, 0, 'Hugo sort de prison, puis la pièce revient deux ans en arrière : le spectateur cherche avec lui pourquoi il a tiré.', 2),
    ('c38ea485-e27b-5545-bfcd-d7f5ccccdcbc'::uuid, 'francais', '1re', 'Les Mains sales, Jean-Paul Sartre', 'Quel poste Hugo occupe-t-il auprès d’Hoederer ?', 'mcq', '["Garde du corps","Chauffeur","Journaliste","Secrétaire"]'::jsonb, 3, 'Devenu son secrétaire pour pouvoir l’abattre, Hugo finit par l’admirer et hésite.', 3),
    ('c01f998f-0491-5156-8e06-65f4cb223a71'::uuid, 'francais', '1re', 'Les Mains sales, Jean-Paul Sartre', 'Pourquoi Hoederer est-il accusé de trahison ?', 'mcq', '["Il a vendu des armes à l’ennemi","Il veut s’allier aux conservateurs et au régent","Il a dénoncé Louis à la police","Il refuse d’entrer au gouvernement"]'::jsonb, 1, 'Chef réaliste, prêt aux compromis pour éviter des morts, il veut s’allier aux conservateurs et au régent — une ligne que le parti adoptera ensuite.', 4),
    ('1b261fa8-6e06-53d6-9497-799fa516d702'::uuid, 'francais', '1re', 'Les Misérables, Victor Hugo', 'Sous quel nom Jean Valjean devient-il maire et industriel ?', 'mcq', '["Monsieur Madeleine","Monsieur Myriel","Monsieur Gillenormand","Monsieur Mabeuf"]'::jsonb, 0, 'Devenu Monsieur Madeleine, maire et industriel, l’ancien forçat vit sa rédemption — jusqu’à ce que Javert le retrouve.', 1),
    ('def3bfde-83d4-58c5-b8df-489b61d42593'::uuid, 'francais', '1re', 'Les Misérables, Victor Hugo', 'Comment meurt Javert ?', 'mcq', '["Tué sur la barricade","Il se jette dans la Seine","Exécuté par les insurgés","De vieillesse, en prison"]'::jsonb, 1, 'Épargné par Valjean, incapable de penser un criminel bon, Javert se jette dans la Seine : la Loi ne comprend pas la conscience.', 2),
    ('b4648282-a61b-5e4e-ab97-0ec712d4ac5a'::uuid, 'francais', '1re', 'Les Misérables, Victor Hugo', 'Quelle bataille fait l’objet d’une longue digression historique ?', 'mcq', '["Austerlitz","Wagram","Waterloo","Iéna"]'::jsonb, 2, 'Hugo mêle au récit des digressions historiques (Waterloo) et sociales (les égouts, l’argot, les couvents) : c’est un roman-monde.', 3),
    ('c93bdcac-6eb6-597d-b710-fdfd3632ba5b'::uuid, 'francais', '1re', 'Les Misérables, Victor Hugo', 'Qui meurt sur la barricade de la rue de la Chanvrerie ?', 'mcq', '["Cosette et Fantine","Marius et Javert","Les Thénardier","Gavroche et Éponine"]'::jsonb, 3, 'L’insurrection de juin 1832 coûte la vie à Gavroche, le peuple de Paris, et à Éponine ; Marius, blessé, est sauvé par Valjean.', 4),
    ('3ac582dc-f8f6-5edb-a6f6-e998f3493cff'::uuid, 'francais', '1re', 'Les Mots, Jean-Paul Sartre', 'Quel métier exerce Charles Schweitzer, le grand-père qui élève Sartre ?', 'mcq', '["Pasteur protestant","Professeur d’allemand","Libraire à Paris","Médecin de campagne"]'::jsonb, 1, 'Charles Schweitzer enseigne l’allemand ; son appartement plein de livres est le premier décor de l’enfant, qui commence sa vie « au milieu des livres ».', 1),
    ('ef461f8a-db7d-5e20-826b-140638d3e1e8'::uuid, 'francais', '1re', 'Les Mots, Jean-Paul Sartre', 'Comment Anne-Marie, la mère de Sartre, est-elle traitée dans le foyer ?', 'mcq', '["En maîtresse de maison respectée","En étrangère tenue à l’écart","En gouvernante de l’enfant","En grande sœur de son propre fils"]'::jsonb, 3, 'Veuve très tôt, Anne-Marie vit chez ses parents : le narrateur la présente comme une grande sœur plus que comme une mère, dans un foyer que domine le grand-père.', 2),
    ('6ade8cd0-44e8-5d6b-b9e9-a8853c06fac6'::uuid, 'francais', '1re', 'Les Mots, Jean-Paul Sartre', 'Selon le cours, qu’est-ce qui distingue Les Mots des Confessions de Rousseau ?', 'mcq', '["Sartre refuse l’émotion et préfère l’analyse lucide","Sartre raconte toute sa vie jusqu’à la vieillesse","Sartre écrit en vers et non en prose","Sartre cherche d’abord à se faire pardonner"]'::jsonb, 0, 'Là où Rousseau fait appel à l’émotion, Sartre démonte son enfance avec ironie : c’est une autobiographie critique, où l’adulte se moque de l’enfant qu’il était.', 3),
    ('40688762-83fa-5702-abf3-d848fe6de51f'::uuid, 'francais', '1re', 'Les Mots, Jean-Paul Sartre', 'Quel rôle l’enfant Sartre joue-t-il pour plaire à sa famille ?', 'mcq', '["Celui du petit rebelle","Celui de l’enfant malade","Celui de l’enfant prodige","Celui du futur soldat"]'::jsonb, 2, 'Unique et adulé, Poulou lit avant de comprendre et recopie des romans d’aventures : il joue l’enfant prodige qu’on attend de lui, jusqu’à se croire destiné à écrire.', 4),
    ('69def352-61a3-5f1c-8112-f2cb7e12b0de'::uuid, 'francais', '1re', 'Les Mouches, Jean-Paul Sartre', 'De quelle tragédie antique Sartre reprend-il le sujet ?', 'mcq', '["Antigone de Sophocle","Médée d’Euripide","Les Choéphores d’Eschyle","Les Perses d’Eschyle"]'::jsonb, 2, 'Les Choéphores, deuxième pièce de l’Orestie d’Eschyle, racontent le retour d’Oreste et le meurtre de Clytemnestre et d’Égisthe : Sartre garde l’histoire mais en change le sens.', 1),
    ('380ee178-5104-5562-9657-929034c072a6'::uuid, 'francais', '1re', 'Les Mouches, Jean-Paul Sartre', 'Pourquoi Sartre choisit-il un sujet antique en 1943 ?', 'mcq', '["Pour passer la censure de l’occupant","Pour plaire au public des lycéens","Pour imiter la mode des tragédies en vers","Pour éviter de parler de politique"]'::jsonb, 0, 'Sous l’Occupation, le mythe grec sert de masque : le message — refuser le remords et la résignation organisés par le pouvoir — reste clair pour qui sait lire.', 2),
    ('79e7048f-eae3-52fc-b3c9-2fa08a2b5e77'::uuid, 'francais', '1re', 'Les Mouches, Jean-Paul Sartre', 'Qui est le Pédagogue dans la pièce ?', 'mcq', '["Le chef des gardes d’Égisthe","Le prêtre de Jupiter à Argos","Un vieillard du peuple d’Argos","Le précepteur d’Oreste, sceptique et prudent"]'::jsonb, 3, 'Sceptique et prudent, le Pédagogue incarne une sagesse détachée ; Oreste, lui, finira par choisir l’acte et l’assumer entièrement.', 3),
    ('1ca2dae3-a301-51ed-85ae-293a8edbac1b'::uuid, 'francais', '1re', 'Les Mouches, Jean-Paul Sartre', 'Quel grand ouvrage philosophique Sartre publie-t-il la même année que Les Mouches ?', 'mcq', '["La Nausée","L’Être et le Néant","Les Mots","Huis clos"]'::jsonb, 1, 'L’Être et le Néant (1943) expose la philosophie que la pièce met en scène : l’homme est libre, sans nature humaine fixée d’avance, et doit assumer ses actes.', 4),
    ('6fa64d04-8b42-5bb8-9875-7d80ee32af24'::uuid, 'francais', '1re', 'Les Nourritures terrestres, André Gide', 'À quels moments le livre devient-il le « bréviaire » de la jeunesse ?', 'mcq', '["Dès sa parution en 1897","Après 1918, puis après 1945","Pendant la Belle Époque, vers 1900","Après Mai 68 seulement"]'::jsonb, 1, 'Passé presque inaperçu en 1897 (à peine cinq cents exemplaires en dix ans), le livre devient le bréviaire de deux générations, au sortir des deux guerres mondiales.', 1),
    ('b0bd3b26-d906-57a2-a130-373f4c418c51'::uuid, 'francais', '1re', 'Les Nourritures terrestres, André Gide', 'Quelle suite Gide donne-t-il au livre en 1935 ?', 'mcq', '["L’Immoraliste","Les Faux-Monnayeurs","Les Nouvelles Nourritures","La Porte étroite"]'::jsonb, 2, 'Les Nouvelles Nourritures paraissent en 1935, près de quarante ans après le premier livre de 1897.', 2),
    ('12357664-2a32-5267-8257-24cc253c8370'::uuid, 'francais', '1re', 'Les Nourritures terrestres, André Gide', 'De quel mouvement littéraire Gide sort-il avec ce livre ?', 'mcq', '["Du symbolisme","Du naturalisme","Du romantisme","Du surréalisme"]'::jsonb, 0, 'Le livre marque le tournant de Gide : il quitte le symbolisme et la contrainte protestante, grâce au voyage en Afrique du Nord et à la renaissance des sens.', 3),
    ('7c43083c-0154-5ff9-a6a5-23d0afe64d01'::uuid, 'francais', '1re', 'Les Nourritures terrestres, André Gide', 'Comment le cours caractérise-t-il l’écriture du livre ?', 'mcq', '["Des alexandrins en strophes régulières","Un récit réaliste à la troisième personne","Un dialogue philosophique argumenté","Une prose rythmée, presque un poème"]'::jsonb, 3, 'Rythme, répétitions, adresses à Nathanaël : le livre est un bon exemple d’écriture poétique en prose, qui fait éprouver le désir au lieu de le définir.', 4),
    ('d6b089b7-d0f7-51eb-8163-8cd3089eb7e0'::uuid, 'francais', '1re', 'Les Plaideurs, Jean Racine', 'De quelle comédie grecque Racine s’inspire-t-il ?', 'mcq', '["Les Nuées d’Aristophane","Les Guêpes d’Aristophane","Les Grenouilles d’Aristophane","Les Oiseaux d’Aristophane"]'::jsonb, 1, 'Dans Les Guêpes, Aristophane se moquait déjà de la manie de juger des Athéniens : Racine transpose ce vieux sujet dans la France de 1668.', 1),
    ('6e5e1734-caaa-57d4-b4fa-2ac0dad0f312'::uuid, 'francais', '1re', 'Les Plaideurs, Jean Racine', 'Comment s’appelle le chien accusé d’avoir mangé un chapon ?', 'mcq', '["Médor","Pataud","Citron","Brutus"]'::jsonb, 2, 'Le procès de Citron est une parodie : un vrai tribunal et de vraies plaidoiries pour un chien, la justice devient un spectacle.', 2),
    ('ee73e6be-be6c-551c-86e9-a957fc472d4c'::uuid, 'francais', '1re', 'Les Plaideurs, Jean Racine', 'Que produit-on au procès pour attendrir le tribunal ?', 'mcq', '["Les chiots du prévenu","Le chapon à moitié mangé","Le témoignage du cuisinier","Une lettre de la comtesse"]'::jsonb, 0, 'Faire paraître les petits de l’accusé parodie les effets pathétiques des avocats : un comique de gestes au cœur d’un procès de mots.', 3),
    ('dc7bcc64-1b10-567b-bc2c-192d78cfffaf'::uuid, 'francais', '1re', 'Les Plaideurs, Jean Racine', 'Quel type de comique naît du pastiche des plaidoiries ?', 'mcq', '["Le comique de situation","Le comique de gestes","Le comique de caractère","Le comique de mots"]'::jsonb, 3, 'Petit Jean qui perd le fil, l’Intimé qui répond en style noble et remonte « avant la naissance du monde » : la parodie de l’éloquence judiciaire est un comique de mots.', 4),
    ('9710eb29-34a7-5396-b183-8b9454c51598'::uuid, 'francais', '1re', 'Les Poètes maudits, Paul Verlaine', 'Chez quel éditeur le livre paraît-il en 1884 ?', 'mcq', '["Léon Vanier","Alphonse Lemerre","Poulet-Malassis","Michel Lévy"]'::jsonb, 0, 'Léon Vanier publie Verlaine au moment où les jeunes poètes décadents et symbolistes cherchent des modèles : le livre tombe à point.', 1),
    ('db92ffe7-8192-5a97-b02f-730d02884899'::uuid, 'francais', '1re', 'Les Poètes maudits, Paul Verlaine', 'Quel recueil de Tristan Corbière le public découvre-t-il grâce à Verlaine ?', 'mcq', '["Les Chants de Maldoror","Poèmes saturniens","Les Amours jaunes","Les Complaintes"]'::jsonb, 2, 'Le ton ironique des Amours jaunes était resté invisible : sans Verlaine, Corbière serait resté inconnu.', 2),
    ('a8515b7e-b167-5195-a1a0-c9d1e0a99dbd'::uuid, 'francais', '1re', 'Les Poètes maudits, Paul Verlaine', 'Quels jeunes poètes cherchent des modèles au moment de la parution ?', 'mcq', '["Les poètes de la Pléiade","Les surréalistes","Les romantiques de 1830","Les décadents et les symbolistes"]'::jsonb, 3, 'En 1884, décadents et symbolistes cherchent des maîtres hors des gloires officielles : Verlaine leur offre Corbière, Rimbaud et Mallarmé.', 3),
    ('34571d66-8a10-5658-9563-007a04d65648'::uuid, 'francais', '1re', 'Les Poètes maudits, Paul Verlaine', 'Quel épisode de 1873 a valu la prison à Verlaine ?', 'mcq', '["Un pamphlet contre la République","Le coup de revolver de Bruxelles","Une dette de jeu impayée","Un duel avec Mallarmé"]'::jsonb, 1, 'Au terme de sa liaison orageuse avec Rimbaud, Verlaine tire sur lui à Bruxelles et est condamné à deux ans de prison : en 1884, il est lui-même peu lu.', 4),
    ('eb7cf3f9-88d5-54e0-90fb-2608d3ea35f4'::uuid, 'francais', '1re', 'Les Précieuses ridicules, Molière', 'Que désigne la périphrase « le conseiller des grâces » ?', 'mcq', '["L’éventail","La perruque","Le miroir","Le fauteuil"]'::jsonb, 2, 'Les précieuses ridicules refusent le mot simple : le miroir devient « le conseiller des grâces », comme les fauteuils deviennent « les commodités de la conversation ».', 1),
    ('5e36865a-e1e5-5460-a2c9-758a114307f3'::uuid, 'francais', '1re', 'Les Précieuses ridicules, Molière', 'Dans quelle salle la pièce est-elle créée en novembre 1659 ?', 'mcq', '["Au Petit-Bourbon","À l’Hôtel de Bourgogne","À la Comédie-Française","Au théâtre du Marais"]'::jsonb, 0, 'La troupe de Molière, revenue à Paris après treize ans de tournées en province, joue au Petit-Bourbon : c’est la pièce qui la lance.', 2),
    ('66ffe12e-c740-52a5-bfda-3b7c8c821a0a'::uuid, 'francais', '1re', 'Les Précieuses ridicules, Molière', 'Dans quel salon la préciosité est-elle née, selon le cours ?', 'mcq', '["Celui de Mme Geoffrin","Celui de Mme du Deffand","Celui de Mme de Staël","Celui de Mme de Rambouillet"]'::jsonb, 3, 'La préciosité, née dans des salons comme celui de Mme de Rambouillet, cherche un langage raffiné : Molière n’attaque pas ce mouvement réel, mais sa caricature provinciale.', 3),
    ('32458ac8-7e61-5bb5-b624-6c3fc03e690f'::uuid, 'francais', '1re', 'Les Précieuses ridicules, Molière', 'Comment la pièce se termine-t-elle pour les faux marquis ?', 'mcq', '["Ils épousent les deux précieuses","Leurs maîtres les font bâtonner et déshabiller","Ils s’enfuient avant d’être démasqués","Gorgibus les fait jeter en prison"]'::jsonb, 1, 'La Grange et Du Croisy surviennent et dépouillent leurs valets : les précieuses découvrent qu’elles se sont extasiées devant des domestiques déguisés.', 4),
    ('86d43936-1a9c-50c5-ba19-2f0ec20279a3'::uuid, 'francais', '1re', 'Les Provinciales, Blaise Pascal', 'Sous quel pseudonyme les lettres paraissent-elles ?', 'mcq', '["Jean de Port-Royal","Louis de Montalte","Antoine de Sorbonne","Pierre de Clermont"]'::jsonb, 1, 'Publiées clandestinement sous le nom de Louis de Montalte, les lettres seront condamnées et brûlées, sans que cela empêche leur diffusion massive.', 1),
    ('e7a094b9-e065-535f-a3a1-f5232d4a344e'::uuid, 'francais', '1re', 'Les Provinciales, Blaise Pascal', 'Qui est Escobar ?', 'mcq', '["Le provincial à qui les lettres sont adressées","Un ami janséniste de Pascal","Un casuiste réel dont les ouvrages sont cités","Un docteur de la Sorbonne qui défend Arnauld"]'::jsonb, 2, 'Pascal cite les ouvrages du casuiste Escobar : les citations exactes des adversaires, retournées contre eux, sont l’une de ses armes.', 2),
    ('6568edb0-767f-5d5f-ba75-0d8c75f24e11'::uuid, 'francais', '1re', 'Les Provinciales, Blaise Pascal', 'Que fait Pascal des textes de ses adversaires ?', 'mcq', '["Il les cite exactement et les retourne contre eux","Il les résume sans jamais les citer","Il les réfute en latin pour les savants","Il les ignore pour exposer sa doctrine"]'::jsonb, 0, 'Pascal n’invente rien : il laisse le bon père jésuite exposer fièrement sa doctrine, citations à l’appui, et les textes se condamnent d’eux-mêmes.', 3),
    ('bf811361-761b-55f9-914b-948686fe2d97'::uuid, 'francais', '1re', 'Les Provinciales, Blaise Pascal', 'Que découvre-t-on dans les premières lettres, sur la querelle de la grâce ?', 'mcq', '["Que les jansénistes ont tort sur tous les points","Que le pape a déjà tranché le débat","Que la querelle ne touche que l’Espagne","Que les mots employés ne veulent rien dire de précis"]'::jsonb, 3, 'Le provincial demande naïvement qu’on lui explique les termes du débat : il découvre qu’ils n’ont pas de sens précis, et le débat savant s’effondre.', 4),
    ('d1fc1462-709e-53b0-a401-55c836dbc79c'::uuid, 'francais', '1re', 'Les Raisins de la colère, John Steinbeck', 'D’où sort Tom Joad au début du roman ?', 'mcq', '["De l’armée","De prison","Du séminaire","D’un hôpital"]'::jsonb, 1, 'Tom Joad sort de prison quand le roman commence ; à la fin, après la mort de Casy, il devient un militant.', 1),
    ('f1ca1849-9970-5447-904e-fa053afe8692'::uuid, 'francais', '1re', 'Les Raisins de la colère, John Steinbeck', 'Quel prix le roman obtient-il en 1940 ?', 'mcq', '["Le prix Goncourt","Le prix Femina","Le prix Nobel","Le prix Pulitzer"]'::jsonb, 3, 'Le roman reçoit le prix Pulitzer en 1940 ; Steinbeck obtiendra le Nobel en 1962. Le livre fut pourtant brûlé et interdit dans certains comtés à sa sortie.', 2),
    ('c009e12e-d412-5917-a6cf-9fa9001411ac'::uuid, 'francais', '1re', 'Les Raisins de la colère, John Steinbeck', 'Comment le roman est-il construit ?', 'mcq', '["Il alterne récit familial et chapitres collectifs","Il suit le journal intime de Man Joad","Il est raconté par Tom à la première personne","Il remonte le temps de la Californie à l’Oklahoma"]'::jsonb, 0, 'Les chapitres consacrés aux Joad alternent avec des chapitres collectifs qui élargissent le récit à toute une classe de migrants.', 3),
    ('a3be7400-f14c-5449-b64b-d2bd749b4002'::uuid, 'francais', '1re', 'Les Raisins de la colère, John Steinbeck', 'Quel personnage perd peu à peu son autorité au fil du voyage ?', 'mcq', '["Tom Joad","Casy","Pa Joad","Rose de Saron"]'::jsonb, 2, 'Pa Joad voit son autorité s’effacer tandis que Man Joad devient le pilier de la famille : le voyage bouleverse l’ordre de la ferme.', 4),
    ('ca5d7b62-0c92-5f40-957a-2430910ddee5'::uuid, 'francais', '1re', 'Les Rayons et les Ombres, Victor Hugo', 'Que fait le poète selon « Fonction du poète » ?', 'mcq', '["Il se retire loin des foules","Il ne chante que ses amours","Il guide le peuple et éclaire l’avenir","Il sert le roi et la cour"]'::jsonb, 2, 'Le poème qui ouvre le recueil fait du poète celui qui « voit » : un guide et un prophète, c’est le versant « rayons » du recueil.', 1),
    ('f3e75dd0-4b2d-51fa-b3a3-dd39b7881d42'::uuid, 'francais', '1re', 'Les Rayons et les Ombres, Victor Hugo', 'Lequel de ces recueils précède Les Rayons et les Ombres ?', 'mcq', '["Les Voix intérieures","Les Contemplations","La Légende des siècles","Les Châtiments"]'::jsonb, 0, 'Les Feuilles d’automne, Les Chants du crépuscule et Les Voix intérieures précèdent le recueil de 1840 ; Les Châtiments (1853), Les Contemplations et La Légende des siècles viendront après.', 2),
    ('4fd274e0-89b7-5090-99a6-c1c9a284841c'::uuid, 'francais', '1re', 'Les Rayons et les Ombres, Victor Hugo', 'Avec quels poèmes compare-t-on « Tristesse d’Olympio » ?', 'mcq', '["« Le Bateau ivre » et « Voyelles » de Rimbaud","« Le Lac » de Lamartine et « Souvenir » de Musset","« Mignonne, allons voir » et un sonnet de Du Bellay","« Le Cygne » et « L’Albatros » de Baudelaire"]'::jsonb, 1, 'Les trois poèmes traitent le même motif — le retour sur les lieux d’un amour passé — et se prêtent à une comparaison très attendue à l’oral.', 3),
    ('8d03441b-8828-53ed-b0ed-c19b325189f0'::uuid, 'francais', '1re', 'Les Rayons et les Ombres, Victor Hugo', 'Où se situe la vallée de « Tristesse d’Olympio » ?', 'mcq', '["Au bord de la mer, à Guernesey","Sur les rives de la Seine, à Villequier","Dans les Alpes, près du lac du Bourget","Près de la Bièvre, lieu de ses amours avec Juliette"]'::jsonb, 3, 'La vallée de la Bièvre garde les souvenirs de Hugo et de Juliette Drouet ; en y revenant, le poète découvre que la nature a tout oublié.', 4),
    ('dc2d4d3d-fdaf-5a51-8bcb-05df5a3383df'::uuid, 'francais', '1re', 'Les Trois Mousquetaires, Alexandre Dumas', 'En quelle année commence l’histoire ?', 'mcq', '["1572","1625","1715","1789"]'::jsonb, 1, 'Le roman s’ouvre en 1625, sous Louis XIII et Richelieu : Dumas mêle à sa fiction des faits réels comme le siège de La Rochelle.', 1),
    ('057e6d97-f74d-5eb7-bdb5-d93b54d6d14f'::uuid, 'francais', '1re', 'Les Trois Mousquetaires, Alexandre Dumas', 'Qui est Constance Bonacieux ?', 'mcq', '["La lingère de la reine, aimée de d’Artagnan","La sœur d’Athos, enlevée par Milady","L’épouse de M. de Tréville","Une espionne au service du cardinal"]'::jsonb, 0, 'Constance, lingère de la reine Anne d’Autriche, est l’amour de d’Artagnan ; Milady l’empoisonnera.', 2),
    ('1dc9ecd6-8a83-56df-930a-240375914dd6'::uuid, 'francais', '1re', 'Les Trois Mousquetaires, Alexandre Dumas', 'Quelle marque Milady porte-t-elle à l’épaule ?', 'mcq', '["Une cicatrice d’épée","Un tatouage de serpent","Une fleur de lys","Une croix rouge"]'::jsonb, 2, 'La fleur de lys était la marque au fer infligée aux condamnés : elle trahit le passé de Milady, ancienne épouse d’Athos.', 3),
    ('b83f2eeb-c961-5847-998b-abe7325f48b7'::uuid, 'francais', '1re', 'Les Trois Mousquetaires, Alexandre Dumas', 'Quelles sont les deux suites du roman ?', 'mcq', '["Le Comte de Monte-Cristo et La Reine Margot","Les Misérables et Quatrevingt-treize","Le Capitaine Fracasse et Le Bossu","Vingt ans après et Le Vicomte de Bragelonne"]'::jsonb, 3, 'Dumas retrouve ses héros vieillis dans Vingt ans après, puis dans Le Vicomte de Bragelonne.', 4),
    ('951e5c24-dc54-5811-af49-20a2295ef583'::uuid, 'francais', '1re', 'Les Trophées, José-Maria de Heredia', 'Où José-Maria de Heredia est-il né ?', 'mcq', '["En Espagne","Au Mexique","À Cuba","En Martinique"]'::jsonb, 2, 'Né à Cuba dans une plantation de café, Heredia vient étudier en France, entre à l’École des chartes et devient le disciple de Leconte de Lisle.', 1),
    ('fdee7eb6-aa55-5a3b-9588-702eb33cc847'::uuid, 'francais', '1re', 'Les Trophées, José-Maria de Heredia', 'Que se passe-t-il pour Heredia l’année qui suit la publication des Trophées ?', 'mcq', '["Il entre à l’Académie française","Il repart vivre à Cuba","Il fonde une revue symboliste","Il publie un second recueil"]'::jsonb, 0, 'Heredia entre à l’Académie française en 1894 ; Les Trophées restent pourtant son unique recueil.', 2),
    ('d35246e7-942d-514a-ba43-9828f40987a5'::uuid, 'francais', '1re', 'Les Trophées, José-Maria de Heredia', 'Que vise le Parnasse, contre l’épanchement romantique ?', 'mcq', '["La confidence","L’impersonnalité","L’engagement","La spontanéité"]'::jsonb, 1, 'Le « je » du poète disparaît derrière le tableau : le Parnasse oppose au lyrisme romantique le culte de la forme, l’érudition et des images précises.', 3),
    ('e886c849-737e-5c67-94b9-a2b055bfccac'::uuid, 'francais', '1re', 'Les Trophées, José-Maria de Heredia', 'Quel mouvement viendra bousculer la formule parnassienne ?', 'mcq', '["Le classicisme","La Pléiade","Le romantisme","Le symbolisme"]'::jsonb, 3, 'Les Trophées portent la formule parnassienne à son point de perfection — et de rigidité : c’est le symbolisme qui viendra la bousculer.', 4),
    ('512704ef-b59d-5e5e-a318-5ea429849f79'::uuid, 'francais', '1re', 'Les Vrilles de la vigne, Colette', 'Quelle signature Colette adopte-t-elle pour ce recueil ?', 'mcq', '["Willy","Colette Willy","Sido","Claudine"]'::jsonb, 1, 'Après les Claudine parus sous le nom de son mari, elle signe « Colette Willy » : une étape de son émancipation, elle s’affranchit peu à peu.', 1),
    ('0203cf64-68e2-56b1-9396-238ef332bf76'::uuid, 'francais', '1re', 'Les Vrilles de la vigne, Colette', 'En quelle année le recueil paraît-il ?', 'mcq', '["1893","1930","1908","1945"]'::jsonb, 2, 'Paru en 1908, deux ans après la séparation d’avec Willy (1906), le recueil est la parole d’une femme qui parle pour elle-même.', 2),
    ('26c71a3a-e270-55d9-b089-bf535f9996f1'::uuid, 'francais', '1re', 'Les Vrilles de la vigne, Colette', 'Sous quel parcours du bac l’œuvre est-elle étudiée avec Sido ?', 'mcq', '["La célébration du monde","Émancipations créatrices","Alchimie poétique","Les mémoires d’une âme"]'::jsonb, 0, 'Sido (1930) et Les Vrilles de la vigne forment le volume au programme, sous le parcours « la célébration du monde » : une écriture des sensations et du vivant.', 3),
    ('a29f3de9-a7ae-503e-9cc6-bcca46f70cf5'::uuid, 'francais', '1re', 'Les Vrilles de la vigne, Colette', 'Que sont « Nuit blanche », « Jour gris » et « Le Dernier Feu » ?', 'mcq', '["Des dialogues entre Toby-Chien et Kiki-la-Doucette","Des chroniques sur le music-hall","Des souvenirs d’enfance en Puisaye","Des textes intimes adressés à une femme aimée"]'::jsonb, 3, 'Ces textes intimes, adressés à une femme aimée, côtoient dans le recueil les dialogues d’animaux et les chroniques.', 4),
    ('1a37a108-bb60-5e00-9d62-ad747cb5dbb4'::uuid, 'francais', '1re', 'Les Yeux d’Elsa, Louis Aragon', 'Quel titre latin porte la préface du recueil ?', 'mcq', '["Carpe diem","Arma virumque cano","Ut pictura poesis","Memento mori"]'::jsonb, 1, '« Arma virumque cano » (« je chante les armes et l’homme ») sont les premiers mots de l’Énéide de Virgile : dans cette préface, Aragon défend le retour à la rime et au vers régulier.', 1),
    ('0ec61d92-a649-5a39-85a2-82dcf15474f9'::uuid, 'francais', '1re', 'Les Yeux d’Elsa, Louis Aragon', 'Pourquoi, selon Aragon, le vers régulier sert-il la Résistance ?', 'mcq', '["Il plaît davantage aux censeurs de Vichy","Il coûte moins cher à imprimer","Il est réservé aux lecteurs savants","Il se retient par cœur, se transmet et se chante"]'::jsonb, 3, 'Une poésie rimée se mémorise : elle peut circuler clandestinement et se chanter. Le vers régulier n’est pas un retour en arrière, mais une arme de transmission.', 2),
    ('669bfefc-0d7a-5b42-9deb-cab5135a1284'::uuid, 'francais', '1re', 'Les Yeux d’Elsa, Louis Aragon', 'Avec quel poète Aragon est-il considéré comme le grand poète de la Résistance ?', 'mcq', '["Paul Éluard","Guillaume Apollinaire","Charles Péguy","Paul Valéry"]'::jsonb, 0, 'Aragon et Éluard, tous deux venus du surréalisme, sont les grandes voix poétiques de la Résistance.', 3),
    ('de3f7f59-103a-511c-ba18-11c4e6f9b4ff'::uuid, 'francais', '1re', 'Les Yeux d’Elsa, Louis Aragon', 'Qui a mis en musique des poèmes d’Aragon, selon le cours ?', 'mcq', '["Debussy, Ravel et Satie","Lully, Rameau et Couperin","Ferré, Ferrat et Brassens","Berlioz, Bizet et Gounod"]'::jsonb, 2, 'Mis en musique par Léo Ferré, Jean Ferrat et Georges Brassens, les poèmes d’Aragon comptent parmi les plus connus du XXe siècle : la forme régulière se chante.', 4),
    ('b49d44a6-148f-59c6-8969-c88faf1af8a0'::uuid, 'francais', '1re', 'Lettre à d’Alembert sur les spectacles, Jean-Jacques Rousseau', 'Où Rousseau vit-il retiré quand il écrit la Lettre, en 1758 ?', 'mcq', '["À Ferney","À Montmorency","À Genève","À Ermenonville"]'::jsonb, 1, 'Retiré à Montmorency après sa brouille avec Diderot et Mme d’Épinay, Rousseau répond à l’article « Genève » de l’Encyclopédie.', 1),
    ('0bd0b4b8-eba8-5204-9d44-ddb845bb43a6'::uuid, 'francais', '1re', 'Lettre à d’Alembert sur les spectacles, Jean-Jacques Rousseau', 'À quel titre Rousseau prend-il la parole pour répondre à d’Alembert ?', 'mcq', '["Comme pasteur de Genève","Comme membre de l’Académie","Comme citoyen de Genève","Comme ami de Voltaire"]'::jsonb, 2, 'Citoyen de Genève, Rousseau défend les mœurs simples de sa patrie contre le projet d’y ouvrir un théâtre.', 2),
    ('fa8f80a8-52d4-5a30-9e92-efa155bce944'::uuid, 'francais', '1re', 'Lettre à d’Alembert sur les spectacles, Jean-Jacques Rousseau', 'Pourquoi Rousseau condamne-t-il Le Misanthrope ?', 'mcq', '["Parce que Molière y fait rire d’Alceste, l’homme vertueux","Parce que la pièce se moque du roi et de la cour","Parce que Molière y défend l’hypocrisie religieuse","Parce que la pièce est trop longue et trop savante"]'::jsonb, 0, 'Pour Rousseau, le théâtre rend le vice aimable : en faisant rire d’Alceste, Molière ridiculise la vertu elle-même.', 3),
    ('569f7f23-ab11-58d4-b6d4-c3ef1815a369'::uuid, 'francais', '1re', 'Lettre à d’Alembert sur les spectacles, Jean-Jacques Rousseau', 'Selon le cours, quelles idées de Rousseau trouve-t-on en germe dans la Lettre ?', 'mcq', '["Le goût du luxe et l’éloge des arts de cour","La foi dans le progrès des sciences et des arts","La défense de la monarchie absolue","La méfiance envers la représentation, la transparence"]'::jsonb, 3, 'Méfiance envers la représentation, éloge de la transparence, préférence pour la communauté sur le spectacle : toute la pensée de Rousseau s’y annonce.', 4),
    ('6542b18a-31a0-5e03-8101-dd522c2123ec'::uuid, 'francais', '1re', 'Lettres d’une Péruvienne, Françoise de Graffigny', 'En quelle année le roman paraît-il ?', 'mcq', '["1721","1747","1762","1789"]'::jsonb, 1, 'Publié en 1747, le roman s’inscrit dans la lignée des Lettres persanes (1721) : une étrangère décrit les usages français.', 1),
    ('770fc77b-ef72-53f2-8b6b-2af46b58df34'::uuid, 'francais', '1re', 'Lettres d’une Péruvienne, Françoise de Graffigny', 'Quand Zilia est-elle enlevée par les conquistadors ?', 'mcq', '["Le jour de ses noces avec Aza","Pendant un voyage en Espagne","Le jour de son couronnement","Pendant une révolte contre son père"]'::jsonb, 0, 'Enlevée le jour même de ses noces avec Aza, puis capturée en mer par des Français, Zilia arrive en France sans en connaître ni la langue ni les usages.', 2),
    ('5c3dcdc6-4ca2-520a-9200-9e498799a7f2'::uuid, 'francais', '1re', 'Lettres d’une Péruvienne, Françoise de Graffigny', 'Qu’est devenu Aza quand Zilia le retrouve ?', 'mcq', '["Il est mort en captivité","Il est devenu chevalier français","Il s’est converti et va épouser une Espagnole","Il est resté fidèle et l’attend au Pérou"]'::jsonb, 2, 'Aza, converti, va épouser une Espagnole ; Zilia refusera aussi Déterville et choisira l’étude, l’amitié et l’indépendance.', 3),
    ('4f4916dd-9f74-51ad-b2d6-51691373200a'::uuid, 'francais', '1re', 'Lettres d’une Péruvienne, Françoise de Graffigny', 'Selon le cours, que représente l’écriture pour Zilia ?', 'mcq', '["Un simple passe-temps de salon","Un moyen de plaire à Déterville","Un devoir imposé par les Incas","Survivre, puis comprendre, enfin exister"]'::jsonb, 3, 'Des quipus au français appris peu à peu, écrire permet à Zilia de survivre à l’exil, de comprendre le monde nouveau, puis d’exister comme sujet libre.', 4),
    ('a03bd6e2-18ca-5297-91a9-22302899fb02'::uuid, 'francais', '1re', 'Lettres de mon moulin, Alphonse Daudet', 'À qui la lettre de « La Chèvre de M. Seguin » est-elle adressée ?', 'mcq', '["Au duc de Morny","Au poète Gringoire","Au poète Mistral","À maître Cornille"]'::jsonb, 1, 'Le conte est un apologue destiné à Gringoire, qui refuse une place de chroniqueur : comme la chèvre, il doit choisir entre la liberté et la sécurité.', 1),
    ('e690e1cc-e707-562a-a99f-ef737e62a3b1'::uuid, 'francais', '1re', 'Lettres de mon moulin, Alphonse Daudet', 'Combien de temps la mule du pape garde-t-elle son coup de pied ?', 'mcq', '["Sept jours","Un an","Sept ans","Toute sa vie"]'::jsonb, 2, 'La mule rancunière garde son coup de pied sept ans avant de le lâcher : un conte plein d’humour, avec la saveur d’une légende provençale.', 2),
    ('954199bc-c28c-5515-89ba-aecd60cf5873'::uuid, 'francais', '1re', 'Lettres de mon moulin, Alphonse Daudet', 'Daudet a réellement possédé le moulin d’où le narrateur écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un dispositif fictif : Daudet vivait à Paris et n’a jamais possédé ce moulin de Fontvieille, où il séjournait chez des cousins.', 3),
    ('914ba36d-d475-5ae9-bc7b-ee613603f1ba'::uuid, 'francais', '1re', 'Lettres de mon moulin, Alphonse Daudet', 'Au service de qui Daudet travaille-t-il à Paris ?', 'mcq', '["Du duc de Morny, demi-frère de Napoléon III","De Victor Hugo, alors exilé à Guernesey","D’un éditeur de journaux provençaux","Du préfet du Gard, à Nîmes"]'::jsonb, 0, 'Monté à Paris pauvre, à dix-sept ans, Daudet devient secrétaire du duc de Morny, demi-frère de Napoléon III.', 4),
    ('68f7da69-b28d-5f91-946a-42ac1e4fcc7a'::uuid, 'francais', '1re', 'Lettres persanes, Montesquieu', 'Sous quelle période le livre paraît-il ?', 'mcq', '["La Fronde","La Régence","La Terreur","La Restauration"]'::jsonb, 1, 'En 1721, sous la Régence qui suit la mort de Louis XIV, les esprits se libèrent : la satire peut circuler, anonyme et publiée à l’étranger.', 1),
    ('0d611b02-063e-530f-8b0c-982ddf2115bf'::uuid, 'francais', '1re', 'Lettres persanes, Montesquieu', 'Que fait croire le pape, « autre magicien » selon Rica ?', 'mcq', '["Que le papier est de l’argent","Que le roi ne meurt jamais","Que trois ne font qu’un","Que la terre est immobile"]'::jsonb, 2, 'Le roi fait croire que le papier est de l’argent, le pape que trois ne font qu’un : décrits par un étranger, pouvoirs et dogmes deviennent des tours de magie.', 2),
    ('f963af80-04ae-5b6e-bae1-61b8f1f1c880'::uuid, 'francais', '1re', 'Lettres persanes, Montesquieu', 'Quelle grande œuvre de Montesquieu le roman annonce-t-il ?', 'mcq', '["Le Contrat social","Candide","L’Encyclopédie","De l’esprit des lois"]'::jsonb, 3, 'De l’esprit des lois (1748) prolonge la réflexion des Troglodytes et du sérail : quelles institutions rendent la liberté possible ?', 3),
    ('9558e310-22d2-5ebf-88af-d0b0824cd3d3'::uuid, 'francais', '1re', 'Lettres persanes, Montesquieu', 'Quelle traduction avait lancé la mode orientale en France ?', 'mcq', '["Les Mille et Une Nuits","Les Fables d’Ésope","L’Odyssée d’Homère","Les Vies de Plutarque"]'::jsonb, 0, 'La traduction des Mille et Une Nuits avait mis l’Orient à la mode : Montesquieu s’en sert pour déguiser sa satire.', 4),
    ('dd96f14c-f5d4-5af9-806a-30c45120b23e'::uuid, 'francais', '1re', 'Lettres, Madame de Sévigné', 'En quelle année Madame de Grignan part-elle vivre en Provence ?', 'mcq', '["1651","1671","1696","1725"]'::jsonb, 1, 'Le départ de sa fille en 1671 déclenche la correspondance et son ton : un amour maternel exalté et douloureux.', 1),
    ('7f929978-d776-55ac-8e02-5b30a6c4f277'::uuid, 'francais', '1re', 'Lettres, Madame de Sévigné', 'Où se trouve le domaine breton de Madame de Sévigné ?', 'mcq', '["À Grignan","À Chantilly","Aux Rochers","À Versailles"]'::jsonb, 2, 'Aux Rochers, en Bretagne, elle raconte la vie quotidienne — les foins, les paysans, le temps qu’il fait — aussi vivement que la cour.', 2),
    ('b4de2641-4d82-5f1f-bb82-3c0e5c6a3f90'::uuid, 'francais', '1re', 'Lettres, Madame de Sévigné', 'Quel romancier du XXe siècle a beaucoup cité ses lettres ?', 'mcq', '["Marcel Proust","Albert Camus","Louis-Ferdinand Céline","Jean-Paul Sartre"]'::jsonb, 0, 'Proust l’a beaucoup citée : le XIXe et le XXe siècle ont admiré chez elle la naissance d’une écriture de l’intime.', 3),
    ('60a868f4-373f-5b96-b103-4b5ccccc356b'::uuid, 'francais', '1re', 'Lettres, Madame de Sévigné', 'Qui est Bussy-Rabutin dans la correspondance ?', 'mcq', '["Son mari, tué en duel","Son gendre, lieutenant général en Provence","Le maître d’hôtel qui se tue pour la marée","Son cousin, esprit brillant et exilé"]'::jsonb, 3, 'Bussy-Rabutin est un cousin brillant tenu en exil ; c’est un autre cousin, Coulanges, qui reçoit la lettre sur le mariage de Lauzun.', 4),
    ('43b713e1-59fa-59a5-8b64-3602f0a86eca'::uuid, 'francais', '1re', 'Lorenzaccio, Alfred de Musset', 'Quand la pièce est-elle créée sur scène ?', 'mcq', '["En 1834, dès sa publication","En 1896, avec Sarah Bernhardt en Lorenzo","En 1830, à la place de La Nuit vénitienne","En 1857, à la mort de Musset"]'::jsonb, 1, 'Trop vaste pour la scène de 1834 — trente-neuf scènes, une quarantaine de personnages —, la pièce attend 1896 : Lorenzo y est joué par Sarah Bernhardt.', 1),
    ('352d57be-6215-5ec2-9624-0d56300160af'::uuid, 'francais', '1re', 'Lorenzaccio, Alfred de Musset', 'Dans quel ensemble Lorenzaccio paraît-il en 1834 ?', 'mcq', '["Les Nuits","La Confession d’un enfant du siècle","Un spectacle dans un fauteuil","Contes d’Espagne et d’Italie"]'::jsonb, 2, 'Après l’échec de La Nuit vénitienne, sifflée en 1830, Musset écrit un théâtre à lire : Un spectacle dans un fauteuil.', 2),
    ('974cf542-e784-5a1a-8da1-f3bead03b8f6'::uuid, 'francais', '1re', 'Lorenzaccio, Alfred de Musset', 'Que tente la marquise Cibo auprès du duc ?', 'mcq', '["Le convertir à la vertu","L’empoisonner pour le pape","Le réconcilier avec Lorenzo","Le faire fuir de Florence"]'::jsonb, 0, 'La marquise Cibo veut ramener Alexandre à la vertu : une autre façon, vaine elle aussi, de changer le tyran.', 3),
    ('bea45b64-de71-5da3-8218-db4b531606ba'::uuid, 'francais', '1re', 'Lorenzaccio, Alfred de Musset', 'Comment finit Lorenzo ?', 'mcq', '["Il est élu duc de Florence à la place d’Alexandre","Il est acclamé par les républicains de Florence","Il se retire dans un couvent près de Rome","Il est assassiné à Venise pour la prime sur sa tête"]'::jsonb, 3, 'Réfugié à Venise, Lorenzo est tué pour la prime mise sur sa tête : son acte n’a rien changé, Côme règne déjà à Florence.', 4),
    ('bae70b6e-e5fa-577f-b922-0fb577353975'::uuid, 'francais', '1re', 'Lucien Leuwen, Stendhal', 'Dans quelle ville Lucien est-il envoyé comme sous-lieutenant ?', 'mcq', '["Verrières","Nancy","Grenoble","Besançon"]'::jsonb, 1, 'À Nancy, Lucien découvre des salons de province aussi féroces que Verrières dans Le Rouge et le Noir, et rencontre Madame de Chasteller.', 1),
    ('9ab19f21-ed0d-5ddc-b0f8-a73f24b961a0'::uuid, 'francais', '1re', 'Lucien Leuwen, Stendhal', 'Quel est le vrai nom de Stendhal ?', 'mcq', '["Henri Beyle","Henri Brulard","Julien Sorel","Lucien Leuwen"]'::jsonb, 0, 'Stendhal est le pseudonyme d’Henri Beyle ; Henri Brulard est le nom qu’il se donne dans son autobiographie.', 2),
    ('6f19adcc-47f8-5037-84c7-ee02b30ea06b'::uuid, 'francais', '1re', 'Lucien Leuwen, Stendhal', 'Quelle fonction Stendhal occupe-t-il quand il écrit le roman ?', 'mcq', '["Préfet de la Meurthe","Député de l’opposition","Banquier à Paris","Consul de France à Civitavecchia"]'::jsonb, 3, 'Consul à Civitavecchia, donc fonctionnaire du régime de Louis-Philippe, Stendhal ne peut guère publier une satire de ce régime : le roman reste inachevé.', 3),
    ('e5df5ea0-ef53-50d2-8b54-3ebfe9b4ebe5'::uuid, 'francais', '1re', 'Lucien Leuwen, Stendhal', 'Qu’est-ce que Le Chasseur vert ?', 'mcq', '["Le surnom de Lucien au régiment","Le journal républicain de Nancy","Le titre parfois donné à la première partie","La suite du roman, jamais écrite"]'::jsonb, 2, 'La première partie, à Nancy, est parfois appelée Le Chasseur vert, du nom d’un café près de la ville.', 4),
    ('b791a8c6-6dd8-53df-a03d-97c44612c22e'::uuid, 'francais', '1re', 'Madame Bovary, Gustave Flaubert', 'Quel procédé, généralisé dans le roman, fait entendre la voix d’Emma à l’intérieur du récit ?', 'mcq', '["Le discours direct entre guillemets","Le discours indirect libre","Le récit à la première personne","Le journal intime d’Emma"]'::jsonb, 1, 'Le discours indirect libre mêle la voix du narrateur et les pensées d’Emma sans guillemets ni verbe introducteur : Flaubert montre ses rêves sans les commenter.', 1),
    ('61ad5ccb-aa4e-5bdb-af41-d7f627da6de8'::uuid, 'francais', '1re', 'Madame Bovary, Gustave Flaubert', 'Qu’obtient le pharmacien Homais à la toute fin du roman ?', 'mcq', '["Un siège de député","L’héritage des Bovary","La Légion d’honneur","La mairie de Yonville"]'::jsonb, 2, 'C’est l’ironie finale : Homais, symbole de la bêtise progressiste, triomphe quand tous les autres sont brisés.', 2),
    ('73e92a10-f87b-5527-a136-1c3de129ff1a'::uuid, 'francais', '1re', 'Madame Bovary, Gustave Flaubert', 'Que devient Berthe, la fille d’Emma, après la mort de ses parents ?', 'mcq', '["Elle est recueillie par Homais","Elle entre au couvent comme sa mère","Elle épouse Justin, l’apprenti","Elle est placée dans une filature"]'::jsonb, 3, 'Négligée par sa mère, Berthe finit ouvrière : la chute des Bovary se prolonge jusqu’à l’enfant.', 3),
    ('da8a7a97-ce3f-564b-b2c3-0e1613ea5ba0'::uuid, 'francais', '1re', 'Madame Bovary, Gustave Flaubert', 'Pourquoi Flaubert relit-il chaque phrase à voix haute dans son « gueuloir » ?', 'mcq', '["Pour éprouver le rythme et le son de la phrase","Pour la dicter à un secrétaire","Pour la répéter avant une lecture publique","Pour la préparer à son procès"]'::jsonb, 0, 'Le style travaillé jusqu’à l’obsession est un trait du réalisme de Flaubert : il met près de cinq ans à écrire le roman.', 4),
    ('440c71af-3e29-5518-b57b-958362fd3b06'::uuid, 'francais', '1re', 'Mademoiselle de Maupin, Théophile Gautier', 'À quel mouvement poétique la préface de Mademoiselle de Maupin ouvre-t-elle la voie ?', 'mcq', '["Le symbolisme","Le surréalisme","Le Parnasse","Le naturalisme"]'::jsonb, 2, 'En défendant une beauté inutile et autonome, Gautier annonce le Parnasse ; Baudelaire lui dédiera Les Fleurs du mal.', 1),
    ('ff5576fb-3649-5c9c-8b21-3ca9dc9a6fa3'::uuid, 'francais', '1re', 'Mademoiselle de Maupin, Théophile Gautier', 'Pourquoi Madeleine de Maupin se déguise-t-elle en homme ?', 'mcq', '["Pour voir les hommes tels qu’ils sont entre eux","Pour fuir un mariage que sa famille lui impose","Pour pouvoir jouer sur une scène de théâtre","Pour provoquer d’Albert en duel incognito"]'::jsonb, 0, 'Avant de choisir un amant, elle veut observer les hommes sans leur masque de séducteurs : le travestissement est une enquête sur l’amour.', 2),
    ('fb0b4bdf-863c-582f-b851-dc0b139a3706'::uuid, 'francais', '1re', 'Mademoiselle de Maupin, Théophile Gautier', 'Qui est Rosette dans le roman ?', 'mcq', '["La cousine de Madeleine, restée au couvent","La maîtresse de d’Albert, éprise de Théodore","L’amie à qui Madeleine écrit ses lettres","Une comédienne engagée pour la pièce"]'::jsonb, 1, 'Rosette aime Théodore sans savoir que c’est une femme : le déguisement trouble tous les désirs. L’amie des lettres, c’est Graciosa.', 3),
    ('48238b3f-70e1-59f2-ab1c-18b3dd6cd83d'::uuid, 'francais', '1re', 'Mademoiselle de Maupin, Théophile Gautier', 'Que cherche d’Albert au début du roman ?', 'mcq', '["Une riche héritière à épouser vite","Une place enviée à la cour du roi","Un sujet neuf pour une pièce de théâtre","Une beauté idéale que nulle femme ne lui offre"]'::jsonb, 3, 'Aucune femme réelle ne satisfait son idéal : c’est pourquoi le cavalier Théodore le trouble tant.', 4),
    ('581c5cdf-b657-5159-b9d4-46ca9f026443'::uuid, 'francais', '1re', 'Mangeclous, Albert Cohen', 'Sur quelle île grecque Albert Cohen est-il né ?', 'mcq', '["Céphalonie","Corfou","Crète","Rhodes"]'::jsonb, 1, 'Né à Corfou en 1895, il grandit à Marseille ; il donne à ses Valeureux une autre île grecque, Céphalonie.', 1),
    ('7a8f8e9e-4aa9-5c1a-9872-aac28c42bbe0'::uuid, 'francais', '1re', 'Mangeclous, Albert Cohen', 'Lequel des cinq Valeureux incarne l’avarice ?', 'mcq', '["Saltiel","Salomon","Michaël","Mattathias"]'::jsonb, 3, 'Chaque cousin a son trait : Saltiel le doux, Salomon le naïf, Michaël le beau, Mattathias l’avare — et Mangeclous le menteur de génie.', 2),
    ('b1f3d6c9-16fc-5167-880f-4dbd0c94ecdf'::uuid, 'francais', '1re', 'Mangeclous, Albert Cohen', 'Quel titre Mangeclous se fait-il donner, entre autres ?', 'mcq', '["Le Bey des Menteurs","Le Prince des Poètes","Le Roi des Truands","Le Pacha des Juges"]'::jsonb, 0, 'Sa parole intarissable et ses mensonges grandioses font de lui l’un des grands personnages comiques du XXe siècle.', 3),
    ('559ce480-6d2b-557f-8fd0-503bb8986cd5'::uuid, 'francais', '1re', 'Mangeclous, Albert Cohen', 'Dans quel but Mangeclous se dit-il malade et mourant ?', 'mcq', '["Pour échapper à un procès","Pour préparer son héritage","Pour attendrir et soutirer","Pour éviter le voyage"]'::jsonb, 2, 'C’est une de ses comédies : l’exagération pathétique sert à obtenir de l’argent ou des faveurs.', 4),
    ('461f76f2-c819-58c3-8841-6bfcab172442'::uuid, 'francais', '1re', 'Manifeste du Surréalisme, André Breton', 'De quel recueil le Manifeste de 1924 est-il d’abord la préface ?', 'mcq', '["Les Champs magnétiques","Poisson soluble","Nadja","Le Paysan de Paris"]'::jsonb, 1, 'Poisson soluble rassemble des textes automatiques : le manifeste en donne la théorie, le recueil la pratique.', 1),
    ('ac98a1a8-57ee-51f5-a486-e2138bf12fc7'::uuid, 'francais', '1re', 'Manifeste du Surréalisme, André Breton', 'Avec qui Breton a-t-il écrit Les Champs magnétiques (1919), première expérience d’écriture automatique ?', 'mcq', '["Paul Éluard","Louis Aragon","Robert Desnos","Philippe Soupault"]'::jsonb, 3, 'Breton et Soupault ont écrit ensemble ces textes automatiques cinq ans avant le Manifeste.', 2),
    ('49135b27-a4c4-5611-a71e-7f51c776c504'::uuid, 'francais', '1re', 'Manifeste du Surréalisme, André Breton', 'Lequel de ces écrivains le manifeste revendique-t-il comme précurseur ?', 'mcq', '["Jarry","Boileau","Zola","Malherbe"]'::jsonb, 0, 'Sade, Lautréamont, Rimbaud et Jarry sont les ancêtres revendiqués : un manifeste se donne toujours une lignée.', 3),
    ('1e67ed32-5fec-5d12-8205-5a9c76c74d4c'::uuid, 'francais', '1re', 'Manifeste du Surréalisme, André Breton', 'Que veut Breton après l’aventure de Dada ?', 'mcq', '["Un retour aux formes classiques","Une école réservée à la peinture","Un mouvement enfin constructif","Un simple prolongement du scandale"]'::jsonb, 2, 'Dada démolissait ; le surréalisme veut un programme positif : écriture automatique, rêve, image, merveilleux.', 4),
    ('361eaf7b-0451-5bd9-bcc4-a6f27b17df00'::uuid, 'francais', '1re', 'Manon des sources, Marcel Pagnol', 'Sous quel titre Pagnol réunit-il Jean de Florette et Manon des sources ?', 'mcq', '["Le Temps des secrets","La Gloire de mon père","L’Eau des collines","Marius"]'::jsonb, 2, 'Après le film de 1952, Pagnol écrit l’histoire complète en deux romans, réunis en 1963 sous ce titre.', 1),
    ('3a9b5433-3635-5b1e-b8de-2c94baf01c2d'::uuid, 'francais', '1re', 'Manon des sources, Marcel Pagnol', 'À qui le Papet lègue-t-il ses biens avant de mourir ?', 'mcq', '["À Manon","Au village des Bastides","À l’Église","À l’instituteur Bernard"]'::jsonb, 0, 'Il découvre qu’il a causé la perte de son propre fils : il laisse tout à la fille de Jean.', 2),
    ('a0e60457-f3e3-50c6-82a2-46bb576c513b'::uuid, 'francais', '1re', 'Manon des sources, Marcel Pagnol', 'Quel rôle le cours donne-t-il au village dans le drame ?', 'mcq', '["Un témoin innocent et ignorant","Le vengeur de Jean de Florette","Un simple décor provençal","Un chœur complice par son silence"]'::jsonb, 3, 'Comme le chœur d’une tragédie, le village commente ; complice par son silence, il est puni collectivement par la soif.', 3),
    ('117483a7-1d50-503d-8f76-1729406af4af'::uuid, 'francais', '1re', 'Manon des sources, Marcel Pagnol', 'Dans quelle ville de Provence Marcel Pagnol est-il né ?', 'mcq', '["Marseille","Aubagne","Aix-en-Provence","Avignon"]'::jsonb, 1, 'Né à Aubagne en 1895, il a parcouru enfant les collines qui servent de décor au roman.', 4),
    ('92eb513c-5b87-5971-a5fc-15586c83adfc'::uuid, 'francais', '1re', 'Manon Lescaut, abbé Prévost', 'En quelle année paraît la version corrigée du roman, après sa saisie pour immoralité ?', 'mcq', '["1753","1731","1715","1789"]'::jsonb, 0, 'Paru en 1731, saisi pour immoralité, le roman est réédité et corrigé en 1753.', 1),
    ('187e97f2-0736-5eee-874c-a2bda97b07ec'::uuid, 'francais', '1re', 'Manon Lescaut, abbé Prévost', 'Qui est Lescaut dans le roman ?', 'mcq', '["Le père sévère de Des Grieux","L’ami fidèle et moraliste","Le frère de Manon, joueur et profiteur","Le gouverneur de la Louisiane"]'::jsonb, 2, 'Lescaut entraîne le couple dans la vie de jeu ; l’ami fidèle, voix de la morale, c’est Tiberge.', 2),
    ('a36cd1e3-2918-5b5d-9352-e1f82849f757'::uuid, 'francais', '1re', 'Manon Lescaut, abbé Prévost', 'Où Des Grieux et Manon sont-ils enfermés ?', 'mcq', '["Tous deux à la Bastille","Lui à Saint-Sulpice, elle au couvent","Tous deux dans une prison d’Amiens","Lui à Saint-Lazare, elle à l’Hôpital"]'::jsonb, 3, 'Après les escroqueries contre G… M…, ils sont emprisonnés séparément, puis s’évadent.', 3),
    ('f40f4a83-6252-5129-bb6d-0677e82ce09b'::uuid, 'francais', '1re', 'Manon Lescaut, abbé Prévost', 'Le rythme du roman, lent et réfléchi, laisse au lecteur le temps de juger les personnages.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Évasions, duels, larmes, exil : l’accélération constante ne laisse jamais le temps de juger, et le narrateur cherche à faire comprendre plus qu’à faire condamner.', 4),
    ('2bf88b05-6cb0-56f7-a860-652c748a506d'::uuid, 'francais', '1re', 'Méditations poétiques, Alphonse de Lamartine', 'Combien de poèmes compte le recueil publié en 1820 ?', 'mcq', '["Douze","Vingt-quatre","Quarante-deux","Cent"]'::jsonb, 1, 'Un mince recueil de vingt-quatre poèmes, au succès immédiat : on y voit l’acte de naissance du romantisme en poésie.', 1),
    ('f2f061ba-1e8d-53e7-9c59-1015fbb6ebba'::uuid, 'francais', '1re', 'Méditations poétiques, Alphonse de Lamartine', 'Au bord de quel lac le poète revient-il seul dans « Le Lac » ?', 'mcq', '["Le lac Léman","Le lac d’Annecy","Le lac du Bourget","Le lac de Côme"]'::jsonb, 2, 'C’est au lac du Bourget, près d’Aix-les-Bains, qu’il avait rencontré Julie Charles en 1816.', 2),
    ('d5efaeee-30ff-5ab1-b708-21d898f303c4'::uuid, 'francais', '1re', 'Méditations poétiques, Alphonse de Lamartine', 'Quelle fonction Lamartine occupe-t-il en 1848 ?', 'mcq', '["Président de la IIe République","Ambassadeur de France à Rome","Préfet de Saône-et-Loire","Ministre des Affaires étrangères"]'::jsonb, 3, 'Il est ministre des Affaires étrangères du gouvernement provisoire : le poète devient un homme politique majeur.', 3),
    ('05bbac27-d165-5ecf-80a9-bba410ed6221'::uuid, 'francais', '1re', 'Méditations poétiques, Alphonse de Lamartine', 'Qu’est-ce qui est neuf dans le « je » lyrique des Méditations ?', 'mcq', '["Il s’expose directement, sans masque mythologique","Il s’efface derrière des tableaux objectifs","Il ne parle qu’au nom de la nation","Il emprunte le masque d’un berger antique"]'::jsonb, 0, 'Le poète dit son deuil sans détour : la nouveauté tient au ton, car le vers reste classique de facture.', 4),
    ('5cd00e6d-35c0-5b3d-996a-d1946ff56b8b'::uuid, 'francais', '1re', 'Mémoires d’Hadrien, Marguerite Yourcenar', 'Comment le cours caractérise-t-il la prose de Yourcenar ?', 'mcq', '["Ample, de rythme latin, aphoristique","Familière, proche de l’oral","Hachée, presque sans ponctuation","Sèche, faite de listes de faits"]'::jsonb, 0, 'Des phrases amples et des maximes : la voix d’un empereur lettré qui médite sur le pouvoir et la mort.', 1),
    ('8bef4034-fc03-5c44-9ac2-b89c6a40d012'::uuid, 'francais', '1re', 'Mémoires d’Hadrien, Marguerite Yourcenar', 'Combien de sections compte le livre, et comment sont-elles titrées ?', 'mcq', '["Trois, sans aucun titre","Douze, aux titres grecs","Six, aux titres latins","Vingt-quatre, numérotées"]'::jsonb, 2, 'La première, Animula vagula blandula, reprend les premiers mots du poème que la tradition attribue à Hadrien mourant.', 2),
    ('99d06f22-ca99-5614-8dfd-cc84fa968c19'::uuid, 'francais', '1re', 'Mémoires d’Hadrien, Marguerite Yourcenar', 'Qui est Plotine ?', 'mcq', '["La mère du jeune Antinoüs","L’épouse de Trajan, protectrice d’Hadrien","La sœur aînée d’Hadrien","La femme de Marc Aurèle"]'::jsonb, 1, 'Amie et protectrice d’Hadrien, elle est l’épouse de son prédécesseur, le conquérant Trajan.', 3),
    ('15239f2d-bc04-520f-97af-ec56fd40d9cc'::uuid, 'francais', '1re', 'Mémoires d’Hadrien, Marguerite Yourcenar', 'Parmi ces monuments, lequel Hadrien fait-il bâtir ?', 'mcq', '["Le Colisée","L’arc de Constantin","Le forum de Trajan","La Villa Adriana"]'::jsonb, 3, 'Bâtisseur, il restaure Athènes et élève la Villa Adriana et le Panthéon : l’art et la paix plutôt que la conquête.', 4),
    ('cc724909-1a05-573c-81a8-4385f3fc6254'::uuid, 'francais', '1re', 'Mémoires d’outre-tombe, François-René de Chateaubriand', 'Sur combien de temps Chateaubriand écrit-il les quarante-deux livres de l’œuvre ?', 'mcq', '["Environ un an","Environ cinq ans","Plus de trente ans","Près de dix ans"]'::jsonb, 2, 'C’est l’œuvre de toute une existence, publiée après sa mort, en 1849-1850.', 1),
    ('c2d07a7c-7ef2-5cbc-8126-8f6c1a2176c9'::uuid, 'francais', '1re', 'Mémoires d’outre-tombe, François-René de Chateaubriand', 'Qui est Lucile dans les Mémoires ?', 'mcq', '["Sa mère, pieuse et mélancolique","Sa sœur, tendre et fragile","Une jeune Américaine de 1791","Une émigrée rencontrée à Londres"]'::jsonb, 1, 'Lucile est la compagne de l’enfance à Combourg, auprès d’un père taciturne et redouté.', 2),
    ('c5849161-daef-5f89-b4d4-e9e5e8258352'::uuid, 'francais', '1re', 'Mémoires d’outre-tombe, François-René de Chateaubriand', 'Par quelle image Chateaubriand dit-il sa place entre deux époques ?', 'mcq', '["Comme au sommet d’une montagne","Comme au milieu d’un naufrage","Comme au seuil d’une maison","Comme au confluent de deux fleuves"]'::jsonb, 3, '« Je me suis rencontré entre les deux siècles comme au confluent de deux fleuves » : né sous l’Ancien Régime, il traverse tout le siècle nouveau.', 3),
    ('640a7b90-f66f-5e36-ac73-41893af179aa'::uuid, 'francais', '1re', 'Mémoires d’outre-tombe, François-René de Chateaubriand', 'Dans les Mémoires, le « je » reste purement intime : l’histoire du siècle n’y entre pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le « je » est double, intime et historique : l’autobiographie devient témoignage sur la Révolution, l’Empire et la Restauration.', 4),
    ('52d0a29e-a340-5c4a-9bea-80545e85d8c5'::uuid, 'francais', '1re', 'Mémoires de guerre, Tome III : Le Salut, 1944-1946, Charles de Gaulle', 'En quelle année paraît Le Salut ?', 'mcq', '["1946","1954","1959","1970"]'::jsonb, 2, 'Il paraît en 1959, l’année où de Gaulle devient président de la Ve République.', 1),
    ('0884e61c-9fbc-5846-aea4-a46969b2a120'::uuid, 'francais', '1re', 'Mémoires de guerre, Tome III : Le Salut, 1944-1946, Charles de Gaulle', 'Quels sont les titres des deux premiers tomes des Mémoires de guerre ?', 'mcq', '["Le Fil de l’épée et L’Appel","L’Appel et L’Unité","L’Épreuve et La Victoire","L’Exil et Le Retour"]'::jsonb, 1, 'L’Appel, L’Unité, Le Salut : le troisième et dernier tome s’achève sur la démission de janvier 1946.', 2),
    ('52ea7618-a646-5aa2-8557-5541b74ac62d'::uuid, 'francais', '1re', 'Mémoires de guerre, Tome III : Le Salut, 1944-1946, Charles de Gaulle', 'Quel rôle les partis jouent-ils dans le récit ?', 'mcq', '["Des alliés fidèles jusqu’au bout","Le moteur des réformes de 1945","Des acteurs absents du récit","L’obstacle qui le pousse à partir"]'::jsonb, 3, 'Face aux partis, de Gaulle démissionne en janvier 1946 : le récit fait de ce départ la solitude du chef.', 3),
    ('ba4a496b-1da6-593d-9698-989d5dfaf8f9'::uuid, 'francais', '1re', 'Mémoires de guerre, Tome III : Le Salut, 1944-1946, Charles de Gaulle', 'Quel trait de la prose gaullienne le cours relève-t-il ?', 'mcq', '["Des phrases amples au rythme ternaire","Des phrases courtes et familières","Un style oral mêlé d’argot","Une prose technique et chiffrée"]'::jsonb, 0, 'Prose classique, volontairement solennelle : elle transforme le récit en épopée nationale.', 4),
    ('dbe389e7-bb17-5c74-870e-1a5dd3b9c8c9'::uuid, 'francais', '1re', 'Mes forêts, Hélène Dorion', 'Quelle place Hélène Dorion occupe-t-elle dans l’histoire du bac de français ?', 'mcq', '["Première poétesse traduite de l’anglais","Première autrice vivante au programme","Première autrice à écrire en prose","Première autrice suisse au programme"]'::jsonb, 1, 'Poétesse québécoise née en 1958, elle est la première autrice vivante inscrite au programme.', 1),
    ('f9c20041-9ae6-505d-b6f5-4d9b0d551a15'::uuid, 'francais', '1re', 'Mes forêts, Hélène Dorion', 'Quel élément de l’arbre dit le temps, dans le recueil ?', 'mcq', '["Les racines","L’écorce","Les feuilles","Les cernes"]'::jsonb, 3, 'Racines, cernes, écorce : l’origine, le temps, la blessure. D’où la formule : regarder un arbre, c’est lire le temps.', 2),
    ('60df3a10-e7d6-5cf8-b112-32d79d52e24c'::uuid, 'francais', '1re', 'Mes forêts, Hélène Dorion', 'Quel effet produisent les nombreux blancs typographiques ?', 'mcq', '["Le silence devient partie du texte","Ils signalent la fin d’une section","Ils remplacent les titres absents","Ils imitent un manuscrit abîmé"]'::jsonb, 0, 'Poèmes courts et blancs nombreux : ce qui n’est pas dit compte autant que ce qui l’est.', 3),
    ('d4c5a116-b032-5019-a2c6-be646a4672cf'::uuid, 'francais', '1re', 'Mes forêts, Hélène Dorion', 'D’où vient la densité du recueil, selon le cours ?', 'mcq', '["D’un vocabulaire savant et botanique","De longues phrases très construites","Des images, non d’un lexique rare","D’une versification régulière et savante"]'::jsonb, 2, 'La langue est simple et concrète : c’est l’image qui porte le sens.', 4),
    ('a652a7e4-7e03-5df6-882a-119eaf21de4a'::uuid, 'francais', '1re', 'Métamorphoses, Ovide', 'Quelle est la forme du poème d’Ovide ?', 'mcq', '["Douze chants en alexandrins","Vingt-quatre chants en prose","Quinze livres en hexamètres","Cinq livres en distiques"]'::jsonb, 2, 'Quinze livres, environ douze mille vers : une épopée de la transformation, achevée vers l’an 8.', 1),
    ('ae165260-c6a2-5824-a54c-60c477e39d98'::uuid, 'francais', '1re', 'Métamorphoses, Ovide', 'Jusqu’où va l’histoire du monde racontée par le poème ?', 'mcq', '["Jusqu’à la chute de Troie","Jusqu’à l’apothéose de César","Jusqu’à la fondation de Rome","Jusqu’au déluge de Deucalion"]'::jsonb, 1, 'Du chaos à l’apothéose de César : le poème traverse toute l’histoire du monde de métamorphose en métamorphose.', 2),
    ('0040a292-30d7-5fbb-ae33-62295cd60156'::uuid, 'francais', '1re', 'Métamorphoses, Ovide', 'Quel thème illustre l’histoire de Philémon et Baucis ?', 'mcq', '["La démesure punie","Le désir et ses dangers","L’art qui donne vie","La fidélité récompensée"]'::jsonb, 3, 'Le vieux couple fidèle est changé en deux arbres entrelacés : la métamorphose peut aussi être une récompense.', 3),
    ('2054c0e8-d292-5ac9-a9cc-00a2bc9d4d84'::uuid, 'francais', '1re', 'Métamorphoses, Ovide', 'Quelle question le mythe de Pygmalion permet-il de poser en dissertation ?', 'mcq', '["L’illusion de l’œuvre qui prend vie","L’orgueil puni par les dieux","Le danger de s’aimer soi-même","La fidélité des vieux époux"]'::jsonb, 0, 'Sa statue s’anime : le mythe interroge le pouvoir de l’art à créer l’illusion du vivant.', 4),
    ('7244f4a2-3c94-52a6-8fab-e09160efd371'::uuid, 'francais', '1re', 'Micromégas, Voltaire', 'Quel philosophe, parmi ceux que les géants interrogent, est le seul approuvé ?', 'mcq', '["Le disciple de Descartes","Le disciple d’Aristote","Le disciple de Leibniz","Le disciple de Locke"]'::jsonb, 3, 'Prudent, il s’en tient à l’expérience : Voltaire célèbre Locke et Newton contre les grands systèmes.', 1),
    ('31b5a7c6-dcfb-52d4-afb7-18cae5090014'::uuid, 'francais', '1re', 'Micromégas, Voltaire', 'Quelle expédition réelle inspire le navire revenant du cercle polaire ?', 'mcq', '["Celle de Cook dans le Pacifique","Celle de Bougainville autour du monde","Celle de Maupertuis en Laponie","Celle de Magellan vers les Indes"]'::jsonb, 2, 'En 1736-1737, Maupertuis part en Laponie mesurer la Terre : le conte naît d’un siècle de science.', 2),
    ('7ebdd38e-8b2b-52fe-ba3e-c4631e3afc7d'::uuid, 'francais', '1re', 'Micromégas, Voltaire', 'Qui accompagne Micromégas dans son voyage ?', 'mcq', '["Un savant terrien, disciple de Newton","Un Saturnien, secrétaire de l’Académie","Un géant de Jupiter, poète de cour","Un prince de Sirius, exilé comme lui"]'::jsonb, 1, 'Le Saturnien ne mesure « que » mille toises : le changement d’échelle joue déjà entre les deux géants.', 3),
    ('d9271849-e4e6-5db4-86ef-0d4eec2b8a4c'::uuid, 'francais', '1re', 'Micromégas, Voltaire', 'Quelles cibles le conte vise-t-il ?', 'mcq', '["La métaphysique bavarde et la guerre","La science expérimentale de Newton","Le commerce et le goût du luxe","La poésie et les gens de théâtre"]'::jsonb, 0, 'Voltaire raille aussi l’anthropocentrisme ; il célèbre au contraire la science expérimentale de Newton et de Locke.', 4),
    ('739a3442-a5d8-52d7-945d-5ba4c44e3629'::uuid, 'francais', '1re', 'Nadja, André Breton', 'En quelle année paraît Nadja ?', 'mcq', '["1928","1924","1938","1919"]'::jsonb, 0, 'Quatre ans après le Manifeste du surréalisme ; la rencontre avec Nadja date d’octobre 1926.', 1),
    ('4a2b45bc-a028-5716-a2cc-b93d08d084df'::uuid, 'francais', '1re', 'Nadja, André Breton', 'Que rassemble la première partie du livre ?', 'mcq', '["Des lettres échangées avec Nadja","Des coïncidences de « hasard objectif »","Des souvenirs d’enfance de Breton","Un traité théorique sur la folie"]'::jsonb, 1, 'Rencontres et coïncidences troublantes : le hasard devient, pour les surréalistes, une voie d’accès au réel.', 2),
    ('edc52ee4-daf7-596b-8310-d010e075d980'::uuid, 'francais', '1re', 'Nadja, André Breton', 'Pendant combien de temps Breton et Nadja errent-ils ensemble dans Paris ?', 'mcq', '["Une nuit","Un an","Dix jours","Trois mois"]'::jsonb, 2, 'Pendant dix jours, Nadja voit des signes partout, dessine, prophétise — puis elle sombre.', 3),
    ('8ed04a13-74e0-5b7d-bb66-c99602aa48af'::uuid, 'francais', '1re', 'Nadja, André Breton', 'À qui s’adresse la dernière partie du livre ?', 'mcq', '["À Nadja, internée","Aux médecins de l’asile","À Philippe Soupault","À une autre femme, « Toi »"]'::jsonb, 3, 'Après l’éloge de la beauté convulsive, Breton s’adresse à une autre femme : Nadja a disparu du récit.', 4),
    ('b17f795e-5a7c-5615-a436-f608b650d55d'::uuid, 'francais', '1re', 'Nana, Émile Zola', 'Dans quelle pièce Nana débute-t-elle au théâtre des Variétés ?', 'mcq', '["La Belle Hélène","La Dame aux camélias","La Blonde Vénus","Orphée aux Enfers"]'::jsonb, 2, 'Elle chante faux et ne sait pas jouer, mais paraît presque nue dans La Blonde Vénus : elle triomphe.', 1),
    ('645eda92-cd91-5960-9810-75678bdd91b6'::uuid, 'francais', '1re', 'Nana, Émile Zola', 'Quel événement commence au moment où Nana meurt ?', 'mcq', '["La Commune de Paris","La guerre de 1870","Le coup d’État de 1851","L’Exposition universelle de 1867"]'::jsonb, 1, 'Sous les fenêtres, la foule crie « À Berlin ! » : la mort de Nana coïncide avec la chute de l’Empire qu’elle symbolise.', 2),
    ('74da67ec-1f52-5b45-8559-6bb2ce26a747'::uuid, 'francais', '1re', 'Nana, Émile Zola', 'Sous quelle image Zola fait-il de Nana une allégorie ?', 'mcq', '["La Vénus du faubourg","La reine des Variétés","La dame aux perles","La mouche d’or"]'::jsonb, 3, 'Née du ruisseau, la « mouche d’or » monte et pourrit tout ce qu’elle touche : une société qui court à sa perte.', 3),
    ('0d70cb26-c20f-5550-aade-8807da39024b'::uuid, 'francais', '1re', 'Nana, Émile Zola', 'Que fait Vandeuvres après avoir triché aux courses ?', 'mcq', '["Il se brûle dans son écurie","Il s’exile en Angleterre","Il épouse Nana en secret","Il dénonce Muffat"]'::jsonb, 0, 'Il fait partie des victimes de Nana, avec Muffat, Steiner ruiné et le jeune Georges Hugon.', 4),
    ('17df644e-84ea-52c6-913b-da4a72c84a7e'::uuid, 'francais', '1re', 'Notre-Dame de Paris, Victor Hugo', 'Qui poignarde le capitaine Phœbus ?', 'mcq', '["Quasimodo","Claude Frollo","Esmeralda","Gringoire"]'::jsonb, 1, 'Frollo frappe Phœbus et laisse accuser Esmeralda : la justice aveugle condamne l’innocente.', 1),
    ('08fbf543-2120-53cb-b7a6-df091279baee'::uuid, 'francais', '1re', 'Notre-Dame de Paris, Victor Hugo', 'Où Quasimodo va-t-il mourir à la fin du roman ?', 'mcq', '["Du haut des tours de la cathédrale","Dans la Cour des miracles, lors de l’assaut","Sur le parvis, lapidé par la foule","Au gibet de Montfaucon, près d’Esmeralda"]'::jsonb, 3, 'Après avoir précipité Frollo du haut des tours, il va mourir près du corps d’Esmeralda : un amour de pur dévouement.', 2),
    ('1fc0547c-c542-5825-a4d8-11b597636b2e'::uuid, 'francais', '1re', 'Notre-Dame de Paris, Victor Hugo', 'Quelle idée de la Préface de Cromwell Quasimodo incarne-t-il ?', 'mcq', '["La règle des trois unités","La stricte séparation des genres","L’union du grotesque et du sublime","L’art pour l’art"]'::jsonb, 2, 'Monstrueux et sublime à la fois, Quasimodo illustre le drame romantique qui mêle le laid et le beau.', 3),
    ('c538079e-a2b2-5f0d-9f6f-301435e31cfa'::uuid, 'francais', '1re', 'Notre-Dame de Paris, Victor Hugo', 'Comment Claude Frollo aime-t-il Esmeralda, selon le cours ?', 'mcq', '["Par possession","Par légèreté","Par dévouement","Par pitié"]'::jsonb, 0, 'Chacun l’aime à sa manière : Frollo par possession, Phœbus par légèreté, Quasimodo par dévouement.', 4),
    ('0e52c5c3-bc09-50f1-a169-4fdef21f528f'::uuid, 'francais', '1re', 'Odyssée, Homère', 'Que désigne le mot grec nostos ?', 'mcq', '["La ruse","Le retour","L’errance en mer","La reconnaissance"]'::jsonb, 1, 'L’Odyssée est le grand poème du nostos, le retour chez soi — et de la ruse d’Ulysse « aux mille tours ».', 1),
    ('3589e13b-ec25-58f3-b283-202478950bbd'::uuid, 'francais', '1re', 'Odyssée, Homère', 'Comment appelle-t-on la partie où Télémaque part chercher des nouvelles de son père ?', 'mcq', '["L’Iliade","L’Énéide","La Théogonie","La Télémachie"]'::jsonb, 3, 'La Télémachie est l’un des trois fils du poème, avec les récits d’Ulysse chez les Phéaciens et le retour à Ithaque.', 2),
    ('cc41e522-a83c-5027-9ee3-5c578c1386ea'::uuid, 'francais', '1re', 'Odyssée, Homère', 'Sous quelle apparence Ulysse rentre-t-il dans son palais ?', 'mcq', '["En roi victorieux, armé","Déguisé en marchand phénicien","Déguisé en mendiant","Caché parmi les prétendants"]'::jsonb, 2, 'Méconnaissable, il observe les prétendants avant l’épreuve de l’arc : la ruse l’emporte sur la force.', 3),
    ('4079f529-d722-580c-ba66-aef089480765'::uuid, 'francais', '1re', 'Odyssée, Homère', 'Quelle ruse de Pénélope montre sa fidélité ?', 'mcq', '["Elle défait la nuit la toile du jour","Elle feint une longue maladie","Elle se réfugie chez son père","Elle exige un tournoi chaque année"]'::jsonb, 0, 'Elle repousse sans cesse le moment de choisir un prétendant : fidèle, elle est aussi rusée qu’Ulysse.', 4),
    ('9081546f-6ef9-58c0-af56-a5eace4baf15'::uuid, 'francais', '1re', 'Œdipe roi, Sophocle', 'Dans quel cadre la pièce est-elle jouée à Athènes ?', 'mcq', '["Les Jeux olympiques","Les fêtes d’Athéna","Les concours du théâtre de Dionysos","Les fêtes d’Apollon à Delphes"]'::jsonb, 2, 'La tragédie naît des concours en l’honneur de Dionysos ; Sophocle y rivalise avec Eschyle et Euripide.', 1),
    ('a522a4f4-933b-5bbb-b66a-1ff4ce64812f'::uuid, 'francais', '1re', 'Œdipe roi, Sophocle', 'Qui Œdipe accuse-t-il de complot après les révélations de Tirésias ?', 'mcq', '["Jocaste","Créon","Le vieux berger","Le messager de Corinthe"]'::jsonb, 1, 'Aveuglé, il refuse la vérité et crie au complot de Créon : chaque réaction le rapproche de sa chute.', 2),
    ('6695438b-4c80-5c08-b26a-5d2d8b7bac87'::uuid, 'francais', '1re', 'Œdipe roi, Sophocle', 'Quelle leçon le chœur tire-t-il à la fin de la pièce ?', 'mcq', '["Les dieux punissent toujours les méchants","Le pouvoir finit par corrompre les rois","Mieux vaut fuir sa cité que la gouverner","Nul ne doit être dit heureux avant sa mort"]'::jsonb, 3, 'Le chœur de vieillards thébains médite sur la chute d’un roi admiré : le bonheur humain reste fragile jusqu’au bout.', 3),
    ('e85ddfd5-fd08-5631-ad87-85f14ccf6e09'::uuid, 'francais', '1re', 'Œdipe roi, Sophocle', 'Pourquoi l’intérêt de la pièce ne repose-t-il pas sur la surprise ?', 'mcq', '["Les spectateurs connaissent déjà le mythe","Le titre annonce le dénouement","Un narrateur résume l’intrigue","La pièce suit un ordre inversé"]'::jsonb, 0, 'Tout l’intérêt vient de la manière dont la vérité éclate — d’où la force de l’ironie tragique.', 4),
    ('62324f8b-e2eb-5708-b61b-abf328ab529b'::uuid, 'francais', '1re', 'On ne badine pas avec l’amour, Alfred de Musset', 'En quelle année la pièce est-elle créée sur scène ?', 'mcq', '["1830","1834","1861","1848"]'::jsonb, 2, 'Publiée en 1834 pour être lue, elle n’est jouée qu’en 1861, après la mort de Musset.', 1),
    ('81678900-f84b-5048-94de-adde75cc4282'::uuid, 'francais', '1re', 'On ne badine pas avec l’amour, Alfred de Musset', 'Qui sont maître Blazius, maître Bridaine et dame Pluche ?', 'mcq', '["Les religieuses du couvent de Camille","Des fantoches, contrepoint comique","Des paysans, amis de Rosette","Les témoins du mariage prévu"]'::jsonb, 1, 'Ces figures grotesques, avec le baron, font rire autour du drame des jeunes gens : c’est le mélange des registres.', 2),
    ('79d977a8-379d-5bc9-9b45-5623a298a27c'::uuid, 'francais', '1re', 'On ne badine pas avec l’amour, Alfred de Musset', 'Avec qui Musset vient-il de vivre une liaison orageuse à Venise quand il publie la pièce ?', 'mcq', '["George Sand","Marie Dorval","Juliette Drouet","Madame Récamier"]'::jsonb, 0, 'La pièce paraît en 1834 dans la Revue des Deux Mondes, au sortir de cette passion douloureuse.', 3),
    ('cb7b837e-d550-550d-aab5-3096c70b5fd5'::uuid, 'francais', '1re', 'On ne badine pas avec l’amour, Alfred de Musset', 'Que dit la tirade de Perdican de l’acte II ?', 'mcq', '["Il faut fuir l’amour qui fait souffrir","Les femmes seules sont infidèles","Le mariage n’est qu’une affaire d’argent","Malgré ses blessures, l’amour vaut d’être vécu"]'::jsonb, 3, '« On est souvent trompé en amour, souvent blessé et souvent malheureux ; mais on aime » : hommes et femmes sont imparfaits, l’amour reste la vraie vie.', 4),
    ('8333c2f0-e572-58fe-a2fe-53fc291de045'::uuid, 'francais', '1re', 'On purge bébé, Georges Feydeau', 'En quelle année On purge bébé est-elle créée ?', 'mcq', '["1885","1898","1925","1910"]'::jsonb, 3, 'C’est une pièce tardive de Feydeau, maître du vaudeville de la Belle Époque (Le Dindon, La Dame de chez Maxim).', 1),
    ('271bfafb-4b2b-5955-9c5a-9977d03732b1'::uuid, 'francais', '1re', 'On purge bébé, Georges Feydeau', 'Dans quelle tenue Julie paraît-elle devant l’invité de son mari ?', 'mcq', '["En peignoir et en pantoufles","En robe de bal","En tablier de cuisinière","En habit de deuil"]'::jsonb, 0, 'Sa tenue fait entrer la trivialité domestique au milieu d’une négociation d’affaires : c’est tout le décalage comique.', 2),
    ('a7638ebe-2dcd-5e38-9658-0491b3105821'::uuid, 'francais', '1re', 'On purge bébé, Georges Feydeau', 'Quel objet devient un ressort comique de la pièce ?', 'mcq', '["Une lettre d’amour compromettante","Un chapeau de paille oublié","Un pot « incassable » qui se casse","La clé d’une chambre d’hôtel"]'::jsonb, 2, 'Le pot de chambre censé séduire l’armée se brise : l’objet ruine le marché et fait rire par le geste.', 3),
    ('309c960d-0a34-53b4-b12c-23e3e736b4e4'::uuid, 'francais', '1re', 'On purge bébé, Georges Feydeau', 'Quel dramaturge du XXe siècle admirera la brutalité conjugale de ces dialogues ?', 'mcq', '["Anouilh","Ionesco","Giraudoux","Claudel"]'::jsonb, 1, 'Ionesco admirera cette brutalité conjugale ; on rapproche d’ailleurs la pièce de sa Cantatrice chauve.', 4),
    ('8befc683-ddc1-585f-b2b5-639cdeefa2b0'::uuid, 'francais', '1re', 'Pantagruel, François Rabelais', 'Quels genres Pantagruel parodie-t-il ?', 'mcq', '["Les tragédies antiques et les sonnets","Les sermons et les vies de saints","Les romans de chevalerie et les almanachs populaires","Les fables et les contes de fées"]'::jsonb, 2, 'Rabelais détourne les récits de chevaliers et les almanachs vendus au peuple : son rire savant se nourrit de la culture populaire.', 1),
    ('78b28307-c7f4-5a4c-860a-8ff2ecb1ba36'::uuid, 'francais', '1re', 'Pantagruel, François Rabelais', 'Qu’a de particulier le procès de Baisecul et Humevesne ?', 'mcq', '["Pantagruel y est accusé de sorcellerie","Les plaidoiries y sont incompréhensibles","Il oppose deux géants rivaux","Il se règle par un duel à l’épée"]'::jsonb, 1, 'Pantagruel doit juger sur des plaidoiries qui ne veulent rien dire : Rabelais fait rire d’un savoir qui parle pour ne rien dire.', 2),
    ('1a5f07b1-36f6-504e-9899-6cffc4e8c924'::uuid, 'francais', '1re', 'Pantagruel, François Rabelais', 'Contre quels vieux savoirs le comique de Rabelais sert-il d’arme ?', 'mcq', '["Les langues anciennes","La médecine grecque","L’humanisme","La scolastique"]'::jsonb, 3, 'Le rire attaque la scolastique, l’ancien savoir des universités ; l’humanisme, lui, est le programme que Rabelais défend dans la lettre de Gargantua.', 3),
    ('d0079760-0db0-5282-b666-aeeafa583bcd'::uuid, 'francais', '1re', 'Pantagruel, François Rabelais', 'Comment Panurge s’adresse-t-il à Pantagruel lors de leur première rencontre ?', 'mcq', '["Dans de nombreuses langues différentes","Par une lettre de Gargantua","En latin de cuisine seulement","Par l’entremise d’Épistémon"]'::jsonb, 0, 'Ce festival de langues annonce le personnage : un beau parleur rusé, plein de ressources, le trickster du livre.', 4),
    ('1ed01f7c-bc37-561b-bf8b-fef293eb293d'::uuid, 'francais', '1re', 'Pierre et Jean, Guy de Maupassant', 'Quel indice met Pierre sur la voie du secret ?', 'mcq', '["Une lettre cachée dans un tiroir","Un testament falsifié","Un portrait disparu","Une bague de fiançailles"]'::jsonb, 2, 'Un portrait disparu, des dates, une phrase de serveuse de brasserie : l’enquête de Pierre est tout intérieure, faite d’indices minuscules.', 1),
    ('ef47e5fb-10c0-534d-8d4b-8335f586efae'::uuid, 'francais', '1re', 'Pierre et Jean, Guy de Maupassant', 'Qui est Madame Rosémilly ?', 'mcq', '["La jeune veuve que Jean va épouser","La sœur de l’ami Maréchal","La serveuse de la brasserie","La première épouse du père Roland"]'::jsonb, 0, 'Tout sourit au cadet — l’héritage, puis ce mariage — pendant que Pierre s’enfonce dans la jalousie et le soupçon.', 2),
    ('0d001c54-a27c-5b60-a3cb-1c0355aaa78f'::uuid, 'francais', '1re', 'Pierre et Jean, Guy de Maupassant', 'Selon la préface, que doit donner le réaliste qui est un artiste ?', 'mcq', '["La photographie exacte de la vie","Le relevé de tout ce qu’il observe","La vision la plus neutre possible","Une vision plus saisissante que la réalité"]'::jsonb, 3, 'Maupassant refuse « la photographie banale de la vie » : le romancier choisit et compose pour donner « l’illusion complète du vrai ».', 3),
    ('00005202-4f10-5cc4-8ae0-f360cb342f77'::uuid, 'francais', '1re', 'Pierre et Jean, Guy de Maupassant', 'Comment la famille réagit-elle au départ de Pierre ?', 'mcq', '["Elle le supplie de rester","Elle le regarde partir, soulagée","Elle le renie publiquement","Elle embarque avec lui"]'::jsonb, 1, 'Devenu insupportable à tous, Pierre s’embarque comme médecin de bord ; le roman se referme sur « une petite fumée grise » qui s’efface.', 4),
    ('e1553d38-32dd-5743-bb7d-04c44b2d0a92'::uuid, 'francais', '1re', 'Poèmes antiques, Charles Leconte de Lisle', 'Lequel de ces poèmes puise dans la mythologie indienne ?', 'mcq', '["Hélène","Bhagavat","Niobé","Midi"]'::jsonb, 1, '« Bhagavat » vient des textes sanskrits ; « Hélène » et « Niobé » viennent de la Grèce, « Midi » des Poésies diverses.', 1),
    ('e8568654-3e84-5888-8b0d-f14b4a1ef07f'::uuid, 'francais', '1re', 'Poèmes antiques, Charles Leconte de Lisle', 'Quel recueil Leconte de Lisle publie-t-il en 1862 ?', 'mcq', '["Poèmes saturniens","Émaux et Camées","Les Trophées","Poèmes barbares"]'::jsonb, 3, 'Après les Poèmes antiques (1852) viennent les Poèmes barbares (1862) puis les Poèmes tragiques (1884) ; les Poèmes saturniens sont de Verlaine.', 2),
    ('9829a9e7-e646-5337-99b7-97f6200a8fce'::uuid, 'francais', '1re', 'Poèmes antiques, Charles Leconte de Lisle', 'À quelle doctrine de Gautier rapproche-t-on le Parnasse ?', 'mcq', '["L’art pour l’art","L’art engagé","Le mal du siècle","La poésie du rêve"]'::jsonb, 0, 'Gautier la défend dans la préface de Mademoiselle de Maupin (1835) : l’art n’a pas à être utile, il vise la beauté.', 3),
    ('2046394b-ebc4-57de-9731-d56a05058d49'::uuid, 'francais', '1re', 'Poèmes antiques, Charles Leconte de Lisle', 'Quel recueil collectif ses jeunes disciples publient-ils en 1866 ?', 'mcq', '["Les Poètes maudits","Les Chansons écossaises","Le Parnasse contemporain","Les Poèmes tragiques"]'::jsonb, 2, 'Heredia, Sully Prudhomme et un temps Verlaine y publient : c’est ce recueil qui donne son nom au mouvement.', 4),
    ('46535215-4819-5090-b3d4-7be1dc50a505'::uuid, 'francais', '1re', 'Poèmes saturniens, Paul Verlaine', 'Qu’est-ce qui encadre le recueil ?', 'mcq', '["Une préface théorique et un art poétique","Deux sonnets dédiés à Baudelaire","Un prologue et un épilogue encore parnassiens","Deux chansons déjà mises en musique"]'::jsonb, 2, 'Le cadre reste fidèle au Parnasse de l’époque, alors que les poèmes du milieu cherchent déjà la musique et la suggestion.', 1),
    ('22c78c05-5995-5fb1-ab44-0bab5487f245'::uuid, 'francais', '1re', 'Poèmes saturniens, Paul Verlaine', 'Quelle section du recueil est celle du crépuscule ?', 'mcq', '["Paysages tristes","Melancholia","Eaux-fortes","Caprices"]'::jsonb, 0, 'Melancholia porte le cœur, Eaux-fortes les tableaux, Paysages tristes le crépuscule et Caprices les pièces brèves.', 2),
    ('36131694-b01a-5053-bbe6-8d601643919a'::uuid, 'francais', '1re', 'Poèmes saturniens, Paul Verlaine', 'Dans « Chanson d’automne », qu’imitent les vers très courts et les sonorités nasales ?', 'mcq', '["Le bruit de la pluie","Le glas d’une cloche","Le vent dans les feuilles","La plainte du violon"]'::jsonb, 3, 'Des vers de quatre et trois syllabes et des nasales (« sanglots longs », « violons ») font entendre une plainte : le son porte le sens.', 3),
    ('f86a77b1-72ae-5710-b074-f3d5ca4e5a7d'::uuid, 'francais', '1re', 'Poèmes saturniens, Paul Verlaine', 'Que cherche Verlaine plutôt que décrire ?', 'mcq', '["Raconter une histoire","Suggérer un état","Enseigner une morale","Reproduire un lieu exact"]'::jsonb, 1, 'Sonorités douces et sujets flous : le poème suggère une humeur au lieu de peindre, ce qui ouvre la voie au symbolisme.', 4),
    ('3ebb4427-6d97-5d9d-86b2-1419ffce8e5a'::uuid, 'francais', '1re', 'Poésies, Stéphane Mallarmé', 'Où Mallarmé réunit-il ses célèbres « mardis » ?', 'mcq', '["Au Cabaret Voltaire","Rue de Rome","Au café du Chat noir","Rue de Fleurus"]'::jsonb, 1, 'Valéry, Gide, Claudel, Verlaine y passent : Mallarmé devient le maître de la jeunesse symboliste.', 1),
    ('00b29fbe-bd9b-5512-bf84-1b7063a62967'::uuid, 'francais', '1re', 'Poésies, Stéphane Mallarmé', 'Quelles œuvres rendent Mallarmé célèbre en 1884 ?', 'mcq', '["Les Fleurs du mal et une traduction de Poe","Un coup de dés et L’Après-midi d’un faune","À rebours de Huysmans et Les Poètes maudits de Verlaine","Le Manifeste du symbolisme et un roman de Zola"]'::jsonb, 2, 'Ces deux livres font découvrir un professeur d’anglais discret, qui devient une référence pour les jeunes poètes symbolistes.', 2),
    ('5eaec237-be8b-52eb-8de6-3828f6103b48'::uuid, 'francais', '1re', 'Poésies, Stéphane Mallarmé', 'Pourquoi l’obscurité de Mallarmé est-elle voulue ?', 'mcq', '["Pour échapper à la censure","Pour imiter la langue des Anciens","Pour décourager les critiques","Pour que le lecteur participe au sens"]'::jsonb, 3, 'Syntaxe déplacée, ellipses, inversions : le mot compte pour ce qu’il fait résonner, et c’est le lecteur qui achève le poème.', 3),
    ('2e7a48b0-f01c-5936-8087-8c5445708373'::uuid, 'francais', '1re', 'Poésies, Stéphane Mallarmé', 'Que représente « L’Azur » dans la poésie de Mallarmé ?', 'mcq', '["L’idéal qui écrase le poète","La mer qui appelle au départ","Le bonheur d’un ciel d’été","La page couverte d’encre"]'::jsonb, 0, 'L’Azur est l’Idéal inaccessible qui domine et accable le poète, hanté par l’impuissance créatrice et la page blanche.', 4),
    ('5a951507-b1e3-525b-96e9-b062deceb167'::uuid, 'francais', '1re', 'Polyeucte, Pierre Corneille', 'Qui conseille à Polyeucte de se faire baptiser en secret ?', 'mcq', '["Sévère","Félix","Néarque","Pauline"]'::jsonb, 2, 'Néarque, l’ami chrétien, pousse Polyeucte au baptême secret : c’est l’acte qui déclenche toute la tragédie.', 1),
    ('059a5c84-b6fe-59c7-8aa2-165e9421af50'::uuid, 'francais', '1re', 'Polyeucte, Pierre Corneille', 'Où et sous quel empereur se déroule l’action ?', 'mcq', '["En Arménie, sous l’empereur Décie","À Rome, sous l’empereur Néron","En Grèce, sous l’empereur Auguste","À Byzance, sous l’empereur Constantin"]'::jsonb, 0, 'Corneille puise dans la vie d’un saint des premiers siècles, martyrisé au IIIe siècle, au temps des persécutions.', 2),
    ('b8c23ebd-1c37-5bdc-984b-de022699bd39'::uuid, 'francais', '1re', 'Polyeucte, Pierre Corneille', 'Que promet Sévère à la fin de la pièce ?', 'mcq', '["D’épouser enfin Pauline","De venger Polyeucte sur Félix","De repartir aussitôt pour Rome","De protéger les chrétiens"]'::jsonb, 3, 'Magnanime, Sévère répond au martyre par la générosité : la pièce s’achève sur des conversions et une promesse de paix.', 3),
    ('2e3eadbd-866e-5b81-9d35-ffa431d80fa8'::uuid, 'francais', '1re', 'Polyeucte, Pierre Corneille', 'Pourquoi Pauline est-elle une grande héroïne ?', 'mcq', '["Elle fuit avec Sévère par amour","Elle aime Sévère mais choisit son devoir","Elle dénonce Polyeucte à son père","Elle se convertit dès le premier acte"]'::jsonb, 1, 'Pauline n’a pas oublié Sévère, mais elle reste fidèle à son époux par devoir : c’est le choix qui grandit, marque du héros cornélien.', 4),
    ('04d71f5e-e815-577a-b82d-b622d837700c'::uuid, 'francais', '1re', 'Pour un oui ou pour un non, Nathalie Sarraute', 'D’où vient le mot « tropisme » ?', 'mcq', '["De la rhétorique antique","De la biologie","De la psychanalyse","Du solfège"]'::jsonb, 1, 'En biologie, il désigne le mouvement d’un organisme vers ou contre une source, comme la plante vers la lumière ; Sarraute l’applique aux mouvements intérieurs infimes.', 1),
    ('25afd5e8-0ad7-5a83-ab3a-9a58237e9d3b'::uuid, 'francais', '1re', 'Pour un oui ou pour un non, Nathalie Sarraute', 'Que vient demander H1 à H2 au début de la pièce ?', 'mcq', '["Pourquoi il ne le voit plus","De l’argent pour un voyage","Pardon pour une trahison","S’il veut être son témoin"]'::jsonb, 0, 'La réponse tarde, puis tombe, dérisoire : un « C’est bien… ça » prononcé un jour avec une nuance de condescendance.', 2),
    ('9f4e30d9-9904-57f6-9093-7bd11d7e9a66'::uuid, 'francais', '1re', 'Pour un oui ou pour un non, Nathalie Sarraute', 'De quel mouvement littéraire Nathalie Sarraute est-elle une figure ?', 'mcq', '["Le surréalisme","L’existentialisme","Le théâtre de l’absurde","Le Nouveau Roman"]'::jsonb, 3, 'Figure du Nouveau Roman, elle renonce à l’intrigue et à la psychologie classique pour saisir ce qui se passe sous les mots.', 3),
    ('5e7f8c9f-6c60-52b8-ab63-a4d5d4303c12'::uuid, 'francais', '1re', 'Pour un oui ou pour un non, Nathalie Sarraute', 'À quels dramaturges rapproche-t-on la pièce pour son dépouillement ?', 'mcq', '["Racine et Corneille","Hugo et Musset","Beckett et Ionesco","Molière et Marivaux"]'::jsonb, 2, 'Comme chez Beckett et Ionesco, le théâtre se passe d’action : ici, tout est parole.', 4),
    ('982c1672-a4e1-5984-9238-f7a3965409f7'::uuid, 'francais', '1re', 'Préface de Cromwell, Victor Hugo', 'Selon Hugo, qu’a révélé le christianisme sur l’homme ?', 'mcq', '["Sa perfection naturelle","Sa dualité : corps et âme, bête et ange","Son besoin de règles strictes","Sa ressemblance avec les héros antiques"]'::jsonb, 1, 'Cette double nature fonde le drame : l’art moderne doit montrer ensemble le sublime et le grotesque.', 1),
    ('4b866dad-23cf-5feb-b39d-faa9b0c0dce4'::uuid, 'francais', '1re', 'Préface de Cromwell, Victor Hugo', 'Quel rôle Hugo donne-t-il au grotesque ?', 'mcq', '["Faire ressortir le beau par contraste","Montrer le laid pour lui-même","Faire rire le seul public populaire","Remplacer entièrement le sublime"]'::jsonb, 0, 'Le grotesque n’est pas le laid gratuit : placé près du sublime, il le met en valeur. Hugo cite Sganarelle et Méphistophélès.', 2),
    ('27b55882-d41e-5196-91a7-f14e877a1887'::uuid, 'francais', '1re', 'Préface de Cromwell, Victor Hugo', 'Que devient l’alexandrin selon la Préface ?', 'mcq', '["Il est remplacé par la prose","Il est réservé aux personnages nobles","Il est gardé mais assoupli","Il garde une césure stricte"]'::jsonb, 2, 'Hugo conserve le vers mais le libère par les enjambements, les rejets et les coupes irrégulières ; Stendhal, lui, voulait la prose.', 3),
    ('26c37a69-45bd-5d4a-b55e-1269a0ebbf59'::uuid, 'francais', '1re', 'Préface de Cromwell, Victor Hugo', 'Quel personnage grotesque Hugo créera-t-il en 1831 ?', 'mcq', '["Sganarelle","Méphistophélès","Ruy Blas","Quasimodo"]'::jsonb, 3, 'Quasimodo (1831) puis Triboulet (1832) mettent la théorie en pratique ; Sganarelle et Méphistophélès sont les exemples que Hugo emprunte à d’autres.', 4),
    ('c9d57393-d0b5-562c-a1ac-320fb7aa0585'::uuid, 'francais', '1re', 'Premières poésies, Alfred de Musset', 'Quelle notion le poème Rolla illustre-t-il ?', 'mcq', '["L’art pour l’art","Le « mal du siècle »","La poésie engagée","Le culte de la forme"]'::jsonb, 1, 'Débauche et désenchantement : Rolla dit la nostalgie d’un temps de foi perdu, le « mal du siècle » de la jeunesse romantique.', 1),
    ('0f99342d-4eee-5492-9618-825662c0883e'::uuid, 'francais', '1re', 'Premières poésies, Alfred de Musset', 'Par quels procédés Musset crée-t-il une complicité avec le lecteur ?', 'mcq', '["Des notes savantes en bas de page","Des épigraphes latines","Des scènes dialoguées","Des digressions et des adresses au lecteur"]'::jsonb, 3, 'Il interrompt son récit pour parler à son lecteur : le romantisme se regarde, et rien n’est jamais tout à fait sérieux.', 2),
    ('5884cd4b-e424-5add-bffe-17f0bd3fb3f5'::uuid, 'francais', '1re', 'Premières poésies, Alfred de Musset', 'Lequel de ces titres est un grand poème narratif des Premières poésies ?', 'mcq', '["Namouna","La Nuit de mai","Les Contemplations","Le Lac"]'::jsonb, 0, 'Namouna, Rolla et La Coupe et les Lèvres sont les grands poèmes narratifs ; La Nuit de mai appartient aux Nuits, écrites plus tard.', 3),
    ('a6936bc5-c754-570f-a8c2-6480becebd9a'::uuid, 'francais', '1re', 'Premières poésies, Alfred de Musset', 'Quel récit en prose de Musset rapproche-t-on de ces poèmes ?', 'mcq', '["René","Adolphe","La Confession d’un enfant du siècle","Les Rêveries du promeneur solitaire"]'::jsonb, 2, 'Parue en 1836, la Confession d’un enfant du siècle prolonge en prose le désenchantement de la jeunesse que disait Rolla.', 4),
    ('cf1823a8-42df-5ca2-8684-a8976df7ca6e'::uuid, 'francais', '1re', 'Racine et Shakespeare, Stendhal', 'Quel est le vrai nom de Stendhal ?', 'mcq', '["Julien Sorel","Henri Brulard","Henri Beyle","Fabrice del Dongo"]'::jsonb, 2, 'Henri Beyle (1783-1842), ancien soldat de l’Empire et amoureux de l’Italie, n’a pas encore écrit Le Rouge et le Noir (1830).', 1),
    ('38064b50-7835-543f-beee-6df97e160ff0'::uuid, 'francais', '1re', 'Racine et Shakespeare, Stendhal', 'À quoi répond la deuxième brochure ?', 'mcq', '["À une lettre de Victor Hugo","À un discours de l’Académie française","À la censure d’une pièce anglaise","À un article de Goethe"]'::jsonb, 1, 'En 1825, Stendhal riposte à un discours de l’Académie française contre le romantisme : le texte reste une polémique vive et drôle.', 2),
    ('64a9bcc9-6875-5d9b-95dd-237a90490da4'::uuid, 'francais', '1re', 'Racine et Shakespeare, Stendhal', 'Que conseille Stendhal à propos de Shakespeare ?', 'mcq', '["L’imiter plutôt que le copier","Le traduire mot à mot","Le jouer en anglais","Le corriger selon les règles"]'::jsonb, 0, 'Imiter Shakespeare, c’est reprendre sa liberté — plus d’unités, des sujets tirés de l’histoire nationale — et non recopier ses pièces.', 3),
    ('536dae20-be58-52f2-92f6-17c9bc606ce3'::uuid, 'francais', '1re', 'Racine et Shakespeare, Stendhal', 'Sur quel point Hugo se sépare-t-il de Stendhal ?', 'mcq', '["Hugo défend les trois unités","Hugo refuse le modèle de Shakespeare","Hugo veut des sujets antiques","Hugo garde le vers"]'::jsonb, 3, 'La Préface de Cromwell (1827) reprend ces idées mais conserve l’alexandrin, assoupli ; Stendhal voulait la tragédie en prose, car « le vers éloigne ».', 4),
    ('49033884-1e8c-54c7-b2b8-878a1fe0a501'::uuid, 'francais', '1re', 'Réflexions ou sentences et maximes morales, François de la Rochefoucauld', 'Quel nom l’auteur donne-t-il à ce qui se cache derrière chaque vertu apparente ?', 'mcq', '["La grâce","La raison","L’amour-propre","Le hasard"]'::jsonb, 2, 'L’amour-propre, c’est l’amour de soi, la vanité ou l’intérêt : « le plus grand de tous les flatteurs ».', 1),
    ('be5896b7-bfda-5dce-a2c6-06b1a16c3946'::uuid, 'francais', '1re', 'Réflexions ou sentences et maximes morales, François de la Rochefoucauld', 'Quand les Maximes paraissent-elles ?', 'mcq', '["En 1665, retravaillées jusqu’en 1678","En 1648, pendant la Fronde","En 1688, avec Les Caractères","En 1700, après la mort de l’auteur"]'::jsonb, 0, 'L’auteur reprend son livre pendant treize ans : la brièveté de la maxime est le fruit d’un long travail de ciselure.', 2),
    ('fe08ad72-389c-5387-bffd-5cb102c7844f'::uuid, 'francais', '1re', 'Réflexions ou sentences et maximes morales, François de la Rochefoucauld', '« Nous avons tous assez de force pour supporter les maux d’autrui. » Quel procédé repère-t-on ?', 'mcq', '["Une métaphore filée","Une question rhétorique","Une énumération","Une généralisation suivie d’une chute"]'::jsonb, 3, '« Nous avons tous » englobe le lecteur ; « d’autrui », placé en dernier, renverse l’éloge du courage en constat d’égoïsme.', 3),
    ('2c474061-6682-5737-88da-00bacf888622'::uuid, 'francais', '1re', 'Réflexions ou sentences et maximes morales, François de la Rochefoucauld', 'Quels penseurs modernes son pessimisme a-t-il nourris ?', 'mcq', '["Rousseau et Diderot","Nietzsche et Freud","Descartes et Leibniz","Hugo et Lamartine"]'::jsonb, 1, 'En montrant l’intérêt caché sous la vertu, La Rochefoucauld annonce le soupçon que Nietzsche et Freud porteront sur les motifs humains.', 4),
    ('177f32db-eb3d-5527-a5d4-cdd71e39522c'::uuid, 'francais', '1re', 'Rhétorique, Aristote', 'Quel genre oratoire consiste à louer ou à blâmer ?', 'mcq', '["Le judiciaire","Le délibératif","Le didactique","L’épidictique"]'::jsonb, 3, 'L’épidictique regarde le présent ; le judiciaire accuse ou défend (le passé), le délibératif conseille (l’avenir).', 1),
    ('4b90d3ca-c6b8-529f-a56e-44e5648ad820'::uuid, 'francais', '1re', 'Rhétorique, Aristote', 'Un orateur suscite la pitié de son auditoire : quel moyen de persuasion emploie-t-il ?', 'mcq', '["L’ethos","Le pathos","Le logos","L’enthymème"]'::jsonb, 1, 'Le pathos agit par les émotions (crainte, pitié, colère) ; l’ethos passe par l’image de l’orateur, le logos par le raisonnement.', 2),
    ('67faa935-0e63-5e3d-bb93-d5df833ee8e7'::uuid, 'francais', '1re', 'Rhétorique, Aristote', 'Qu’est la rhétorique en elle-même, pour Aristote ?', 'mcq', '["Un simple ornement du discours","Un art de tromper les foules","Une technique neutre en soi","Une science du vrai absolu"]'::jsonb, 2, 'Contre Platon, qui accusait les sophistes de manipuler, Aristote en fait une méthode dont l’usage peut être bon ou mauvais.', 3),
    ('ccaeb16f-53ae-5557-9569-2d69ff333e40'::uuid, 'francais', '1re', 'Rhétorique, Aristote', 'Qu’appelle-t-on le vraisemblable ?', 'mcq', '["Ce qui paraît vrai au plus grand nombre","Ce qui est démontré par la science","Ce que l’orateur croit sincèrement","Ce que la loi impose de croire"]'::jsonb, 0, 'Persuader n’est pas prouver : l’orateur s’appuie sur ce que son auditoire tient pour vrai.', 4),
    ('529718f8-e8b2-5ae9-84d5-8fc73bed8906'::uuid, 'francais', '1re', 'Rhinocéros, Eugène Ionesco', 'Sur quel cri Bérenger conclut-il la pièce ?', 'mcq', '["« Vive les rhinocéros ! »","« Il faut s’adapter ! »","« Je ne capitule pas ! »","« Tous les chats sont mortels ! »"]'::jsonb, 2, 'Resté seul, après avoir tenté en vain de se transformer, Bérenger se proclame « le dernier homme » et refuse de céder.', 1),
    ('aaedddad-a520-5a87-82ba-e3417c152205'::uuid, 'francais', '1re', 'Rhinocéros, Eugène Ionesco', 'Quelle pièce fait d’Ionesco un pionnier du théâtre de l’absurde ?', 'mcq', '["En attendant Godot","La Cantatrice chauve","Huis clos","Les Bonnes"]'::jsonb, 1, 'La Cantatrice chauve date de 1950 ; avec Rhinocéros (1959), l’absurde devient politique. En attendant Godot est de Beckett.', 2),
    ('c0c9ac91-67e9-571c-b062-2bcc85667a4b'::uuid, 'francais', '1re', 'Rhinocéros, Eugène Ionesco', 'Quels signes marquent la métamorphose de Jean sur scène ?', 'mcq', '["La peau verdit, la voix change, une corne pousse","Il perd la parole et s’endort","Il grandit jusqu’à toucher le plafond","Ses mains se couvrent de plumes"]'::jsonb, 0, 'La métamorphose est un spectacle : pendant qu’elle s’accomplit, Jean défend peu à peu la rhinocérite.', 3),
    ('8f01d85d-0d7c-5fae-8305-b2a29d848647'::uuid, 'francais', '1re', 'Rhinocéros, Eugène Ionesco', 'Quel prétexte invoquent ceux qui cèdent à la rhinocérite ?', 'mcq', '["La peur de mourir","L’obéissance à Dieu","L’amour de Bérenger","Le courage, la « force de la nature »"]'::jsonb, 3, 'Logique, mode, adaptation, « force de la nature » : chacun trouve de bonnes raisons de rejoindre le troupeau, c’est le conformisme.', 4),
    ('28905586-3486-511d-88b3-33bb7e5f422e'::uuid, 'francais', '1re', 'Romances sans paroles, Paul Verlaine', 'Que montrent les « Paysages belges » ?', 'mcq', '["Des tableaux de musées flamands","Des paysages vus d’un train","Des scènes de la prison de Mons","Des ports de la mer du Nord"]'::jsonb, 1, 'L’errance avec Rimbaud se lit dans ces paysages qui défilent, flous et fugitifs, comme derrière une vitre.', 1),
    ('ec4a80ff-d2d9-59ac-9782-e32b21c1866d'::uuid, 'francais', '1re', 'Romances sans paroles, Paul Verlaine', 'Quel vers d’« Art poétique » rejette la rhétorique ?', 'mcq', '["« Il faut être absolument moderne »","« Peindre non la chose, mais l’effet »","« Prends l’éloquence et tords-lui son cou »","« Mon verre n’est pas grand… »"]'::jsonb, 2, 'Verlaine veut une poésie de la musique, pas du discours ; les autres formules sont de Rimbaud, de Mallarmé et de Musset.', 2),
    ('9f435413-2ef4-5ca8-a3bf-bb5b1d132ec9'::uuid, 'francais', '1re', 'Romances sans paroles, Paul Verlaine', 'Dans « Il pleure dans mon cœur », d’où vient la tristesse ?', 'mcq', '["D’une trahison amoureuse","De la mort d’un ami","De l’exil loin de Paris","D’aucune cause précise"]'::jsonb, 3, 'Le poème le dit lui-même : ce deuil est « sans raison ». La pluie et les larmes se confondent, la mélancolie n’a pas d’objet.', 3),
    ('47344d7e-6f25-57fd-9f82-c422027459e7'::uuid, 'francais', '1re', 'Romances sans paroles, Paul Verlaine', 'Quels procédés donnent au recueil sa fluidité ?', 'mcq', '["Les rimes atténuées et les répétitions","Les alexandrins et les rimes riches","Les longues périodes oratoires","Les notes et les dédicaces"]'::jsonb, 0, 'Avec les vers impairs et les sonorités liquides, ils font passer le sens après la sensation et le rythme.', 4),
    ('9b1c8cf0-2caf-5d36-9103-d0dd448eeb75'::uuid, 'francais', '1re', 'Roméo et Juliette, William Shakespeare', 'Quelle source Shakespeare reprend-il ?', 'mcq', '["Une chronique de la guerre des Deux-Roses","Une histoire italienne mise en vers par Brooke","Une tragédie latine de Sénèque","Un fait divers survenu à Londres"]'::jsonb, 1, 'L’histoire italienne était déjà connue ; Arthur Brooke l’avait adaptée en poème anglais en 1562, et Shakespeare en fait une pièce vers 1595.', 1),
    ('ef0db409-d5e5-571d-abeb-b10f9ec040d9'::uuid, 'francais', '1re', 'Roméo et Juliette, William Shakespeare', 'Pourquoi Juliette boit-elle le philtre ?', 'mcq', '["Pour mourir avant Roméo","Pour oublier Roméo","Pour échapper au mariage avec Pâris","Pour tromper sa nourrice"]'::jsonb, 2, 'Le philtre la fait passer pour morte ; mais la lettre qui devait prévenir Roméo n’arrive pas, et le hasard devient l’instrument du destin.', 2),
    ('92b7fa9f-6676-5f1d-836f-5a476d53f625'::uuid, 'francais', '1re', 'Roméo et Juliette, William Shakespeare', 'Comment Roméo rencontre-t-il Juliette ?', 'mcq', '["Au bal des Capulet, où il entre masqué","Au couvent de frère Laurent","Lors d’un duel contre Tybalt","Sous le balcon, par hasard"]'::jsonb, 0, 'Roméo, un Montaigu, s’introduit masqué chez les ennemis de sa famille : l’amour naît au cœur même de la haine.', 3),
    ('c744e0f1-fedd-513f-bfa5-486a04f1050b'::uuid, 'francais', '1re', 'Roméo et Juliette, William Shakespeare', 'Quelle œuvre moderne réécrit le mythe des amants ?', 'mcq', '["Cyrano de Bergerac","Les Misérables","Tristan et Iseut","West Side Story"]'::jsonb, 3, 'West Side Story transpose la rivalité des familles en rivalité de bandes : le mythe de l’amour plus fort que la mort traverse les siècles.', 4),
    ('565b42b6-639a-512b-93f9-cc489934054b'::uuid, 'francais', '1re', 'Ruy Blas, Victor Hugo', 'Pourquoi don Salluste veut-il se venger ?', 'mcq', '["Ruy Blas l’a volé","Le roi l’a ruiné","La reine l’a chassé de la cour","Don César l’a trahi"]'::jsonb, 2, 'Grand d’Espagne disgracié, il fait passer son valet pour un noble afin de piéger et de déshonorer la reine.', 1),
    ('f46a732b-e483-51aa-a41a-0b1677224582'::uuid, 'francais', '1re', 'Ruy Blas, Victor Hugo', 'Pour l’ouverture de quel théâtre Ruy Blas est-il joué en 1838 ?', 'mcq', '["Le théâtre de la Renaissance","La Comédie-Française","L’Odéon","Le théâtre du Châtelet"]'::jsonb, 0, 'La pièce inaugure le théâtre de la Renaissance ; Hugo y met en pratique les idées de la Préface de Cromwell.', 2),
    ('ff73cbd6-0f45-5c4b-87a1-83b1c188659f'::uuid, 'francais', '1re', 'Ruy Blas, Victor Hugo', 'Que résume la formule « Ver de terre amoureux d’une étoile » ?', 'mcq', '["La cruauté de Salluste","La solitude du roi","La grandeur de l’Espagne","L’écart entre le valet et la reine"]'::jsonb, 3, 'Le valet se voit en ver de terre, la reine en étoile : l’image dit l’amour impossible entre les classes sociales.', 3),
    ('f831fa70-0828-53e8-a35e-fcbe0bead139'::uuid, 'francais', '1re', 'Ruy Blas, Victor Hugo', 'Selon Hugo, qu’incarne Ruy Blas ?', 'mcq', '["La noblesse ruinée","Le peuple, capable de mieux gouverner","L’Église face au roi","L’armée espagnole"]'::jsonb, 1, 'Un valet de génie gouverne mieux que les grands ; mais la société lui interdit ce rôle, d’où la fin tragique.', 4),
    ('e97c6bfc-02a2-5906-ba59-14829331551d'::uuid, 'francais', '1re', 'Sagesse, Paul Verlaine', 'Que contient la deuxième partie du recueil ?', 'mcq', '["Le récit du procès de Bruxelles","Le dialogue avec le Christ","Des souvenirs de Londres","Des chansons galantes"]'::jsonb, 1, '« Mon Dieu m’a dit : Mon fils, il faut m’aimer » : la deuxième partie met en scène le dialogue du pécheur avec le Christ.', 1),
    ('5240c9ce-53fd-5538-914d-a8f2cc9cb2a0'::uuid, 'francais', '1re', 'Sagesse, Paul Verlaine', 'Que change la conversion dans la poésie de Verlaine ?', 'mcq', '["Le sujet : la faute, le pardon, l’humilité","Le vers : l’alexandrin remplace l’impair","Le ton : l’éloquence remplace la chanson","La langue : il écrit désormais en latin"]'::jsonb, 0, 'La manière reste la même — simplicité, musicalité, refus de l’éloquence — ; seul le sujet change.', 2),
    ('84f7741c-1f92-553c-ba68-61a4e9c93556'::uuid, 'francais', '1re', 'Sagesse, Paul Verlaine', 'Que représente la question « Qu’as-tu fait… de ta jeunesse ? » ?', 'mcq', '["Un reproche adressé à Rimbaud","Une question posée par le juge","Une plainte contre sa femme","Un examen de conscience"]'::jsonb, 3, 'Le poète s’interroge lui-même sur sa vie gâchée : la plainte devient repentir.', 3),
    ('1b82043e-6f8e-56ad-a9a4-b2ee144a97b6'::uuid, 'francais', '1re', 'Sagesse, Paul Verlaine', 'Quel thème « Le ciel est, par-dessus le toit » oppose-t-il à la prison ?', 'mcq', '["La gloire littéraire","La vengeance contre Rimbaud","La liberté entrevue par la fenêtre","Le voyage en Angleterre"]'::jsonb, 2, 'Le ciel « si bleu, si calme », la vie qui passe dehors : la cellule rend plus douloureuse cette liberté toute simple.', 4),
    ('4d91faf6-45af-5c94-a6df-6a0a766f7d1b'::uuid, 'francais', '1re', 'Sept manifestes Dada, Tristan Tzara', 'Que désigne « dada » en langage enfantin ?', 'mcq', '["Un papa","Une poupée","Un cheval de bois","Un tambour"]'::jsonb, 2, 'Le mot, trouvé au hasard selon la légende, ne dit rien du mouvement : « Dada ne signifie rien », et c’est un programme.', 1),
    ('272161d7-b200-5aad-911a-66a889562e14'::uuid, 'francais', '1re', 'Sept manifestes Dada, Tristan Tzara', 'Qu’est Zurich en 1916, quand Dada y naît ?', 'mcq', '["Une ville neutre au milieu de la guerre","La capitale du surréalisme","La ville natale de Tzara","Une ville sur le front de la guerre"]'::jsonb, 0, 'À l’abri dans la Suisse neutre, les dadaïstes répondent par la dérision à une guerre qui vide les valeurs de leur sens.', 2),
    ('10601b16-cf66-5d00-95f5-adf109f29b14'::uuid, 'francais', '1re', 'Sept manifestes Dada, Tristan Tzara', 'Quelle œuvre Marcel Duchamp expose-t-il en 1917 ?', 'mcq', '["Guernica, une toile contre la guerre","Le Penseur, une statue de bronze","Les Demoiselles d’Avignon, une toile","Fontaine, un urinoir signé"]'::jsonb, 3, 'Un objet tout fait, signé et exposé : Duchamp, proche de Dada, pose la question de ce qu’est une œuvre d’art.', 3),
    ('4dabfca6-07ef-5857-b2a2-55808228b6bf'::uuid, 'francais', '1re', 'Sept manifestes Dada, Tristan Tzara', 'Quel dadaïste rompra avec Tzara et ouvrira la voie au surréalisme ?', 'mcq', '["Hugo Ball","André Breton","Hans Arp","Marcel Duchamp"]'::jsonb, 1, 'Dada se dissout dans les années 1920 ; Breton, d’abord dadaïste, rompt avec Tzara, et Dada ouvre directement sur le surréalisme.', 4),
    ('7e85b085-0230-54be-9f6c-c713be8ed1de'::uuid, 'francais', '1re', 'Si le grain ne meurt, André Gide', 'Quelle maladie Gide soigne-t-il lors de ses voyages en Afrique du Nord ?', 'mcq', '["La variole","La tuberculose","Le choléra","La malaria"]'::jsonb, 1, 'La maladie puis la guérison accompagnent la découverte du désir : le corps revient à la vie en même temps que le moi se découvre.', 1),
    ('1657f2c8-61d4-522d-a26e-88d772b0e0c1'::uuid, 'francais', '1re', 'Si le grain ne meurt, André Gide', 'Qui est Anna Shackleton ?', 'mcq', '["La cousine qu’il épousera","Une actrice rencontrée à Alger","L’amie de sa mère, figure douce","Sa première éditrice"]'::jsonb, 2, 'Dans une enfance austère et surveillée, elle est une présence douce ; la cousine qu’il épousera est Madeleine Rondeaux.', 2),
    ('4cca3239-560b-5a51-b6f2-58de6ceff0ec'::uuid, 'francais', '1re', 'Si le grain ne meurt, André Gide', 'Comment le livre est-il d’abord publié ?', 'mcq', '["En feuilleton dans un journal","Après la mort de Gide","Sous un pseudonyme","Confidentiellement, avant la librairie"]'::jsonb, 3, 'Il circule d’abord confidentiellement, puis paraît en librairie en 1926 et fait scandale : Gide y avoue son homosexualité.', 3),
    ('deb62cc3-f40a-53ca-a0da-0eed0c3f303b'::uuid, 'francais', '1re', 'Si le grain ne meurt, André Gide', 'Comment le livre est-il composé ?', 'mcq', '["Deux parties : l’enfance, puis la révélation","Trois parties : l’enfance, la guerre, la vieillesse","Un journal daté jour après jour","Des lettres adressées à Madeleine"]'::jsonb, 0, 'La première partie suit l’enfance protestante en France ; la seconde raconte, en Algérie, la découverte du désir.', 4),
    ('ad865043-c73b-5a12-b937-0f8e08a0a707'::uuid, 'francais', '1re', 'Sido, Colette', 'À quel parcours du bac Sido est-il associé ?', 'mcq', '["Émancipations créatrices","La célébration du monde","Alchimie poétique","Dans l’atelier du poète"]'::jsonb, 1, 'Célébrer, chez Colette, c’est nommer précisément : un souci, une pivoine, l’odeur de la pluie sur la poussière chaude.', 1),
    ('59771016-a17e-5e30-8ce7-9c7905243e1a'::uuid, 'francais', '1re', 'Sido, Colette', 'Que fait Sido quand le merle pille ses cerises ?', 'mcq', '["Elle le chasse avec un bâton","Elle tend un filet sur l’arbre","Elle le laisse faire pour l’admirer","Elle demande au Capitaine de tirer"]'::jsonb, 2, 'Sido préfère la beauté de l’oiseau à ses fruits : c’est une manière de regarder le vivant, dont naît le style de sa fille.', 2),
    ('e7cb8fa3-2aa0-569e-873f-4a972111c5fe'::uuid, 'francais', '1re', 'Sido, Colette', 'Qui est Achille ?', 'mcq', '["Le demi-frère aîné, devenu médecin","Le frère rêveur, resté enfant","Le premier mari de Colette","Un voisin du village"]'::jsonb, 0, 'Avec Léo, le frère rêveur, il forme « les Sauvages », silencieux et indépendants.', 3),
    ('98c75842-3a84-5e62-b91b-6d4d5f21d723'::uuid, 'francais', '1re', 'Sido, Colette', 'Où se trouve la lettre du cactus rose ?', 'mcq', '["Dans Sido","Dans Claudine à l’école","Dans Le Blé en herbe","Dans La Naissance du jour"]'::jsonb, 3, 'Sido y refuse une visite pour voir fleurir son cactus : cette lettre ouvre La Naissance du jour (1928), non Sido (1930).', 4),
    ('a4737849-1ed4-51b1-9eba-565a8877dbcc'::uuid, 'francais', '1re', 'Sonnets pour Hélène, Pierre de Ronsard', 'Quelles femmes Ronsard avait-il déjà chantées avant Hélène ?', 'mcq', '["Laure et Béatrice","Cassandre et Marie","Délie et Olive","Diane et Astrée"]'::jsonb, 1, 'Avant Hélène, Ronsard avait chanté Cassandre, puis Marie : les Sonnets pour Hélène sont le cycle d’un poète mûr. Laure et Béatrice sont les dames de Pétrarque et de Dante.', 1),
    ('9f94376c-ec5d-5e5f-9ecf-348297a55aee'::uuid, 'francais', '1re', 'Sonnets pour Hélène, Pierre de Ronsard', 'Quelle ambition la Pléiade, menée par Ronsard et Du Bellay, se donne-t-elle ?', 'mcq', '["Imposer le latin comme seule langue des poètes","Remplacer les modèles antiques par la chanson populaire","Réserver la poésie aux seuls sujets religieux","Élever la langue française au niveau des langues antiques"]'::jsonb, 3, 'La Pléiade veut prouver que le français peut rivaliser avec le grec et le latin : elle imite les Anciens pour enrichir la langue nationale.', 2),
    ('a16c5c9a-b20e-50de-b576-f3b6895966b9'::uuid, 'francais', '1re', 'Sonnets pour Hélène, Pierre de Ronsard', 'Comment les sonnets du recueil sont-ils construits ?', 'mcq', '["Deux quatrains puis deux tercets, avec une chute","Trois quatrains puis un distique final","Quatre tercets suivis d’un vers isolé","Deux sizains encadrant un refrain"]'::jsonb, 0, 'Deux quatrains, deux tercets : quatorze vers, dont le dernier — la chute — doit frapper, comme « Cueillez dès aujourd’hui les roses de la vie ».', 3),
    ('8913ab79-24ee-5272-ad36-deb9310cb52e'::uuid, 'francais', '1re', 'Sonnets pour Hélène, Pierre de Ronsard', 'Quelle évolution de style le cours relève-t-il dans les Sonnets pour Hélène ?', 'mcq', '["Un retour au latin savant de ses débuts","L’abandon de la rime au profit du vers libre","Une langue plus simple que dans ses recueils pétrarquistes","Le passage de l’amour à la seule poésie religieuse"]'::jsonb, 2, 'Loin des recherches de ses premiers recueils pétrarquistes, Ronsard vieillissant atteint une simplicité de langue qui fait la force du recueil.', 4),
    ('a4e41be4-6c21-5076-8c51-3b987e47bf20'::uuid, 'francais', '1re', 'Supplément au voyage de Bougainville, Denis Diderot', 'Pourquoi Diderot choisit-il la forme du dialogue ?', 'mcq', '["Pour imiter les comédies de Molière","Pour raconter le voyage étape par étape","Pour confronter les idées sans conclure de façon dogmatique","Pour faire parler Bougainville lui-même"]'::jsonb, 2, 'Le dialogue entre A et B, qui encadre les morceaux tahitiens, fait circuler les points de vue : le lecteur est invité à juger par lui-même.', 1),
    ('97737f60-1369-51ef-80b1-ceb1c1bfd9a0'::uuid, 'francais', '1re', 'Supplément au voyage de Bougainville, Denis Diderot', 'Quel est le rôle de l’aumônier dans l’entretien avec Orou ?', 'mcq', '["Il est tiraillé entre ses vœux et l’hospitalité tahitienne","Il convertit Orou au christianisme","Il commande l’expédition à la place de Bougainville","Il rédige le récit officiel du voyage"]'::jsonb, 0, 'Lié par ses vœux, l’aumônier se heurte à une hospitalité qui ignore la morale chrétienne ; face à lui, Orou raisonne mieux que l’Européen.', 2),
    ('ea9de9d2-d0dd-561b-ba74-a87c8d40c683'::uuid, 'francais', '1re', 'Supplément au voyage de Bougainville, Denis Diderot', 'Selon l’entretien d’Orou, que sont le mariage indissoluble, la pudeur ou le péché ?', 'mcq', '["Des lois inscrites dans la nature humaine","Des coutumes que Tahiti partage avec l’Europe","Des vérités révélées que les Tahitiens ignorent","Des institutions, et non des vérités naturelles"]'::jsonb, 3, 'Diderot montre que ces règles sont des conventions : elles varient d’une société à l’autre, donc elles ne viennent pas de la nature.', 3),
    ('b05f4205-1639-5745-8a70-1cda8fb5791f'::uuid, 'francais', '1re', 'Supplément au voyage de Bougainville, Denis Diderot', 'Quand le Supplément au voyage de Bougainville est-il publié ?', 'mcq', '["En 1771, avec le récit de Bougainville","En 1796, après la mort de Diderot","En 1772, dès la fin de sa rédaction","En 1751, dans l’Encyclopédie"]'::jsonb, 1, 'Écrit en 1772, le texte ne paraît qu’en 1796, douze ans après la mort de Diderot (1784) : c’est une œuvre posthume.', 4),
    ('004e72b4-8234-5e49-84d7-3098b8f40a1a'::uuid, 'francais', '1re', 'Terre des hommes, Antoine de Saint-Exupéry', 'Pourquoi Guillaumet, perdu dans les Andes, continue-t-il de marcher ?', 'mcq', '["Pour rejoindre Mermoz à Santiago","Pour sauver son mécanicien blessé","Pour achever la livraison du courrier","Pour que sa famille puisse toucher l’assurance"]'::jsonb, 3, 'Il ne marche pas pour lui : il marche pour les siens. La responsabilité le tient debout — « jamais aucune bête ne l’aurait fait ».', 1),
    ('944b9b28-8a8a-5490-99c0-4febbf8e704d'::uuid, 'francais', '1re', 'Terre des hommes, Antoine de Saint-Exupéry', 'Quel prix Terre des hommes reçoit-il en 1939 ?', 'mcq', '["Le prix Goncourt","Le Grand Prix du roman de l’Académie française","Le prix Femina","Le prix Renaudot"]'::jsonb, 1, 'Le livre est couronné par l’Académie française. C’est Vol de nuit qui avait reçu le prix Femina, en 1931.', 2),
    ('8b34cacc-9ba0-5e5e-82af-3133dd61357a'::uuid, 'francais', '1re', 'Terre des hommes, Antoine de Saint-Exupéry', 'Qui sauve Saint-Exupéry et Prévot perdus dans le désert de Libye ?', 'mcq', '["Un Bédouin anonyme","Une patrouille de l’armée","Guillaumet, parti à leur recherche","Des pilotes de l’Aéropostale"]'::jsonb, 0, 'Un Bédouin les sauve : Saint-Exupéry fait de ce sauveur sans nom la figure de « l’Homme ».', 3),
    ('4578b38d-385d-59cf-bd57-0e69abbf662c'::uuid, 'francais', '1re', 'Terre des hommes, Antoine de Saint-Exupéry', 'Que représente l’avion pour Saint-Exupéry dans Terre des hommes ?', 'mcq', '["Une machine dont il détaille la technique","Un symbole de la puissance militaire","Un outil qui révèle la terre et les hommes","Un moyen de fuir la société"]'::jsonb, 2, 'L’avion n’est pas une fin en soi : il fait voir la terre autrement, et le métier lie les hommes entre eux.', 4),
    ('fc406ef7-c5cc-54d5-bb34-ea8c377ff6ca'::uuid, 'francais', '1re', 'Thérèse Desqueyroux, François Mauriac', 'Qui est Jean Azévédo ?', 'mcq', '["Le frère aîné de Bernard, héritier des pins","Un jeune homme cultivé qui lui fait entrevoir une autre vie","L’avocat chargé de la défense de Thérèse","Le médecin qui soigne Bernard"]'::jsonb, 1, 'Jean Azévédo fait entrevoir à Thérèse une vie de l’esprit que sa famille de propriétaires ignore : son étouffement n’en est que plus sensible.', 1),
    ('4efafd22-2dbe-5750-8a2c-c5c9d51295dd'::uuid, 'francais', '1re', 'Thérèse Desqueyroux, François Mauriac', 'De quoi Mauriac s’inspire-t-il pour écrire ce roman ?', 'mcq', '["Des souvenirs de sa propre mère","D’une tragédie de Racine qu’il transpose","D’un procès réel de 1906 pour tentative d’empoisonnement","D’un fait divers parisien survenu en 1925"]'::jsonb, 2, 'Mauriac part du procès d’une femme accusée d’avoir voulu empoisonner son mari ; il en tire le portrait intérieur d’une accusée qui ne comprend pas son propre geste.', 2),
    ('e5b8cdc9-470a-5a2f-9efa-80641245ba0f'::uuid, 'francais', '1re', 'Thérèse Desqueyroux, François Mauriac', 'Comment Thérèse obtient-elle le non-lieu ?', 'mcq', '["Sa famille a menti pour éviter le scandale","Elle a avoué et obtenu le pardon","Aucune trace d’arsenic n’a été trouvée","Un autre coupable a été arrêté"]'::jsonb, 0, 'Pour protéger le nom et les apparences, la famille a menti : ce mensonge ouvre le roman et annonce la séquestration de Thérèse.', 3),
    ('c627afe3-3515-5f61-b67d-afdf5528e55c'::uuid, 'francais', '1re', 'Thérèse Desqueyroux, François Mauriac', 'Outre les doses d’arsenic, quel acte Thérèse a-t-elle commis ?', 'mcq', '["Elle a mis le feu aux pins de Bernard","Elle a volé les titres de propriété","Elle a écrit des lettres anonymes","Elle a falsifié une ordonnance"]'::jsonb, 3, 'Elle a d’abord laissé Bernard augmenter ses doses d’arsenic, puis falsifié une ordonnance : un geste lent, sans mobile clair.', 4),
    ('7f8bb2f0-490c-5c59-aaec-94f490b075d8'::uuid, 'francais', '1re', 'Thérèse Raquin, Émile Zola', 'Quels tempéraments Zola donne-t-il aux deux amants ?', 'mcq', '["Thérèse est nerveuse, Laurent sanguin","Thérèse est sanguine, Laurent nerveux","Tous deux sont mélancoliques","Tous deux sont lymphatiques"]'::jsonb, 0, 'Zola étudie des tempéraments, non des caractères : Thérèse, nerveuse et longtemps contenue ; Laurent, sanguin et paresseux. Leurs corps décident plus que leur volonté.', 1),
    ('9f6ba3b5-5c41-536d-b64d-0b2ff6cb5a0d'::uuid, 'francais', '1re', 'Thérèse Raquin, Émile Zola', 'À quel moment de la carrière de Zola Thérèse Raquin paraît-il ?', 'mcq', '["En 1880, au milieu des Rougon-Macquart","En 1898, l’année de J’accuse","En 1893, à la fin des Rougon-Macquart","En 1867, avant les Rougon-Macquart"]'::jsonb, 3, 'Zola a vingt-sept ans : c’est un roman de jeunesse, écrit avant qu’il ne commence le cycle des Rougon-Macquart.', 2),
    ('d353ffec-be4c-56cd-bfab-8dcdc3f3d148'::uuid, 'francais', '1re', 'Thérèse Raquin, Émile Zola', 'Comment le roman est-il accueilli à sa parution ?', 'mcq', '["Dans l’indifférence générale","Par un scandale : on parle de « littérature putride »","Par le prix Goncourt, dès sa parution","Par des éloges pour sa leçon morale"]'::jsonb, 1, 'Le scandale est immédiat ; Zola y répond dans la préface de la seconde édition, qui devient un manifeste du naturalisme.', 3),
    ('68c90564-ac7f-5bfb-b7cc-2f2b8b36809f'::uuid, 'francais', '1re', 'Thérèse Raquin, Émile Zola', 'Pourquoi peut-on parler de huis clos à propos de Thérèse Raquin ?', 'mcq', '["Parce que le roman a d’abord été écrit pour la scène","Parce que l’action se passe dans une prison","Parce que tout se joue dans la boutique close et humide du passage","Parce que Camille ne quitte jamais sa chambre"]'::jsonb, 2, 'La mercerie sombre du passage du Pont-Neuf enferme les personnages : l’enfermement devient un thème, et le crime les y enferme davantage.', 4),
    ('a46c8f14-3576-5ecf-b4bd-c3b5509e0d65'::uuid, 'francais', '1re', 'Tobie des Marais, Sylvie Germain', 'Quelle malédiction pèse sur Sarra ?', 'mcq', '["Elle a perdu la vue dans son enfance","Elle ne peut pas quitter le marais","Tous ses amoureux meurent par accident, depuis ses treize ans","Elle a perdu la parole à la mort de sa mère"]'::jsonb, 2, 'C’est la transposition de la Sara biblique, dont un démon a tué les sept maris : dans le roman, les amoureux de Sarra meurent accidentellement.', 1),
    ('441a3939-eea3-5eb2-8b62-0c84e6a26bf7'::uuid, 'francais', '1re', 'Tobie des Marais, Sylvie Germain', 'Que garde Sylvie Germain du Livre de Tobie ?', 'mcq', '["La trame et les noms, transportés à notre époque","Le décor antique, mais pas les personnages","La langue biblique, recopiée mot pour mot","Uniquement le titre"]'::jsonb, 0, 'Elle conserve l’histoire et les noms (Tobie, Raphaël, Sarra), mais transporte le récit dans le Marais poitevin contemporain : c’est le principe de la réécriture.', 2),
    ('1cbdfc4c-1902-59d2-a6ab-513d2c8356ec'::uuid, 'francais', '1re', 'Tobie des Marais, Sylvie Germain', 'Comment le roman fait-il sentir le sacré ?', 'mcq', '["Comme un monde céleste séparé du nôtre","Par des miracles expliqués à la fin","Par des sermons du narrateur","Comme une présence obscure dans le monde ordinaire"]'::jsonb, 3, 'Le sacré n’est pas au-dessus du monde, il est dedans, à peine visible : dans les eaux, les brumes, un compagnon de route qui ressemble à tout le monde.', 3),
    ('29a81cf5-a306-568c-bdc3-a3afafd95c0f'::uuid, 'francais', '1re', 'Tobie des Marais, Sylvie Germain', 'Quel prix Sylvie Germain a-t-elle reçu pour Jours de colère, en 1989 ?', 'mcq', '["Le prix Goncourt","Le prix Femina","Le prix Renaudot","Le prix Médicis"]'::jsonb, 1, 'Jours de colère obtient le prix Femina en 1989 ; son œuvre, marquée par la spiritualité et le mal, avait commencé avec Le Livre des nuits (1985).', 4),
    ('b1f38df5-b251-5535-a7b3-b1c96d11e15f'::uuid, 'francais', '1re', 'Tous les matins du monde, Pascal Quignard', 'Tandis qu’il joue seul dans sa cabane, qui apparaît parfois à Sainte Colombe ?', 'mcq', '["Le roi Louis XIV, en visite","Sa femme morte","Un ange musicien","Son propre père"]'::jsonb, 1, 'Il joue des heures durant pour la morte, qui lui apparaît parfois : la musique devient un moyen d’atteindre les morts.', 1),
    ('8da50663-ae7d-5138-bc01-a994ddb47ba5'::uuid, 'francais', '1re', 'Tous les matins du monde, Pascal Quignard', 'Que devient Marin Marais après avoir été chassé par Sainte Colombe ?', 'mcq', '["Il renonce à la musique","Il part enseigner en Italie","Il devient le gendre de son maître","Il devient musicien du roi, célèbre et riche"]'::jsonb, 3, 'Marais choisit la cour, le succès et l’argent que son maître refuse — avant de revenir, bien plus tard, écouter le vieil homme en secret.', 2),
    ('2d6111cc-bb18-5d74-bb93-f3e8ac39f767'::uuid, 'francais', '1re', 'Tous les matins du monde, Pascal Quignard', 'Quel peintre, ami de Sainte Colombe, apparaît dans le roman ?', 'mcq', '["Georges de La Tour","Nicolas Poussin","Baugin","Jean Siméon Chardin"]'::jsonb, 2, 'Le peintre Baugin, ami de Sainte Colombe, peint une nature morte aux gaufrettes : le roman fait dialoguer la peinture et la musique.', 3),
    ('0d532706-e631-5a24-9f55-0761508877d4'::uuid, 'francais', '1re', 'Tous les matins du monde, Pascal Quignard', 'Qui a porté le livre à l’écran en 1991 ?', 'mcq', '["Alain Corneau, avec la musique de Jordi Savall","Patrice Leconte, avec la musique de Michel Legrand","Bertrand Tavernier, avec la musique de Philippe Sarde","Claude Berri, avec la musique de Jean-Claude Petit"]'::jsonb, 0, 'Le film d’Alain Corneau, avec la musique de Jordi Savall, a fait connaître le livre au monde entier.', 4),
    ('ad69cb09-a976-55bd-a877-76d8f2bc42b5'::uuid, 'francais', '1re', 'Traité sur la tolérance, Voltaire', 'Sur quoi repose la condamnation de Jean Calas ?', 'mcq', '["Sur les aveux du père","Sur le témoignage d’un voisin","Sur une lettre laissée par le fils","Sur la seule clameur publique, sans preuve"]'::jsonb, 3, 'Aucune preuve ne l’accuse : la rumeur contre une famille protestante suffit à le faire rouer vif en mars 1762.', 1),
    ('f201b5b7-3a52-5302-a481-df0e4fe7d3c3'::uuid, 'francais', '1re', 'Traité sur la tolérance, Voltaire', 'Quand Voltaire publie-t-il le Traité sur la tolérance ?', 'mcq', '["En 1763, pendant sa campagne pour Calas","En 1759, l’année de Candide","En 1765, après la réhabilitation","En 1685, à la révocation de l’édit de Nantes"]'::jsonb, 0, 'Le livre paraît en 1763, au cœur des trois ans de combat : il sert la cause avant la cassation du jugement, en 1765.', 2),
    ('2649d452-4e90-528e-b4fd-13c8710a61bc'::uuid, 'francais', '1re', 'Traité sur la tolérance, Voltaire', 'Où vit Voltaire lorsqu’il mène l’affaire Calas ?', 'mcq', '["À Versailles, à la cour","À Cirey, chez Mme du Châtelet","À Ferney, près de Genève","À la Bastille"]'::jsonb, 2, 'Installé à Ferney, près de Genève, Voltaire est alors l’écrivain le plus célèbre d’Europe : de là, il mobilise lettres, mémoires et réseau d’influence.', 3),
    ('9cda4256-3719-54f3-bf43-9e28f5b12ba3'::uuid, 'francais', '1re', 'Traité sur la tolérance, Voltaire', 'Quel rôle nouveau Voltaire invente-t-il avec l’affaire Calas ?', 'mcq', '["Celui du juriste qui plaide au tribunal","Celui de l’intellectuel qui universalise une cause particulière","Celui du prélat qui défend son Église","Celui du ministre qui réforme la justice"]'::jsonb, 1, 'Voltaire part d’un cas — un marchand protestant de Toulouse — pour poser la question de la tolérance : un modèle d’engagement que suivront Hugo et Zola.', 4),
    ('37a1f248-abae-5e45-b57d-abda768a0961'::uuid, 'francais', '1re', 'Tristan et Iseult', 'Qui a donné en 1900 la reconstitution du récit qu’on lit le plus souvent aujourd’hui ?', 'mcq', '["Chrétien de Troyes","Denis de Rougemont","Joseph Bédier","Richard Wagner"]'::jsonb, 2, 'À partir des versions fragmentaires du Moyen Âge, Joseph Bédier a composé en 1900 un récit continu : c’est lui qu’on lit le plus souvent.', 1),
    ('0d6fcbe5-3751-5d6b-8f1a-0c07a6b731eb'::uuid, 'francais', '1re', 'Tristan et Iseult', 'Que pousse-t-il sur les tombes des amants ?', 'mcq', '["Deux rosiers qui se tournent le dos","Une ronce que l’on coupe en vain","Un chêne frappé par la foudre","Un lys blanc qui fane aussitôt"]'::jsonb, 1, 'La ronce repousse chaque fois qu’on la coupe : même la mort ne sépare pas les amants.', 2),
    ('491b4afb-c07c-579c-bb66-7a5211ff9d7b'::uuid, 'francais', '1re', 'Tristan et Iseult', 'Quel essayiste a fait de Tristan le mythe de la passion, dans L’Amour et l’Occident ?', 'mcq', '["Joseph Bédier","Roland Barthes","Jean-Paul Sartre","Denis de Rougemont"]'::jsonb, 3, 'Denis de Rougemont voit dans Tristan le mythe occidental de la passion contre la loi.', 3),
    ('beec869d-05a2-57ab-83a7-b2103d4bbedd'::uuid, 'francais', '1re', 'Tristan et Iseult', 'En quoi la passion de Tristan et Iseult s’oppose-t-elle à l’amour courtois ?', 'mcq', '["Elle ne connaît ni loi ni mesure","Elle respecte les règles du service amoureux","Elle reste chaste et secrète","Elle se soumet à la volonté du roi"]'::jsonb, 0, 'L’amour courtois est un art réglé, fait de mesure ; la passion emporte tout, au mépris de la loi et du mariage.', 4),
    ('a92e4583-0305-5f8a-8ed4-1511968b3917'::uuid, 'francais', '1re', 'Tropismes, Nathalie Sarraute', 'D’où vient le mot « tropisme » ?', 'mcq', '["De la rhétorique","De la biologie","De la musique","De la psychanalyse"]'::jsonb, 1, 'En biologie, un tropisme est le mouvement élémentaire d’un organisme vers la lumière ou la chaleur ; Sarraute l’applique aux mouvements intérieurs infimes.', 1),
    ('adc83475-3405-521e-a096-2c4454ba5da7'::uuid, 'francais', '1re', 'Tropismes, Nathalie Sarraute', 'Quels temps installent les scènes de Tropismes ?', 'mcq', '["Le passé simple et le plus-que-parfait","Le futur et le conditionnel","Le passé composé seul","Le présent et l’imparfait"]'::jsonb, 3, 'Présent et imparfait installent des scènes sans début ni fin : pas d’événement daté, seulement un mouvement qui dure.', 2),
    ('ad33229a-2e87-53b1-a5a3-cd95f128594a'::uuid, 'francais', '1re', 'Tropismes, Nathalie Sarraute', 'Quel essai de 1956 Sarraute consacre-t-elle au roman ?', 'mcq', '["L’Ère du soupçon","Pour un nouveau roman","Le Degré zéro de l’écriture","Qu’est-ce que la littérature ?"]'::jsonb, 0, 'Dans L’Ère du soupçon, elle montre que le lecteur ne croit plus aux personnages : l’essai prolonge la découverte de Tropismes.', 3),
    ('0d04852e-d896-5007-b00e-76ba0d22a928'::uuid, 'francais', '1re', 'Tropismes, Nathalie Sarraute', 'Quel métier Nathalie Sarraute exerce-t-elle jusqu’en 1940 ?', 'mcq', '["Professeure de lettres","Journaliste","Avocate","Traductrice"]'::jsonb, 2, 'Née en Russie et arrivée enfant à Paris, elle est avocate jusqu’en 1940 ; elle écrit les textes de Tropismes à partir de 1932.', 4),
    ('9f0deeda-8c3c-5269-81d6-1960511d3f98'::uuid, 'francais', '1re', 'Un Balcon en forêt, Julien Gracq', 'Quel pamphlet Gracq a-t-il publié contre le milieu littéraire ?', 'mcq', '["La Littérature à l’estomac","Le Rivage des Syrtes","L’Ère du soupçon","Contre Sainte-Beuve"]'::jsonb, 0, 'Après ce pamphlet contre le milieu littéraire, Gracq refuse le Goncourt en 1951 pour Le Rivage des Syrtes.', 1),
    ('5a78cdb3-5067-52b5-990b-78eab3e955d1'::uuid, 'francais', '1re', 'Un Balcon en forêt, Julien Gracq', 'Comment appelle-t-on la période d’attente, sans combats, que vit Grange ?', 'mcq', '["La guerre de tranchées","L’Occupation","La drôle de guerre","La guerre éclair"]'::jsonb, 2, 'De l’automne 1939 à mai 1940, la France est en guerre sans combattre : c’est la drôle de guerre, que le roman change en rêverie éveillée.', 2),
    ('2701f338-a56d-5368-ab5e-81b9c50db339'::uuid, 'francais', '1re', 'Un Balcon en forêt, Julien Gracq', 'Comment le roman se termine-t-il ?', 'mcq', '["Grange est fait prisonnier et emmené en Allemagne","Grange rejoint Mona à Paris","La maison forte résiste jusqu’à l’armistice","Blessé, Grange rentre à la maison vide et ferme les yeux"]'::jsonb, 3, 'La maison forte est encerclée, les hommes s’égaillent ; Grange, blessé, revient à la maison vide, se couche et ferme les yeux : une fin suspendue.', 3),
    ('b1b67f4d-cf92-5e15-9da1-f121e6897389'::uuid, 'francais', '1re', 'Un Balcon en forêt, Julien Gracq', 'Quelle expérience personnelle Gracq a-t-il mise dans le roman ?', 'mcq', '["Il a été résistant dans les Ardennes en 1944","Il a été mobilisé en 1939, puis fait prisonnier en 1940","Il a été correspondant de guerre en Espagne","Il a combattu à Verdun en 1916"]'::jsonb, 1, 'Mobilisé en 1939 et fait prisonnier en 1940, Gracq a connu l’attente de la drôle de guerre : le roman puise dans cette expérience.', 4),
    ('810ac689-7339-5fa4-a2c1-7073f5550f58'::uuid, 'francais', '1re', 'Un Barrage contre le Pacifique, Marguerite Duras', 'Qu’espère la mère des visites de Monsieur Jo ?', 'mcq', '["Qu’il rachète la concession inondée","Qu’il trouve un emploi à Joseph","Qu’il finance de nouveaux barrages","Un mariage pour Suzanne, et un diamant"]'::jsonb, 3, 'La mère voit en Monsieur Jo une chance de sortir de la misère ; mais la bague sera vendue et l’argent dilapidé.', 1),
    ('f602c1f6-5f98-5176-a351-eb9ddaecd49f'::uuid, 'francais', '1re', 'Un Barrage contre le Pacifique, Marguerite Duras', 'Quel prix le roman a-t-il failli obtenir en 1950 ?', 'mcq', '["Le prix Femina","Le prix Goncourt","Le prix Renaudot","Le prix Nobel"]'::jsonb, 1, 'Le livre a failli obtenir le Goncourt en 1950 ; Duras reviendra sur la même enfance dans L’Amant (1984).', 2),
    ('666b160b-f941-572c-ba77-2add7ef4c884'::uuid, 'francais', '1re', 'Un Barrage contre le Pacifique, Marguerite Duras', 'Pourquoi la mère est-elle un personnage tragique ?', 'mcq', '["Sa lutte contre la mer est héroïque et vaine","Elle trahit ses enfants par ambition","Elle meurt dès le début du roman","Elle ignore tout de sa propre misère"]'::jsonb, 0, 'Elle a cru pouvoir tenir tête au Pacifique : ses barrages de rondins sont emportés, et toute sa vie se brise contre cette illusion.', 3),
    ('c8261e01-133c-58a3-b712-332204f716c3'::uuid, 'francais', '1re', 'Un Barrage contre le Pacifique, Marguerite Duras', 'Qui est Joseph ?', 'mcq', '["Le fils héritier de Monsieur Jo","Un paysan qui bâtit les barrages","Le frère de Suzanne, chasseur désœuvré","L’agent corrompu du cadastre"]'::jsonb, 2, 'Joseph, vingt ans, chasse et s’ennuie ; comme Suzanne, il partira après la mort de la mère.', 4),
    ('10a92bdc-59bf-567f-aedc-9d86f3bd3f37'::uuid, 'francais', '1re', 'Une Saison en Enfer, Arthur Rimbaud', 'Quelle est la forme d’Une saison en enfer ?', 'mcq', '["Vingt-quatre sonnets en alexandrins","Une pièce de théâtre en trois actes","Neuf sections en prose","Un journal intime daté jour par jour"]'::jsonb, 2, 'Le livre compte neuf sections en prose poétique, aux rythmes brisés, de « Mauvais sang » à « Adieu ».', 1),
    ('056e2ff2-22e9-57b6-81e1-dd27de494c0a'::uuid, 'francais', '1re', 'Une Saison en Enfer, Arthur Rimbaud', 'Quel âge Rimbaud a-t-il quand il écrit Une saison en enfer ?', 'mcq', '["Dix-huit ans","Quinze ans","Vingt-cinq ans","Trente-sept ans"]'::jsonb, 0, 'Écrit d’avril à août 1873, le livre est le bilan d’un poète de dix-huit ans ; Rimbaud mourra à trente-sept ans, loin de la poésie.', 2),
    ('065ebbe9-b908-5ba6-8914-99c4d8dc1803'::uuid, 'francais', '1re', 'Une Saison en Enfer, Arthur Rimbaud', 'Quelle section clôt le livre ?', 'mcq', '["« Mauvais sang »","« Nuit de l’enfer »","« Alchimie du verbe »","« Adieu »"]'::jsonb, 3, '« Adieu » est la sortie : on y lit « Il faut être absolument moderne » et le vœu de « posséder la vérité dans une âme et un corps ».', 3),
    ('34f295db-45ab-556a-8b2a-f75540f9d876'::uuid, 'francais', '1re', 'Une Saison en Enfer, Arthur Rimbaud', 'Quel regard le livre porte-t-il sur le projet du voyant ?', 'mcq', '["Il le présente comme un programme à suivre","Il le récapitule et en montre l’échec","Il n’en dit pas un mot","Il l’attribue entièrement à Verlaine"]'::jsonb, 1, 'Une saison en enfer est un bilan et une rupture : Rimbaud y raconte son entreprise poétique, la juge, puis dit adieu.', 4),
    ('3800bce0-049a-5b22-9fb0-696a0f92b95b'::uuid, 'francais', '1re', 'Une Vie, Guy de Maupassant', 'D’où sort Jeanne au début du roman ?', 'mcq', '["D’un pensionnat parisien","Du couvent, pleine de rêves","D’un premier mariage malheureux","D’un séjour chez une tante à Rouen"]'::jsonb, 1, 'Jeanne quitte le couvent pleine de rêves : tout le roman mesure l’écart entre ces rêves et ce que la vie lui réserve.', 1),
    ('34a754f3-c2f4-5084-9229-8bb9bc26c922'::uuid, 'francais', '1re', 'Une Vie, Guy de Maupassant', 'Qui est Rosalie ?', 'mcq', '["La fille unique de Jeanne","La comtesse Gilberte de Fourville","La maîtresse parisienne de Paul","La bonne séduite par Julien, qui reviendra servir Jeanne"]'::jsonb, 3, 'Julien trompe d’abord Jeanne avec Rosalie, la femme de chambre ; c’est elle qui, revenue la servir, prononce la dernière phrase du roman.', 2),
    ('c9152528-8c98-5059-9ff9-2d45378f8908'::uuid, 'francais', '1re', 'Une Vie, Guy de Maupassant', 'À quelle héroïne de Flaubert compare-t-on souvent Jeanne ?', 'mcq', '["Emma Bovary","Félicité","Salammbô","Madame Arnoux"]'::jsonb, 0, 'On rapproche souvent Jeanne d’Emma Bovary ; mais, à la différence d’Emma, Jeanne ne se révolte jamais.', 3),
    ('b39a9231-e992-5bf2-88ea-c1f2603524e4'::uuid, 'francais', '1re', 'Une Vie, Guy de Maupassant', 'Pourquoi parle-t-on de « roman du désenchantement » ?', 'mcq', '["Parce que Jeanne y perd la foi de son enfance","Parce que le roman raconte une défaite militaire","Parce que la vie use peu à peu une femme sans faute","Parce que le narrateur raille tous ses personnages"]'::jsonb, 2, 'Rien d’extraordinaire n’arrive : ni crime ni aventure héroïque, seulement le temps qui use une femme bonne et naïve. Le roman tient sans héroïsme.', 4),
    ('67fde5e2-7987-55fb-8220-8005114267b6'::uuid, 'francais', '1re', 'Vendredi ou les Limbes du Pacifique, Michel Tournier', 'Qui reste avec Robinson sur l’île à la fin ?', 'mcq', '["Vendredi, revenu du navire","Le capitaine du navire anglais","Personne : il reste seul","Un jeune mousse fugueur, qu’il nomme Jeudi"]'::jsonb, 3, 'Vendredi s’embarque sur le navire anglais ; un jeune mousse fugueur reste avec Robinson, qui le nomme Jeudi.', 1),
    ('d46f58f6-0a3a-5cc7-a128-10755f701764'::uuid, 'francais', '1re', 'Vendredi ou les Limbes du Pacifique, Michel Tournier', 'Qui est Vendredi ?', 'mcq', '["Un Caraïbe de la Jamaïque","Un Araucan joyeux, libre et inventif","Un Polynésien de Tahiti","Un marin anglais naufragé"]'::jsonb, 1, 'Vendredi, l’Araucan, conduit Robinson vers une autre existence : jeu, danse, contemplation, adhésion au soleil et à l’île.', 2),
    ('7097e79d-c60f-57d2-a5b0-dd427c8040a7'::uuid, 'francais', '1re', 'Vendredi ou les Limbes du Pacifique, Michel Tournier', 'Qu’est-ce que le log-book de Robinson ?', 'mcq', '["Le journal qu’il tient, dont la voix alterne avec le récit","Le registre du navire naufragé, retrouvé intact","Le code pénal qu’il impose à l’île","Le calendrier qu’il grave sur un mât"]'::jsonb, 0, 'Robinson tient un journal de bord : cette voix intime, à la première personne, alterne avec le récit.', 3),
    ('cc52dab9-8f4b-54f4-ba65-690ae317c41c'::uuid, 'francais', '1re', 'Vendredi ou les Limbes du Pacifique, Michel Tournier', 'Quelle discipline, étudiée auprès de Claude Lévi-Strauss, nourrit le roman ?', 'mcq', '["La géologie","La médecine","L’ethnologie","L’astronomie"]'::jsonb, 2, 'Élève de Lévi-Strauss et philosophe de formation, Tournier nourrit son roman d’ethnologie et de mythes solaires.', 4),
    ('66af9653-ba4f-582d-93cc-a0a9523212a7'::uuid, 'francais', '1re', 'Vol de nuit, Antoine de Saint-Exupéry', 'Qui a préfacé Vol de nuit ?', 'mcq', '["Jean-Paul Sartre","André Gide","Paul Valéry","André Malraux"]'::jsonb, 1, 'André Gide préface le roman, couronné par le prix Femina en 1931.', 1),
    ('ae7a090f-9bd6-5beb-9fd8-60491279c9bc'::uuid, 'francais', '1re', 'Vol de nuit, Antoine de Saint-Exupéry', 'Quels courriers de nuit convergent vers Buenos Aires ?', 'mcq', '["Ceux de Dakar, Casablanca et Toulouse","Ceux de Rio, Lima et Santiago","Ceux de Patagonie, du Chili et du Paraguay","Ceux de New York, Montréal et Mexico"]'::jsonb, 2, 'Trois courriers rejoignent Buenos Aires pour que parte, à l’aube, le courrier d’Europe ; Fabien pilote celui de Patagonie.', 2),
    ('9b296133-d819-51de-82f1-e805e95016fe'::uuid, 'francais', '1re', 'Vol de nuit, Antoine de Saint-Exupéry', 'Pourquoi Rivière refuse-t-il toute excuse à ses hommes ?', 'mcq', '["Parce que la ligne ne tient que par une discipline sans faille","Parce qu’il méprise les pilotes","Pour obtenir une promotion à Paris","Pour obéir au gouvernement argentin"]'::jsonb, 0, 'Rivière n’est pas cruel : il sait que seule la régularité de la ligne justifiera les vies risquées. D’où la question tragique : qu’est-ce qui vaut d’être payé d’une vie ?', 3),
    ('0d01f032-ca33-5748-adc1-9b3dd0292672'::uuid, 'francais', '1re', 'Vol de nuit, Antoine de Saint-Exupéry', 'Qui est Robineau ?', 'mcq', '["Le pilote du courrier du Chili","Le mari de la femme qui attend","Le radio de Fabien","L’inspecteur, tenté par l’amitié"]'::jsonb, 3, 'Robineau, l’inspecteur, est tenté par l’amitié des hommes ; Rivière, chef inflexible, assume seul la solitude du commandement.', 4),
    ('b5e9892e-dd4f-56ed-b08e-dc686aa101cb'::uuid, 'francais', '1re', 'Voyage au bout de la nuit, Louis-Ferdinand Céline', 'Comment Bardamu s’engage-t-il en 1914 ?', 'mcq', '["Sur un coup de tête","Par conviction patriotique","Pour suivre Robinson","Pour échapper à la prison"]'::jsonb, 0, 'Il s’engage sur un coup de tête et découvre aussitôt l’horreur absurde de la guerre.', 1),
    ('2926b89e-bfe6-5340-8520-11c9bf7e71b8'::uuid, 'francais', '1re', 'Voyage au bout de la nuit, Louis-Ferdinand Céline', 'Comment meurt Robinson ?', 'mcq', '["Il est tué au front en 1914","Il meurt de fièvre en Afrique","Il disparaît à New York","Il est assassiné par sa fiancée Madelon"]'::jsonb, 3, 'Robinson, le double sombre de Bardamu, qui échoue partout, finit tué par Madelon, sa fiancée jalouse.', 2),
    ('cff76f0d-0767-5c3f-af6c-16ab4c3cc17a'::uuid, 'francais', '1re', 'Voyage au bout de la nuit, Louis-Ferdinand Céline', 'Quel genre de roman le cours associe-t-il au Voyage ?', 'mcq', '["Le roman épistolaire","Le roman à thèse","Le roman picaresque","Le roman historique"]'::jsonb, 2, 'Comme dans le roman picaresque, un personnage traverse des milieux — la guerre, les colonies, l’usine, la banlieue — et les juge.', 3),
    ('ca3cb9f6-78f3-5e11-9f34-1daedf7a1c4b'::uuid, 'francais', '1re', 'Voyage au bout de la nuit, Louis-Ferdinand Céline', 'Quelle vision du monde le roman exprime-t-il ?', 'mcq', '["Un optimisme qui résiste à la guerre","Un pessimisme radical, qui voit partout le même mensonge","Une foi confiante dans le progrès technique","Un appel nostalgique au retour à la terre"]'::jsonb, 1, 'Pour Bardamu, la guerre, le colonialisme, l’usine et la misère sont les visages d’un même mensonge.', 4),
    ('ebf595cb-fca4-5fe6-ab53-ba32d2babc10'::uuid, 'francais', '1re', 'Voyage au centre de la Terre, Jules Verne', 'Qui raconte l’histoire ?', 'mcq', '["Le professeur Lidenbrock","Axel, le neveu du professeur","Hans, le guide islandais","Arne Saknussemm"]'::jsonb, 1, 'Axel, le neveu, est le narrateur : peureux mais fidèle, il suit son oncle et fait partager ses doutes au lecteur.', 1),
    ('76c88383-c2b9-5020-9498-18a921cb7feb'::uuid, 'francais', '1re', 'Voyage au centre de la Terre, Jules Verne', 'Par quel volcan les explorateurs ressortent-ils ?', 'mcq', '["Le Stromboli, en Italie","Le Vésuve, près de Naples","L’Etna, en Sicile","Le Sneffels, en Islande"]'::jsonb, 0, 'Entrés par le cratère du Sneffels, en Islande, ils sont remontés par une éruption et ressortent par le Stromboli, en Italie.', 2),
    ('57b783f5-fbb7-5890-b6f6-3b949065306c'::uuid, 'francais', '1re', 'Voyage au centre de la Terre, Jules Verne', 'Quelle était la formule de l’éditeur Hetzel pour ces romans ?', 'mcq', '["L’art pour l’art","Plaire et toucher","Rien n’est impossible","Instruire en amusant"]'::jsonb, 3, 'Hetzel veut instruire en amusant : le roman fait découvrir la géologie, la paléontologie et la minéralogie au fil de l’aventure.', 3),
    ('3d46f410-123d-5d2f-bcb3-fa7b21535994'::uuid, 'francais', '1re', 'Voyage au centre de la Terre, Jules Verne', 'Quel grand débat scientifique de l’époque le roman met-il en scène ?', 'mcq', '["La conquête de l’espace","L’origine des maladies","L’âge de la Terre et les fossiles","La vitesse de la lumière"]'::jsonb, 2, 'On discute alors de l’âge de la Terre et des fossiles : la descente des explorateurs est aussi une plongée dans le temps géologique.', 4),
    ('4fd9d7d0-b3ec-55c2-81f1-553ff155fdf2'::uuid, 'francais', '1re', 'Zadig ou la Destinée, Voltaire', 'Sous quel titre une première version du conte paraît-elle en 1747 ?', 'mcq', '["Micromégas","L’Ingénu","Memnon","Candide"]'::jsonb, 2, 'Memnon, paru en 1747, devient Zadig en 1748.', 1),
    ('558cb918-a9e0-5ae2-b46d-84aec344520a'::uuid, 'francais', '1re', 'Zadig ou la Destinée, Voltaire', 'Qui est Astarté ?', 'mcq', '["La reine aimée de Zadig","La femme du marchand Sétoc","Une déesse que Zadig invoque","La sœur de l’ermite Jesrad"]'::jsonb, 0, 'Devenu premier ministre, Zadig aime la reine Astarté, face au roi jaloux Moabdar ; il doit fuir, avant de retrouver le trône et la reine.', 2),
    ('ced8d07f-0afa-56e4-98e7-2519e7d61f28'::uuid, 'francais', '1re', 'Zadig ou la Destinée, Voltaire', 'Pourquoi l’épisode du chien et du cheval est-il resté célèbre ?', 'mcq', '["Il fonde la fable animalière","Il annonce le roman d’amour","Il parodie un récit biblique","On y voit un ancêtre du raisonnement policier"]'::jsonb, 3, 'Zadig décrit les deux animaux sans les avoir vus, d’après leurs seules traces : une méthode d’indices qui annonce les détectives.', 3),
    ('2ed8cb5b-c4ba-5878-a305-4bd3f1a854e0'::uuid, 'francais', '1re', 'Zadig ou la Destinée, Voltaire', 'De quelle philosophie Voltaire est-il encore proche dans Zadig ?', 'mcq', '["Du scepticisme de Montaigne","De l’optimisme de Leibniz","Du pessimisme de Pascal","Du matérialisme de Diderot"]'::jsonb, 1, 'Jesrad soutient que chaque mal engendre un bien : c’est l’optimisme de Leibniz, que Voltaire démolira dans Candide après le tremblement de terre de Lisbonne.', 4),
    ('40f834f7-aeed-5448-9699-060d8fcb3cf3'::uuid, 'francais', '1re', 'Zazie dans le métro, Raymond Queneau', 'Pourquoi Zazie ne peut-elle pas prendre le métro ?', 'mcq', '["Sa mère le lui a interdit","Gabriel refuse de l’y emmener","Il est fermé la nuit","Le métro est en grève"]'::jsonb, 3, 'Son unique désir se heurte à une grève : d’où une errance comique dans Paris, jusqu’au mot de la fin, « J’ai vieilli ».', 1),
    ('809643b7-dc90-5f02-8aee-1ac244118045'::uuid, 'francais', '1re', 'Zazie dans le métro, Raymond Queneau', 'Qu’a de particulier le personnage de Trouscaillon ?', 'mcq', '["Il ne parle qu’en alexandrins","Il change sans cesse d’identité et de fonction","Il est le seul à prendre le métro","Il ne prononce pas un mot"]'::jsonb, 1, 'Trouscaillon passe d’un rôle à l’autre : avec lui, l’identité devient un jeu, comme la langue du roman.', 2),
    ('0fd22bd7-37d2-5d79-8a96-39080865978e'::uuid, 'francais', '1re', 'Zazie dans le métro, Raymond Queneau', 'Qui adapte Zazie dans le métro au cinéma en 1960 ?', 'mcq', '["Louis Malle","François Truffaut","Jacques Tati","Jean-Luc Godard"]'::jsonb, 0, 'Louis Malle porte le roman à l’écran dès 1960, un an après sa parution.', 3),
    ('733a07d0-1aa9-5f90-a602-9a7c8edd2a7a'::uuid, 'francais', '1re', 'Zazie dans le métro, Raymond Queneau', 'Quel livre de 1947 Queneau avait-il déjà publié ?', 'mcq', '["La Disparition","Les Gommes","Exercices de style","Le Parti pris des choses"]'::jsonb, 2, 'Dans les Exercices de style (1947), Queneau jouait déjà avec les registres de langue ; Zazie pousse ce jeu jusqu’au roman.', 4)
  ) AS v(id, slug, level, chapter, question, kind, options, correct_index, explanation, rang)
  JOIN public.subjects s ON s.slug = v.slug
  JOIN public.chapters c ON c.subject_id = s.id AND c.level = v.level AND c.title = v.chapter
  JOIN LATERAL (
    SELECT qz.id FROM public.lessons l
      JOIN public.quizzes qz ON qz.lesson_id = l.id
     WHERE l.chapter_id = c.id
     ORDER BY l.position, qz.id
     LIMIT 1
  ) qz ON true
ON CONFLICT (id) DO NOTHING;

-- 3. Sonde finale ---------------------------------------------------------
DO $$
DECLARE n integer;
